local shootingRangeCache, shootingRangeChecked = false, 0
local function isShootingRange()
    local now = os.clock()
    if now - shootingRangeChecked < 0.5 then return shootingRangeCache end
    shootingRangeChecked = now

    local function matches(value)
        if value == nil then return false end
        local text = tostring(value):lower():gsub("[%s_%-]", "")
        return text:find("shootingrange", 1, true) ~= nil
            or text:find("firingrange", 1, true) ~= nil
            or text:find("사격장", 1, true) ~= nil
    end

    for _, object in ipairs({workspace, LocalPlayer}) do
        for _, attribute in ipairs({"Map", "MapName", "Mode", "GameMode", "Arena", "Environment", "EnvironmentName", "ShootingRange"}) do
            local value = object:GetAttribute(attribute)
            if (value == true and attribute == "ShootingRange") or matches(value) then
                shootingRangeCache = true
                return true
            end
        end
    end

    local character = LocalPlayer.Character
    local current = character
    while current and current ~= workspace do
        if matches(current.Name) then
            shootingRangeCache = true
            return true
        end
        current = current.Parent
    end

    local root = character and character:FindFirstChild("HumanoidRootPart")
    local function matchingAreaIsNear(object)
        if not matches(object.Name) or not root then return false end
        local part = object:IsA("BasePart") and object or object:FindFirstChildWhichIsA("BasePart", true)
        return part and (part.Position - root.Position).Magnitude < 2000
    end
    for _, child in ipairs(workspace:GetChildren()) do
        if matchingAreaIsNear(child) then
            shootingRangeCache = true
            return true
        end
        for _, grandchild in ipairs(child:GetChildren()) do
            if matchingAreaIsNear(grandchild) then
                shootingRangeCache = true
                return true
            end
        end
    end

    shootingRangeCache = false
    return false
end

local playerTargetCache, dummyTargetCache, rangeTargetCache = {}, {}, {}
local rangeTargetPending = setmetatable({}, {__mode = "k"})
local rangeCacheStarted = false
local combatTargetListCache = {}
local combatTargetCacheVersion = 0

local function invalidateCombatTargetCache()
    combatTargetCacheVersion += 1
    table.clear(combatTargetListCache)
end

local function rangeNameMatches(model, words)
    if not model or not model:IsA("Model") then return false end
    local node = model
    while node and node ~= workspace do
        local name = node.Name:lower():gsub("[%s_%-]", "")
        for _, word in ipairs(words) do
            if name:find(word, 1, true) then return true end
        end
        node = node.Parent
    end
    return false
end

local function isWorkingDummy(model)
    if not model or not model:IsA("Model") or Players:GetPlayerFromCharacter(model) then return false end
    if model:GetAttribute("IsDummy") == true then return true end
    return rangeNameMatches(model, {"workingdummy", "dummy", "training"})
end

local function isShootingRangeTarget(model)
    if not model or not model:IsA("Model") or Players:GetPlayerFromCharacter(model) then return false end
    if isWorkingDummy(model) then return false end
    return rangeNameMatches(model, {"shootingrange", "firingrange", "rangetarget", "target"})
end

local function isTrainingDummy(model)
    return isWorkingDummy(model) or isShootingRangeTarget(model)
end

local combatRootCache = setmetatable({}, {__mode = "k"})
local combatAimPartCache = setmetatable({}, {__mode = "k"})

local function resolveCombatTargetRoot(model)
    if not model then return nil end
    return model:FindFirstChild("HumanoidRootPart")
        or model:FindFirstChild("UpperTorso")
        or model:FindFirstChild("Torso")
        or model:FindFirstChild("Head")
        or model.PrimaryPart
        or model:FindFirstChildWhichIsA("BasePart", true)
end

local function getCombatTargetRoot(model)
    if not model then return nil end
    local now = os.clock()
    local cached = combatRootCache[model]
    if cached and now < cached.Expires then
        local part = cached.Part
        if part and part.Parent and part:IsDescendantOf(model) then
            return part
        end
    end
    local part = resolveCombatTargetRoot(model)
    combatRootCache[model] = {Part = part, Expires = now + 0.75}
    return part
end

local function resolveCombatTargetAimPart(model, preferred)
    if not model then return nil end
    if preferred and preferred ~= "" then
        local exact = model:FindFirstChild(preferred, true)
        if exact and exact:IsA("BasePart") then return exact end
    end
    for _, name in ipairs({"Head", "Hitbox", "Target", "Center", "HumanoidRootPart", "UpperTorso", "Torso"}) do
        local part = model:FindFirstChild(name, true)
        if part and part:IsA("BasePart") then return part end
    end
    return model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart", true)
end

local function getCombatTargetAimPart(model, preferred)
    if not model then return nil end
    local key = tostring(preferred or "")
    local now = os.clock()
    local cachedByName = combatAimPartCache[model]
    local cached = cachedByName and cachedByName[key]
    if cached and now < cached.Expires then
        local part = cached.Part
        if part and part.Parent and part:IsDescendantOf(model) then
            return part
        end
    end
    local part = resolveCombatTargetAimPart(model, preferred)
    if not cachedByName then
        cachedByName = {}
        combatAimPartCache[model] = cachedByName
    end
    cachedByName[key] = {Part = part, Expires = now + 0.75}
    return part
end

local function isCombatTargetAlive(model)
    if not model or not model.Parent then return false end
    local hum = model:FindFirstChildOfClass("Humanoid")
    if hum then return hum.Health > 0 end
    return isTrainingDummy(model) and getCombatTargetAimPart(model) ~= nil
end

local function cacheRangeModel(model)
    if not model or not model:IsA("Model") then return end
    local dummy = model.Parent and not Players:GetPlayerFromCharacter(model)
        and isWorkingDummy(model) and (model:FindFirstChildOfClass("Humanoid") ~= nil
            or (model:GetAttribute("IsDummy") == true and getCombatTargetAimPart(model) ~= nil)) or false
    local range = not dummy and model.Parent and not Players:GetPlayerFromCharacter(model)
        and isShootingRangeTarget(model) and getCombatTargetAimPart(model) ~= nil or false
    if (dummyTargetCache[model] ~= nil) == dummy and (rangeTargetCache[model] ~= nil) == range then return end
    dummyTargetCache[model] = dummy and true or nil
    rangeTargetCache[model] = range and true or nil
    invalidateCombatTargetCache()
end

local function removeCombatModel(model)
    if not model then return end
    local changed = false
    if playerTargetCache[model] then playerTargetCache[model], changed = nil, true end
    if dummyTargetCache[model] then dummyTargetCache[model], changed = nil, true end
    if rangeTargetCache[model] then rangeTargetCache[model], changed = nil, true end
    combatRootCache[model] = nil
    combatAimPartCache[model] = nil
    if changed then invalidateCombatTargetCache() end
end

local function registerPlayerCharacter(character)
    if not character or not character:IsA("Model") or character == LocalPlayer.Character then return end
    dummyTargetCache[character] = nil
    rangeTargetCache[character] = nil
    combatRootCache[character] = nil
    combatAimPartCache[character] = nil
    playerTargetCache[character] = true
    invalidateCombatTargetCache()
end

local function registerPlayer(player)
    if player == LocalPlayer then return end
    if player.Character then registerPlayerCharacter(player.Character) end
    table.insert(mainapi.Connections, player.CharacterAdded:Connect(registerPlayerCharacter))
    table.insert(mainapi.Connections, player.CharacterRemoving:Connect(removeCombatModel))
end

local function queueRangeModel(model)
    if not model or not model:IsA("Model") or rangeTargetPending[model] then return end
    rangeTargetPending[model] = true
    task.defer(function()
        rangeTargetPending[model] = nil
        cacheRangeModel(model)
    end)
end

local function isPotentialRangeModel(model)
    if not model or not model:IsA("Model") then return false end
    if model:GetAttribute("IsDummy") == true or model:FindFirstChildOfClass("Humanoid") then return true end
    local name = model.Name:lower()
    if name:find("dummy", 1, true) or name:find("target", 1, true)
        or name:find("training", 1, true) then return true end
    local parent = model.Parent
    if parent then
        local parentName = parent.Name:lower()
        return parentName:find("range", 1, true) ~= nil
            or parentName:find("dummy", 1, true) ~= nil
            or parentName:find("target", 1, true) ~= nil
    end
    return false
end

-- Rivals already maintains the live enemies, dummies, and targets. Observe that
-- registry when present so target discovery does not depend on workspace churn.
local function watchNativeEnemyRegistry()
    local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
    local controllers = scripts and scripts:FindFirstChild("Controllers")
    local module = controllers and controllers:FindFirstChild("EnemyController")
    if not module or not module:IsA("ModuleScript") then return end
    local ok, controller = pcall(require, module)
    if not ok or type(controller) ~= "table" then return end

    local function getEnemyModel(enemy)
        if typeof(enemy) == "Instance" and enemy:IsA("Model") then
            return enemy
        end
        local readOk, value = pcall(function() return enemy.Model end)
        if readOk and typeof(value) == "Instance" and value:IsA("Model") then return value end
    end
    local function register(enemy)
        local model = getEnemyModel(enemy)
        if model then queueRangeModel(model) end
        return model ~= nil
    end
    local function unregister(enemy)
        local model = getEnemyModel(enemy)
        if model then removeCombatModel(model) end
    end

    local added = controller.ObjectAdded
    local removed = controller.ObjectRemoved
    if not added or not removed then return end
    local addOk, addConnection = pcall(function() return added:Connect(register) end)
    local removeOk, removeConnection = pcall(function() return removed:Connect(unregister) end)
    if not addOk or not removeOk then
        if addConnection then addConnection:Disconnect() end
        if removeConnection then removeConnection:Disconnect() end
        return
    end
    table.insert(mainapi.Connections, addConnection)
    table.insert(mainapi.Connections, removeConnection)
    local existing = controller._model_to_enemy
    if type(existing) == "table" then
        local found, seeded = 0, 0
        for _, enemy in pairs(existing) do
            found += 1
            if register(enemy) then seeded += 1 end
        end
        return found == seeded
    end
end

local function startRangeCacheScan()
    if rangeCacheStarted then return end
    rangeCacheStarted = true
    for _, player in ipairs(Players:GetPlayers()) do
        registerPlayer(player)
    end
    table.insert(mainapi.Connections, Players.PlayerAdded:Connect(registerPlayer))
    table.insert(mainapi.Connections, Players.PlayerRemoving:Connect(function(player)
        removeCombatModel(player.Character)
    end))
    local nativeRegistryReady = watchNativeEnemyRegistry()
    table.insert(mainapi.Connections, workspace.DescendantAdded:Connect(function(node)
        if node:IsA("Model") then
            if isPotentialRangeModel(node) then queueRangeModel(node) end
        elseif node:IsA("Humanoid") or (node:IsA("BasePart") and (
            node.Name == "Head" or node.Name == "Hitbox" or node.Name == "Target"
            or node.Name == "Center" or node.Name == "HumanoidRootPart"
            or node.Name == "UpperTorso" or node.Name == "Torso")) then
            local model = node:FindFirstAncestorOfClass("Model")
            if isPotentialRangeModel(model) then queueRangeModel(model) end
        end
    end))
    table.insert(mainapi.Connections, workspace.DescendantRemoving:Connect(function(node)
        if node:IsA("Model") then
            removeCombatModel(node)
        end
    end))
    if nativeRegistryReady then return end
    task.spawn(function()
        -- Walk the hierarchy in small chunks instead of allocating/scanning every
        -- workspace descendant on a gameplay frame.
        local queue, head, processed = {workspace}, 1, 0
        while queue[head] do
            local node = queue[head]
            queue[head] = nil
            head += 1

            if isPotentialRangeModel(node) then cacheRangeModel(node) end
            for _, child in ipairs(node:GetChildren()) do
                table.insert(queue, child)
            end

            processed += 1
            if processed >= 80 then
                processed = 0
                RunService.Heartbeat:Wait()
            end
        end
    end)
end

local function getCombatTargetModels(rangeOptions)
    local cacheKey = rangeOptions == nil and "legacy"
        or ((rangeOptions.WorkingDummy and "dummy" or "") .. (rangeOptions.RangeTargets and "range" or ""))
    if mainapi:IsCombatFiring() then
        local cached = combatTargetListCache[cacheKey]
        return cached and cached.Models or mainapi.EmptyCombatTargets
    end
    startRangeCacheScan()
    local now = os.clock()
    local cached = combatTargetListCache[cacheKey]
    if cached and cached.Version == combatTargetCacheVersion and now < cached.Expires then
        return cached.Models
    end

    local result = {}

    local function appendCache(cache)
        for model in pairs(cache) do
            if model.Parent then
                table.insert(result, model)
            else
                cache[model] = nil
            end
        end
    end
    appendCache(playerTargetCache)

    -- Legacy callers keep humanoid training dummies without a workspace rescan.
    if rangeOptions == nil then
        appendCache(dummyTargetCache)
        combatTargetListCache[cacheKey] = {Models = result, Expires = now + 0.25, Version = combatTargetCacheVersion}
        return result
    end

    if not rangeOptions.WorkingDummy and not rangeOptions.RangeTargets then
        combatTargetListCache[cacheKey] = {Models = result, Expires = now + 0.25, Version = combatTargetCacheVersion}
        return result
    end
    if not isShootingRange() then
        combatTargetListCache[cacheKey] = {Models = result, Expires = now + 0.25, Version = combatTargetCacheVersion}
        return result
    end
    if rangeOptions.WorkingDummy then appendCache(dummyTargetCache) end
    if rangeOptions.RangeTargets then appendCache(rangeTargetCache) end
    combatTargetListCache[cacheKey] = {Models = result, Expires = now + 0.25, Version = combatTargetCacheVersion}
    return result
end

