shared.ModernLoadingOwner = mainapi

shared.PlexStartupDiagPath = "Overlay/startup_diagnostics.log"
shared.PlexStartupDiagBuffer = ""
local pendingStartupDiag = {}
local lastStartupDiagFlush = os.clock()
pcall(function()
    if type(makefolder) == "function" then makefolder("Overlay") end
    if type(writefile) == "function" then
        writefile(shared.PlexStartupDiagPath, "")
    end
end)

shared.PlexFlushStartupDiag = function()
    if #pendingStartupDiag == 0 then return end
    local block = table.concat(pendingStartupDiag)
    table.clear(pendingStartupDiag)
    lastStartupDiagFlush = os.clock()
    if type(appendfile) == "function" then
        pcall(appendfile, shared.PlexStartupDiagPath, block)
    elseif type(writefile) == "function" then
        shared.PlexStartupDiagBuffer ..= block
        pcall(writefile, shared.PlexStartupDiagPath, shared.PlexStartupDiagBuffer)
    end
end

shared.PlexStartupDiag = function(event, detail)
    local memory = "?"
    pcall(function()
        memory = string.format("%.1fKB", collectgarbage("count"))
    end)

    local line = string.format(
        "[%s][clock=%.3f][mem=%s] %s | %s\n",
        os.date("%H:%M:%S"),
        os.clock(),
        tostring(memory),
        tostring(event or "event"),
        tostring(detail or "")
    )

    table.insert(pendingStartupDiag, line)
    if event == "module_error" or event == "loader_ready" or event == "slow_heartbeat" then
        pcall(print, "[PlexDiag] "..line:gsub("\n$", ""))
    end
    if event == "module_error" or event == "module_end" or event == "loader_ready" or os.clock() - lastStartupDiagFlush >= 0.75 then
        shared.PlexFlushStartupDiag()
    end
end

