shared.PlexFeatureMeta = shared.PlexFeatureMeta or setmetatable({}, {__mode = "k"})

local run = function(func)
    local meta = {QueuedAt = os.clock()}
    pcall(function()
        meta.Source = debug.info(func, "s")
        meta.Line = debug.info(func, "l")
        meta.Name = debug.info(func, "n")
    end)
    shared.PlexFeatureMeta[func] = meta

    if mainapi.DeferredLoad then
        table.insert(mainapi.FeatureQueue, func)
        shared.PlexStartupDiag(
            "module_queued",
            "index="..tostring(#mainapi.FeatureQueue)
            .." source="..tostring(meta.Source)
            .." line="..tostring(meta.Line)
            .." name="..tostring(meta.Name)
        )
    else
        shared.PlexStartupDiag("module_immediate_start", "line="..tostring(meta.Line))
        local started = os.clock()
        local ok, err = xpcall(func, function(message)
            return debug.traceback(tostring(message), 2)
        end)
        shared.PlexStartupDiag(
            ok and "module_immediate_end" or "module_immediate_error",
            "line="..tostring(meta.Line).." cost="..string.format("%.4f", os.clock()-started).." err="..tostring(err or "")
        )
        if not ok then warn("[LionUI] immediate feature load failed:", err) end
    end
end

function mainapi:StartBackgroundLoad()
    if self.FeatureLoadStarted then return end
    self.FeatureLoadStarted = true
    shared.PlexFeatureErrors = {}
    shared.PlexStartupDiag("loader_start", "queued="..tostring(#self.FeatureQueue))

    task.spawn(function()
        local succeeded,startupError=xpcall(function()
        local queue = self.FeatureQueue
        local total = math.max(#queue, 1)
        local lastSlowFrameLog = 0

        shared.PlexStartupDiag("loader_thread", "total="..tostring(total))
        StartupLoader:Set("loading modules · 0 / "..total, 0.14)

        while self.FeatureLoadIndex < #queue do
            if self.Uninjecting then return end

            local dt = RunService.Heartbeat:Wait()
            if dt > (1/30) and os.clock() - lastSlowFrameLog > 0.5 then
                lastSlowFrameLog = os.clock()
                shared.PlexStartupDiag(
                    "slow_heartbeat",
                    "index="..tostring(self.FeatureLoadIndex).." dt="..string.format("%.4f", dt)
                )
            end

            -- Process a few cheap initializers on the same frame, but always
            -- make progress when the game is already running below 42 FPS.
            local frameStart = os.clock()
            local frameBudget = dt > (1/30) and 0.002 or 0.006
            local maxPerFrame = dt > (1/30) and 1 or 4
            local processed = 0
            while self.FeatureLoadIndex < #queue and processed < maxPerFrame do
                if self.Uninjecting then return end
                if processed > 0 and os.clock() - frameStart >= frameBudget then break end
                self.FeatureLoadIndex += 1
                processed += 1
                local index = self.FeatureLoadIndex
                local fn = queue[index]

                StartupLoader:Set(
                    "loading modules · "..index.." / "..total,
                    0.14 + (index / total) * 0.76
                )

                if fn then
                    local meta = shared.PlexFeatureMeta and shared.PlexFeatureMeta[fn] or {}
                    shared.PlexStartupDiag(
                        "module_start",
                        "index="..tostring(index).."/"..tostring(total)
                        .." source="..tostring(meta.Source)
                        .." line="..tostring(meta.Line)
                        .." name="..tostring(meta.Name)
                    )

                    getgenv().__PlexLastInitModule = index
                    getgenv().__PlexLastInitMeta = meta

                    local started = os.clock()
                    local ok, err = xpcall(fn, function(message)
                        return debug.traceback(tostring(message), 2)
                    end)
                    local cost = os.clock() - started

                    if not ok then
                        table.insert(shared.PlexFeatureErrors, {
                            Index = index,
                            Error = tostring(err)
                        })
                        shared.PlexStartupDiag(
                            "module_error",
                            "index="..tostring(index)
                            .." cost="..string.format("%.4f", cost)
                            .." err="..tostring(err)
                        )
                        warn("[LionUI] feature load failed:", err)
                    else
                        shared.PlexStartupDiag(
                            "module_end",
                            "index="..tostring(index)
                            .." cost="..string.format("%.4f", cost)
                        )
                    end

                    StartupLoader:Set(
                        (ok and "loaded module · " or "module error · ")..index.." / "..total,
                        0.14 + (index / total) * 0.76
                    )
                    if cost > frameBudget then break end
                end
            end
        end

        if self.Uninjecting then return end

        self.DeferredLoad = false
        self.FeatureLoadComplete = true
        shared.PlexStartupDiag("modules_complete", "count="..tostring(self.FeatureLoadIndex))
        table.clear(queue)
        if LionLibrary and LionLibrary.NativeUI and LionLibrary.NativeUI.refilter then
            pcall(LionLibrary.NativeUI.refilter)
        end

        self.DeferModuleActivations=true
        shared.PlexStartupDiag("autoload_begin", "")
        if self.InitializeWeaponProfiles then self:InitializeWeaponProfiles() end
        if self.InitializeServerBrowser then self:InitializeServerBrowser() end
        StartupLoader:Set("applying saved settings", 0.92)
        RunService.Heartbeat:Wait()

        if LionSaveManager and LionSaveManager.TryAutoLoad then
            local ok, err = pcall(function()
                LionSaveManager:TryAutoLoad()
            end)
            if not ok then
                warn("[Plex Config] Auto load crashed: "..tostring(err))
            end
        end

        RunService.Heartbeat:Wait()

        if shared.LionCosmeticChanger and shared.LionCosmeticChanger.TryAutoLoadConfig then
            local ok, err = pcall(shared.LionCosmeticChanger.TryAutoLoadConfig)
            if not ok then
                warn("[Plex Skins] Auto load crashed: "..tostring(err))
            end
        end
        if self.StartWeaponProfiles then self:StartWeaponProfiles() end

        self.DeferModuleActivations=false
        self:FlushModuleActivations()
        while self.PendingModuleActivations>0 do
            if self.Uninjecting then return end
            StartupLoader:Set("starting saved features · "..self.PendingModuleActivations.." remaining",0.96)
            RunService.Heartbeat:Wait()
        end
        StartupLoader:Set("finishing", 0.97)
        RunService.Heartbeat:Wait()
        if self.Uninjecting then return end

        local selectedFrontend = LionLibrary and LionLibrary.FrontendName or nil
        local needsFrontendReload = false
        if LionLibrary and LionLibrary.PromptFrontendAfterInit then
            StartupLoader:Set("choose interface", 0.985)
            local ok, selected, changed = pcall(function()
                return LionLibrary:PromptFrontendAfterInit()
            end)
            if not ok then
                warn("[Plex] UI selection failed after init: " .. tostring(selected))
            elseif selected then
                selectedFrontend = selected
                needsFrontendReload = changed == true
            end
        end

        if needsFrontendReload then
            local env = getgenv and getgenv() or _G
            local source = env.__PlexMainSource
            if type(source) == "string" and source ~= "" then
                StartupLoader:Set("switching interface", 0.99)
                env.__PlexUIChoice = selectedFrontend
                env.__PlexUIChoiceOnce = selectedFrontend
                env.__PlexSkipUISelector = true
                task.defer(function()
                    pcall(function() mainapi:Uninject() end)
                    local chunk, compileError = loadstring(source, "PlexMain")
                    if not chunk then
                        env.__PlexSkipUISelector = nil
                        warn("[Plex] Selected UI reload failed to compile: " .. tostring(compileError))
                        return
                    end
                    local ran, runError = pcall(chunk)
                    env.__PlexSkipUISelector = nil
                    if not ran then
                        warn("[Plex] Selected UI reload failed: " .. tostring(runError))
                    end
                end)
                return
            end
            warn("[Plex] Selected UI will apply on the next run because cached main source is unavailable.")
        end

        if shared.ModernLoadingOwner == self then
            shared.ModernLoading = false
            shared.ModernLoadingOwner = nil
        end
        showLionWindow()
        RunService.Heartbeat:Wait()
        if LionLibrary and LionLibrary.NativeMenu and LionLibrary.NativeMenu.syncNow then
            pcall(LionLibrary.NativeMenu.syncNow)
        end

        if LionSaveManager and LionSaveManager.StartAutoSave then
            LionSaveManager:StartAutoSave()
        end

        do
            local env = getgenv and getgenv() or _G
            if env.__PlexRunningOwner==self and self.StartupBootToken
                and env.__PlexExpectedBootToken==self.StartupBootToken then
                env.__PlexRuntimeReadyToken=self.StartupBootToken
            end
        end

        shared.PlexStartupDiag(
            "loader_ready",
            "errors="..tostring(#(shared.PlexFeatureErrors or {}))
        )
        StartupLoader:Set("ready", 1)
        StartupLoader:Finish()

        local edition = getgenv and tostring(getgenv().PlexLoaderEdition or "normal") or "normal"
        local version = LionLibrary and LionLibrary.NativeUI and LionLibrary.NativeUI.publicVersion or "1"

        mainapi:Notify({
            Kind = "ready",
            Title = "plex.cc",
            Text = "ready · "..edition.." · v"..version,
            Duration = 4
        })
        end,function(err) return debug.traceback(tostring(err),2) end)
        if not succeeded and not self.Uninjecting then
            self.StartupFailed=tostring(startupError)
            self.DeferModuleActivations=false
            for _,module in pairs(self.Modules or {}) do self:CancelModuleActivation(module) end
            shared.PlexStartupDiag("loader_fatal",self.StartupFailed)
            if shared.ModernLoadingOwner==self then shared.ModernLoading=false;shared.ModernLoadingOwner=nil end
            local env=getgenv and getgenv() or _G
            if env.__PlexRunningOwner==self then
                env.__PlexRunning,env.__PlexRunningJobId,env.__PlexRunningOwner=nil,nil,nil
                local token=self.StartupBootToken
                if token and env.__PlexExpectedBootToken==token then env.__PlexExpectedBootToken=nil end
                if token and type(env.__PlexTPHandlerBoot)=="table" and env.__PlexTPHandlerBoot.Token==token then env.__PlexTPHandlerBoot=nil end
            end
            pcall(function() StartupLoader:Finish() end)
            pcall(showLionWindow)
            warn("[Plex startup] "..self.StartupFailed)
        end
    end)
end


local textBoundsCache = {Values={}, Keys={}, Next=1, Limit=512}

local getfontsize = function(text, size, font)

    local key = text .. "_" .. tostring(size) .. "_" .. tostring(font)

    if textBoundsCache.Values[key] then
        return textBoundsCache.Values[key]
    end

    fontsize.Text = text
    fontsize.Size = size

    if typeof(font) == "Font" then
        fontsize.Font = font
    end

    local bounds = TextService:GetTextBoundsAsync(fontsize)

    local slot=textBoundsCache.Next
    local previous=textBoundsCache.Keys[slot]
    if previous then textBoundsCache.Values[previous]=nil end
    textBoundsCache.Keys[slot]=key
    textBoundsCache.Values[key]=bounds
    textBoundsCache.Next=slot % textBoundsCache.Limit + 1

    return bounds
end

local function getTableSize(tab)
    local ind = 0
