local function isValidBind(bind)
    return typeof(bind) == "EnumItem"
end

local function inputMatchesBind(inputObj, bind)
    if not isValidBind(bind) then
        return false
    end

    if bind.EnumType == Enum.KeyCode then
        return inputObj.UserInputType == Enum.UserInputType.Keyboard and inputObj.KeyCode == bind
    end

    if bind.EnumType == Enum.UserInputType then
        return inputObj.UserInputType == bind
    end

    return false
end

local function addMaid(object)
    object.Connections = object.Connections or {}

    function object:Clean(callback)
        if typeof(callback) == 'Instance' then
            table.insert(self.Connections, {
                Disconnect = function()
                    callback:ClearAllChildren()
                    callback:Destroy()
                end
            })
        elseif type(callback) == 'function' then
            table.insert(self.Connections, {
                Disconnect = callback
            })
        else
            table.insert(self.Connections, callback)
        end
    end
end

addMaid(mainapi)

-- Inactive workers own no Heartbeat connection or repeating timer. Settings
-- changes and game events wake them explicitly; cleanup cancels owned work.
do
    local workers = {}
    mainapi.IdleWorkers = workers
    function mainapi:CreateIdleWorker(name, definition)
        if workers[name] then workers[name]:Stop() end
        local worker = {Running=false, Updates=0, Generation=0}
        workers[name] = worker
        function worker:Stop()
            self.Generation += 1
            self.Running = false
            if self.Connection then self.Connection:Disconnect(); self.Connection=nil end
            if self.Thread then pcall(task.cancel,self.Thread); self.Thread=nil end
        end
        local function active()
            return not mainapi.Uninjecting and definition.IsActive() == true
        end
        function worker:Wake()
            if not active() then self:Stop(); return false end
            if self.Running then return true end
            self.Running = true
            self.Generation += 1
            local generation = self.Generation
            local function step(dt)
                self.Thread=nil
                if not self.Running or self.Generation~=generation then return end
                if not active() then self:Stop(); return end
                self.Updates += 1
                local ok,why=pcall(definition.Update,dt)
                if not ok then self:Stop();warn("[Plex Worker] "..name..": "..tostring(why));return end
                if not self.Running or self.Generation~=generation then return end
                if not active() then self:Stop();return end
                if definition.Interval then self.Thread=task.delay(definition.Interval,step) end
            end
            if definition.Interval then self.Thread=task.delay(definition.Interval,step)
            else self.Connection=RunService.Heartbeat:Connect(step) end
            return true
        end
        self:Clean(function() worker:Stop(); if workers[name]==worker then workers[name]=nil end end)
        worker:Wake()
        return worker
    end
    function mainapi:WakeIdleWorkers()
        for _,worker in pairs(workers) do worker:Wake() end
    end
end

-- Saved toggles describe final state before any activation starts. Staggering
-- native setup prevents a saved config from launching every scanner in one frame.
do
    local jobs,order,head,thread={}, {}, 1, nil
    mainapi.PendingModuleActivations=0
    function mainapi:CancelModuleActivation(module)
        if jobs[module] then jobs[module]=nil;self.PendingModuleActivations-=1 end
    end
    function mainapi:QueueModuleActivation(module,callback)
        if not self.DeferModuleActivations then return false end
        if not jobs[module] then order[#order+1]=module;self.PendingModuleActivations+=1 end
        jobs[module]=callback
        return true
    end
    function mainapi:FlushModuleActivations()
        if thread or self.Uninjecting then return end
        local function step()
            thread=nil
            if self.Uninjecting then return end
            while head<=#order do
                local module=order[head];head+=1
                local callback=jobs[module]
                if callback then
                    jobs[module]=nil;self.PendingModuleActivations-=1
                    if not module.Disposed and module.Enabled then
                        shared.PlexStartupDiag("saved_feature_start",module.Name or "")
                        local ok,err=pcall(callback)
                        if not ok then warn("[Plex startup] "..tostring(err)) end
                    end
                    break
                end
            end
            if self.PendingModuleActivations>0 then thread=task.delay(0.075,step)
            else table.clear(order);head=1 end
        end
        thread=task.defer(step)
    end
    mainapi:Clean(function()
        if thread then pcall(task.cancel,thread);thread=nil end
        table.clear(jobs);table.clear(order)
        mainapi.PendingModuleActivations=0
    end)
end

do
    local knownDummies = {}
    local nextDummySync = 0

    -- startRangeCacheScan owns filtered target lifecycle events. Shot effects
    -- must not enqueue their enclosing weapon/map model for target discovery.
    startRangeCacheScan()

    mainapi:Clean(RunService.Heartbeat:Connect(function()
        local now = os.clock()
        if now < nextDummySync then return end
        nextDummySync = now + 1

        if not isShootingRange() then
            for model in pairs(knownDummies) do
                entitylib.removeEntity(model)
            end
            table.clear(knownDummies)
            return
        end

        local present = {}
        for model in pairs(dummyTargetCache) do
            if model.Parent then
                present[model] = true
                if not entitylib.getEntity(model) and not entitylib.EntityThreads[model] then
                    entitylib.addEntity(model, nil)
                end
            else
                dummyTargetCache[model] = nil
            end
        end

        for model in pairs(knownDummies) do
            if not present[model] then entitylib.removeEntity(model) end
        end
        knownDummies = present
    end))
end

local function makeDraggable(obj, window)
    obj.InputBegan:Connect(function(inputObj)
        if not mainapi.ClickGuiStatus then return end
        if
            (inputObj.UserInputType == Enum.UserInputType.MouseButton1 or inputObj.UserInputType == Enum.UserInputType.Touch)
            and (inputObj.Position.Y - obj.AbsolutePosition.Y < 40 or window)
        then
            local dragPosition = Vector2.new(obj.AbsolutePosition.X - inputObj.Position.X, obj.AbsolutePosition.Y - inputObj.Position.Y + GuiService:GetGuiInset().Y) / mainapi.Scale.Value
            local changed = UserInputService.InputChanged:Connect(function(input)
                if input.UserInputType == (inputObj.UserInputType == Enum.UserInputType.MouseButton1 and Enum.UserInputType.MouseMovement or Enum.UserInputType.Touch) then
                    local position = input.Position
                    if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
                        dragPosition = Vector2.new(math.floor(dragPosition.X / 3) * 3, math.floor(dragPosition.Y / 3) * 3)
                        position = Vector3.new(math.floor(position.X / 3) * 3, math.floor(position.Y / 3) * 3, position.Z)
                    end
                    obj.Position = UDim2.fromOffset((position.X / mainapi.Scale.Value) + dragPosition.X, (position.Y / mainapi.Scale.Value) + dragPosition.Y)
                end
            end)

            local ended
            ended = inputObj.Changed:Connect(function()
                if inputObj.UserInputState == Enum.UserInputState.End then
                    if changed then
                        changed:Disconnect()
                    end
                    if ended then
                        ended:Disconnect()
                    end
                    pcall(SaveConfig, true)
                end
            end)
        end
    end)
end

