    function UI.resetRegistries()
        for _, c in ipairs(UI.conns) do
            pcall(c.Disconnect, c)
        end
        table.clear(UI.conns)
        UI.dragInstalled = false
        UI.drag = nil
        table.clear(UI.rows)
        table.clear(UI.groups)
        table.clear(UI.sync)
