    function Menu.rebuild()
        local wasOpen = S.menuOpen
        local tab = Menu.activeTab
        local ok, err = pcall(function()
            Menu.destroy()
            S.menuOpen = false
            Menu.build()
        end)
        if not ok then
            Menu.panic(err)



            pcall(Menu.destroy)
            local ok2, err2 = pcall(Menu.build)
            if not ok2 then
                Menu.panic(err2)
                return
            end
        end
        if tab ~= "" and Menu.pages[tab] then
            Menu.showTab(tab)
        end
        if wasOpen then
