local overlaySource = [====[
-- All Zone overlay frames are created and themed through Linoria's registry.
return function(library, UI)
    local visibility={Watermark=true,KeybindList=true,ActiveFeatures=true}
    local activePanel
    function library:SetOverlayVisibility(kind,enabled)
        visibility[kind]=enabled==true
        if kind=="Watermark" then self:SetWatermarkVisibility(visibility[kind])
        elseif kind=="KeybindList" then self.KeybindFrame.Visible=visibility[kind]
        elseif kind=="ActiveFeatures" and activePanel then activePanel.Visible=visibility[kind]end
    end
    local function panel(parent,title,width,height)
        local frame=library:Create("Frame",{Name="Zone"..title:gsub("%W",""),
            BackgroundColor3=library.MainColor,BorderSizePixel=1,BorderColor3=library.OutlineColor,
            Size=UDim2.fromOffset(width,height),ZIndex=100,Parent=parent})
        library:AddToRegistry(frame,{BackgroundColor3="MainColor",BorderColor3="OutlineColor"},true)
        local accent=library:Create("Frame",{BackgroundColor3=library.AccentColor,BorderSizePixel=0,
            Size=UDim2.new(1,0,0,2),ZIndex=101,Parent=frame})
        library:AddToRegistry(accent,{BackgroundColor3="AccentColor"},true)
        local label=library:CreateLabel({Text=title,TextSize=14,Font=library.Font,
            BackgroundTransparency=1,Position=UDim2.fromOffset(6,3),Size=UDim2.new(1,-12,0,20),
            TextXAlignment=Enum.TextXAlignment.Left,ZIndex=102,Parent=frame})
        return frame,label,accent
    end
    function library:CreatePreviewPanel(parent,title)
        local frame,label,accent=panel(parent,title,250,380)
        local stroke=self:Create("UIStroke",{Color=self.OutlineColor,Thickness=1,Parent=frame})
        self:AddToRegistry(stroke,{Color="OutlineColor"},true)
        -- The preview belongs to the backend's GUI, outside Linoria.ScreenGui.
        frame.Destroying:Connect(function()
            for _,object in ipairs({frame,label,accent,stroke})do self:RemoveFromRegistry(object)end
        end)
        return {Frame=frame,Title=label,Stroke=stroke}
    end
    function library:InitializeOverlays(api)
        local players=game:GetService("Players")
        local run=game:GetService("RunService")
        self.Watermark.Position=UDim2.fromOffset(14,16)
        self.KeybindFrame.AnchorPoint=Vector2.new(0,0)
        self.KeybindFrame.Position=UDim2.fromOffset(14,62)
        local title
        activePanel,title=panel(self.ScreenGui,"Active features",210,26)
        activePanel.Position=UDim2.fromOffset(244,62)
        self:MakeDraggable(activePanel)
        local rows=self:CreateLabel({Text="",TextSize=13,Font=self.Font,BackgroundTransparency=1,
            Position=UDim2.fromOffset(6,26),Size=UDim2.new(1,-12,0,0),
            TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,
            ZIndex=102,Parent=activePanel})
        self.ActiveFeaturesFrame=activePanel
        local signature
        local function refresh()
            local names={}
            for name,module in pairs(api.Modules or {})do
                if module.Enabled and not module.HideEnabled and name~="Interface"then names[#names+1]=name end
            end
            table.sort(names)
            local text=table.concat(names,"\n")
            if text==signature then return end
            signature=text
            rows.Text=text~="" and text or "No active features"
            local height=math.max(1,#names)*18
            rows.Size=UDim2.new(1,-12,0,height)
            activePanel.Size=UDim2.fromOffset(210,32+height)
        end
        for kind in pairs(visibility)do self:SetOverlayVisibility(kind,UI.cfg["PlexShow"..kind]~=false)end
        self:SetWatermark("Zone | Rivals")
        self:SetWatermarkVisibility(visibility.Watermark)
        local frames,elapsed=0,0
        api:Clean(run.Heartbeat:Connect(function(dt)
            frames+=1;elapsed+=dt
            if elapsed<0.5 then return end
            local fps=math.floor(frames/elapsed+0.5)
            frames,elapsed=0,0
            if not visibility.Watermark then return end
            local ping=0
            pcall(function()ping=math.floor(players.LocalPlayer:GetNetworkPing()*1000+0.5)end)
            self:SetWatermark(string.format("Zone | Rivals | %d fps | %d ms | %s",fps,ping,os.date("%H:%M")))
        end))
        refresh()
        return refresh
    end
end

