-- Zone-only Plex control registration bridge.
local context=... or {}
local compatibility=assert(loadstring(compatibilitySource,"ZoneCompatibility"))(context)
local UI=compatibility.NativeUI
local library=assert(loadstring(vendorSource,"ZoneLinoria"))()
library.Toggles,library.Options=getgenv().Toggles,getgenv().Options
local themeManager=assert(loadstring(themeSource,"ZoneThemes"))()
local manager=compatibility.SaveManager
local events,connections={},{}
local alive,window=true,nil
local menu={subs={},pages={},activeTab="",activeSub=""}
local directToggles={}
library.NativeUI,library.NativeMenu=UI,menu
library.SaveManager,library.ThemeManager=manager,themeManager
library.FrontendName,library.UIFrontend="linoria","linoria"
library.ScreenGui.Name="ZoneRivalsLinoria"
library.ScreenGui.ResetOnSpawn=false
library.ScreenGui.DisplayOrder=100000
library.Font=Enum.Font.Code
UI.publicVersion="Linoria"
if Font then
    local font=Font.fromEnum(library.Font)
    UI.F={body=font,medium=font,semibold=font,bold=font}
end
themeManager:SetLibrary(library)
function library:OnEvent(name)
    if not events[name] then events[name]=Instance.new("BindableEvent") end
    return events[name].Event
end
local function fire(name,...)
    if events[name] then events[name]:Fire(...) end
end
function library:AttemptSave() manager:ScheduleAutoSave() end
local function palette()
    local c=UI.C
    c.text,c.bg,c.surface,c.card,c.pop=library.FontColor,library.BackgroundColor,library.MainColor,library.MainColor,library.BackgroundColor
    c.accent,c.accent2,c.edge,c.hairline=library.AccentColor,library.AccentColor,library.OutlineColor,library.OutlineColor
    c.dim,c.muted,c.faint=c.text:Lerp(c.bg,0.2),c.text:Lerp(c.bg,0.4),c.text:Lerp(c.bg,0.65)
    for _,callback in ipairs(UI.themeListeners or {})do
        task.defer(function()if alive then pcall(callback,c,"Linoria")end end)
    end
end
local updateColors=library.UpdateColorsUsingRegistry
function library:UpdateColorsUsingRegistry(...) updateColors(self,...);palette() end
palette()
local wrapGroup, wrapOption
wrapOption = function(object, id, definition)
    if not object or object.PlexWrapped then return object end
    object.PlexWrapped = true
    if id then compatibility:RegisterExternalOption(id,object) end
    if object.Type == "KeyPicker" then
        local originalSet, originalState = object.SetValue, object.GetState
        object.HandlesInput = false
        object.ModeChanged = function(mode)
            if definition and definition.ModeCallback then definition.ModeCallback(mode) end
        end
        if id=="MenuKeybind" then library.ToggleKeybind=object end
        function object:SetValue(value)
            local key, mode = value, self.Mode
            if type(value)=="table" then key,mode = value[1] or value.key,value[2] or value.mode or mode end
            if typeof(key)=="EnumItem" then key=key.Name end
            if mode=="Never" then mode="None" end
            key = tostring(key or "...")
            key = ({MouseButton1="MB1",MouseButton2="MB2",MouseButton3="MB3"})[key] or key
            if key=="None" or key=="Unknown" or key=="" then key="..." end
            originalSet(self,{key,mode})
            if definition and definition.Callback then definition.Callback(key) end
        end
        function object:SetMode(mode)
            self:SetValue({self.Value,mode})
            if definition and definition.ModeCallback then definition.ModeCallback(mode) end
        end
        function object:GetState()
            if self.Mode=="None" or self.Mode=="Never" or self.Value=="..." then return false end
            if self.Mode=="Hold" and self.Value~="MB1" and self.Value~="MB2" then
                local ok,key=pcall(function() return Enum.KeyCode[self.Value] end)
                if not ok or not key then return false end
            end
            return originalState(self)
        end
    end
    for _, method in ipairs({"AddColorPicker","AddKeyPicker"}) do
        local original = object[method]
        if original then
            object[method] = function(self, optionId, config)
                config = config or {}
                local changed = config.Callback
                if method=="AddKeyPicker" then
                    config = table.clone(config)
                    config.SyncToggleState = false
                    config.NoUI = optionId=="MenuKeybind"
                    config.Modes = {"None","Toggle","Hold","Always"}
                    config.Default = (config.Default=="None" or not config.Default) and "..." or config.Default
                    config.Callback = function() end
                    config.ChangedCallback = function()
                        local picker=library.Options[optionId]
                        if picker and changed then changed(picker.Value) end
                    end
                end
                local result = original(self,optionId,config)
                local option=library.Options[optionId]
                wrapOption(option,optionId,method=="AddKeyPicker" and {Callback=changed,ModeCallback=config.ModeCallback} or config)
                return result
            end
        end
    end
    return object
end
wrapGroup = function(group)
    if group.PlexWrapped then return group end
    group.PlexWrapped = true
    group.Native = {}
    function group.Native:custom(height, name)
        local row = Instance.new("Frame")
        row.Name = name or "CustomControl"
        row.BackgroundTransparency = 1
        row.Size = UDim2.new(1,-4,0,height)
        row.Parent = group.Container
        group:Resize()
        return row
    end
    for _, method in ipairs({"AddToggle","AddSlider","AddDropdown","AddInput"}) do
        local original = group[method]
        group[method] = function(self,id,definition)
            definition=table.clone(definition or {})
            if method=="AddSlider" then definition.Rounding=definition.Rounding or 0 end
            if method=="AddDropdown" and definition.Default==nil then definition.AllowNull=true end
            if method=="AddDropdown" and definition.Multi and type(definition.Default)=="table" then
                local defaults={}
                for key,value in pairs(definition.Default)do
                    if type(key)=="number" then defaults[#defaults+1]=value
                    elseif value==true then defaults[#defaults+1]=key end
                end
                definition.Default=defaults
            end
            local result=original(self,id,definition)
            return wrapOption(library.Toggles[id] or library.Options[id] or result,id,definition)
        end
    end
    local addLabel=group.AddLabel
    function group:AddLabel(...)
        return wrapOption(addLabel(self,...),nil)
    end
    function group:AddColorPicker(id,definition)
        self:AddLabel(definition.Title or definition.Text or "Color"):AddColorPicker(id,definition)
        return library.Options[id]
    end
    function group:AddKeyPicker(id,definition)
        self:AddLabel(definition.Text or "Keybind"):AddKeyPicker(id,definition)
        return library.Options[id]
    end
    return group
end

local serial=0
local function nextId()
    serial+=1
    return "ZoneControl_"..serial
end
local originalGroup=UI.group
-- Cosmetic panels use the same native Linoria controls as feature cards.
function UI.group(parent,title,params)
    if type(parent)~="table" or not parent.ZoneColumn then return originalGroup(parent,title,params) end
    local tab=parent.Tab
    local group=wrapGroup(parent.Side=="L" and tab:AddLeftGroupbox(title) or tab:AddRightGroupbox(title))
    local g={frame=group.Container,Native=group.Native}
    function g:AddLabel(text)
        local label=group:AddLabel(tostring(text),true)
        return {SetText=function(_,value)label:SetText(tostring(value))end}
    end
    function g:note(text)return self:AddLabel(text)end
    function g:button(text,callback)return group:AddButton({Text=text,Func=callback})end
    function g:toggle(text,key,params)
        params=params or {}
        local toggle=group:AddToggle(key,{Text=text,Default=UI.cfg[key]==true,Callback=function(value)
            UI.cfg[key]=value
            if params.onChange then params.onChange(value) end
        end})
        directToggles[key]=toggle
        return toggle
    end
    function g:field(text,placeholder,default)
        local option=group:AddInput(nextId(),{Text=text,Placeholder=placeholder,Default=tostring(default or ""),Finished=false})
        return setmetatable({}, {__index=function(_,key)if key=="Text"then return option.Value end end,
            __newindex=function(_,key,value)if key=="Text"then option:SetValue(tostring(value))end end})
    end
    function g:slider(text,min,max,default)
        return group:AddSlider(nextId(),{Text=text,Min=min,Max=max,Default=default,Rounding=0})
    end
    local function list(text,params,multi)
        params=params or {}
        local busy=false
        local query,page="",1
        local labels,ids={},{}
        local dropdown
        local refresh
        group:AddInput(nextId(),{Text="Search "..text,Default="",Finished=false,Callback=function(value)
            query=tostring(value):lower();page=1
            if refresh then refresh()end
        end})
        dropdown=group:AddDropdown(nextId(),{Text=text,Values={},Multi=multi,AllowNull=true,Callback=function(value)
            if busy or not params.onSelect then return end
            if multi then
                local chosen=params.selected and table.clone(params.selected() or {}) or {}
                for label,id in pairs(ids)do chosen[id]=value[label]==true or nil end
                params.onSelect(chosen)
            elseif ids[value]~=nil then params.onSelect(ids[value]) end
        end})
        local count=group:AddLabel("")
        refresh=function()
            busy=true
            local ok,err=pcall(function()
                local items={}
                for _,item in ipairs(params.items and params.items() or {})do
                    if query=="" or tostring(item.label or item.id):lower():find(query,1,true) then items[#items+1]=item end
                end
                local size=params.pageSize or 30
                local pages=math.max(1,math.ceil(#items/size))
                page=math.clamp(page,1,pages)
                labels,ids={},{}
                local selected=params.selected and params.selected()
                local value=multi and {} or nil
                for index=(page-1)*size+1,math.min(page*size,#items)do
                    local item=items[index]
                    local label=tostring(item.label or item.id)
                    if ids[label]~=nil then label=label.." ["..tostring(item.id).."]" end
                    labels[#labels+1]=label;ids[label]=item.id
                    if multi then
                        if type(selected)=="table" and selected[item.id] then value[label]=true end
                    elseif selected==item.id then value=label end
                end
                dropdown:SetValues(labels)
                dropdown:SetValue(value)
                count:SetText("Page "..page.." / "..pages.." · "..#items.." items")
            end)
            busy=false
            if not ok then warn("[Zone Linoria] Catalog refresh: "..tostring(err))end
        end
        group:AddButton({Text="Previous page",Func=function()page=math.max(1,page-1);refresh()end})
        group:AddButton({Text="Next page",Func=function()page+=1;refresh()end})
        refresh()
        return refresh
    end
    function g:list(text,params)return list(text,params,false)end
    function g:multilist(text,params)return list(text,params,true)end
    return g
end

function menu.refreshToggles()
    for id,object in pairs(directToggles)do
        if UI.cfg[id]~=nil and object.Value~=(UI.cfg[id]==true)then object:SetValue(UI.cfg[id]==true)end
    end
end
menu.syncNow=menu.refreshToggles
function menu.showTab(name)
    local tab=menu.pages[name]
    if tab then tab:ShowTab()end
end
function menu.showSub(page,sub)menu.activeSub=sub;menu.showTab(page)end
function library:IsPreviewTabActive()return menu.activeTab=="esp"end
local createWindow=library.CreateWindow
function library:CreateWindow(config)
    config=table.clone(config or {})
    config.Title="Zone · Rivals"
    config.Size=UDim2.fromOffset(960,650)
    config.MenuFadeTime=0
    config.AutoShow=false
    window=createWindow(self,config)
    window.PreviewAnchor=window.Holder
    self.Holder=window.Holder
    UI.root,UI.popupHost=window.Holder,window.Holder
    self.Opened=false
    local toggle=self.Toggle
    function self:Toggle()
        -- Upstream's keyboard listener spawns Library.Toggle without a receiver.
        toggle(library)
        library.Opened=window.Holder.Visible
        fire("VisibilityChanged",library.Opened)
    end
    local addTab=window.AddTab
    function window:AddTab(name)
        local tab=addTab(self,name)
        menu.pages[name]=tab
        menu.subs[name]={}
        for _,sub in ipairs(UI.PAGE_SUBTABS[name] or {"general"})do
            menu.subs[name][sub]={L={ZoneColumn=true,Tab=tab,Side="L"},R={ZoneColumn=true,Tab=tab,Side="R"}}
        end
        local show=tab.ShowTab
        function tab:ShowTab()
            show(self);menu.activeTab=name
            fire("TabChanged",name)
        end
        local addGroup=tab.AddGroupbox
        function tab:AddGroupbox(info)return wrapGroup(addGroup(self,info))end
        local addTabbox=tab.AddTabbox
        function tab:AddTabbox(info)
            local box=addTabbox(self,info)
            local add=box.AddTab
            function box:AddTab(title)return wrapGroup(add(self,title))end
            return box
        end
        if menu.activeTab=="" then menu.activeTab=name end
        if name=="settings" then
            local overlayGroup=tab:AddRightGroupbox("Overlays")
            for _,entry in ipairs({{"Watermark","Show watermark"},{"KeybindList","Show keybind list"},{"ActiveFeatures","Show active features"}})do
                local kind,text=entry[1],entry[2]
                overlayGroup:AddToggle("PlexShow"..kind,{Text=text,Default=true,Callback=function(value)
                    UI.cfg["PlexShow"..kind]=value
                    if library.SetOverlayVisibility then library:SetOverlayVisibility(kind,value)end
                end})
            end
        end
        return tab
    end
    self.ToggleKeybind={Type="KeyPicker",Value="Insert"}
    return window
end
function library:SetVisible(value)
    if self.Opened~=(value==true) then self:Toggle()end
end
compatibility.SetVisible=function(_,value)library:SetVisible(value)end
compatibility.Notify=function(_,value,duration)return library:Notify(value,duration)end
local notify=library.Notify
