    do
        local tpHandoffStarted = false
        local submittedStages={}
        mainapi:Clean(LocalPlayer.OnTeleport:Connect(function(state)
            if state == Enum.TeleportState.Failed then
                tpHandoffStarted=false;table.clear(submittedStages)
                if LionSaveManager then LionSaveManager.TPHandlerArmed=false end
                return
            end
            if state~=Enum.TeleportState.Started and state~=Enum.TeleportState.WaitingForServer
                and state~=Enum.TeleportState.InProgress then return end
            if submittedStages[state] or not LionSaveManager or not LionSaveManager.PrepareTPHandlerHandoff then return end
            local ok,prepared=pcall(function()
                -- Some executor queues are reset later in the transition. Requeue
                -- once per distinct stage; destination boot tokens deduplicate.
                if not LionSaveManager:ArmTPHandler(true) then return false end
                submittedStages[state]=true
                if not tpHandoffStarted then
                    tpHandoffStarted=LionSaveManager:PrepareTPHandlerHandoff()==true
                end
                return tpHandoffStarted
            end)
            local success=ok and prepared==true
            if type(writefile)=="function" then pcall(writefile,"Overlay/tphandler_arm_status.txt",
                (success and "queued" or "failed").."|"..tostring(state).."|"..tostring(getgenv().__PlexBuildId)) end
            if not success then
                submittedStages[state]=nil;LionSaveManager.TPHandlerArmed=false
                warn("[Plex TPHandler] Teleport handoff failed; next stage may retry: "..tostring(prepared))
            end
        end))
    end

