                function Input:Load(tab)
                    if tab and tab.Value ~= nil then
                        Input.Value = tab.Value
                        if Options and Options[id] then Options[id]:SetValue(tostring(tab.Value)) end
                    end
                end
                Module.Settings[Input.Name] = Input
                return Input
            end

            function Module.AddKeybind(self, arg)
                local optionGroup = getOptionGroup(arg)
                local id = lionId("Key", Module.Name, arg["Name"] or arg["Text"] or "Keybind")
                local initialized = false
                local Keybind = {
                    Name = arg["Name"] or arg["Text"] or "keybind",
                    Value = tostring(arg["Default"] or arg["Value"] or "None"),
                    Mode = arg["Mode"] or "Hold",
                    Function = arg["Function"] or arg["function"] or function() end,
                }
                local lionOption = optionGroup:AddKeyPicker(id, {
                    Text = arg["Text"] or Keybind.Name,
                    Default = Keybind.Value,
                    Mode = Keybind.Mode,
                    Callback = function(value)
                        Keybind.Value = tostring(value or "None")
                        if initialized then
                            task.spawn(function() pcall(Keybind.Function, Keybind.Value, Keybind.Mode) end)
                        end
                        saveFeature()
                    end,
                    ModeCallback = function(mode)
                        Keybind.Mode = mode
                        if initialized then
                            task.spawn(function() pcall(Keybind.Function, Keybind.Value, Keybind.Mode) end)
                        end
                        saveFeature()
                    end,
                })
                Keybind._LionOption = lionOption
                initialized = true

                function Keybind:GetState()
                    return lionOption and lionOption.GetState and lionOption:GetState() or false
                end
                function Keybind:Save(tab)
                    tab[Keybind.Name] = {Value = Keybind.Value, Mode = Keybind.Mode}
                end
                function Keybind:Load(tab)
                    if not tab then return end
                    if tab.Value ~= nil then
                        Keybind.Value = tostring(tab.Value)
                        if lionOption and lionOption.SetValue then lionOption:SetValue(Keybind.Value) end
                    end
                    if tab.Mode ~= nil then
                        Keybind.Mode = tostring(tab.Mode)
                        if lionOption and lionOption.SetMode then lionOption:SetMode(Keybind.Mode) end
                    end
                end

                Module.Settings[Keybind.Name] = Keybind
                return Keybind
            end

            function Module.AddCurveEditor(self, arg)
                local optionGroup = getOptionGroup(arg)
                local source = type(arg["Default"]) == "table" and arg["Default"] or {0, 0.14, 0.29, 0.43, 0.57, 0.71, 0.86, 1}
                local Curve = {
                    Name = arg["Name"] or "curve",
                    Value = {},
                    Function = arg["Function"] or arg["function"] or function() end,
                }
                local curveBlue = Color3.fromRGB(73, 145, 255)
                for i, value in ipairs(source) do
                    Curve.Value[i] = math.clamp(tonumber(value) or 0, 0, 1)
                end
                while #Curve.Value < 2 do
                    table.insert(Curve.Value, #Curve.Value == 0 and 0 or 1)
                end

                local height = math.max(138, tonumber(arg["Height"]) or 166)
                local row = optionGroup.Native:custom(height, arg["Text"] or Curve.Name)
                row.ClipsDescendants = false

                local title = Instance.new("TextLabel")
                title.Name = "CurveTitle"
                title.BackgroundTransparency = 1
                title.Position = UDim2.fromOffset(1, 0)
                title.Size = UDim2.new(0.58, 0, 0, 18)
                title.Font = Enum.Font.GothamMedium
                title.Text = string.lower(arg["Text"] or Curve.Name)
                title.TextSize = 12
                title.TextColor3 = Color3.fromRGB(205, 208, 216)
                title.TextXAlignment = Enum.TextXAlignment.Left
                title.Parent = row

                local hint = Instance.new("TextLabel")
                hint.Name = "CurveHint"
                hint.BackgroundTransparency = 1
                hint.AnchorPoint = Vector2.new(1, 0)
                hint.Position = UDim2.new(1, -2, 0, 0)
                hint.Size = UDim2.new(0.38, 0, 0, 18)
                hint.Font = Enum.Font.Gotham
                hint.Text = "drag points"
                hint.TextSize = 10
                hint.TextColor3 = Color3.fromRGB(112, 116, 128)
                hint.TextXAlignment = Enum.TextXAlignment.Right
                hint.Parent = row

                local shell = Instance.new("Frame")
                shell.Name = "CurveShell"
                shell.Position = UDim2.fromOffset(0, 22)
                shell.Size = UDim2.new(1, 0, 1, -26)
                shell.BackgroundColor3 = Color3.fromRGB(11, 11, 15)
                shell.BorderSizePixel = 0
                shell.Parent = row
                local shellCorner = Instance.new("UICorner")
                shellCorner.CornerRadius = UDim.new(0, 7)
                shellCorner.Parent = shell
                local shellStroke = Instance.new("UIStroke")
                shellStroke.Color = Color3.fromRGB(42, 43, 51)
                shellStroke.Transparency = 0.2
                shellStroke.Thickness = 1
                shellStroke.Parent = shell

                local graph = Instance.new("Frame")
                graph.Name = "CurveGraph"
                graph.Position = UDim2.fromOffset(6, 6)
                graph.Size = UDim2.new(1, -12, 1, -12)
                graph.BackgroundColor3 = Color3.fromRGB(15, 15, 20)
                graph.BorderSizePixel = 0
                graph.ClipsDescendants = true
                graph.Parent = shell
                local graphCorner = Instance.new("UICorner")
                graphCorner.CornerRadius = UDim.new(0, 5)
                graphCorner.Parent = graph
                local graphStroke = Instance.new("UIStroke")
                graphStroke.Color = Color3.fromRGB(45, 46, 55)
                graphStroke.Transparency = 0.5
                graphStroke.Thickness = 1
                graphStroke.Parent = graph

                for i = 1, 3 do
                    local h = Instance.new("Frame")
                    h.Name = "GridH"
                    h.BorderSizePixel = 0
                    h.BackgroundColor3 = Color3.fromRGB(51, 52, 61)
                    h.BackgroundTransparency = 0.66
                    h.Size = UDim2.new(1, 0, 0, 1)
                    h.Position = UDim2.fromScale(0, i / 4)
                    h.Parent = graph
                end
                for i = 1, 7 do
                    local v = Instance.new("Frame")
                    v.Name = "GridV"
                    v.BorderSizePixel = 0
                    v.BackgroundColor3 = Color3.fromRGB(51, 52, 61)
                    v.BackgroundTransparency = 0.72
                    v.Size = UDim2.new(0, 1, 1, 0)
                    v.Position = UDim2.fromScale(i / 8, 0)
                    v.Parent = graph
                end

                local handles, halos, segments, glows = {}, {}, {}, {}
                local dragging
                local dragChanged = false
                local inputService = game:GetService("UserInputService")

                local function makeSegment(name, thickness, transparency, z)
                    local line = Instance.new("Frame")
                    line.Name = name
                    -- Rotate around the center. Anchoring at the left edge makes Roblox
                    -- rotate the frame around the wrong pivot and creates detached/broken
                    -- looking line pieces.
                    line.AnchorPoint = Vector2.new(0.5, 0.5)
                    line.BorderSizePixel = 0
                    line.BackgroundColor3 = curveBlue
                    line.BackgroundTransparency = transparency
                    line.Size = UDim2.fromOffset(0, thickness)
                    line.ZIndex = z
                    line.Parent = graph
                    local lc = Instance.new("UICorner")
                    lc.CornerRadius = UDim.new(1, 0)
                    lc.Parent = line
                    return line
                end

                for i = 1, #Curve.Value - 1 do
                    glows[i] = makeSegment("CurveGlow", 5, 0.8, 2)
                    segments[i] = makeSegment("CurveLine", 2, 0, 3)
                end

                local redrawQueued = false
                local function redraw()
                    local size = graph.AbsoluteSize
                    if size.X <= 1 or size.Y <= 1 then
                        if not redrawQueued then
                            redrawQueued = true
                            task.defer(function()
                                redrawQueued = false
                                if graph.Parent then redraw() end
                            end)
                        end
                        return
                    end
                    local count = #Curve.Value
                    local edgePad = 7
                    local usableW = math.max(size.X - edgePad * 2, 1)
                    local usableH = math.max(size.Y - edgePad * 2, 1)
                    local points = table.create(count)

                    for i = 1, count do
                        local xAlpha = count > 1 and (i - 1) / (count - 1) or 0
                        local yAlpha = 1 - math.clamp(Curve.Value[i], 0, 1)
                        local x = edgePad + xAlpha * usableW
                        local y = edgePad + yAlpha * usableH
                        points[i] = Vector2.new(x, y)

                        local handle = handles[i]
                        if handle then handle.Position = UDim2.fromOffset(x, y) end
                    end

                    for i = 1, count - 1 do
                        local a = points[i]
                        local b = points[i + 1]
                        local delta = b - a
                        local length = delta.Magnitude
                        local midpoint = (a + b) * 0.5
                        local rotation = math.deg(math.atan2(delta.Y, delta.X))

                        local glow = glows[i]
                        glow.Position = UDim2.fromOffset(midpoint.X, midpoint.Y)
                        glow.Size = UDim2.fromOffset(length, 5)
                        glow.Rotation = rotation

                        local line = segments[i]
                        line.Position = UDim2.fromOffset(midpoint.X, midpoint.Y)
                        line.Size = UDim2.fromOffset(length, 2)
                        line.Rotation = rotation
                    end
                end

                for i = 1, #Curve.Value do
                    local halo = Instance.new("Frame")
                    halo.Name = "CurvePointHalo_" .. tostring(i)
                    halo.AnchorPoint = Vector2.new(0.5, 0.5)
                    halo.Size = UDim2.fromOffset(17, 17)
                    halo.BackgroundColor3 = curveBlue
                    halo.BackgroundTransparency = 0.84
                    halo.BorderSizePixel = 0
                    halo.ZIndex = 4
                    halo.Parent = graph
                    local haloCorner = Instance.new("UICorner")
                    haloCorner.CornerRadius = UDim.new(1, 0)
                    haloCorner.Parent = halo
                    halos[i] = halo

                    local handle = Instance.new("TextButton")
                    handle.Name = "CurvePoint_" .. tostring(i)
                    handle.Text = ""
                    handle.AutoButtonColor = false
                    handle.AnchorPoint = Vector2.new(0.5, 0.5)
                    handle.Size = UDim2.fromOffset(9, 9)
                    handle.BackgroundColor3 = (curveBlue):Lerp(Color3.new(1,1,1), 0.16)
                    handle.BorderSizePixel = 0
                    handle.ZIndex = 5
                    handle.Parent = graph
                    local hc = Instance.new("UICorner")
                    hc.CornerRadius = UDim.new(1, 0)
                    hc.Parent = handle
                    local hs = Instance.new("UIStroke")
                    hs.Color = curveBlue
                    hs.Transparency = 0
                    hs.Thickness = 1
                    hs.Parent = handle
                    handles[i] = handle
                    handle:GetPropertyChangedSignal("Position"):Connect(function()
                        if halos[i] then halos[i].Position = handle.Position end
                    end)
                    handle.MouseEnter:Connect(function()
                        handle.Size = UDim2.fromOffset(11, 11)
                        halo.Size = UDim2.fromOffset(20, 20)
                        halo.BackgroundTransparency = 0.76
                    end)
                    handle.MouseLeave:Connect(function()
                        if dragging ~= i then
                            handle.Size = UDim2.fromOffset(9, 9)
                            halo.Size = UDim2.fromOffset(17, 17)
                            halo.BackgroundTransparency = 0.84
                        end
                    end)
                    handle.InputBegan:Connect(function(input)
                        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                            dragging = i
                            dragChanged = false
                            handle.Size = UDim2.fromOffset(12, 12)
                            halo.Size = UDim2.fromOffset(22, 22)
                            halo.BackgroundTransparency = 0.7
                        end
                    end)
                end

                local moveConnection = inputService.InputChanged:Connect(function(input)
                    if not dragging then return end
                    if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
                    local size = graph.AbsoluteSize
                    local edgePad = 7
                    if size.Y <= edgePad * 2 then return end
                    local localY = math.clamp(
                        input.Position.Y - graph.AbsolutePosition.Y,
                        edgePad,
                        size.Y - edgePad
                    )
                    Curve.Value[dragging] = math.clamp(
                        1 - ((localY - edgePad) / math.max(size.Y - edgePad * 2, 1)),
                        0,
                        1
                    )
                    dragChanged = true
                    redraw()
                    task.spawn(function() pcall(Curve.Function, table.clone(Curve.Value), true) end)
                end)

                local endConnection = inputService.InputEnded:Connect(function(input)
                    if not dragging then return end
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        local finished = dragging
                        dragging = nil
                        local handle = handles[finished]
                        local halo = halos[finished]
                        if handle then handle.Size = UDim2.fromOffset(9, 9) end
                        if halo then
                            halo.Size = UDim2.fromOffset(17, 17)
                            halo.BackgroundTransparency = 0.84
                        end
                        if dragChanged then
                            task.spawn(function() pcall(Curve.Function, table.clone(Curve.Value), false) end)
                            saveFeature()
                        end
                        dragChanged = false
                    end
                end)

                local resizeConnection = graph:GetPropertyChangedSignal("AbsoluteSize"):Connect(redraw)
                row.Destroying:Connect(function()
                    pcall(function() moveConnection:Disconnect() end)
                    pcall(function() endConnection:Disconnect() end)
                    pcall(function() resizeConnection:Disconnect() end)
                end)

                function Curve:SetValue(values, silent)
                    if type(values) ~= "table" then return end
                    for i = 1, #Curve.Value do
                        if values[i] ~= nil then
                            Curve.Value[i] = math.clamp(tonumber(values[i]) or Curve.Value[i], 0, 1)
                        end
                    end
                    redraw()
                    if not silent then
                        task.spawn(function() pcall(Curve.Function, table.clone(Curve.Value), false) end)
                        saveFeature()
                    end
                end
                function Curve:Reset()
                    Curve:SetValue(source)
                end
                function Curve:Save(tab)
                    tab[Curve.Name] = {Value = table.clone(Curve.Value)}
                end
                function Curve:Load(tab)
                    if tab and type(tab.Value) == "table" then Curve:SetValue(tab.Value, true) end
                end

                Curve.Frame = row
                Curve.Graph = graph
                Module.Settings[Curve.Name] = Curve
                task.defer(redraw)
                return Curve
            end

            function Module.AddLabel(self, arg)
                local optionGroup = getOptionGroup(arg)
                local text = type(arg) == "table" and (arg["Text"] or "") or tostring(arg or "")
                return optionGroup:AddLabel(text)
            end

            function Module.AddColorPicker(self, arg)
                local id = lionId("Color", Module.Name, arg["Name"] or arg["Text"] or "Color")
                local initialized = false
                local Color = {
                    Name = arg["Name"] or arg["Text"] or "Color",
                    Frame = Instance.new("Frame"),
                    Value = arg["Default"] or arg["Value"] or Color3.fromRGB(255, 255, 255),
                    Transparency = arg["Transparency"],
                    Function = arg["Function"] or arg["function"] or function() end,
                }

                local label = group:AddLabel(arg["Text"] or Color.Name)
                if label and label.AddColorPicker then
                    label:AddColorPicker(id, {
                        Default = Color.Value,
                        Title = arg["Title"] or Color.Name,
                        Transparency = Color.Transparency,
                        Callback = function(value, transparency)
                            Color.Value = value
                            Color.Transparency = transparency ~= nil and transparency or Color.Transparency
                            if initialized then
                                task.spawn(function()
                                    pcall(Color.Function, value)
                                end)
                            end
                            saveFeature()
                        end,
                    })
                end
                initialized = true

                function Color:Save(tab)
                    tab[Color.Name] = {
                        R = Color.Value.R,
                        G = Color.Value.G,
                        B = Color.Value.B,
                        Transparency = Color.Transparency,
                    }
                end

                function Color:Load(tab)
                    if tab and tab.R and tab.G and tab.B then
                        Color.Value = Color3.new(tab.R, tab.G, tab.B)
                        Color.Transparency = tab.Transparency
                        if Options and Options[id] then
                            Options[id]:SetValueRGB(Color.Value)
                        end
                    end
                end

                Module.Settings[Color.Name] = Color
                return Color
            end

            function Module.AddButton(self, arg)
                local text = typeof(arg) == "table" and (arg["Text"] or arg["Name"] or "button") or tostring(arg)
                local func = typeof(arg) == "table" and (arg["Func"] or arg["Function"] or arg["function"] or function() end) or function() end
                return group:AddButton({ Text = text, Func = func })
            end

            mainapi.Modules[moduleName] = Module
            Catalog.Modules[moduleName] = Module
            return Module
        end

        mainapi.Catalogs[Catalog.Name] = Catalog
        return Catalog
    end

    local MenuGroup = LionTabs.settings:AddLeftGroupbox("settings")
    MenuGroup:AddButton({ Text = "Unload", Func = function()
        if type(mainapi.Uninject) == "function" then mainapi:Uninject() end
        if LionLibrary then LionLibrary:Unload() end
    end })
    MenuGroup:AddLabel("Menu bind"):AddKeyPicker("MenuKeybind", {
        Default = KeybindData.Menu or "End",
        NoUI = true,
        Text = "Menu keybind",
        Callback = function(key)
            KeybindData.Menu = typeof(key) == "EnumItem" and key.Name or tostring(key or "End")
            SaveKeybinds()
        end,
    })
    LionLibrary.ToggleKeybind = Options.MenuKeybind
    -- The window stays closed while feature modules and saved settings initialize.
    mainapi.ClickGuiStatus = false
    setMenuBlur(false)
    if LionWindow and LionWindow.Holder then
        mainapi:Clean(LionWindow.Holder:GetPropertyChangedSignal("Visible"):Connect(function()
            local open=LionWindow.Holder.Visible==true
            if open==mainapi.ClickGuiStatus then return end
            mainapi.ClickGuiStatus=open
            setMenuBlur(open)
            if not open and mainapi.BindingBusy and mainapi.ActiveBindCancel then mainapi.ActiveBindCancel() end
            if mainapi.SetMenuInputBlocked then mainapi:SetMenuInputBlocked(open) end
        end))
    end

