-- BEGIN PLEX SOURCE: shared/000_combat_input.lua
-- Shared input routing. Controller lookup is lazy and never scans game registries.
do (function()
    local controllers, nextLookup = {}, 0
    local pendingShot
    local windowFocused = true

    function mainapi:IsTouchInput()
        return UserInputService.TouchEnabled and (not UserInputService.MouseEnabled
            or UserInputService:GetLastInputType() == Enum.UserInputType.Touch)
    end

    function mainapi:ResolveCombatMode(mode)
        if mode == "Camera" or mode == "Mouse" then return mode end
        return self:IsTouchInput() and "Camera" or "Mouse"
    end

    function mainapi:GetCombatInputController(name)
        if controllers[name] then return controllers[name] end
        local now = os.clock()
        if now < nextLookup then return nil end
        local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
        local folder = scripts and scripts:FindFirstChild("Controllers")
        local module = folder and folder:FindFirstChild(name)
        if module then
            local ok, result = pcall(require, module)
            if ok and type(result) == "table" then controllers[name] = result return result end
        end
        nextLookup = now + 1
    end

    function mainapi:GetCombatPointer(mode, camera)
        camera = camera or workspace.CurrentCamera
        if not camera then return Vector2.zero end
        -- Auto retains the desktop crosshair origin; only explicit Mouse follows the cursor.
        if mode == "Mouse" and not self:IsTouchInput() then
            local inset = GuiService:GetGuiInset()
            return UserInputService:GetMouseLocation() - inset
        end
        return camera.ViewportSize / 2
    end

    function mainapi:CanUseCombatInput(mode)
        if not windowFocused or self.Uninjecting or self.ClickGuiStatus or UserInputService:GetFocusedTextBox() then return false end
        local focus = isrbxactive or iswindowactive
        if not self:IsTouchInput() and type(focus) == "function" and not focus() then return false end
        if self:ResolveCombatMode(mode) == "Mouse" then
            return type(mousemoverel) == "function" and UserInputService.MouseBehavior ~= Enum.MouseBehavior.Default
        end
        local camera = self:GetCombatInputController("CameraController")
        return camera ~= nil and not camera.IsFrozen
    end

    function mainapi:MoveCombatCamera(position, fraction, xScale, yScale)
        local controller = self:GetCombatInputController("CameraController")
        local camera = workspace.CurrentCamera
        if not controller or not camera or controller.IsFrozen or type(controller.SetRotation) ~= "function" then return false end
        local direction = position - camera.CFrame.Position
        if direction.Magnitude < 0.001 or typeof(controller.Rotation) ~= "Vector2" then return false end
        -- Rivals SetRotation takes pitch/yaw radians; preserve its springs and touch controls.
        local pitch, yaw = CFrame.lookAt(camera.CFrame.Position, position):ToOrientation()
        local current = controller.Rotation
        local yawDelta = (yaw - current.Y + math.pi) % (2 * math.pi) - math.pi
        fraction = math.clamp(fraction or 1, 0, 1)
        controller:SetRotation(current + Vector2.new((pitch - current.X) * fraction * (xScale or 1),
            yawDelta * fraction * (yScale or 1)))
        return true
    end

    function mainapi:IsCombatInputDown(button)
        if UserInputService:IsMouseButtonPressed(button) then return true end
        local controls = self:GetCombatInputController("ControlsController")
        return controls and type(controls.IsInputDown) == "function" and controls:IsInputDown(button) == true or false
    end

    function mainapi:ReleaseCombatShot(owner)
        local shot = pendingShot
        if not shot or (owner and shot.Owner ~= owner) then return end
        pendingShot = nil
        -- Release the same fighter, including after an equip/respawn or module disable.
        pcall(shot.Fighter.Input, shot.Fighter, "FinishShooting")
    end

    function mainapi:FireCombatShot(mode, owner, fighter)
        if pendingShot or not windowFocused or self.Uninjecting or self.ClickGuiStatus or UserInputService:GetFocusedTextBox() then return false end
        local focus = isrbxactive or iswindowactive
        if not self:IsTouchInput() and type(focus) == "function" and not focus() then return false end
        if self:ResolveCombatMode(mode) == "Mouse" and type(mouse1click) == "function" then
            local ok = pcall(mouse1click)
            if ok then self:MarkCombatFire(0.12) end
            return ok
        end
        if not fighter then
            local controller = self:GetCombatInputController("FighterController")
            fighter = controller and controller.LocalFighter
        end
        if not fighter or not fighter.EquippedItem or type(fighter.Input) ~= "function" then return false end
        local shot = {Owner = owner, Fighter = fighter}
        pendingShot = shot
        -- ClientFighter.Input owns the native item action, animation and replication pipeline.
        local ok, result = pcall(fighter.Input, fighter, "StartShooting")
        if not ok or result == false then self:ReleaseCombatShot(owner) return false end
        self:MarkCombatFire(0.12)
        task.delay(0.05, function()
            if pendingShot == shot then self:ReleaseCombatShot(owner) end
        end)
        return true
    end

    mainapi:Clean(function() mainapi:ReleaseCombatShot() table.clear(controllers) end)
    mainapi:Clean(UserInputService.WindowFocused:Connect(function() windowFocused = true end))
    mainapi:Clean(UserInputService.WindowFocusReleased:Connect(function()
        windowFocused = false
        mainapi:ReleaseCombatShot()
    end))
end)() end

-- END PLEX SOURCE: shared/000_combat_input.lua
-- BEGIN PLEX SOURCE: shared/000_menu_input.lua
-- Menu ownership is separate from game UI focus: native Rivals input can
-- otherwise keep shooting while a custom ScreenGui is being clicked.
do
    local records = {}
    local bound, disposed = false, false
    local actionName = "PlexMenuGameplayInput"
    local function currentFighter()
        local controller = mainapi:GetCombatInputController("FighterController")
        return controller, controller and controller.LocalFighter
    end
    local function installGuard()
        local controller, fighter = currentFighter()
        local class = fighter and getmetatable(fighter)
        local owner = type(class)=="table" and (type(class.Input)=="function" and class or class.__index)
        if type(owner)~="table" or type(owner.Input)~="function" then return end
        for _,record in ipairs(records) do if record.Owner==owner then return record, fighter end end
        local record = {Owner=owner, Original=owner.Input}
        record.Wrapper = function(self, input, ...)
            if not disposed and self==controller.LocalFighter and (mainapi.MenuGameplayBlocked or mainapi.ClickGuiStatus
                or os.clock() < (mainapi.MenuInputBlockUntil or 0)) then return false end
            return record.Original(self,input,...)
        end
        owner.Input = record.Wrapper
        records[#records+1] = record
        return record, fighter
    end
    local function sink(_, _, input)
        if not mainapi.MenuGameplayBlocked then return Enum.ContextActionResult.Pass end
        local selected=input and (input.UserInputType==Enum.UserInputType.Keyboard and input.KeyCode or input.UserInputType)
        if selected and selected.Name==(KeybindData.Menu or "End") then return Enum.ContextActionResult.Pass end
        if input and input.UserInputType==Enum.UserInputType.Keyboard
            and (mainapi.BindingBusy or UserInputService:GetFocusedTextBox()) then return Enum.ContextActionResult.Pass end
        return Enum.ContextActionResult.Sink
    end
    function mainapi:SetMenuInputBlocked(open)
        if disposed then return end
        self.MenuGameplayBlocked=open==true
        if open then
            self.MenuInputBlockUntil=0
            self:ReleaseCombatShot()
            local record,fighter=installGuard()
            -- Gun releases stop an already-held shot/ADS. Releasing a throwable
            -- can itself throw it, so those commands stay blocked with the menu.
            local item=fighter and fighter.EquippedItem
            if record and item and item.Info and item.Info.Type=="Gun" then
                pcall(record.Original,fighter,"FinishShooting")
                pcall(record.Original,fighter,"FinishAiming")
            end
            if not bound then
                ContextService:BindActionAtPriority(actionName,sink,false,4000,
                    Enum.UserInputType.MouseButton1,Enum.UserInputType.MouseButton2,Enum.UserInputType.MouseButton3,
                    Enum.UserInputType.MouseWheel,Enum.KeyCode.W,Enum.KeyCode.A,Enum.KeyCode.S,Enum.KeyCode.D,
                    Enum.KeyCode.Space,Enum.KeyCode.LeftShift,Enum.KeyCode.LeftControl,Enum.KeyCode.R,
                    Enum.KeyCode.F,Enum.KeyCode.Q,Enum.KeyCode.E,Enum.KeyCode.G,Enum.KeyCode.V,
                    Enum.KeyCode.One,Enum.KeyCode.Two,Enum.KeyCode.Three,Enum.KeyCode.Four,Enum.KeyCode.Five)
                bound=true
            end
        else
            self.MenuInputBlockUntil=os.clock()+0.12
            if bound then ContextService:UnbindAction(actionName);bound=false end
        end
        if self.WakeIdleWorkers then self:WakeIdleWorkers() end
    end
    mainapi:Clean(LionLibrary:OnEvent("VisibilityChanged"):Connect(function(open) mainapi:SetMenuInputBlocked(open) end))
    mainapi:Clean(entitylib:GetEvent("LocalAdded"):Connect(function()
        if mainapi.MenuGameplayBlocked then installGuard() end
    end))
    mainapi:Clean(function()
        disposed=true
        if bound then ContextService:UnbindAction(actionName);bound=false end
        for i=#records,1,-1 do
            local record=records[i]
            if record.Owner.Input==record.Wrapper then record.Owner.Input=record.Original end
        end
        mainapi.MenuGameplayBlocked=false
        mainapi.MenuInputBlockUntil=nil
    end)
    if mainapi.ClickGuiStatus then mainapi:SetMenuInputBlocked(true) end
end

-- END PLEX SOURCE: shared/000_menu_input.lua
-- BEGIN PLEX SOURCE: shared/000_performance_flags.lua
-- Executor flag changes are action-driven and owned separately by each control.
do
    local records={}
    local flags={}
    mainapi.PerformanceFlags=flags
    local function api()
        local env=getgenv and getgenv() or _G
        local synApi=type(env.syn)=="table" and env.syn or {}
        return setflag or setfflag or set_fflag or env.setflag or env.setfflag or env.set_fflag or synApi.set_fflag,
            getflag or getfflag or get_fflag or env.getflag or env.getfflag or env.get_fflag or synApi.get_fflag
    end
    local function shortName(name)
        for _,prefix in ipairs({"DFFlag","DFInt","DFString","FFlag","FInt","FString","FLog"}) do
            if name:sub(1,#prefix)==prefix then return name:sub(#prefix+1) end
        end
        return name
    end
    local function read(getter,name)
        if type(getter)~="function" then return false end
        for _,key in ipairs({name,shortName(name)}) do
            local ok,value=pcall(getter,key)
            if ok and (type(value)=="string" or type(value)=="number" or type(value)=="boolean") then return true,tostring(value) end
        end
        return false
    end
    local function write(setter,name,value)
        if type(setter)~="function" then return false end
        for _,key in ipairs({name,shortName(name)}) do
            local ok,result=pcall(setter,key,tostring(value))
            if ok and result~=false then return true end
        end
        return false
    end
    local function equal(a,b) return tostring(a):lower()==tostring(b):lower() end
    local function result() return {Accepted=0,Total=0,Failed={}} end
    function flags:Apply(owner,values)
        local report=result()
        local setter,getter=api()
        for name,value in pairs(values) do
            report.Total+=1
            if type(name)~="string" or not (type(value)=="string" or type(value)=="number" or type(value)=="boolean") then
                table.insert(report.Failed,tostring(name));continue
            end
            local known,original=read(getter,name)
            local record=records[name]
            if record and known and not equal(original,record.Current) then record=nil;records[name]=nil end
            if not write(setter,name,value) then table.insert(report.Failed,name);continue end
            if not record then record={Original=original,Readable=known,Owners={},Order={}};records[name]=record end
            local index=table.find(record.Order,owner)
            if index then table.remove(record.Order,index) end
            table.insert(record.Order,owner)
            record.Owners[owner]=tostring(value)
            record.Current=tostring(value)
            report.Accepted+=1
        end
        table.sort(report.Failed)
        self.LastResult=report
        return report
    end
    function flags:Restore(owner)
        local report=result()
        local setter,getter=api()
        for name,record in pairs(records) do
            local index=table.find(record.Order,owner)
            if not index then continue end
            report.Total+=1
            local wasTop=index==#record.Order
            table.remove(record.Order,index);record.Owners[owner]=nil
            if not wasTop then report.Accepted+=1;continue end
            local known,current=read(getter,name)
            if known and not equal(current,record.Current) then
                -- Another script changed this flag after us; do not overwrite it.
                records[name]=nil;table.insert(report.Failed,name);continue
            end
            local top=record.Order[#record.Order]
            local target=top and record.Owners[top] or record.Original
            if target~=nil and write(setter,name,target) then
                report.Accepted+=1;record.Current=target
                if not top then records[name]=nil end
            else
                table.insert(report.Failed,name)
                if not top then records[name]=nil end
            end
        end
        table.sort(report.Failed)
        self.LastResult=report
        return report
    end
    mainapi:Clean(function()
        local owners={}
        for _,record in pairs(records) do for owner in pairs(record.Owners) do owners[owner]=true end end
        for owner in pairs(owners) do flags:Restore(owner) end
        table.clear(records)
    end)
end

-- END PLEX SOURCE: shared/000_performance_flags.lua
-- BEGIN PLEX SOURCE: shared/000_scope_checks.lua
do (function()
    local weaponNames
    function mainapi:AddCombatScopeCheck(module,defaults)
        if not weaponNames then
            weaponNames={"All weapons"}
            local library=require(ReplicatedStorage.Modules.ItemLibrary)
            local names={}
            for name in pairs(library.Items or {}) do names[#names+1]=name end
            table.sort(names)
            for _,name in ipairs(names) do weaponNames[#weaponNames+1]=name end
        end
        module.ScopeWeapons=module:AddDropdown({Name="check scoped if",List=weaponNames,Default=defaults or {},Multi=true})
        return module.ScopeWeapons
    end
    function mainapi:IsCombatItemScoped(item)
        if not item then return false end
        -- Requested scalar reads only; no registry discovery, raycasts, or timers.
        local ok,aiming=pcall(function()
            local nativeAiming=item:Get("IsAiming")
            if type(nativeAiming)=="boolean" then return nativeAiming end
            if type(item.IsFullyAiming)=="function" and item:IsFullyAiming()==true then return true end
            local interface=item.ItemInterface
            if interface and type(interface.IsScopeActive)=="function" and interface:IsScopeActive()==true then return true end
            local view,info=item.ViewModel,item.Info
            return view and info and type(view.CurrentAimValue)=="number" and type(info.AimScopePercent)=="number"
                and info.AimScopePercent>0 and view.CurrentAimValue>=info.AimScopePercent or false
        end)
        return ok and aiming==true
    end
    function mainapi:IsCombatScopeAllowed(module,item,force)
        local selected=module and module.ScopeWeapons and module.ScopeWeapons.Value or {}
        if not force and not next(selected) then return true end
        if not item then
            local controller=self:GetCombatInputController("FighterController")
            item=controller and controller.LocalFighter and controller.LocalFighter.EquippedItem
        end
        if not item then return false end
        local name=item.Info and item.Info.Name or item.Name
        local checked=selected["All weapons"] or (name and selected[name]) or (item.Name and selected[item.Name])
        if not checked then
            for _,value in ipairs(selected) do
                if value=="All weapons" or value==name or value==item.Name then checked=true;break end
            end
        end
        if not force and name and not checked then return true end
        return self:IsCombatItemScoped(item)
    end
end)() end

-- END PLEX SOURCE: shared/000_scope_checks.lua
-- BEGIN PLEX SOURCE: shared/000_mode_configs.lua
do (function()
    if not LionSaveManager or not LionTabs or not LionTabs.settings then return end
    local manager = LionSaveManager
    local showMode = type(LionLibrary.SetGameMode)=="function"
    local path = "Overlay/mode_configs.json"
    local modes = {"Ranked", "Normal", "Lobby", "Private server"}
    local state = {Enabled=false, Assignments={}}
    if isfile and readfile and isfile(path) then
        local ok, data = pcall(function() return HttpService:JSONDecode(readfile(path)) end)
        if ok and type(data)=="table" then
            state.Enabled=data.Enabled==true
            for _,mode in ipairs(modes) do
                local name=type(data.Assignments)=="table" and data.Assignments[mode]
                if type(name)=="string" then state.Assignments[mode]=name end
            end
        end
    end
    local function save()
        if writefile then pcall(function()
            if makefolder then makefolder("Overlay") end
            writefile(path,HttpService:JSONEncode(state))
        end) end
    end
    local controller, duel, enabledConnections = nil, nil, {}
    local armed, queued, lastMode, loading = false, false, nil, false
    local armEvents, eventsArmed
    local function currentMode()
        if game.PrivateServerId~="" then return "Private server" end
        local current=controller and controller.CurrentObject
        if not current then return "Lobby" end
        local queue=current:Get("QueueName")
        return type(queue)=="string" and queue:sub(1,7)=="ranked_" and "Ranked" or "Normal"
    end
    local function loadMode(mode, manual)
        local name=state.Assignments[mode]
        if loading or type(name)~="string" or name=="" or name=="None" then return false end
        if not manual and (not armed or not state.Enabled or mainapi.Uninjecting) then return false end
        if not manual and lastMode==mode then return false end
        loading=true
        local ok,result,why=pcall(manager.Load,manager,name)
        loading=false
        if ok and result~=false then
            lastMode=mode
            if manager.ConfigNameInput then manager.ConfigNameInput:SetValue(name) end
            return true
        end
        warn("[Plex Config] "..mode..": "..tostring(why or result))
        return false
    end
    local function requested()
        if queued or loading or mainapi.Uninjecting then return end
        queued=true
        task.defer(function()
            queued=false
            if mainapi.Uninjecting then return end
            local mode=currentMode()
            if showMode then LionLibrary:SetGameMode(mode) end
            if armed and state.Enabled then loadMode(mode,false) end
        end)
    end
    local function disconnect()
        for _,connection in ipairs(enabledConnections) do connection:Disconnect() end
        table.clear(enabledConnections)
        duel=nil
    end
    local function bindDuel()
        disconnect()
        duel=controller and controller.CurrentObject
        if duel then
            for _,key in ipairs({"QueueName","EnvironmentID"}) do
                table.insert(enabledConnections,duel:GetDataChangedSignal(key):Connect(requested))
            end
        end
        requested()
    end
    local group=LionTabs.settings:AddRightGroupbox("Mode configurations")
    local selectedMode="Lobby"
    manager.Ignore=manager.Ignore or {}
    manager.Ignore.ModeConfig_Mode=true
    manager.Ignore.ModeConfig_Auto=true
    group:AddDropdown("ModeConfig_Mode",{Text="Game mode",Values=modes,Default="Lobby",Callback=function(value) selectedMode=value end})
    local names=manager:RefreshConfigList()
    table.insert(names,1,"None")
    local choices={}
    for _,mode in ipairs(modes) do
        local id="ModeConfig_"..mode:gsub("%s","")
        manager.Ignore=manager.Ignore or {}; manager.Ignore[id]=true
        choices[mode]=group:AddDropdown(id,{Text=mode.." config",Values=names,Default=state.Assignments[mode] or "None",Callback=function(value)
            state.Assignments[mode]=value
            lastMode=nil
            save()
        end})
    end
    group:AddToggle("ModeConfig_Auto",{Text="Auto-load by mode",Default=state.Enabled,Callback=function(value)
        state.Enabled=value==true
        lastMode=nil
        save()
        if armed and (state.Enabled or showMode) then armEvents() elseif not state.Enabled then disconnect() end
    end})
    group:AddButton({Text="Load selected mode now",Func=function() return loadMode(selectedMode,true) end})
    group:AddButton({Text="Refresh config choices",Func=function()
        local values=manager:RefreshConfigList(); table.insert(values,1,"None")
        for _,choice in pairs(choices) do choice:SetValues(values) end
    end})
    local oldAutoLoad=manager.TryAutoLoad
    manager.TryAutoLoad=function(self,...)
        armed=true
        if state.Enabled then
            local ok,result=pcall(function()
                armEvents()
                local mode=currentMode()
                local assigned=state.Assignments[mode]
                if type(assigned)~="string" or assigned=="" or assigned=="None" then return nil end
                return loadMode(mode,false)
            end)
            if not ok then warn("[Plex Config] Mode setup: "..tostring(result)) end
            if ok and result~=nil then return result end
        end
        return oldAutoLoad(self,...)
    end
    -- A game-owned join/leave event is the only trigger for mode rediscovery.
    armEvents = function()
        if not controller then controller=require(LocalPlayer.PlayerScripts.Controllers.DuelController) end
        if not eventsArmed then
        eventsArmed=true
        mainapi:Clean(controller.LocalPlayerJoinedOrLeftDuel:Connect(function()
            if armed and (state.Enabled or showMode) then bindDuel() end
        end))
        end
        if state.Enabled or showMode then bindDuel() end
    end
    local oldStart=manager.StartAutoSave
    manager.StartAutoSave=function(self,...)
        local result=oldStart(self,...)
        if state.Enabled or showMode then
            local ok,err=pcall(armEvents)
            if not ok then warn("[Plex Config] Mode events: "..tostring(err)) end
        end
        return result
    end
    mainapi:Clean(function() armed=false; disconnect() end)
end)() end

