-- BEGIN PLEX SOURCE: shared/000_menu_cursor.lua
do (function()
    local nativeUI=LionLibrary and LionLibrary.NativeUI
    local gui=Instance.new("ScreenGui")
    gui.Name="PlexMenuCursor"
    gui.IgnoreGuiInset=true
    gui.ResetOnSpawn=false
    local menuGuis={}
    for _,candidate in pairs({LionLibrary and LionLibrary.ScreenGui,mainapi.MainScreenGui}) do
        if candidate and candidate:IsA("ScreenGui") and not table.find(menuGuis,candidate) then
            menuGuis[#menuGuis+1]=candidate
        end
    end
    local function syncLayer()
        local order=10000
        for _,menuGui in ipairs(menuGuis) do order=math.max(order,menuGui.DisplayOrder) end
        gui.DisplayOrder=order+10
    end
    syncLayer()
    for _,menuGui in ipairs(menuGuis) do
        mainapi:Clean(menuGui:GetPropertyChangedSignal("DisplayOrder"):Connect(syncLayer))
    end
    gui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
    gui.Parent=mainapi.MainScreenGui.Parent
    local cursor=Instance.new("Frame")
    cursor.Name="Cursor"
    cursor.BackgroundTransparency=1
    cursor.Size=UDim2.fromOffset(16,22)
    cursor.Visible=false
    cursor.Active=false
    cursor.Parent=gui
    local fills,outlines={},{}
    local customColor,followTheme=nil,true
    local polygons={
        Arrow={{0,0},{0,17},{4,13},{7,20},{10,18},{7,12},{14,12}},
        Triangle={{0,0},{0,17},{14,12}},
        Diamond={{8,0},{16,10},{8,20},{0,10}},
        Crosshair={{7,0},{9,0},{9,9},{16,9},{16,11},{9,11},{9,20},{7,20},{7,11},{0,11},{0,9},{7,9}},
    }
    local style="Arrow"
    local function color()
        return not followTheme and customColor or plexOverlayPalette().accent or Color3.fromRGB(59,130,246)
    end
    local function shape(value)
        style=polygons[value] and value or "Arrow"
        local vertices=polygons[style]
        cursor.AnchorPoint=(style=="Diamond" or style=="Crosshair") and Vector2.new(0.5,0.5) or Vector2.zero
        for y=0,19 do
            local intersections={}
            local scan=y+0.5
            for index,a in ipairs(vertices) do
                local b=vertices[index%#vertices+1]
                if (a[2]<=scan and b[2]>scan) or (b[2]<=scan and a[2]>scan) then
                    intersections[#intersections+1]=a[1]+(scan-a[2])*(b[1]-a[1])/(b[2]-a[2])
                end
            end
            table.sort(intersections)
            local fill,outline=fills[y+1],outlines[y+1]
            if #intersections>=2 then
                if not fill then
                    outline=Instance.new("Frame")
                    outline.Name="Outline"
                    outline.BorderSizePixel=0
                    outline.BackgroundColor3=Color3.fromRGB(0,0,0)
                    outline.ZIndex=1
                    outline.Parent=cursor
                    fill=Instance.new("Frame")
                    fill.Name="Fill"
                    fill.BorderSizePixel=0
                    fill.ZIndex=2
                    fill.Parent=cursor
                    fills[y+1],outlines[y+1]=fill,outline
                end
                local left=math.floor(intersections[1])
                local width=math.max(1,math.ceil(intersections[#intersections])-left)
                outline.Position=UDim2.fromOffset(left-1,y-1)
                outline.Size=UDim2.fromOffset(width+2,3)
                fill.Position=UDim2.fromOffset(left,y)
                fill.Size=UDim2.fromOffset(width,1)
                fill.BackgroundColor3=color()
                fill.Visible=true;outline.Visible=true
            elseif fill then
                fill.Visible=false;outline.Visible=false
            end
        end
    end
    shape(style)
    local enabled,focused=true,true
    local menuOpen=mainapi.ClickGuiStatus==true
    local originalIcon,moveConnection
    local originalOverride,overrideCaptured
    local function position()
        local point=UserInputService:GetMouseLocation()
        cursor.Position=UDim2.fromOffset(point.X,point.Y)
    end
    local function theme()
        for _,fill in pairs(fills) do fill.BackgroundColor3=color() end
    end
    local function hide()
        cursor.Visible=false
        if nativeUI then nativeUI.PlexCustomCursorActive=false end
        if moveConnection then moveConnection:Disconnect(); moveConnection=nil end
        if overrideCaptured then
            pcall(function() UserInputService.OverrideMouseIconBehavior=originalOverride end)
            originalOverride=nil
            overrideCaptured=false
        end
        if originalIcon~=nil then
            UserInputService.MouseIconEnabled=originalIcon
            originalIcon=nil
        end
    end
    local function refresh()
        local show=enabled and focused and menuOpen and UserInputService.MouseEnabled and not mainapi.Uninjecting
        if not show then hide(); return end
        if cursor.Visible then return end
        originalIcon=UserInputService.MouseIconEnabled
        if nativeUI then nativeUI.PlexCustomCursorActive=true end
        theme(); position(); cursor.Visible=true
        UserInputService.MouseIconEnabled=false
        -- CoreScripts can force-show the mouse independently of MouseIconEnabled.
        local ok,value=pcall(function() return UserInputService.OverrideMouseIconBehavior end)
        if ok and value~=nil then
            originalOverride=value
            overrideCaptured=true
            pcall(function()
                UserInputService.OverrideMouseIconBehavior=Enum.OverrideMouseIconBehavior.ForceHide
            end)
        end
        moveConnection=UserInputService.InputChanged:Connect(function(input)
            if input.UserInputType==Enum.UserInputType.MouseMovement then position() end
        end)
    end
    local group=LionTabs.settings:AddRightGroupbox("Menu cursor")
    group:AddToggle("PlexCustomMenuCursor",{Text="Custom cursor",Default=true,Callback=function(value)
        enabled=value==true
        refresh()
    end})
    group:AddDropdown("PlexMenuCursorStyle",{Text="Cursor style",Values={"Arrow","Triangle","Diamond","Crosshair"},Default="Arrow",Callback=shape})
    local themeToggle=group:AddToggle("PlexMenuCursorTheme",{Text="Use theme color",Default=true,Callback=function(value)
        followTheme=value==true
        theme()
    end})
    group:AddColorPicker("PlexMenuCursorColor",{Title="Cursor color",Default=plexOverlayPalette().accent,Callback=function(value)
        customColor=value
        followTheme=false
        if themeToggle then themeToggle:SetValue(false) end
        theme()
    end})
    mainapi:Clean(LionLibrary:OnEvent("VisibilityChanged"):Connect(function(open)
        menuOpen=open==true
        refresh()
    end))
    mainapi:Clean(UserInputService.WindowFocusReleased:Connect(function() focused=false; hide() end))
    mainapi:Clean(UserInputService.WindowFocused:Connect(function() focused=true; refresh() end))
    mainapi:Clean(UserInputService:GetPropertyChangedSignal("MouseEnabled"):Connect(refresh))
    if nativeUI and nativeUI.onThemeChanged then mainapi:Clean(nativeUI.onThemeChanged(theme)) end
    mainapi:Clean(function() hide(); gui:Destroy() end)
    refresh()
end)() end

