    local FillColor1
    local FillColor2
    local FillColor3
    local Lerp
    local MovingRotation
    local RotationValue
    local RotationSpeed
    local FOVPosition
    local ShowTarget
    local CircleObject
    local FillCircleObject
    local FillGradientObject
    local FillScreenGui
    local FillGradientLines = {}
    local OutlineGradientLines = {}
    local FOVVisualPosition
    local SilentTargetPart
    local VisibleOnly
    local WallCheck
    local TeamCheck
    local KatanaCheck
    local ShieldCheck
    local IgnoreProtected
    local DisableOnFlash
    local DistanceMode
    local MaxDistance
    local WorkingDummyTargeting
