    local manipulation = {}

    manipulation.get_closest = function()
        if not lplr.Character or not lplr.Character:FindFirstChild("HumanoidRootPart") then
            return nil, nil
        end

        local target, char, dist = nil, nil, math.huge

        for i, v in next, ps:GetPlayers() do
            if v ~= lplr and v.Character and v.Character:FindFirstChild("Head") then
                local mag = (lplr.Character.HumanoidRootPart.Position - v.Character.Head.Position).Magnitude
                if mag < dist then
                    dist = mag
                    target = v.Character.Head
                    char = v.Character
                end
            end
        end

        return target, char
    end

    manipulation.calculate_point = function(origin, target_pos, target_char)
        ray_params.FilterDescendantsInstances = {lplr.Character, target_char}
        ray_params.FilterType = Enum.RaycastFilterType.Exclude

        if not workspace:Raycast(origin, target_pos - origin, ray_params) then
            return origin, nil
        end

        for i, offset in next, offsets do
            local scan_pos = origin + offset
            if not workspace:Raycast(scan_pos, target_pos - scan_pos, ray_params) then
                return scan_pos, offset.Y
            end
        end

        return nil, nil
    end

    local getPredictedPosition

    local function buildManipulationCameraData(fromPos, part, existingData)
        if not util or not part then return existingData end

        -- Keep the hit point inside the replicated target part.  The old
        -- velocity-based lead could place the encoded hit position outside a
        -- moving player's hitbox, which made otherwise valid shots get rejected.
        local aimPosition = (getPredictedPosition and getPredictedPosition(part)) or part.Position
        local look = CFrame.new(fromPos, aimPosition)
        local encodedLook = util:EncodeCFrame(look)
        local encodedHit = util:EncodeCFrame(part.CFrame:ToObjectSpace(CFrame.new(aimPosition)))
        local k0, k1, k2, k3 = utf8.char(0), utf8.char(1), utf8.char(2), utf8.char(3)

        -- Preserve the game's original camera-data shape.  Some weapons provide
        -- more than one shot/ray entry; replacing the whole table with one entry
        -- causes pellets/bullets to disappear or fail validation.
        local data = typeof(existingData) == "table" and existingData or {}
        local patched = 0
        for _, shot in pairs(data) do
            if typeof(shot) == "table"
                and (shot[k0] ~= nil or shot[k1] ~= nil or shot[k2] ~= nil or shot[k3] ~= nil) then
                shot[k0] = encodedLook
                shot[k1] = encodedLook
                shot[k2] = part
                shot[k3] = encodedHit
                patched += 1
            end
        end

        if patched == 0 then
            data[k1] = {
                [k0] = encodedLook,
                [k1] = encodedLook,
                [k2] = part,
                [k3] = encodedHit
            }
        end
        return data
    end

    local function getManipulationShootPosition(targetPart, targetChar)
        local camera = workspace.CurrentCamera or cam
        local fromPos = camera and camera.CFrame.Position or targetPart.Position

        if not Manipulation or not Manipulation.Enabled then
            return fromPos
        end

        if mainapi:IsCombatFiring() then
            if cachedManipPart == targetPart and cachedManipTarget == targetChar
                and cachedManipOffset and os.clock() < (cachedManipUntil or 0) then
                return fromPos + cachedManipOffset
            end
            return fromPos
        end

        local manip = manipulation.calculate_point(fromPos, targetPart.Position, targetChar)
        cachedManipPart, cachedManipTarget = targetPart, targetChar
        cachedManipOffset = manip and (manip - fromPos) or Vector3.zero
        cachedManipUntil = os.clock() + 0.5
        return manip or fromPos
    end

    -------------------------------------------------
    -- PREDICTION
    -------------------------------------------------

    getPredictedPosition = function(targetPart)
        -- StartShooting sends a claimed hit part plus an object-space hit point.
        -- Leading a moving player moves that claimed point outside the part and
        -- can fail server-side validation.  Aim at the replicated part center;
        -- the game handles its own weapon/network timing from there.
        return targetPart.Position
    end

    local function canSeeTarget(target, targetPart)
        if not entitylib.isAlive then return false end
        if not target then return false end
        targetPart = targetPart or target:FindFirstChild("Head")
        if not targetPart then return false end

        local now = os.clock()
        local cached = silentWallCache[target]
        if cached and cached.Part == targetPart
            and (now < cached.Expires or (mainapi:IsCombatFiring() and now < cached.Expires + 0.35)) then
            return cached.Visible
        end
        if mainapi:IsCombatFiring() then return false end

        local myPos = cam.CFrame.Position
        local targetPos = targetPart.Position

        rayParams.FilterDescendantsInstances = {
            lplr.Character,
            target,
            cam
        }

        local ray = workspace:Raycast(myPos, targetPos - myPos, rayParams)

        local visible = not ray or ray.Instance:IsDescendantOf(target)
        if cached then
            cached.Part, cached.Visible, cached.Expires = targetPart, visible, now + 0.15
        else
            silentWallCache[target] = {Part = targetPart, Visible = visible, Expires = now + 0.15}
        end
        return visible
    end

    local function isProtectedTarget(target)
        if not target then return true end
        if target:FindFirstChild("InvincibilityParticles", true) then return true end
        local root = target:FindFirstChild("HumanoidRootPart")
        if not root then return true end
        for _, obj in root:GetChildren() do
            if obj:IsA("Attachment") and obj.Name == "Attachment" then
                return true
            end
        end
        return false
    end

    local targetWeaponCache = setmetatable({}, {__mode = "k"})
    local weaponNameKind = {}
    local viewModelWeaponNames = setmetatable({}, {__mode = "k"})
    local viewModelFolder, viewModelAdded, viewModelRemoving
    local viewModelIndexVersion = 0
    local function indexViewModel(object)
        if not object:IsA("Model") then return end
        local name = object.Name:lower()
        if name:find("riot", 1, true) or name:find("shield", 1, true)
            or name:find("katana", 1, true) then
            viewModelWeaponNames[object] = name
        end
    end
    local function ensureViewModelIndex()
        local folder = workspace:FindFirstChild("ViewModels")
        if folder == viewModelFolder then return end
        if viewModelAdded then viewModelAdded:Disconnect() end
        if viewModelRemoving then viewModelRemoving:Disconnect() end
        viewModelFolder = folder
        viewModelIndexVersion += 1
        table.clear(viewModelWeaponNames)
        if not folder then return end
        viewModelAdded = folder.DescendantAdded:Connect(indexViewModel)
        viewModelRemoving = folder.DescendantRemoving:Connect(function(object)
            viewModelWeaponNames[object] = nil
        end)
        local version = viewModelIndexVersion
        task.spawn(function()
            for i, object in ipairs(folder:GetDescendants()) do
                if version ~= viewModelIndexVersion then return end
                if object:IsDescendantOf(folder) then indexViewModel(object) end
                if i % 200 == 0 then RunService.Heartbeat:Wait() end
            end
        end)
    end
    mainapi:Clean(function()
        if viewModelAdded then viewModelAdded:Disconnect() end
        if viewModelRemoving then viewModelRemoving:Disconnect() end
    end)
    ensureViewModelIndex()
    local function getTargetWeapon(target)
        local cached = targetWeaponCache[target]
        local now = os.clock()
        if cached and now - cached.At < 1 then return cached.Name end
        local player = ps:GetPlayerFromCharacter(target)
        if not player then return "" end
        local result = ""
        for _, object in target:GetDescendants() do
            local name = object.Name
            local kind = weaponNameKind[name]
            if kind == nil then
                local lower = name:lower()
                if lower:find("riot", 1, true) or lower:find("shield", 1, true) then
                    kind = "riot shield"
                elseif lower:find("katana", 1, true) then
                    kind = "katana"
                else
                    kind = false
                end
                weaponNameKind[name] = kind
            end
            if kind then
                result = kind
                break
            end
        end
        if result == "" then
            ensureViewModelIndex()
            local playerName = player.Name:lower()
            for model, lower in pairs(viewModelWeaponNames) do
                if model:IsDescendantOf(viewModelFolder) and lower:find(playerName, 1, true) then
                    if lower:find("riot", 1, true) or lower:find("shield", 1, true) then
                        result = "riot shield"
                        break
                    elseif lower:find("katana", 1, true) then
                        result = "katana"
                        break
                    end
                end
            end
        end
        targetWeaponCache[target] = {Name = result, At = now}
        return result
    end

    local function isBlockedByRiotShield(target)
        if getTargetWeapon(target) ~= "riot shield" then return false end
        local targetRoot = target and target:FindFirstChild("HumanoidRootPart")
        local localRoot = lplr.Character and lplr.Character:FindFirstChild("HumanoidRootPart")
        if not targetRoot or not localRoot then return false end
        local offset = localRoot.Position - targetRoot.Position
        return offset.Magnitude > 0 and targetRoot.CFrame.LookVector:Dot(offset.Unit) > 0
    end

    local function isFlashed()
        if game:GetService("Lighting"):FindFirstChild("Flashbang") then return true end
        local playerGui = lplr:FindFirstChild("PlayerGui")
        return playerGui and playerGui:FindFirstChild("FlashbangGui") ~= nil or false
    end

    local function computeShouldIgnoreTarget(target)
        local root = getCombatTargetRoot(target)
        if not root or not isCombatTargetAlive(target) then return true end
        local player = ps:GetPlayerFromCharacter(target)
        if TeamCheck and TeamCheck.Enabled and player and player.Team and lplr.Team and not player.Neutral and not lplr.Neutral and player.Team == lplr.Team then return true end
        local checkedPart = getCombatTargetAimPart(target, TargetPart and TargetPart.Value or "Head")
        if VisibleOnly and VisibleOnly.Enabled then
            if not checkedPart then return true end
            local _, onScreen = cam:WorldToViewportPoint(checkedPart.Position)
            if not onScreen then return true end
        end
        if WallCheck and WallCheck.Enabled and not canSeeTarget(target, checkedPart) then return true end
        if player and IgnoreProtected and IgnoreProtected.Enabled and isProtectedTarget(target) then return true end
        if DistanceMode and DistanceMode.Value == "limit distance" then
            local myRoot = lplr.Character and lplr.Character:FindFirstChild("HumanoidRootPart")
            if not myRoot or (root.Position - myRoot.Position).Magnitude > MaxDistance.Value then return true end
        end
        if player and KatanaCheck and KatanaCheck.Enabled and shouldBlockShotForKatana(target) then return true end
        if player and ShieldCheck and ShieldCheck.Enabled and isBlockedByRiotShield(target) then return true end
        return false
    end

    local ignoreDecisionCache = setmetatable({}, {__mode = "k"})
    local function shouldIgnoreTarget(target)
        if not target then return true end
        local now = os.clock()
        local cached = ignoreDecisionCache[target]
        if cached and now < cached.Expires then return cached.Ignore end
        if mainapi:IsCombatFiring() then
            return if cached and now < cached.Expires + 0.35 then cached.Ignore else true
        end
        local ignored = computeShouldIgnoreTarget(target)
        ignoreDecisionCache[target] = {Ignore = ignored, Expires = now + 0.075}
        return ignored
    end

    -------------------------------------------------
