    local function getTargetPosition()
        local root = entitylib.isAlive and entitylib.character and entitylib.character.RootPart
        return root and root.Position or nil
    end

    local aimPartCache = setmetatable({}, {__mode = "k"})
    local function getAimParts(char)
        local parts = {}
        if not char then return parts end
        local now = os.clock()
        local cached = aimPartCache[char]
        if cached and now < cached.Expires then
            local valid = true
            for _, part in ipairs(cached.Parts) do
                if not part.Parent or not part:IsDescendantOf(char) then valid = false break end
            end
            if valid then return cached.Parts end
        end
        local blacklist = ClosestPartBlacklist and ClosestPartBlacklist.Value or {}
        for _, name in ipairs(R15Parts) do
            if blacklist[name] then continue end
            local part = char:FindFirstChild(name) or char:FindFirstChild(name, true)
            if part and part:IsA("BasePart") then
                table.insert(parts, part)
            end
        end
        if #parts == 0 then
            local fallback = getCombatTargetAimPart(char, TargetPart and TargetPart.Value or nil)
            if fallback then table.insert(parts, fallback) end
        end
        aimPartCache[char] = {Parts = parts, Expires = now + 1}
        return parts
    end

    local function getFOVOrigin(targetPart)
        local camera = workspace.CurrentCamera or cam
        local mode = FOVPosition and FOVPosition.Value or ""
        local origin
        if mode == "position on target" and targetPart then
            local pos, visible = camera:WorldToViewportPoint(targetPart.Position)
            if visible then
                origin = Vector2.new(pos.X, pos.Y)
            end
        end

        if not origin and mode == "position on barrel" and camera then
            origin = getMuzzleScreenPosition(camera)
        end

        if not origin and camera then
            local viewport = camera.ViewportSize
            origin = Vector2.new(viewport.X / 2, viewport.Y / 2)
        end
        origin = origin or UserInputService:GetMouseLocation()
        return origin
    end

    local function getClosestPart(char, origin)
        local best, dist = nil, math.huge
        for _, part in ipairs(getAimParts(char)) do
            local pos, visible = cam:WorldToViewportPoint(part.Position)
            if visible then
                local d = (Vector2.new(pos.X, pos.Y) - origin).Magnitude
                if d < dist then
                    best, dist = part, d
                end
            end
        end
        return best, dist
    end

    -- Position ? ル??꾤땟??? 360?????? 維????????좊읈?????좊읈?? 싲 ?  ???????
    local function getTargetByPosition()
        local myPos = getTargetPosition()
        if not myPos then return nil end

        local maxRange = RageCircle.Enabled and Range.Value or math.huge
        local best, dist = nil, maxRange

        local origin = getFOVOrigin()
        for _, character in ipairs(getCombatTargetModels({
            WorkingDummy = WorkingDummyTargeting and WorkingDummyTargeting.Enabled,
            RangeTargets = RangeTargetsTargeting and RangeTargetsTargeting.Enabled
        })) do
            if character then
                local hrp = getCombatTargetRoot(character)

                if hrp and isCombatTargetAlive(character) and not shouldIgnoreTarget(character) then
                    local fixedPart = getCombatTargetAimPart(character, TargetPart and TargetPart.Value or "Head")
                    local targetPart, screenDist = fixedPart, 0
                    if ClosestPart and ClosestPart.Enabled then
                        targetPart, screenDist = getClosestPart(character, origin)
                    end
                    local d = targetPart and (RageCircle.Enabled and screenDist or (hrp.Position - myPos).Magnitude) or math.huge
                    if d < dist then
                        best = character
                        SilentTargetPart = targetPart
                        dist = d
                    end
                end
            end
        end

        return best, SilentTargetPart
    end

    -- Mouse ? ル??꾤땟??? ? ル?????????  ??? (Circle ??? ? 땾????源끹걬癲?? 꾧???????????   ???? 챶??
    local function getTargetByMouse()
        local mouse = getFOVOrigin()
        local maxRange = RageCircle.Enabled and Range.Value or math.huge
        local best, dist = nil, maxRange

        for _, character in ipairs(getCombatTargetModels({
            WorkingDummy = WorkingDummyTargeting and WorkingDummyTargeting.Enabled,
            RangeTargets = RangeTargetsTargeting and RangeTargetsTargeting.Enabled
        })) do
            if character then
                local hrp = getCombatTargetRoot(character)

                if hrp and isCombatTargetAlive(character) and not shouldIgnoreTarget(character) then
                    local fixedPart = getCombatTargetAimPart(character, TargetPart and TargetPart.Value or "Head")
                    local part = (ClosestPart and ClosestPart.Enabled) and getClosestPart(character, mouse) or fixedPart
                    local pos, vis
                    if part then
                        pos, vis = cam:WorldToViewportPoint(part.Position)
                    end
                    if part and vis then
                        local d = (Vector2.new(pos.X, pos.Y) - mouse).Magnitude
                        if d < dist then
                            best = character
                            SilentTargetPart = part
                            dist = d
                        end
                    end
                end
            end
        end

        return best, SilentTargetPart
    end

    -- Rage ? ル??꾤땟??? ???뺤깓?? ?????좊읈?????좊읈?? 싲 ?  ???????
    local function getTargetRage()
        local myPos = getTargetPosition()
        if not myPos then return nil end

        local best, dist = nil, 1000

        for _, character in ipairs(getCombatTargetModels({WorkingDummy = false, RangeTargets = false})) do
            if character then
                local head = getCombatTargetAimPart(character, "Head")
                local hrp = getCombatTargetRoot(character)

                if head and hrp and isCombatTargetAlive(character) and not shouldIgnoreTarget(character) then
                    local d = (hrp.Position - myPos).Magnitude
                    if d < dist then
                        best = character
                        dist = d
                    end
                end
            end
        end

        return best
    end

    local function isLobby()
        local pg = lplr:FindFirstChild("PlayerGui")
        if not pg then return false end

        local main = pg:FindFirstChild("MainGui")
        if not main then return false end

        local frame = main:FindFirstChild("MainFrame")
        if not frame then return false end

        local lobby = frame:FindFirstChild("Lobby")
        if not lobby then return false end

        local currency = lobby:FindFirstChild("Currency")
        if not currency then return false end

        return currency.Visible == true
    end

    local function silentTargetValid(target, part)
        if not target or not part or not target.Parent or not part.Parent
            or not part:IsDescendantOf(target) or not isCombatTargetAlive(target)
            or shouldIgnoreTarget(target) then
            return false
        end
        local point, visible = cam:WorldToViewportPoint(part.Position)
        if not visible or point.Z <= 0 then return false end
        if RageCircle and RageCircle.Enabled then
            return (Vector2.new(point.X, point.Y) - getFOVOrigin(part)).Magnitude <= Range.Value
        end
        return true
    end

    local function getTarget()
        if not mainapi:IsCombatScopeAllowed(SilentAim) then
            SilentTargetPart,LockedTarget,LockedTargetPart,CandidateTarget=nil,nil,nil,nil
            return nil
        end
        SilentTargetPart = nil
        if DisableOnFlash and DisableOnFlash.Enabled and isFlashed() then
            LockedTarget = nil
            LockedTargetPart = nil
            CandidateTarget = nil
            return nil
        end

        local scanNow = os.clock()
        if silentTargetValid(LockedTarget, LockedTargetPart) then
            LastTargetSeen = tick()
            SilentTargetPart = LockedTargetPart
            return LockedTarget
        end

        LockedTarget = nil
        LockedTargetPart = nil
        LastTargetSeen = 0

        -- Shot callbacks only consume a target acquired before firing. A cache
        -- miss waits for the next idle update instead of scanning the registry.
        if mainapi:IsCombatFiring() then return nil end

        local target, part
        if scanNow < NextSilentDiscovery
            and CachedSilentTarget and CachedSilentTarget.Parent
            and CachedSilentPart and CachedSilentPart.Parent
            and silentTargetValid(CachedSilentTarget, CachedSilentPart) then
            target, part = CachedSilentTarget, CachedSilentPart
        else
            if FOVPosition and FOVPosition.Value == "position on target" then
                target, part = getTargetByPosition()
            else
                target, part = getTargetByMouse()
            end
            CachedSilentTarget, CachedSilentPart = target, part
            NextSilentDiscovery = scanNow + (target and 0.25 or 0.12)
        end

        local now = tick()
        if target then
            if target ~= CandidateTarget then
                CandidateTarget = target
                CandidateSince = now
            end

            local reaction = (ReactionTime and ReactionTime.Value or 0) / 1000
            if target == LockedTarget or now - CandidateSince >= reaction then
                LockedTarget = target
                LockedTargetPart = part
                LastTargetSeen = now
            end
        else
            CandidateTarget = nil
        end

        if not target or target ~= LockedTarget then
            SilentTargetPart = nil
            return nil
        end
        SilentTargetPart = LockedTargetPart or part
        return LockedTarget
    end

    -------------------------------------------------
    -- RANGE CIRCLE CHECK
    -------------------------------------------------

    local function isInCircleRange(target)
        -- Circle????? ? 땾????源끹걬癲?????true (? 꾧???????????   ???? 챶??
        if not RageCircle.Enabled then return true end
        if not target then return false end

        local part = SilentTargetPart or getCombatTargetAimPart(target, "Head")
        if not part then return false end
        local pos, vis = cam:WorldToViewportPoint(part.Position)
        if not vis then return false end

        local mouse = getFOVOrigin()
        return (Vector2.new(pos.X, pos.Y) - mouse).Magnitude <= Range.Value
    end

