-- BEGIN PLEX SOURCE: modules/silent_aim.lua
    local function resolveSilentShot(cameradata)
        if isLobby() then return false, cameradata end
        local fighter = getFighter()
        local item = fighter and fighter.EquippedItem
        if not mainapi:IsCombatScopeAllowed(SilentAim,item) then return false,cameradata end
        if tryAutoReload(item, fighter) then return true end
        if rand:NextNumber(0, 100) > HitChance.Value then return false, cameradata end

        local target = getTarget()
        if not target or shouldIgnoreTarget(target) or not isInCircleRange(target)
            or not target:FindFirstChild("Head") or not target:FindFirstChild("HumanoidRootPart") then
            return false, cameradata
        end

        local targetPart = SilentTargetPart
        if not targetPart and ClosestPart and ClosestPart.Enabled then
            targetPart = select(1, getClosestPart(target, getFOVOrigin()))
        end
        if not targetPart then
            targetPart = (HeadshotChance and rand:NextNumber(0, 100) <= HeadshotChance.Value)
                and target.Head
                or target.HumanoidRootPart
        end
        targetPart = targetPart or getCombatTargetAimPart(target, TargetPart and TargetPart.Value or "Head")
        if WallCheck and WallCheck.Enabled and not canSeeTarget(target, targetPart) then
            return false, cameradata
        end

        local fromPos = getManipulationShootPosition(targetPart, target)
        cameradata = buildManipulationCameraData(fromPos, targetPart, cameradata) or cameradata

        if ShowTarget.Enabled and mainapi.Libraries.Targetinfo then
            local ent = select(1, entitylib.getEntity(target))
            if ent then
                mainapi.Libraries.Targetinfo.Targets[ent] = tick() + 2
            end
        end
        return false, cameradata
    end

    local function silentPreScan()
        local target = getTarget()
        local part = SilentTargetPart
        if target and part then
            if WallCheck and WallCheck.Enabled then canSeeTarget(target, part) end
            if Manipulation and Manipulation.Enabled then getManipulationShootPosition(part, target) end
        end
    end

    local function resolveAutoFire()
        local target_char = getTarget()
        local target_part = SilentTargetPart
        if not target_part or not target_char or shouldIgnoreTarget(target_char) then return nil end
        if WallCheck and WallCheck.Enabled and not canSeeTarget(target_char, target_part) then return nil end
        if RageCircle.Enabled and not isInCircleRange(target_char) then return nil end
        return buildManipulationCameraData(getManipulationShootPosition(target_part, target_char), target_part)
    end

    SilentAim = Combat:AddModule({
        Name = 'Silent Aim',
        Function = function(callback)
            NextSilentDiscovery = 0
            CachedSilentTarget = nil
            CachedSilentPart = nil
            if callback then
                if RageCircle and RageCircle.Enabled then
                    ensureCircle()
                end

                if CircleObject then
                    CircleObject.Visible = RageCircle and RageCircle.Enabled or false
                end

                if not silentHookInstalled then
                    local useItemRemote = getUseItemRemote()
                    if not useItemRemote then
                        return
                    end

                    local startShooting = enums:ToEnum("StartShooting")
                    local hookOk, hookErr = pcall(function()
                        oldFireServer = hookfunction(
                            useItemRemote.FireServer,
                            newcclosure(function(self, obj, action, cameradata, ...)
                        if autoFireDispatching or action ~= startShooting
                            or not (self == useItemRemote or self.Name == "UseItem") then
                            return oldFireServer(self, obj, action, cameradata, ...)
                        end
                        if SilentAim.Enabled then
                            mainapi.ShotResolving = true
                            local ok, drop, data = pcall(resolveSilentShot, cameradata)
                            mainapi.ShotResolving = false
                            mainapi:MarkCombatFire(0.12)
                            if ok then
                                if drop then return nil end
                                cameradata = data
                            end
                        else
                            mainapi:MarkCombatFire(0.12)
                        end
                        return oldFireServer(self, obj, action, cameradata, ...)
                            end)
                        )
                    end)
                    if not hookOk then
                        warn("[Silent Aim] hook failed:", hookErr)
                        return
                    end
                    silentHookInstalled = true
                end

                local nextSilentPreScan = 0
                SilentAim:Clean(RunService.Heartbeat:Connect(function()
                    local now = os.clock()
                    if now < nextSilentPreScan or mainapi.ClickGuiStatus then return end
                    nextSilentPreScan = now + (mainapi:IsCombatFiring() and 0.25 or 0.125)
                    mainapi.ShotResolving = true
                    pcall(silentPreScan)
                    mainapi.ShotResolving = false
                end))

                -- AutoFire Loop (???? ??manipulation ? ?? ?먰맪?
                if AutoFire and AutoFire.Enabled then
                    local fighter = require(lplr.PlayerScripts.Controllers.FighterController)
                    local nextAutoFireUpdate, nextAutoFireShot, lastAutoFireErrorAt = 0, 0, 0
                    SilentAim:Clean(RunService.Heartbeat:Connect(function()
                        if not SilentAim.Enabled or mainapi.Uninjecting then return end
                        local now = os.clock()
                        if now < nextAutoFireUpdate or now < nextAutoFireShot then return end
                        nextAutoFireUpdate = now + 1 / 30
                        if not lplr.Character then return end
                        if mainapi.ClickGuiStatus then return end
                        if isLobby() then return end

                        local root = lplr.Character:FindFirstChild("HumanoidRootPart")
                        if not root then return end

                        if not fighter or not fighter.LocalFighter then return end

                        local localFighter = fighter.LocalFighter
                        local item = localFighter.EquippedItem
                        if not item then return end
                        if tryAutoReload(item, localFighter) then return end

                        mainapi.ShotResolving = true
                        local resolved, cameradata = pcall(resolveAutoFire)
                        mainapi.ShotResolving = false
                        if not resolved or not cameradata then return end
                        mainapi:MarkCombatFire(0.12)

                        local useItemRemote = getUseItemRemote()
if not useItemRemote then
    return
end

                        nextAutoFireShot = now + 0.075
                        autoFireDispatching = true
                        local fired, fireError = pcall(useItemRemote.FireServer, useItemRemote,
                            item:Get("ObjectID"), enums:ToEnum("StartShooting"), cameradata, nil)
                        autoFireDispatching = false
                        if not fired and now - lastAutoFireErrorAt > 2 then
                            lastAutoFireErrorAt = now
                            warn("[Silent Aim] auto-fire failed:", fireError)
                        end
                    end))
                end

                -- TargetHud Update Loop
                local nextTargetHudUpdate = 0
                SilentAim:Clean(RunService.Heartbeat:Connect(function()
                    local now = os.clock()
                    if now < nextTargetHudUpdate then return end
                    nextTargetHudUpdate = now + 0.1
                    if ShowTarget and ShowTarget.Enabled and mainapi.Libraries.Targetinfo then
                        mainapi.Libraries.Targetinfo:UpdateInfo()
                    end
                end))

                -- Circle Update Loop
                local circleHidden = false
                SilentAim:Clean(RunService.Heartbeat:Connect(function(dt)
                    local visible = SilentAim.Enabled and RageCircle.Enabled
                    if not visible and circleHidden then return end
                    circleHidden = not visible
                    local fovPos = tweenFOVPosition(getFOVOrigin(SilentTargetPart), dt)
                    local radius = Range.Value
                    updateGradientGui(fovPos, radius, CircleFilled, visible and CircleFilled and CircleFilled.Enabled)
                    local circle = CircleObject
                    if circle then
                        if gui.circle ~= circle then
                            gui.circle, gui.cv, gui.cr, gui.cc, gui.ct = circle, nil, nil, nil, nil
                            circle.Transparency = 1
                            circle.Filled = false
                        end
                        circle.Position = fovPos
                        if gui.cv ~= visible then gui.cv = visible circle.Visible = visible end
                        if gui.cr ~= radius then gui.cr = radius circle.Radius = radius end
                        local color = select(2, getThreeColors(Outline and Outline.Enabled and Outline or RageCircle))
                        if gui.cc ~= color then gui.cc = color circle.Color = color end
                        local thickness = Outline and Outline.Enabled and 2 or 1
                        if gui.ct ~= thickness then gui.ct = thickness circle.Thickness = thickness end
                    end
                end))

                -- ???????? 밸Ŧ? 얕 ????hook ?????
                SilentAim:Clean(lplr.CharacterAdded:Connect(function()
                    task.wait(1)
                    if SilentAim.Enabled then
                        SilentAim:Toggle()
                        task.wait()
                        SilentAim:Toggle()
                    end
                end))

                SilentAim:Clean(lplr.OnTeleport:Connect(removeCircle))

            else
                removeCircle()
            end
        end,
        ExtraText = function()
            return FOVPosition and FOVPosition.Value or ""
        end
    })

