                pivotESPPreviewModel()
            end)
        end

        local reset = shell and shell:CreateButton() or Instance.new("TextButton")
        reset.Size = UDim2.new(1,-24,0,30)
        reset.Position = UDim2.new(0,12,1,-42)
        reset.Text = "Reset view"
        reset.Font = Enum.Font.Code
        reset.TextSize = 14
        reset.TextColor3 = Color3.fromRGB(255, 255, 255)
        reset.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
        reset.BorderColor3 = Color3.fromRGB(65, 65, 65)
        reset.ZIndex = 52
        reset.Parent = frame
        chromeButtons[#chromeButtons + 1] = reset
        reset.MouseButton1Click:Connect(function()
            ESPPreview.Angle = 0
            ESPPreview.Offset = Vector3.new()
            if ESPPreview.Model then
                pivotESPPreviewModel()
            end
        end)

        local dragging, lastX, lastY = false, 0, 0
        viewport.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                dragging = true
                lastX = input.Position.X
                lastY = input.Position.Y
            end
        end)
        viewport.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                dragging = false
            end
        end)
        mainapi:Clean(UserInputService.InputChanged:Connect(function(input)
            if dragging and isESPPreviewVisible() and input.UserInputType == Enum.UserInputType.MouseMovement and ESPPreview.Model then
                local delta = input.Position.X - lastX
                local deltaY = input.Position.Y - lastY
                lastX = input.Position.X
                lastY = input.Position.Y
                ESPPreview.Angle += math.rad(delta)
                ESPPreview.Offset += Vector3.new(0, -deltaY * 0.02, 0)
                pivotESPPreviewModel()
            end
        end))

        ESPPreview.Parts = {
            Box = box,
            Box3D = box3D,
            Fill = fill,
            Health = health,
            Name = nameText,
