        local nativeUI = LionLibrary and LionLibrary.NativeUI
        local function applyPreviewTheme()
            if not gui.Parent then return end
            local colors = plexOverlayPalette()
            local fonts = nativeUI and nativeUI.F
            frame.BackgroundColor3 = colors.pop or colors.bg
            frame.BackgroundTransparency = shell and 0 or 0.04
            panelStroke.Color = shell and colors.hairline or colors.edge
            title.TextColor3 = colors.text
            if fonts then title.FontFace = fonts.semibold or fonts.medium or fonts.body end
            viewport.BackgroundColor3 = colors.bg
            viewport.BorderColor3 = colors.edge
            for _, button in ipairs(chromeButtons) do
                button.BackgroundColor3 = colors.card or colors.surface or colors.bg
                button.BorderColor3 = colors.edge
                button.TextColor3 = colors.text
                if fonts then button.FontFace = fonts.medium or fonts.body end
            end
        end
        applyPreviewTheme()
        if nativeUI and nativeUI.onThemeChanged then
            mainapi:Clean(nativeUI.onThemeChanged(applyPreviewTheme))
        end
        local function dockPreview()
            if not gui.Parent or not anchor or not anchor.Parent then return end
            local size, position = anchor.AbsoluteSize, anchor.AbsolutePosition
            local camera = workspace.CurrentCamera
            local screen = camera and camera.ViewportSize or Vector2.new(1920, 1080)
            local inset = Vector2.zero
            -- AbsolutePosition includes the ScreenGui origin; detached panel
            -- offsets must remove that origin to align with the menu.
            position -= previewGui.AbsolutePosition
            local width = math.min(280, math.max(160, screen.X - 24))
            local height = math.min(460, math.max(280, size.Y), math.max(160, screen.Y - inset.Y - 24))
            local right = position.X + size.X + 12
            gui.Size = UDim2.fromOffset(width, height)
            fitPreviewCamera(visualClone, cam, viewport)
            gui.Position = UDim2.fromOffset(
                math.clamp(right, 12, math.max(12, screen.X - width - 12)),
                math.clamp(position.Y - inset.Y, 12, math.max(12, screen.Y - inset.Y - height - 12))
            )
        end
        if anchor then
            mainapi:Clean(anchor:GetPropertyChangedSignal("AbsolutePosition"):Connect(dockPreview))
            mainapi:Clean(anchor:GetPropertyChangedSignal("AbsoluteSize"):Connect(dockPreview))
        end
        mainapi:Clean(gui)
        mainapi:Clean(clone)
        mainapi:Clean(function()
            cleanupESPPreviewDrawings()
            if visualClone then visualClone:Destroy() end
        end)
        dockPreview()
        local nextPreviewUpdate = 0
        local previewConnection
        local function renderPreview()
            local now = os.clock()
            if now < nextPreviewUpdate then return end
            nextPreviewUpdate = now + 0.05
            local menuOpen = isLionMenuOpen()
            gui.Visible = isESPPreviewVisible()
            if gui.Visible then
                local ok, err = pcall(updateESPPreview)
                if not ok then
                    warn("[ESP Preview] update failed:", err)
                    gui.Visible = false
                    ESPPreview.Wanted = false
                end
            elseif ESPPreview.Drawings then
                setESPVisible(ESPPreview.Drawings, false)
            end
            if not gui.Visible and ESPPreview.SyncVisibility then task.defer(ESPPreview.SyncVisibility) end
        end
        local function syncPreviewVisibility()
            if not gui.Parent then
                if previewConnection then previewConnection:Disconnect(); previewConnection = nil end
                return
            end
            gui.Visible = isESPPreviewVisible()
            if gui.Visible and not previewConnection then
                dockPreview()
                previewConnection = RunService.Heartbeat:Connect(renderPreview)
            elseif not gui.Visible and previewConnection then
                previewConnection:Disconnect()
                previewConnection = nil
            end
            if not gui.Visible and ESPPreview.Drawings then setESPVisible(ESPPreview.Drawings, false) end
        end
        ESPPreview.SyncVisibility = syncPreviewVisibility
        if LionLibrary and LionLibrary.OnEvent then
            mainapi:Clean(LionLibrary:OnEvent("VisibilityChanged"):Connect(function()
                task.defer(syncPreviewVisibility)
            end))
        end
        if LionLibrary and LionLibrary.OnEvent then
            mainapi:Clean(LionLibrary:OnEvent("TabChanged"):Connect(function()
                task.defer(syncPreviewVisibility)
            end))
        end
        mainapi:Clean(function()
            if previewConnection then previewConnection:Disconnect() end
            if ESPPreview.SyncVisibility == syncPreviewVisibility then ESPPreview.SyncVisibility = nil end
        end)
        syncPreviewVisibility()
        pcall(updateESPPreview)
    end

    local ESPAdded = {
        Drawing2D = function(ent)
            if Teammates.Enabled and (not ent.Targetable) and (not ent.Friend) then return end
            if mainapi.ThreadFix then
                pcall(setthreadidentity, 8)
            end
            local EntityESP = {}
            EntityESP.Main = Drawing.new('Square')
            EntityESP.Main.Transparency = BoundingBox.Enabled and 1 or 0
            EntityESP.Main.ZIndex = 2
            EntityESP.Main.Filled = false
            EntityESP.Main.Thickness = EspLineThickness and EspLineThickness.Value or 1
            local baseColor = entitylib.getEntityColor(ent) or (uipallet and uipallet.FinalColor) or Color3.new(1, 1, 1)
            EntityESP.Main.Color = espGradientColor(BoundingBox, 0.5, baseColor)

            if BoundingBox.Enabled then
                EntityESP.Border = Drawing.new('Square')
                EntityESP.Border.Transparency = 0.35
                EntityESP.Border.ZIndex = 1
                EntityESP.Border.Thickness = math.max(1, (EspLineThickness and EspLineThickness.Value or 1))
                EntityESP.Border.Filled = false
                EntityESP.Border.Color = Color3.new()
            end
