    local function applyEspPreset(name)
        if name == "clean" then
            setToggle(BoundingBox, true)
            setToggle(Filled, false)
            setToggle(Skeleton, false)
            setToggle(Name, true)
            setToggle(HealthBar, true)
            setToggle(Weapon, false)
            setToggle(DistanceText, true)
            setToggle(Background, false)
        elseif name == "info" then
            setToggle(BoundingBox, true)
            setToggle(Filled, true)
            setToggle(Skeleton, true)
            setToggle(Name, true)
            setToggle(HealthBar, true)
            setToggle(Weapon, true)
            setToggle(DistanceText, true)
            setToggle(Background, true)
        elseif name == "minimal" then
            setToggle(BoundingBox, false)
            setToggle(Filled, false)
            setToggle(Skeleton, false)
            setToggle(Name, true)
            setToggle(HealthBar, false)
            setToggle(Weapon, false)
            setToggle(DistanceText, false)
            setToggle(Background, true)
        end
        refreshESP(true)
        updateESPPreview()
    end
    QuickESP:AddButton({Text = "Clean ESP", Func = function() applyEspPreset("clean") end})
