-- BEGIN PLEX SOURCE: shared/005_esp.lua
run(function()
    local OverrideAppearance
    local OverrideColor
    local OverrideMaterial
    local Material
    local DisableAppearance
    local OverrideTransparency
    local HighlightESP
    local ThroughWalls
    local HighlightPulse
    local Particle
    local ParticleType
    local Aura
    local AuraType
    local IncludeTeammates
    local BoundingMode
    local FixedWidth
    local ESPFont
    local NameType
    local originalAppearance = setmetatable({}, {__mode = "k"})
    local highlights = {}
    local effects = {}

    local materialNames = {}
    for _, material in ipairs(Enum.Material:GetEnumItems()) do
        table.insert(materialNames, material.Name)
    end
    table.sort(materialNames)

    local function selectedMulti(option, name)
        return option and type(option.Value) == "table" and option.Value[name] == true
    end

    local function remember(inst, property)
        originalAppearance[inst] = originalAppearance[inst] or {}
        if originalAppearance[inst][property] == nil then
            originalAppearance[inst][property] = inst[property]
        end
    end

    local function restoreAppearance()
        for inst, values in pairs(originalAppearance) do
            for property, value in pairs(values) do
                pcall(function() inst[property] = value end)
            end
        end
        table.clear(originalAppearance)
    end

    local function applyAppearance(character)
        if not OverrideAppearance.Enabled or not character or character == LocalPlayer.Character then return end
        for _, inst in ipairs(character:GetDescendants()) do
            if inst:IsA("BasePart") then
                if OverrideColor and OverrideColor.Enabled then
                    remember(inst, "Color")
                    inst.Color = OverrideColor.Value or Color3.fromRGB(255, 255, 255)
                end
                if OverrideMaterial and OverrideMaterial.Enabled then
                    remember(inst, "Material")
                    inst.Material = Enum.Material[Material.Value] or Enum.Material.ForceField
                end
                remember(inst, "Transparency")
                inst.Transparency = math.clamp((OverrideTransparency and OverrideTransparency.Value or 0) / 100, 0, 1)
            elseif inst:IsA("Decal") and selectedMulti(DisableAppearance, "decals") then
                remember(inst, "Transparency")
                inst.Transparency = 1
            elseif (inst:IsA("Shirt") or inst:IsA("Pants") or inst:IsA("ShirtGraphic")) and selectedMulti(DisableAppearance, "clothing") then
                local property = inst:IsA("Shirt") and "ShirtTemplate" or inst:IsA("Pants") and "PantsTemplate" or "Graphic"
                remember(inst, property)
                inst[property] = ""
            elseif inst:IsA("Highlight") and selectedMulti(DisableAppearance, "highlight") then
                remember(inst, "Enabled")
                inst.Enabled = false
            end
        end
    end

    local function validTarget(character)
        if not character or character == LocalPlayer.Character then return false end
        local player = Players:GetPlayerFromCharacter(character)
        return (not player and isTrainingDummy(character)) or (player ~= LocalPlayer and (IncludeTeammates.Enabled or not player.Team or not LocalPlayer.Team or player.Team ~= LocalPlayer.Team))
    end

    local function removeVisual(player)
        if highlights[player] then highlights[player]:Destroy(); highlights[player] = nil end
        if effects[player] then
            effects[player]:Destroy()
            effects[player] = nil
        end
    end

    local function particleShape(emitter, style)
        emitter.Texture = "rbxassetid://243660364"
        emitter.Rate = 18
        emitter.Lifetime = NumberRange.new(0.7, 1.25)
        emitter.Speed = NumberRange.new(0.5, 2)
        emitter.SpreadAngle = Vector2.new(180, 180)
        emitter.Rotation = NumberRange.new(0, 360)
        emitter.RotSpeed = NumberRange.new(-90, 90)
        emitter.LightEmission = (style == "glowing" or style == "heavenly") and 1 or 0.35
        if style == "hearts" then emitter.Texture = "rbxassetid://241837157" end
        if style == "triangles" then emitter.Texture = "rbxassetid://121580522" end
    end

    local function auraShape(emitter, style)
        particleShape(emitter, "glowing")
        emitter.Rate = 28
        emitter.Lifetime = NumberRange.new(0.9, 1.8)
        emitter.Speed = NumberRange.new(style == "tornado" and 5 or 1, style == "wind" and 7 or 3)
        emitter.Acceleration = Vector3.new(0, style == "moon" and 1 or 3, 0)
        emitter.Orientation = Enum.ParticleOrientation.VelocityPerpendicular
    end

    local function ensureVisual(character)
        if not validTarget(character) then removeVisual(character); return end
        local player = character
        if HighlightESP.Enabled then
            local high = highlights[player]
            if not high or high.Parent ~= character then
                if high then high:Destroy() end
                high = Instance.new("Highlight")
                high.Name = "__LionESPHighlight"
                high.Adornee = character
                high.Parent = character
                highlights[player] = high
            end
            high.DepthMode = ThroughWalls.Enabled and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded
            high.FillColor = HighlightESP.Colors and HighlightESP.Colors[1] or Color3.fromRGB(255, 255, 255)
            high.OutlineColor = HighlightESP.Colors and HighlightESP.Colors[2] or Color3.fromRGB(255, 255, 255)
            if not (HighlightPulse and HighlightPulse.Enabled) then
                high.FillTransparency = 0.35
                high.OutlineTransparency = 0
            end
        else
            if highlights[player] then highlights[player]:Destroy(); highlights[player] = nil end
        end

        local root = character:FindFirstChild("HumanoidRootPart")
        if root and ((Particle and Particle.Enabled) or (Aura and Aura.Enabled)) then
            local attachment = effects[player]
            if not attachment or attachment.Parent ~= root then
                if attachment then attachment:Destroy() end
                attachment = Instance.new("Attachment")
                attachment.Name = "__LionESPEffects"
                attachment.Parent = root
                effects[player] = attachment
            end
            local particle = attachment:FindFirstChild("Particle")
            if Particle.Enabled then
                particle = particle or Instance.new("ParticleEmitter")
                particle.Name = "Particle"
                particle.Parent = attachment
                particleShape(particle, ParticleType.Value)
                particle.Color = ColorSequence.new(Particle.Colors[1], Particle.Colors[3] or Particle.Colors[1])
            elseif particle then particle:Destroy() end
            local aura = attachment:FindFirstChild("Aura")
            if Aura.Enabled then
                aura = aura or Instance.new("ParticleEmitter")
                aura.Name = "Aura"
                aura.Parent = attachment
                auraShape(aura, AuraType.Value)
                aura.Color = ColorSequence.new(Aura.Colors[1], Aura.Colors[3] or Aura.Colors[1])
            elseif aura then aura:Destroy() end
        elseif effects[player] then
            effects[player]:Destroy()
            effects[player] = nil
        end
    end

    local appearanceWatchers = {}
    local visualRefreshAlive = true
    local function visualFeaturesActive()
        return (OverrideAppearance and OverrideAppearance.Enabled) or (HighlightESP and HighlightESP.Enabled)
    end
    local function unwatchCharacter(character)
        local record = appearanceWatchers[character]
        if not record then return end
        record.Alive = false
        for _, connection in ipairs(record.Connections) do connection:Disconnect() end
        appearanceWatchers[character] = nil
    end
    local function queueCharacterVisual(character)
        local record = appearanceWatchers[character]
        if not record or record.Queued then return end
        record.Queued = true
        task.defer(function()
            record.Queued = false
            if not visualRefreshAlive or not record.Alive or not visualFeaturesActive() then return end
            if not character.Parent then unwatchCharacter(character); removeVisual(character); return end
            if OverrideAppearance and OverrideAppearance.Enabled then applyAppearance(character) end
            ensureVisual(character)
        end)
    end
    local function watchCharacter(character)
        if appearanceWatchers[character] then return end
        local record = {Alive=true, Connections={}}
        appearanceWatchers[character] = record
        record.Connections[#record.Connections + 1] = character.DescendantAdded:Connect(function(object)
            if object:IsA("BasePart") or object:IsA("Decal") or object:IsA("Shirt")
                or object:IsA("Pants") or object:IsA("ShirtGraphic") then queueCharacterVisual(character) end
        end)
        record.Connections[#record.Connections + 1] = character.AncestryChanged:Connect(function()
            if not character.Parent then unwatchCharacter(character); removeVisual(character) end
        end)
        local player = Players:GetPlayerFromCharacter(character)
        if player then
            record.Connections[#record.Connections + 1] = player:GetPropertyChangedSignal("Team"):Connect(function()
                queueCharacterVisual(character)
            end)
        end
    end
    local function refreshVisuals()
        if not visualFeaturesActive() then
            for character in pairs(appearanceWatchers) do unwatchCharacter(character) end
            for character in pairs(highlights) do removeVisual(character) end
            for character in pairs(effects) do removeVisual(character) end
            return
        end
        for _, character in ipairs(getCombatTargetModels()) do
            watchCharacter(character)
            queueCharacterVisual(character)
        end
    end
    mainapi:Clean(function()
        visualRefreshAlive = false
        for character in pairs(appearanceWatchers) do unwatchCharacter(character) end
        for character in pairs(highlights) do removeVisual(character) end
        for character in pairs(effects) do removeVisual(character) end
        restoreAppearance()
    end)

-- END PLEX SOURCE: shared/005_esp.lua
-- BEGIN PLEX SOURCE: modules/esp_override_appearance.lua
    OverrideAppearance = Render:AddModule({
        Name = "ESP Override Appearance",
        Colors = {Color3.fromRGB(255, 255, 255)},
        Function = function(enabled)
            if enabled then
                for _, character in ipairs(getCombatTargetModels()) do applyAppearance(character) end
            else
                restoreAppearance()
            end
            refreshVisuals()
        end
    })
    OverrideColor = OverrideAppearance:AddToggle({Name = "color", Colors = {Color3.fromRGB(255, 255, 255)}, Function = function() restoreAppearance(); for _, character in ipairs(getCombatTargetModels()) do applyAppearance(character) end end})
    OverrideMaterial = OverrideAppearance:AddToggle({Name = "material", Default = true, Function = function() restoreAppearance(); for _, character in ipairs(getCombatTargetModels()) do applyAppearance(character) end end})
    Material = OverrideAppearance:AddDropdown({Name = "material type", List = materialNames, Default = "ForceField", Function = function() restoreAppearance(); for _, character in ipairs(getCombatTargetModels()) do applyAppearance(character) end end})
    DisableAppearance = OverrideAppearance:AddDropdown({Name = "disable", List = {"decals", "clothing", "highlight"}, Default = {}, Multi = true, Function = function() restoreAppearance(); for _, character in ipairs(getCombatTargetModels()) do applyAppearance(character) end end})
    OverrideTransparency = OverrideAppearance:AddSlider({Name = "transparency", Min = 0, Max = 100, Default = 0, Suffix = "%", Function = function() restoreAppearance(); for _, character in ipairs(getCombatTargetModels()) do applyAppearance(character) end end})

-- END PLEX SOURCE: modules/esp_override_appearance.lua
-- BEGIN PLEX SOURCE: modules/esp_highlight.lua
    HighlightESP = Render:AddModule({
        Name = "ESP Highlight",
        Colors = {Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 255, 255)},
        Function = refreshVisuals
    })
