-- BEGIN PLEX SOURCE: shared/006_aim_work_budget.lua
local function newAimWorkBudget()
    local state={Status="warming up",Paused=false,Samples=0,Total=0,Baseline=0,FrameTime=0,Drop=0}
    function state:Reset()
        self.Status,self.Paused="warming up",false
        self.Notified,self.Current=false,0
        self.Samples,self.Total,self.Baseline,self.FrameTime,self.Drop=0,0,0,0,0
    end
    function state:Observe(dt,enabled,limit)
        if not enabled then self.Status="off"; return true end
        if self.Paused then return false end
        if type(dt)~="number" or dt<=0 then return false end
        if self.Samples<16 then
            self.Samples+=1
            self.Total+=dt
            if self.Samples==16 then
                self.FrameTime=self.Total/16
                self.Baseline=1/self.FrameTime
                self.Status="ready"
            end
            return false
        end
        self.FrameTime+=(dt-self.FrameTime)/8
        self.Current=1/math.max(self.FrameTime,0.000001)
        self.Drop=math.max(0,self.Baseline-self.Current)
        if self.Drop>=limit then
            self.Paused=true
            self.Status="paused: FPS budget exceeded"
            return false
        end
        self.Status="ready"
        return true
    end
    return state
end

