    local aimDynamics = {}

    -- Sample speed variation at a fixed cadence, then blend it on Heartbeat.
    -- Target acquisition time is separate from scans so cached targets retain
    -- their reaction deadline while firing.
    local function updateAimDynamics(state, target, now, dt, reactionMs, randomness)
        if state.Target ~= target then
            state.Target, state.Since, state.NextSample = target, now, 0
            state.Speed = 1
        end
        local amount = math.clamp(randomness / 100, 0, 1)
        if amount == 0 then
            state.Speed, state.SpeedGoal = 1, 1
        else
            if now >= state.NextSample then
                state.SpeedGoal = 1 + (math.random() * 2 - 1) * amount
                state.NextSample = now + 0.25
            end
            state.Speed += (state.SpeedGoal - state.Speed) * (1 - math.exp(-math.max(dt, 0) * 8))
        end
        return now - state.Since >= math.max(reactionMs, 0) / 1000, state.Speed
    end

    local function aimPointOnSurface(part, ray, reduction)
        local centerDistance = math.max(0, (part.Position - ray.Origin):Dot(ray.Direction))
        local localPoint = part.CFrame:PointToObjectSpace(ray.Origin + ray.Direction * centerDistance)
        local half = part.Size * (0.5 * (1 - math.clamp(reduction, 0, 100) / 100))
        return part.CFrame:PointToWorldSpace(Vector3.new(
            math.clamp(localPoint.X, -half.X, half.X),
            math.clamp(localPoint.Y, -half.Y, half.Y),
            math.clamp(localPoint.Z, -half.Z, half.Z)))
    end
