    local aimRuntime={Requested=true,Active=false,Revision=0,Plan={},Stats={Scans=0,Plans=0,CurveBakes=0}}
    aimRuntime.Budget=newAimWorkBudget()
    function aimRuntime:ClearMouse()
        self.MouseX,self.MouseY,self.MouseElapsed=0,0,0
    end
    function aimRuntime:MoveMouse(x,y,dt)
        if type(self.MouseMove)~="function" or x~=x or y~=y or math.abs(x)==math.huge or math.abs(y)==math.huge then return end
        self.MouseX=(self.MouseX or 0)+x
        self.MouseY=(self.MouseY or 0)+y
        self.MouseElapsed=(self.MouseElapsed or 0)+math.clamp(dt,0,0.05)
        if self.MouseElapsed<1/120 then return end
        self.MouseElapsed=self.MouseElapsed%(1/120)
        local dx,dy=math.round(self.MouseX),math.round(self.MouseY)
        if dx==0 and dy==0 then return end
        self.MouseX-=dx
        self.MouseY-=dy
        self.MouseMove(dx,dy)
        self.Stats.MouseCalls=(self.Stats.MouseCalls or 0)+1
    end
