    local gradState = {}

    local CURVE_PRESETS = {
        ["Linear"] = {0, 0.14, 0.29, 0.43, 0.57, 0.71, 0.86, 1},
        ["Ease In"] = {0, 0.02, 0.08, 0.18, 0.33, 0.52, 0.75, 1},
        ["Ease Out"] = {0, 0.25, 0.48, 0.67, 0.82, 0.92, 0.98, 1},
        ["Smooth"] = {0, 0.055, 0.20, 0.395, 0.605, 0.80, 0.945, 1},
        ["Aggressive"] = {0, 0.10, 0.30, 0.62, 0.86, 0.96, 0.995, 1},
        ["Humanized"] = {0, 0.08, 0.24, 0.50, 0.66, 0.58, 0.88, 1},
    }

    local function copyCurvePreset(name)
        local source = CURVE_PRESETS[name] or CURVE_PRESETS.Linear
        local out = {}
        for i, value in ipairs(source) do out[i] = value end
        return out
    end

    local function sampleCurve(editor, alpha)
        alpha = math.clamp(tonumber(alpha) or 0, 0, 1)
        local points = editor and editor.Value
        if type(points) ~= "table" or #points < 2 then return alpha end
        local scaled = alpha * (#points - 1)
        local index = math.clamp(math.floor(scaled) + 1, 1, #points - 1)
        local frac = scaled - math.floor(scaled)
        local a = math.clamp(tonumber(points[index]) or 0, 0, 1)
        local b = math.clamp(tonumber(points[index + 1]) or 1, 0, 1)
        return a + (b - a) * frac
    end

    function aimRuntime:Predict(part, position, cameraFrame, now, duration, tolerance, editor)
        local plan=self.Plan
        local velocity=part.AssemblyLinearVelocity
        local elapsed=plan.Start and math.max(0,now-plan.Start) or 0
        local changed=plan.Part~=part or plan.Revision~=self.Revision
        local drift=false
        if not changed then
            local expected=plan.Position+plan.Velocity*elapsed
            drift=(position-expected).Magnitude>tolerance or (velocity-plan.Velocity).Magnitude>8
            plan.Deviations=drift and (plan.Deviations or 0)+1 or 0
        end
        if changed or (drift and plan.Deviations>=2) then
            if self.CurveRevision~=self.Revision then
                local samples=self.CurveSamples or table.create(33)
                local first=sampleCurve(editor,0)
                local span=sampleCurve(editor,1)-first
                for i=0,32 do
                    local t=i/32
                    samples[i+1]=math.abs(span)>0.0001 and math.clamp((sampleCurve(editor,t)-first)/span,0,1) or t
                end
                samples[1],samples[33]=0,1
                self.CurveSamples,self.CurveRevision=samples,self.Revision
                self.Stats.CurveBakes+=1
            end
            duration=math.clamp(duration,0.02,0.5)
            local distance=math.max((position-cameraFrame.Position).Magnitude,1)
            plan.From=cameraFrame.Position+cameraFrame.LookVector*distance
            plan.To=position+velocity*duration
            plan.Part,plan.Position,plan.Velocity=part,position,velocity
            plan.Start,plan.Duration,plan.Revision,plan.Deviations=now,duration,self.Revision,0
            self.Stats.Plans+=1
            elapsed=0
        end
        if elapsed>=plan.Duration then return plan.To+plan.Velocity*elapsed end
        local sample=math.clamp(elapsed/plan.Duration,0,1)*32
        local index=math.min(math.floor(sample)+1,32)
        local samples=self.CurveSamples
        local progress=samples[index]+(samples[index+1]-samples[index])*(sample-(index-1))
        return plan.From:Lerp(plan.To+plan.Velocity*elapsed,progress)
    end

    local moveConst = Vector2.new(1, 0.77) * math.rad(0.5)

    local function removeCircle()
        if CircleObject then
            pcall(function()
