        end

        if not CircleObject and Drawing then
            CircleObject = Drawing.new("Circle")
            CircleObject.Filled = false
            CircleObject.Color = (RangeCircle and RangeCircle.Value) or Color3.fromRGB(255,255,255)
            CircleObject.Radius = FOV and FOV.Value or 100
            CircleObject.Transparency = 1
            CircleObject.Thickness = 2
            CircleObject.Visible = false
        end
    end

    local function getThreeColors(option)
        if option and option.Colors then
            return option.Colors[1] or Color3.new(), option.Colors[2] or Color3.new(), option.Colors[3] or Color3.new()
        end
        return Color3.new(), Color3.new(), Color3.new()
    end

    local function getThreeTransparency(option)
        if option and option.ColorTransparency then
            return option.ColorTransparency[1] or 0, option.ColorTransparency[2] or 0, option.ColorTransparency[3] or 0
        end
        return 0, 0, 0
    end

    local function updateGradientGui(center, radius, option, visible)
        if not FillCircleObject or not FillGradientObject then return end
        if FillCircleObject.Visible ~= visible then FillCircleObject.Visible = visible end
        if not visible then return end
        local a, b, c = getThreeColors(option)
        local ta, tb, tc = getThreeTransparency(option)
        local gs = gradState
        if gs.obj ~= FillGradientObject then
            table.clear(gs)
            gs.obj = FillGradientObject
        end
        if gs.cx ~= center.X or gs.cy ~= center.Y then
            gs.cx, gs.cy = center.X, center.Y
            FillCircleObject.Position = UDim2.fromOffset(center.X, center.Y)
        end
        if gs.r ~= radius then
            gs.r = radius
            FillCircleObject.Size = UDim2.fromOffset(radius * 2, radius * 2)
        end
        if gs.a ~= a or gs.b ~= b or gs.c ~= c then
            gs.a, gs.b, gs.c = a, b, c
            FillGradientObject.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, a),
                ColorSequenceKeypoint.new(0.5, b),
                ColorSequenceKeypoint.new(1, c),
            })
        end
        if gs.ta ~= ta or gs.tb ~= tb or gs.tc ~= tc then
            gs.ta, gs.tb, gs.tc = ta, tb, tc
            local opacity = 0.46
            FillGradientObject.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 1 - (opacity * (1 - ta))),
                NumberSequenceKeypoint.new(0.5, 1 - (opacity * (1 - tb))),
                NumberSequenceKeypoint.new(1, 1 - (opacity * (1 - tc))),
            })
        end
        local rotation = RotationValue and RotationValue.Value or 0
        if MovingRotation and MovingRotation.Enabled then
            rotation += os.clock() * 360 * (RotationSpeed and RotationSpeed.Value or 1)
        end
        FillGradientObject.Rotation = rotation % 360
    end

    local function tweenFOVPosition(target, dt)
        if not FOVVisualPosition then
            FOVVisualPosition = target
            return target
        end
        local progress = math.clamp((dt or 0) / 0.18, 0, 1)
        local alpha = TweenService:GetValue(progress, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        FOVVisualPosition = FOVVisualPosition:Lerp(target, alpha)
        if (FOVVisualPosition - target).Magnitude < 0.1 then FOVVisualPosition = target end
        return FOVVisualPosition
    end

    local function gradientColor(a, b, c)
        if a and a.Colors then
            a, b, c = a.Colors[1], a.Colors[2], a.Colors[3]
        end
        local function asColor(value, fallback)
            if typeof(value) == "Color3" then
                return value
            end
            if type(value) == "table" and typeof(value.Value) == "Color3" then
                return value.Value
            end
            return fallback or Color3.fromRGB(255, 255, 255)
        end
        a = asColor(a)
        b = asColor(b, a)
        c = asColor(c, b)
        local t = (tick() * 0.25) % 1
        if t < 0.5 then
            return a:Lerp(b, t * 2)
        end
        return b:Lerp(c, (t - 0.5) * 2)
    end

    local function gradientColorAt(option, alpha)
        local a, b, c = getThreeColors(option)
        alpha = math.clamp(alpha or 0, 0, 1)
        if alpha < 0.5 then
            return a:Lerp(b, alpha * 2)
        end
        return b:Lerp(c, (alpha - 0.5) * 2)
    end

    local function hideDrawingLines(lines, startIndex)
        for i = startIndex or 1, #lines do
            if lines[i] then
                lines[i].Visible = false
            end
        end
    end

    local function getDrawingLine(lines, index)
        local line = lines[index]
        if not line and Drawing then
            line = Drawing.new("Line")
            line.Visible = false
            lines[index] = line
        end
        return line
    end

    local function updateGradientFill(lines, center, radius, option, visible, transparency)
        local count = math.clamp(math.floor(radius * 3), 240, 520)
        if not visible then
            hideDrawingLines(lines)
            return
        end
        local drawRadius = math.max(radius - 1.25, 1)
        local step = (drawRadius * 2) / count
        for i = 1, count do
            local alpha = (i - 1) / math.max(count - 1, 1)
            local x = -drawRadius + (step * (i - 0.5))
            local h = math.sqrt(math.max((drawRadius * drawRadius) - (x * x), 0)) * 2
            local line = getDrawingLine(lines, i)
            if line then
                line.From = Vector2.new(center.X + x, center.Y - (h / 2))
                line.To = Vector2.new(center.X + x, center.Y + (h / 2))
                line.Color = gradientColorAt(option, alpha)
                line.Transparency = transparency
                line.Thickness = math.max(1, step + 0.15)
                line.Visible = true
            end
        end
        hideDrawingLines(lines, count + 1)
    end

    local function updateGradientOutline(lines, center, radius, option, visible, thickness, transparency)
        local count = math.clamp(math.floor(radius * 2), 160, 320)
        if not visible then
            hideDrawingLines(lines)
            return
        end
        for i = 1, count do
            local a1 = ((i - 1) / count) * math.pi * 2
            local a2 = (i / count) * math.pi * 2
            local drawRadius = radius
            local x1, y1 = math.cos(a1) * drawRadius, math.sin(a1) * drawRadius
            local x2, y2 = math.cos(a2) * drawRadius, math.sin(a2) * drawRadius
            local alpha = ((x1 / drawRadius) + 1) * 0.5
            local line = getDrawingLine(lines, i)
            if line then
                line.From = Vector2.new(center.X + x1, center.Y + y1)
                line.To = Vector2.new(center.X + x2, center.Y + y2)
                line.Color = gradientColorAt(option, alpha)
                line.Transparency = transparency
                line.Thickness = thickness
                line.Visible = true
            end
        end
        hideDrawingLines(lines, count + 1)
    end

    mainapi:Clean(removeCircle)
    mainapi:Clean(LocalPlayer.OnTeleport:Connect(removeCircle))

    local function wrapAngle(num)
        num = num % math.pi
        num -= num >= (math.pi / 2) and math.pi or 0
        num += num < -(math.pi / 2) and math.pi or 0
        return num
    end

    local aimPartsCache = setmetatable({}, {__mode = "k"})
    local aimPartNames = {"Head", "UpperTorso", "Torso", "HumanoidRootPart", "LowerTorso", "LeftUpperArm", "RightUpperArm", "LeftUpperLeg", "RightUpperLeg"}
    local function getAimParts(char)
        local parts = {}
        if not char then return parts end
        local now = os.clock()
        local cached = aimPartsCache[char]
        if cached and now < cached.Expires then
            local valid = true
            for _, part in ipairs(cached.Parts) do
                if not part.Parent or not part:IsDescendantOf(char) then valid = false break end
            end
            if valid then return cached.Parts end
        end
        for _, name in ipairs(aimPartNames) do
            local part = char:FindFirstChild(name, true)
            if part and part:IsA("BasePart") then
                table.insert(parts, part)
            end
        end
        if #parts == 0 then
            local fallback = getCombatTargetAimPart(char)
            if fallback then table.insert(parts, fallback) end
        end
        aimPartsCache[char] = {Parts = parts, Expires = now + 1}
        return parts
    end

    local fighterController
    local function getLocalFighter()
        if not fighterController then
            local ok, fighter = pcall(function()
                return require(LocalPlayer.PlayerScripts.Controllers.FighterController)
            end)
            if ok then fighterController = fighter end
        end
        return fighterController and fighterController.LocalFighter or nil
    end

    function aimRuntime:InputMode()
        return mainapi:ResolveCombatMode(AimInputMode and AimInputMode.Value or "Auto")
    end
    local function canMoveMouse()
        return mainapi:CanUseCombatInput(aimRuntime:InputMode())
            and getLocalFighter() ~= nil
    end

    local cachedMuzzleAt, cachedMuzzlePos, cachedMuzzleCamera = 0, nil, nil
    local function getMuzzleScreenPosition(camera)
        local now = os.clock()
        if camera == cachedMuzzleCamera and now < cachedMuzzleAt then return cachedMuzzlePos end
        cachedMuzzleAt, cachedMuzzleCamera = now + 0.08, camera
        local muzzle
        local fighter = getLocalFighter()
        local item = fighter and fighter.EquippedItem
        pcall(function()
            if item and item.ViewModel and item.ViewModel.GetMuzzlePosition then
                muzzle = item.ViewModel:GetMuzzlePosition()
            end
        end)
        if not muzzle then
            pcall(function()
                local viewModels = workspace:FindFirstChild("ViewModels")
                if viewModels then
                    for _, model in viewModels:GetChildren() do
                        if model:IsA("Model") and model.Name:find(LocalPlayer.Name, 1, true) then
                            local part = model:FindFirstChild("Muzzle", true)
                                or model:FindFirstChild("Barrel", true)
                                or model:FindFirstChild("Handle", true)
                            if part and part:IsA("BasePart") then
                                muzzle = part.Position
                                break
                            elseif part and part:IsA("Attachment") then
                                muzzle = part.WorldPosition
                                break
                            end
                        end
                    end
                end
            end)
        end
        if muzzle and camera then
            local pos, visible = camera:WorldToViewportPoint(muzzle)
            if visible then
                cachedMuzzlePos = Vector2.new(pos.X, pos.Y)
                return cachedMuzzlePos
            end
        end
        cachedMuzzlePos = nil
    end

    local function getFOVOrigin(part)
        local mode = FOVPosition and FOVPosition.Value or ""
        local origin
        if mode == "position on target" and part then
            local pos, visible = Camera:WorldToViewportPoint(part.Position)
            if visible then origin = Vector2.new(pos.X, pos.Y) end
        end
        if not origin and mode == "position on barrel" and Camera then
            origin = getMuzzleScreenPosition(Camera)
        end
        if not origin and Camera then
            local viewport = Camera.ViewportSize
            origin = Vector2.new(viewport.X / 2, viewport.Y / 2)
        end
        origin = origin or UserInputService:GetMouseLocation()
        return origin
    end

    local function aimShouldBlockShotForKatana(target)
        local blocker = rawget(_G, "ShouldBlockShotForKatana")
        if type(blocker) == "function" then
            local ok, blocked = pcall(blocker, target)
            if ok then
                return blocked == true
            end
        end

        local player = typeof(target) == "Instance" and Players:GetPlayerFromCharacter(target)
        local deflecting = rawget(_G, "LionSilentDeflecting")
        local expires = player and type(deflecting) == "table" and deflecting[player.UserId]
        if expires and expires > tick() then
            return true
        end
        if player and expires and type(deflecting) == "table" then
            deflecting[player.UserId] = nil
        end
        return false
    end
    local aimStaticCheckCache = setmetatable({}, {__mode = "k"})
    aimRuntime.ClearChecks=function() table.clear(aimStaticCheckCache) end
    local function getAimStaticChecks(char)
        local cached=aimStaticCheckCache[char]
        if cached then return cached end
        cached={}
        local function refresh()
            if aimStaticCheckCache[char]~=cached or not char.Parent then return end
            cached.Protected=char:FindFirstChild("InvincibilityParticles",true)~=nil
            cached.Shield=char:FindFirstChild("Riot Shield",true)~=nil or char:FindFirstChild("RiotShield",true)~=nil
        end
        aimStaticCheckCache[char]=cached
        refresh()
        local function changed(object)
            if object.Name~="InvincibilityParticles" and object.Name~="Riot Shield" and object.Name~="RiotShield" then return end
            if cached.Pending then return end
            cached.Pending=true
            task.defer(function() cached.Pending=false; refresh() end)
        end
        AimAssist:Clean(char.DescendantAdded:Connect(changed))
        AimAssist:Clean(char.DescendantRemoving:Connect(changed))
        return cached
    end


    -- ???ENTITYLIB ?????????
    local function getClosestTarget()
        local closest
        local closestDist = math.huge
        local baseOrigin = getFOVOrigin()
        local wallParams = sharedRayParams
        wallParams.FilterDescendantsInstances = {LocalPlayer.Character, Camera}
        local fovValue = FOV.Value

        for _,char in ipairs(getCombatTargetModels({
            WorkingDummy = AimWorkingDummy and AimWorkingDummy.Enabled,
            RangeTargets = AimRangeTargets and AimRangeTargets.Enabled
        })) do
            if char ~= LocalPlayer.Character then
                local plr = Players:GetPlayerFromCharacter(char)

                if char and isCombatTargetAlive(char) then
                    if AimTeamCheck and AimTeamCheck.Enabled and plr and plr.Team and LocalPlayer.Team and not plr.Neutral and not LocalPlayer.Neutral and plr.Team == LocalPlayer.Team then continue end
                    local root = getCombatTargetRoot(char)
                    local myRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if AimDistanceMode and AimDistanceMode.Value == "limit distance" and (not root or not myRoot or (root.Position - myRoot.Position).Magnitude > AimMaxDistance.Value) then continue end
                    if plr and AimProtectedCheck and AimProtectedCheck.Enabled and getAimStaticChecks(char).Protected then continue end
                    if plr and AimKatanaCheck and AimKatanaCheck.Enabled and aimShouldBlockShotForKatana(char) then continue end
                    if plr and AimShieldCheck and AimShieldCheck.Enabled and root and myRoot then
                        local shield = getAimStaticChecks(char).Shield
                        local toward = myRoot.Position - root.Position
                        if shield and toward.Magnitude > 0 and root.CFrame.LookVector:Dot(toward.Unit) > 0 then continue end
                    end
                    local part = getCombatTargetAimPart(char, "Head")
                    local bestPartDist = math.huge
                    if (ClosestPart and ClosestPart.Enabled) or (Legitbot and Legitbot.Enabled and LegitNearest and LegitNearest.Enabled) then
                        for _, aimPart in ipairs(getAimParts(char)) do
                            local screenPos, screenVisible = Camera:WorldToViewportPoint(aimPart.Position)
                            if screenVisible then
                                local screenDist = (Vector2.new(screenPos.X, screenPos.Y) - baseOrigin).Magnitude
                                if screenDist < bestPartDist then
                                    bestPartDist = screenDist
                                    part = aimPart
                                end
                            end
                        end
                    end

                    if part then
                        local pos, visible = Camera:WorldToViewportPoint(part.Position)

                        if visible or (AimVisibleCheck and not AimVisibleCheck.Enabled and pos.Z > 0) then
                            local dist = (Vector2.new(pos.X,pos.Y) - baseOrigin).Magnitude
                            if dist < fovValue then
                                if ClosestPosition and ClosestPosition.Enabled and myRoot then
                                    local targetRoot = root or char:FindFirstChild("HumanoidRootPart")
                                    if targetRoot then
                                        dist = (targetRoot.Position - myRoot.Position).Magnitude
                                    end
                                end
                                if dist < closestDist then
                                    -- Only raycast candidates inside the FOV that can improve
                                    -- the selection; cached-target checks retain their own cadence.
                                    if (AimWallCheck and AimWallCheck.Enabled) or (Legitbot and Legitbot.Enabled and LegitVisible and LegitVisible.Enabled) then
                                        local hit = workspace:Raycast(Camera.CFrame.Position, part.Position - Camera.CFrame.Position, wallParams)
                                        if not hit or not hit.Instance:IsDescendantOf(char) then continue end
                                    end
                                    closestDist = dist
                                    closest = {
                                        Player = plr,
                                        Character = char,
                                        Part = part,
                                        ScreenDistance = dist
                                    }
                                end
                            end
                        end
                    end
                end
            end
        end

        return closest
    end

    local function cachedAimTargetValid(ent, now)
        Camera = workspace.CurrentCamera
        if not (Camera and ent and ent.Character and ent.Part) then return false end
        local char, part = ent.Character, ent.Part
        if not char.Parent or not part.Parent or not part:IsDescendantOf(char) or not isCombatTargetAlive(char) then return false end

        local plr = ent.Player or Players:GetPlayerFromCharacter(char)
        if AimTeamCheck and AimTeamCheck.Enabled and plr and plr.Team and LocalPlayer.Team and not plr.Neutral and not LocalPlayer.Neutral and plr.Team == LocalPlayer.Team then
            return false
        end

        local root = getCombatTargetRoot(char)
        local myRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if AimDistanceMode and AimDistanceMode.Value == "limit distance" and (not root or not myRoot or (root.Position - myRoot.Position).Magnitude > AimMaxDistance.Value) then
            return false
        end
        if plr and AimProtectedCheck and AimProtectedCheck.Enabled and getAimStaticChecks(char).Protected then return false end
        if plr and AimKatanaCheck and AimKatanaCheck.Enabled and aimShouldBlockShotForKatana(char) then return false end
        if plr and AimShieldCheck and AimShieldCheck.Enabled and root and myRoot then
            local shield = getAimStaticChecks(char).Shield
            local toward = myRoot.Position - root.Position
            if shield and toward.Magnitude > 0 and root.CFrame.LookVector:Dot(toward.Unit) > 0 then return false end
        end

        local point, visible = Camera:WorldToViewportPoint(part.Position)
        if (AimVisibleCheck and AimVisibleCheck.Enabled and not visible) or point.Z <= 0 then return false end
        local origin = getFOVOrigin()
        local distance = (Vector2.new(point.X, point.Y) - origin).Magnitude
        if distance > FOV.Value then return false end

        if (AimWallCheck and AimWallCheck.Enabled) or (Legitbot and Legitbot.Enabled and LegitVisible and LegitVisible.Enabled) then
            local originPosition=Camera.CFrame.Position
            local targetPosition=part.Position
            if cachedAimWallTarget~=char or not cachedAimWallOrigin
                or (originPosition-cachedAimWallOrigin).Magnitude>0.5
                or (targetPosition-cachedAimWallPosition).Magnitude>0.5 then
                cachedAimWallTarget,cachedAimWallOrigin,cachedAimWallPosition=char,originPosition,targetPosition
                sharedRayParams.FilterDescendantsInstances={LocalPlayer.Character,Camera}
                local hit=workspace:Raycast(originPosition,targetPosition-originPosition,sharedRayParams)
                cachedAimWallOk=not hit or hit.Instance:IsDescendantOf(char)
            end
            if not cachedAimWallOk then return false end
        end

        return true
    end

-- END PLEX SOURCE: shared/006_aim_assist.lua
-- BEGIN PLEX SOURCE: modules/aim_assist.lua
    AimAssist = Combat:AddModule({
        Name = "Aim Assist",
        Function = function(enabled)
            if enabled and (not AimAssist or not AimAssist.Enabled or mainapi.Uninjecting) then return end
            aimRuntime:Reset()
            if not enabled then
                table.clear(aimDynamics)
                cachedAimTarget = nil
                cachedAimWallTarget = nil

            end
            if enabled and RangeCircle and RangeCircle.Enabled then
                ensureCircle()
            end

            if CircleObject then
                CircleObject.Visible = enabled and RangeCircle and RangeCircle.Enabled or false
            end

            if enabled then

                local rightClicked = not RightClick.Enabled
                local gameSettings = UserSettings():GetService("UserGameSettings")
                local legitItem, legitIsSniper
                local lastObj, lastPos, lastVis, lastRad, lastCol, lastThick
                local nextFOVVisualUpdate, fovVisualDelta = 0, 0
                local budgetHidden=false

                AimAssist:Clean(RunService.Heartbeat:Connect(function(dt)
                    if not AimAssist.Enabled or mainapi.Uninjecting then aimRuntime:ClearMouse(); return end
                    if mainapi.ClickGuiStatus then aimRuntime:ClearMouse(); return end
                    if not canMoveMouse() then
                        aimRuntime.Active=false
                        aimRuntime:ClearMouse()
                        LastTargetPosition=nil
                        return
                    end
                    if not aimRuntime.Budget:Observe(dt,AimFpsGuard and AimFpsGuard.Enabled,
                        AimFpsDropLimit and AimFpsDropLimit.Value or 20) then
                        aimRuntime:ClearMouse()
                        if aimRuntime.Budget.Paused and not aimRuntime.Budget.Notified then
                            aimRuntime.Budget.Notified=true
                            mainapi:Notify({Title="Aim Assist paused",Text="FPS budget exceeded. Use resume / recalibrate aim to restart.",Duration=5})
                        end
                        if not budgetHidden then
                            budgetHidden=true
                            LastTargetPosition=nil
                            if CircleObject then CircleObject.Visible=false end
                            if FillCircleObject then FillCircleObject.Visible=false end
                            hideDrawingLines(FillGradientLines)
                            hideDrawingLines(OutlineGradientLines)
                            lastVis=false
                        end
                        return
                    end
                    budgetHidden=false
                    Camera = workspace.CurrentCamera
                    if not Camera then return end
                    local now = os.clock()
                    fovVisualDelta = math.min(fovVisualDelta + dt, 0.18)
                    if now >= nextFOVVisualUpdate and (RangeCircle.Enabled or lastVis) then
                        nextFOVVisualUpdate = now + 1 / 30
                        local fovTarget = FOVPosition and FOVPosition.Value == "position on target" and LastTargetPosition and {Position = LastTargetPosition} or nil
                        local fovPos = tweenFOVPosition(getFOVOrigin(fovTarget), fovVisualDelta)
                        fovVisualDelta = 0
                        local radius = FOV.Value
                        local visible = AimAssist.Enabled and RangeCircle.Enabled

                        updateGradientGui(fovPos, radius, CircleFilled, visible and CircleFilled and CircleFilled.Enabled)
                        if CircleObject then
                            if lastObj ~= CircleObject then
                                lastObj, lastPos, lastVis, lastRad, lastCol, lastThick = CircleObject
                                CircleObject.Transparency = 1
                                CircleObject.Filled = false
                            end
                            if lastPos ~= fovPos then lastPos = fovPos CircleObject.Position = fovPos end
                            if lastVis ~= visible then lastVis = visible CircleObject.Visible = visible end
                            if lastRad ~= radius then lastRad = radius CircleObject.Radius = radius end
                            local col = select(2, getThreeColors(Outline and Outline.Enabled and Outline or RangeCircle))
                            if lastCol ~= col then lastCol = col CircleObject.Color = col end
                            local thick = Outline and Outline.Enabled and 2 or 1
                            if lastThick ~= thick then lastThick = thick CircleObject.Thickness = thick end
                        end
                    end
                    if RightClick.Enabled and not (rightClicked or mainapi:IsCombatInputDown(Enum.UserInputType.MouseButton2)) then
                        LastTargetPosition = nil
                        aimRuntime.Active=false
                        return
                    end

                    if not mainapi:IsCombatScopeAllowed(AimAssist) or (Legitbot and Legitbot.Enabled and not mainapi:IsCombatScopeAllowed(Legitbot)) then
                        aimRuntime.Active=false
                        aimRuntime:ClearMouse()
                        LastTargetPosition=nil
                        return
                    end
                    aimRuntime.Active=true
                    local ent = cachedAimTarget
                    if ent and not cachedAimTargetValid(ent, now) then
                        aimRuntime:ClearMouse()
                        aimRuntime.InvalidSamples=(aimRuntime.InvalidSamples or 0)+1
                        LastTargetPosition=nil
                        local removed=not ent.Character.Parent or not ent.Part.Parent
                        if not removed and aimRuntime.InvalidSamples<3 then return end
                        cachedAimTarget=nil
                        cachedAimWallTarget=nil
                        ent=nil
                        aimRuntime.InvalidSamples=0
                        aimRuntime:Invalidate()
                    else
                        aimRuntime.InvalidSamples=0
                    end

                    if not ent and aimRuntime.Requested and not mainapi:IsCombatFiring() then
                        aimRuntime.Requested=false
                        aimRuntime.Stats.Scans+=1
                        cachedAimTarget=getClosestTarget()
                        ent=cachedAimTarget
                        cachedAimWallTarget=nil
                    end

                    if ent then
                        local part = ent.Part
                        local partPos = part.Position
                        local camCF = Camera.CFrame
                        local legit = Legitbot and Legitbot.Enabled
                        local origin = getFOVOrigin()
                        local ready, speedMultiplier = updateAimDynamics(aimDynamics, ent.Character, now, dt,
                            AimReactionTime and AimReactionTime.Value or 0, AimSpeedRandomness and AimSpeedRandomness.Value or 0)
                        if not ready then aimRuntime:ClearMouse(); LastTargetPosition=nil; return end
                        local reduction = AimSurfaceReduction and AimSurfaceReduction.Value or 100
                        if reduction < 100 then
                            partPos = aimPointOnSurface(part, Camera:ViewportPointToRay(origin.X, origin.Y), reduction)
                        end

                        if legit then
                            if ent.Character ~= legitLastTarget then
                                legitLastTarget = ent.Character
                                legitTargetSince = now
                            end
                            if LegitShooting and LegitShooting.Enabled and not mainapi:IsCombatInputDown(Enum.UserInputType.MouseButton1) then
                                aimRuntime:ClearMouse()
                                LastTargetPosition = nil
                                return
                            end
                        end

                        local screen = Camera:WorldToViewportPoint(partPos)
                        local pixels = (Vector2.new(screen.X, screen.Y) - origin).Magnitude
                        if legit and pixels <= (LegitDeadzone and LegitDeadzone.Value or 0) then aimRuntime:ClearMouse(); return end

                        if ShowTarget.Enabled then
                            Targetinfo.Targets[ent] = tick() + 1
                        end

                        local targetPosition = partPos
                        local vel = part.AssemblyLinearVelocity
                        if DelayPosition and DelayPosition.Enabled then
                            targetPosition += vel * math.clamp((Speed and Speed.Value or 100) / 1000, 0, 0.2)
                        end
                        if JumpSmoothing and JumpSmoothing.Value then
                            targetPosition += Vector3.new(0, vel.Y * ((JumpSmoothing.Value or 100) / 100) * dt, 0)
                        end
                        local predict=AimType and AimType.Value=="Predict"
                        if predict then
                            targetPosition=aimRuntime:Predict(part,targetPosition,camCF,now,
                                (AimPredictionTime and AimPredictionTime.Value or 150)/1000,
                                AimPredictionTolerance and AimPredictionTolerance.Value or 2,AimCurveEditor)
                        end
                        LastTargetPosition = targetPosition

                        local toTarget = targetPosition - camCF.Position
                        if toTarget.Magnitude > 1e-3 then
                            local fraction = math.clamp(pixels / math.max(FOV.Value, 1), 0, 1)
                            local factor = math.min(((Speed and Speed.Value or 100) / 100) * speedMultiplier * (Lerp and Lerp.Value or 1) * dt * 10, 1)
                            if not predict then
                                factor *= math.clamp(sampleCurve(AimCurveEditor, fraction) * 1.35, 0.06, 1)
                            end
                            if legit then
                                local ramp = (LegitRamp and LegitRamp.Value or 0) / 1000
                                if ramp > 0 then factor *= math.clamp((now - legitTargetSince) / ramp, 0.08, 1) end
                                factor *= math.clamp(fraction ^ (1 + (LegitCurve and LegitCurve.Value or 0) / 100), 0.08, 1)
                                factor /= math.max(LegitSmoothing and LegitSmoothing.Value or 1, 1)
                                local fighter = getLocalFighter()
                                local item = fighter and fighter.EquippedItem
                                if item ~= legitItem then
                                    legitItem = item
                                    local itemName = item and tostring(item.Name or ""):lower() or ""
                                    legitIsSniper = itemName:find("sniper", 1, true) ~= nil or itemName:find("rifle", 1, true) ~= nil
                                end
                                if legitIsSniper then
                                    factor /= math.max(LegitSniper and LegitSniper.Value or 1, 1)
                                end
                            end
                            if aimRuntime:InputMode()=="Camera" then
                                aimRuntime:ClearMouse()
                                mainapi:MoveCombatCamera(targetPosition, factor, (YSmooth and YSmooth.Value or 100) / 100, (XSmooth and XSmooth.Value or 100) / 100)
                            else
                                local facing = camCF.LookVector
                                local new = toTarget.Unit
                                local diffYaw = wrapAngle(math.atan2(facing.X, facing.Z) - math.atan2(new.X, new.Z))
                                local diffPitch = math.asin(math.clamp(facing.Y, -1, 1)) - math.asin(math.clamp(new.Y, -1, 1))
                                local angle = Vector2.new(diffYaw, diffPitch) / (moveConst * gameSettings.MouseSensitivity)
                                angle = Vector2.new(angle.X * ((XSmooth and XSmooth.Value or 100) / 100), angle.Y * ((YSmooth and YSmooth.Value or 100) / 100))

                                angle *= factor
                                aimRuntime:MoveMouse(angle.X,angle.Y,dt)
                            end
                        end
                    else
                        aimRuntime:ClearMouse()
                        table.clear(aimDynamics)
                        LastTargetPosition = nil
                    legitLastTarget = nil
                    end

                end))


                if RightClick.Enabled then

                    AimAssist:Clean(
                        UserInputService.InputBegan:Connect(function(input, processed)

                            if input.UserInputType == Enum.UserInputType.MouseButton2 and not processed then
                                rightClicked = true
                            end

                        end)
                    )

                    AimAssist:Clean(
                        UserInputService.InputEnded:Connect(function(input)

                            if input.UserInputType == Enum.UserInputType.MouseButton2 then
                                rightClicked = false
                            end

                        end)
                    )

                end
            end

            if enabled then
                AimAssist:Clean(LocalPlayer.OnTeleport:Connect(removeCircle))
            else
                removeCircle()
            end
        end
    })
    AimAssist.PredictionStats=aimRuntime.Stats
    AimAssist.WorkBudget=aimRuntime.Budget
    AimFpsGuard=AimAssist:AddToggle({Name="FPS guard",Default=true,Function=function() aimRuntime.Budget:Reset() end})
    AimFpsDropLimit=AimAssist:AddSlider({Name="FPS loss limit",Min=5,Max=60,Default=20,Function=function() aimRuntime.Budget:Reset() end})
    AimAssist:AddButton({Text="resume / recalibrate aim",Func=function()
        aimRuntime.Budget:Reset()
        aimRuntime.Requested=true
    end})
    AimType=AimAssist:AddDropdown({Name="aim type",List={"Standard","Predict"},Default="Standard"})
    AimPredictionTime=AimAssist:AddSlider({Name="prediction time",Min=20,Max=500,Default=150,Suffix="ms"})
    AimPredictionTolerance=AimAssist:AddSlider({Name="prediction tolerance",Min=0.5,Max=10,Default=2,Decimal=10,Suffix="studs"})
    AimInputMode = AimAssist:AddDropdown({Name = "mode", Text="input mode", List = {"Auto", "Camera", "Mouse"}, Default = "Auto"})

    mainapi:AddCombatScopeCheck(AimAssist)

