    Outline = AimAssist:AddToggle({
        Name = "outline",
        Colors = {Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 255, 255)},
        ColorTransparency = {0, 0, 0},
        Function = function()
            if CircleObject then
                CircleObject.Thickness = Outline.Enabled and 2 or 1
            end
        end
    })

    CircleFilled = AimAssist:AddToggle({
        Name = "fill",
        Colors = {Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 255, 255)},
        ColorTransparency = {0, 0, 0},
        Function = function(val)

            hideDrawingLines(FillGradientLines)
            if FillCircleObject then
                FillCircleObject.Visible = false
            end
            if CircleObject then
                CircleObject.Filled = false
            end

        end
    })
    task.defer(function()
        if RangeCircle and RangeCircle.Enabled then
            ensureCircle()
        end
    end)

    Lerp = AimAssist:AddSlider({
        Name = "lerp",
        Min = 1,
        Max = 10,
        Default = 1,
        Decimal = 10,
        Suffix = "x"
    })

    MovingRotation = AimAssist:AddToggle({
        Name = "moving rotation"
    })

    RotationValue = AimAssist:AddSlider({
        Name = "rotation",
        Min = 0,
        Max = 360,
        Default = 0,
        Suffix = "°",
        Compact = true
    })

    RotationSpeed = AimAssist:AddSlider({
        Name = "speed",
        Min = 1,
        Max = 10,
        Default = 1,
        Decimal = 10,
        Suffix = "rps",
        Compact = true,
        Parent = RotationValue
    })

    FOVPosition = AimAssist:AddDropdown({
        Name = "fov settings",
        List = {"", "position on target", "position on barrel"},
        Default = "",
        Function = function()
            LastTargetPosition = nil
        end
    })

    FOV = AimAssist:AddSlider({
        Name = "radius",
        Text = "field of view",
        Min = 0,
        Max = 1000,
        Default = 100,
        Function = function(val)
            if FillCircleObject then
                FillCircleObject.Size = UDim2.fromOffset(val * 2, val * 2)
            end
            if CircleObject then
                CircleObject.Radius = val
            end
        end,
        Suffix = "px"
    })

    Speed = AimAssist:AddSlider({
        Name = "smoothing",
        Text = "aim speed",
        Min = 1,
        Max = 100,
        Default = 100,
        Suffix = "%"
    })

    AimSpeedRandomness = AimAssist:AddSlider({Name = "speed randomness", Min = 0, Max = 100, Default = 0, Suffix = "%"})
    AimReactionTime = AimAssist:AddSlider({Name = "reaction time", Min = 0, Max = 1000, Default = 0, Suffix = "ms"})
    AimSurfaceReduction = AimAssist:AddSlider({Name = "surface reduction", Min = 0, Max = 100, Default = 100, Suffix = "%"})

    AimCurvePreset = AimAssist:AddDropdown({
        Name = "curve preset",
        List = {"Linear", "Ease In", "Ease Out", "Smooth", "Aggressive", "Humanized", "Custom"},
        Default = "Linear",
        Function = function(value)
            if value ~= "Custom" and AimCurveEditor then
                AimCurveEditor:SetValue(copyCurvePreset(value))
            end
        end
    })
    AimCurveEditor = AimAssist:AddCurveEditor({
        Name = "custom curve",
        Text = "curve",
        Default = copyCurvePreset("Linear"),
        Height = 154,
    })
    AimAssist:AddButton({
        Text = "reset curve",
        Func = function()
            if AimCurveEditor then AimCurveEditor:SetValue(copyCurvePreset(AimCurvePreset and AimCurvePreset.Value or "Linear")) end
        end
    })


    if false then
    RightClick = AimAssist:AddToggle({
        Name = "Require right click"
    })
    end
    RightClick = {Enabled = false}


    if false then
    ShowTarget = AimAssist:AddToggle({
        Name = "Show Target",
        Visible = false
    })
    end
    ShowTarget = {Enabled = false}

    do
        local relevant={"aim type","prediction time","prediction tolerance","mode","checks","radius","fov settings",
            "distance mode","max distance","working dummy","shooting range targets","check scoped if",
            "closest part","closest position","surface reduction","smoothing","x smooth","y smooth",
            "delay position","jump smoothing","reaction time","speed randomness","lerp","custom curve","curve preset"}
        for _,name in ipairs(relevant) do
            local setting=AimAssist.Settings[name]
            if setting then
                local original=setting.Function
                setting.Function=function(...)
                    if original then original(...) end
                    aimRuntime:Invalidate()
                end
            end
        end
        for _,setting in pairs(Legitbot.Settings) do
            local original=setting.Function
            setting.Function=function(...)
                if original then original(...) end
                aimRuntime:Invalidate()
            end
        end
        local original=Legitbot.Function
        Legitbot.Function=function(...)
            if original then original(...) end
            aimRuntime:Invalidate()
        end
    end

    -- Flickbot lives on the Aimbot page but has its own right-side native tab.
    local Flickbot
    local FlickKeybind
    local FlickFOV
    local FlickShowFOV
    local FlickTargetPart
    local FlickWallCheck
    local FlickScopeCheck
    local FlickPartBlacklist
    local FlickDuration
    local FlickSpeed
    local FlickSmoothness
    local FlickRandomness
    local FlickShoot
    local FlickPredict
    local FlickPrediction
    local FlickCurvePreset
    local FlickCurveEditor
    local FlickCircle
    local flicking = false

    local FLICK_PARTS = {
        "Head", "UpperTorso", "LowerTorso", "HumanoidRootPart",
        "LeftUpperArm", "LeftLowerArm", "LeftHand",
        "RightUpperArm", "RightLowerArm", "RightHand",
        "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
        "RightUpperLeg", "RightLowerLeg", "RightFoot",
    }

    local function flickInputMatches(input, key)
        key = tostring(key or "")
        if key == "MB1" or key == "MouseButton1" then return input.UserInputType == Enum.UserInputType.MouseButton1 end
        if key == "MB2" or key == "MouseButton2" then return input.UserInputType == Enum.UserInputType.MouseButton2 end
        if key == "MB3" or key == "MouseButton3" then return input.UserInputType == Enum.UserInputType.MouseButton3 end
        return input.KeyCode and input.KeyCode.Name == key
    end

    local function flickScopedEnough()
        return mainapi:IsCombatScopeAllowed(Flickbot,nil,FlickScopeCheck and FlickScopeCheck.Enabled)
    end

    local function flickPartAllowed(part)
        if not part or not part:IsA("BasePart") then return false end
        local blacklist = FlickPartBlacklist and FlickPartBlacklist.Value or {}
        return not blacklist[part.Name]
    end

    local flickRayParams = RaycastParams.new()
    flickRayParams.FilterType = Enum.RaycastFilterType.Exclude

    local function flickHasLineOfSight(char, part)
        if not FlickWallCheck or not FlickWallCheck.Enabled then return true end
        local camera = workspace.CurrentCamera
        if not camera then return false end
        flickRayParams.FilterDescendantsInstances = {LocalPlayer.Character, camera}
        local hit = workspace:Raycast(camera.CFrame.Position, part.Position - camera.CFrame.Position, flickRayParams)
        return not hit or hit.Instance:IsDescendantOf(char)
    end

    local function getFlickPart(char, center)
        local selected = FlickTargetPart and FlickTargetPart.Value or "Head"
        if selected ~= "Closest" then
            local part = char:FindFirstChild(selected, true)
            if flickPartAllowed(part) then return part end
        end

        local camera = workspace.CurrentCamera
        local best, bestDist
        for _, name in ipairs(FLICK_PARTS) do
            local part = char:FindFirstChild(name, true)
            if flickPartAllowed(part) then
                local point, visible = camera:WorldToViewportPoint(part.Position)
                if visible and point.Z > 0 then
                    local dist = (Vector2.new(point.X, point.Y) - center).Magnitude
                    if not bestDist or dist < bestDist then
                        best, bestDist = part, dist
                    end
                end
            end
        end
        return best
    end

    local function getClosestFlickTarget()
        local camera = workspace.CurrentCamera
        if not camera then return nil end
        local center = camera.ViewportSize / 2
        local maxFov = FlickFOV and FlickFOV.Value or 300
        local best, bestPart, bestDist

        for _, char in ipairs(getCombatTargetModels({WorkingDummy = false, RangeTargets = false})) do
            if char ~= LocalPlayer.Character and isCombatTargetAlive(char) then
                local plr = Players:GetPlayerFromCharacter(char)
                if not (plr and AimTeamCheck and AimTeamCheck.Enabled and plr.Team and LocalPlayer.Team and not plr.Neutral and not LocalPlayer.Neutral and plr.Team == LocalPlayer.Team) then
                    local part = getFlickPart(char, center)
                    if part then
                        local point, visible = camera:WorldToViewportPoint(part.Position)
                        if visible and point.Z > 0 then
                            local dist = (Vector2.new(point.X, point.Y) - center).Magnitude
                            if dist <= maxFov and (not bestDist or dist < bestDist) and flickHasLineOfSight(char, part) then
                                best, bestPart, bestDist = char, part, dist
                            end
                        end
                    end
                end
            end
        end
        if best then return {Character = best, Part = bestPart} end
    end

    local function updateFlickCircle()
        if not FlickShowFOV or not FlickShowFOV.Enabled or not Flickbot or not Flickbot.Enabled or not Drawing then
            if FlickCircle then FlickCircle.Visible = false end
            return
        end
        if not FlickCircle then
            FlickCircle = Drawing.new("Circle")
            FlickCircle.Filled = false
            FlickCircle.Thickness = 1
            FlickCircle.Transparency = 1
            FlickCircle.Color = Color3.fromRGB(255, 255, 255)
        end
        local camera = workspace.CurrentCamera
        if not camera then FlickCircle.Visible = false return end
        local center, radius, vis = camera.ViewportSize / 2, FlickFOV and FlickFOV.Value or 300, not mainapi.ClickGuiStatus
        if FlickCircle.Position ~= center then FlickCircle.Position = center end
        if FlickCircle.Radius ~= radius then FlickCircle.Radius = radius end
        if FlickCircle.Visible ~= vis then FlickCircle.Visible = vis end
    end

    local function runFlick()
        if flicking or not Flickbot or not Flickbot.Enabled or not canMoveMouse() then return end
        if not flickScopedEnough() then return end
        local target = getClosestFlickTarget()
        if not target then return end
        flicking = true

        task.spawn(function()
            pcall(function()
            local started = os.clock()
            local speedScale = math.max((FlickSpeed and FlickSpeed.Value or 100) / 100, 0.05)
            local duration = math.max((FlickDuration and FlickDuration.Value or 110) / 1000 / speedScale, 0.01)
            local smooth = math.clamp((FlickSmoothness and FlickSmoothness.Value or 0) / 100, 0, 1)
            local randomness = math.clamp((FlickRandomness and FlickRandomness.Value or 0) / 100, 0, 1)
            local lastProgress = 0

            while Flickbot.Enabled and target.Character.Parent and target.Part.Parent do
                if not canMoveMouse() then break end
                local elapsed = os.clock() - started
                local alpha = math.clamp(elapsed / duration, 0, 1)
                local progress = sampleCurve(FlickCurveEditor, alpha)
                local smoothProgress = progress * progress * (3 - 2 * progress)
                progress = progress + (smoothProgress - progress) * smooth
                if randomness > 0 and alpha < 1 then
                    progress = math.clamp(progress + (math.random() - 0.5) * randomness * 0.03, 0, 1)
                end

                local camera = workspace.CurrentCamera
                if not camera or not flickScopedEnough() then break end
                local targetPosition = target.Part.Position
                if FlickPredict and FlickPredict.Enabled then
                    targetPosition += target.Part.AssemblyLinearVelocity * ((FlickPrediction and FlickPrediction.Value or 80) / 1000)
                end
                local point, visible = camera:WorldToViewportPoint(targetPosition)
                if not visible or point.Z <= 0 then break end

                local center = camera.ViewportSize / 2
                local remaining = Vector2.new(point.X, point.Y) - center
                local denom = math.max(1 - lastProgress, 0.001)
                local step = math.clamp((progress - lastProgress) / denom, -1, 1)
                if step ~= 0 then
                    if mainapi:ResolveCombatMode(AimInputMode.Value) == "Camera" then
                        mainapi:MoveCombatCamera(targetPosition, math.max(step, 0))
                    else
                        mousemoverel(remaining.X * step, remaining.Y * step)
                    end
                end
                lastProgress = progress
                if alpha >= 1 then break end
                RunService.Heartbeat:Wait()
            end

            if Flickbot.Enabled and target.Part and target.Part.Parent and canMoveMouse() then
                local camera = workspace.CurrentCamera
                if camera then
                    local targetPosition = target.Part.Position
                    if FlickPredict and FlickPredict.Enabled then
                        targetPosition += target.Part.AssemblyLinearVelocity * ((FlickPrediction and FlickPrediction.Value or 80) / 1000)
                    end
                    local point, visible = camera:WorldToViewportPoint(targetPosition)
                    if visible and point.Z > 0 then
                        local center = camera.ViewportSize / 2
                        local remaining = Vector2.new(point.X, point.Y) - center
                        if mainapi:ResolveCombatMode(AimInputMode.Value) == "Camera" then
                            mainapi:MoveCombatCamera(targetPosition, 1)
                        else
                            mousemoverel(remaining.X, remaining.Y)
                        end
                    end
                end
                if FlickShoot and FlickShoot.Enabled then
                    mainapi:FireCombatShot(AimInputMode.Value, Flickbot, getLocalFighter())
                end
            end

            end)
            flicking = false
        end)
    end

    mainapi:AddCombatScopeCheck(Legitbot)

-- END PLEX SOURCE: modules/legitbot.lua
-- BEGIN PLEX SOURCE: modules/flickbot.lua
    Flickbot = Combat:AddModule({
        Name = "Flickbot",
        Function = function(enabled)
            flicking = false
            if not enabled then mainapi:ReleaseCombatShot(Flickbot) end
            if enabled then
                Flickbot:Clean(UserInputService.InputBegan:Connect(function(input, processed)
                    if processed or mainapi.ClickGuiStatus then return end
                    if FlickKeybind and flickInputMatches(input, FlickKeybind.Value) then
                        runFlick()
                    end
                end))
                Flickbot:Clean(RunService.Heartbeat:Connect(updateFlickCircle))
            elseif FlickCircle then
                FlickCircle.Visible = false
            end
        end,
    })

    FlickKeybind = Flickbot:AddKeybind({Name = "keybind", Default = "MB3", Mode = "Hold"})
    FlickFOV = Flickbot:AddSlider({Name = "field of view", Min = 20, Max = 1000, Default = 300, Suffix = " px"})
    FlickShowFOV = Flickbot:AddToggle({Name = "draw fov circle", Default = true})
    FlickTargetPart = Flickbot:AddDropdown({Name = "target part", List = {"Head", "UpperTorso", "HumanoidRootPart", "Closest"}, Default = "Head"})
    FlickWallCheck = Flickbot:AddToggle({Name = "wall-check", Default = true})
    FlickScopeCheck = Flickbot:AddToggle({Name = "scope check", Default = false})
    FlickPartBlacklist = Flickbot:AddDropdown({Name = "part blacklist", List = FLICK_PARTS, Default = {}, Multi = true})
    FlickPredict = Flickbot:AddToggle({Name = "predict projectiles", Default = false})
    FlickPrediction = Flickbot:AddSlider({Name = "prediction lead", Min = 0, Max = 250, Default = 80, Suffix = " ms"})
    FlickDuration = Flickbot:AddSlider({Name = "flick duration", Min = 20, Max = 500, Default = 110, Suffix = " ms"})
    FlickSpeed = Flickbot:AddSlider({Name = "flick speed", Min = 10, Max = 200, Default = 50, Suffix = "%"})
    FlickSmoothness = Flickbot:AddSlider({Name = "flick smoothness", Min = 0, Max = 100, Default = 0, Suffix = "%"})
    FlickRandomness = Flickbot:AddSlider({Name = "flick randomness", Min = 0, Max = 100, Default = 0, Suffix = "%"})
    FlickShoot = Flickbot:AddToggle({Name = "shoot on flick", Default = false})
    FlickCurvePreset = Flickbot:AddDropdown({
        Name = "curve preset",
        List = {"Linear", "Ease In", "Ease Out", "Smooth", "Aggressive", "Humanized", "Custom"},
        Default = "Linear",
        Function = function(value)
            if value ~= "Custom" and FlickCurveEditor then
                FlickCurveEditor:SetValue(copyCurvePreset(value))
            end
        end
    })
    FlickCurveEditor = Flickbot:AddCurveEditor({
        Name = "custom curve",
        Text = "curve",
        Default = copyCurvePreset("Linear"),
        Height = 154,
    })
    Flickbot:AddButton({
        Text = "reset curve",
        Func = function()
            if FlickCurveEditor then FlickCurveEditor:SetValue(copyCurvePreset(FlickCurvePreset and FlickCurvePreset.Value or "Linear")) end
        end,
    })

    mainapi:AddCombatScopeCheck(Flickbot)
end)

