-------------------------------------------------
function DisableProjectileTP()
    ENABLED = false

    for _, conn in ipairs(connections) do
        pcall(function()
            conn:Disconnect()
        end)
    end

    table.clear(connections)
    table.clear(attached)

end
            else
                DisableProjectileTP()
            end
        end
    })

