run(function()

            -- Unlock All integrated with the cosmetic changer
local plrs = game:GetService("Players")
local reps = game:GetService("ReplicatedStorage")
local http = game:GetService("HttpService")
local collectionService = game:GetService("CollectionService")

local lp = plrs.LocalPlayer
if not lp then return end

local lps = lp:FindFirstChild("PlayerScripts") or lp:WaitForChild("PlayerScripts", 10)
if not lps then return end

local ctrls = lps:FindFirstChild("Controllers") or lps:WaitForChild("Controllers", 10)
local rmods = reps:FindFirstChild("Modules") or reps:WaitForChild("Modules", 10)
if not ctrls or not rmods then return end

local cosmeticStartup = {Deadline = os.clock() + 15, Pending = {}}
function cosmeticStartup.Stage(label)
    if StartupLoader and StartupLoader.Alive then
        StartupLoader:Set("cosmetics · "..label, StartupLoader.Progress)
    end
    if shared.PlexStartupDiag then shared.PlexStartupDiag("cosmetic_stage", label) end
end
-- A protected call catches errors, but cannot stop a yielding game require.
-- Only startup calls use the deadline; action callbacks keep native semantics.
function cosmeticStartup.Call(label, callback)
    if not shared.ModernLoading then return pcall(callback) end
    cosmeticStartup.Stage(label)
    local budget = math.min(5, cosmeticStartup.Deadline - os.clock())
    if budget <= 0 then return false, "cosmetic startup dependency budget exhausted: "..label end
    local wake = Instance.new("BindableEvent")
    local done, result, worker, timer = false, nil, nil, nil
    local function finish(...)
        if done then return end
        done, result = true, table.pack(...)
        cosmeticStartup.Pending[wake] = nil
        local current = coroutine.running()
        if worker and worker ~= current then pcall(task.cancel, worker) end
        if timer and timer ~= current then pcall(task.cancel, timer) end
        wake:Fire()
    end
    cosmeticStartup.Pending[wake] = finish
    worker = task.defer(function() finish(pcall(callback)) end)
    timer = task.delay(budget, function() finish(false, "timed out waiting for "..label) end)
    if not done then wake.Event:Wait() end
    wake:Destroy()
    return table.unpack(result, 1, result.n)
end
mainapi:Clean(function()
    local pending = table.clone(cosmeticStartup.Pending)
    for _, finish in pairs(pending) do finish(false, "cosmetic startup unloaded") end
end)
cosmeticStartup.Methods={}
function cosmeticStartup.QueueMethod(class,key,replacement)
    local record={Class=class,Key=key,Original=rawget(class,key),Replacement=replacement}
    table.insert(cosmeticStartup.Methods,record)
    if cosmeticStartup.MethodsActive then rawset(class,key,replacement) end
end
function cosmeticStartup.ActivateMethods()
    if cosmeticStartup.MethodsActive or mainapi.Uninjecting then return end
    cosmeticStartup.MethodsActive=true
    for _,record in ipairs(cosmeticStartup.Methods) do rawset(record.Class,record.Key,record.Replacement) end
end
mainapi:Clean(function()
    for i=#cosmeticStartup.Methods,1,-1 do
        local record=cosmeticStartup.Methods[i]
        if rawget(record.Class,record.Key)==record.Replacement then rawset(record.Class,record.Key,record.Original) end
    end
    table.clear(cosmeticStartup.Methods)
end)
function cosmeticStartup.Require(module)
    if not module then return nil end
    local ok, result = cosmeticStartup.Call(module.Name, function() return require(module) end)
    if not ok then warn("[Plex Skins] "..tostring(result)) end
    return ok and result or nil
end

local elib = cosmeticStartup.Require(rmods:WaitForChild("EnumLibrary", 10))
if elib and elib.WaitForEnumBuilder then
    local ready, why = cosmeticStartup.Call("EnumLibrary builder", function()
        elib:WaitForEnumBuilder()
    end)
    if not ready then error("[Plex Skins] "..tostring(why), 0) end
end
local clib = cosmeticStartup.Require(rmods:WaitForChild("CosmeticLibrary", 10))
local ilib = cosmeticStartup.Require(rmods:WaitForChild("ItemLibrary", 10))
local consts = cosmeticStartup.Require(rmods:WaitForChild("CONSTANTS", 10))
local dctrl = cosmeticStartup.Require(ctrls:WaitForChild("PlayerDataController", 10))
if not (elib and clib and ilib and consts and dctrl and clib.Cosmetics) then
    error("[Plex Skins] Required cosmetic dependencies unavailable; cosmetic initialization stopped", 0)
end
cosmeticStartup.Stage("building catalog")
local coss = clib.Cosmetics

local function findDescendantByName(parent, name)
    if not parent then return nil end
    local direct = parent:FindFirstChild(name)
    if direct then return direct end
    for _, descendant in ipairs(parent:GetDescendants()) do
        if descendant.Name == name then
            return descendant
        end
    end
    return nil
end

