local fcache = {}
local customCosmeticsRuntime = {
    CachedEquip = {},
    EquipSuspended = false,
    Definitions = {},
    Assets = {},
    Injected = {},
    Boxes = {},
    Granted = {},
    Locked = {},
    LockedBoxes = {},
