cosmeticStartup.WorldPreparers = {}
function cosmeticStartup.PrepareWorldEffect(weapon)
    local prepare = cosmeticStartup.WorldPreparers[weapon]
    if prepare and not mainapi.Uninjecting then return prepare() end
end
-- Observe successful native input without changing its payload or return values.
-- Capture before the call so a later effect retains the skin used for that action.
function cosmeticStartup.ObserveWorldEffectUse(class, method, weapon, snapshot, remember)
    if type(class) ~= "table" or type(class[method]) ~= "function" then return end
    local original = class[method]
    cosmeticStartup.QueueMethod(class, method, function(self, ...)
        local fighter = self.ClientFighter
        local owned = not mainapi.Uninjecting and fighter and fighter.Player == lp
        local data = owned and snapshot(self) or nil
        local lastShot, shootCooldown, useCooldown = self._last_shot, self._shoot_cooldown, self._use_cooldown
        local attackCooldown, throwCooldown = self._attack_cooldown, self._throw_cooldown
        local result = table.pack(original(self, ...))
        if data and (lastShot ~= self._last_shot or shootCooldown ~= self._shoot_cooldown or useCooldown ~= self._use_cooldown
            or attackCooldown ~= self._attack_cooldown or throwCooldown ~= self._throw_cooldown) then
            remember(self, data)
        end
        return table.unpack(result, 1, result.n)
    end)
end
mainapi:Clean(function() table.clear(cosmeticStartup.WorldPreparers) end)

local function getEquippedWeaponWrap(weapon)
    local item = getLocalItem(weapon)
    if item and item.GetWrap then
        local ok, wrap = pcall(item.GetWrap, item)
        if ok then
            return wrap
        end
    end
    return equip[weapon] and equip[weapon].Wrap
end

local function isInsideWorkspaceViewModels(inst)
    local viewModels = workspace:FindFirstChild("ViewModels")
    return viewModels and inst:IsDescendantOf(viewModels)
end

local function isRpgRazeEquipped()
    return getWorldSkinName("RPG") == RPG_CUSTOM_SKIN
end

local function tryApplyRpgProjectileSkin(inst)
    local profile = RPG_MESH_SKIN_OVERRIDES[RPG_CUSTOM_SKIN]
    if not (profile and isRpgRazeEquipped() and typeof(inst) == "Instance") then return end
    if isInsideWorkspaceViewModels(inst) then return end
    if inst:GetAttribute("__LionRpgProjectileSkinChecked") then return end

    local shouldApply = false
    if inst:IsA("MeshPart") or inst:IsA("SpecialMesh") then
        shouldApply = meshMatchesAnyAssetId(inst, profile.RocketMeshIds) or meshMatchesAnyAssetId(inst, profile.JuggleMeshIds)
    elseif inst:IsA("Model") then
        shouldApply = namePathContains(inst, "rocket") or namePathContains(inst, "projectile")
    end
    if not shouldApply then return end

    inst:SetAttribute("__LionRpgProjectileSkinChecked", true)
    applyRpgMeshProfile(inst, profile, {
        ShowRocket = true,
        ForceRocket = true
    })
end

local function installRpgProjectileSkinHook()
    local env = getgenv and getgenv() or _G
    local state = env.__LionRpgProjectileSkinHookState or {}
    env.__LionRpgProjectileSkinHookState = state
    local version = 2
    if state.Version == version and state.Connection then return end
    if state.Connection then
        pcall(function() state.Connection:Disconnect() end)
    end
    state.Version = version
    state.Connection = workspace.DescendantAdded:Connect(function(inst)
        if isRpgRazeEquipped() and (inst:IsA("MeshPart") or inst:IsA("SpecialMesh") or inst:IsA("Model")) then
            task.defer(tryApplyRpgProjectileSkin, inst)
        end
    end)
    task.spawn(function()
        if not isRpgRazeEquipped() then return end
        for i, inst in ipairs(workspace:GetDescendants()) do
            if state.Version ~= version then return end
            tryApplyRpgProjectileSkin(inst)
            if i % 250 == 0 then RunService.Heartbeat:Wait() end
        end
    end)
end

local function disableRpgProjectileSkinHook()
    local env = getgenv and getgenv() or _G
    local state = env.__LionRpgProjectileSkinHookState
    if state and state.Connection then
        pcall(function() state.Connection:Disconnect() end)
    end
    env.__LionRpgProjectileSkinHookState = {
        Version = 3,
        Connection = nil
    }
end

local function ensurePlacedTripmineWrapTargets(visual)
    if typeof(visual) ~= "Instance" then return end
    for _, descendant in ipairs(visual:GetDescendants()) do
        if descendant:IsA("BasePart") and descendant:GetAttribute("__LionCustomTripmineMeshPart") then
            if descendant:GetAttribute("WrapGroup") == nil then
                descendant:SetAttribute("WrapGroup", 1)
            end
            descendant:SetAttribute("IgnoreTransparency", true)
            pcall(function() descendant:AddTag("Wrappable") end)
            pcall(function() collectionService:AddTag(descendant, "Wrappable") end)
        end
    end
end

local function applyPlacedTripmineWrap(visual)
    if not wrapController or typeof(visual) ~= "Instance" then return end
    ensurePlacedTripmineWrapTargets(visual)
    local wrap = getEquippedWeaponWrap("Subspace Tripmine")
    pcall(function()
        local originalWrapProperties = wrapController:RecordOriginalWrapProperties(visual)
        wrapController:ApplyWrap(originalWrapProperties, wrap, true)
    end)
end

local function isLocalPlacedObject(object, weapon)
    local userId = object:GetAttribute("PlacedByUserID")
        or object:GetAttribute("ThrownByUserID")
        or object:GetAttribute("OwnerUserID")
        or object:GetAttribute("UserID")
    if userId ~= nil then
        return tonumber(userId) == lp.UserId
    end

    local objectId = object:GetAttribute("ObjectID")
    local item = getLocalItem(weapon)
    return objectId ~= nil and item and item.Get and item:Get("ObjectID") == objectId
end

local function isInsidePlacedSkinVisual(inst)
    local current = inst
    while current do
        if current.Name == "__LionPlacedSkin" or current:GetAttribute("__LionPlacedSkin") then
            return true
        end
        current = current.Parent
    end
    return false
end

-- World objects retain their native hitboxes and owner metadata. Keep local
-- visual changes reversible, and never hide the native model before a clone exists.
local placedVisualRecords = setmetatable({}, {__mode = "k"})
local function placedRecord(object)
    local record = placedVisualRecords[object]
    if not record then
        record = {Properties = {}, Guards = {}, ViewModelName = object:GetAttribute("ViewModelName")}
        placedVisualRecords[object] = record
    end
    return record
end
local function hidePlacedPart(object, inst)
    if isInsidePlacedSkinVisual(inst) then return end
    local property = inst:IsA("BasePart") and "LocalTransparencyModifier"
        or ((inst:IsA("Decal") or inst:IsA("Texture")) and "Transparency")
        or ((inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam")) and "Enabled")
    if not property then return end
    local record = placedRecord(object)
    local saved = record.Properties[inst]
    if not saved then saved = {}; record.Properties[inst] = saved end
    if saved[property] == nil then saved[property] = inst[property] end
    if property == "Enabled" then inst[property] = false else inst[property] = 1 end
    if inst:IsA("BasePart") then
        -- Native tripmine fading writes LocalTransparencyModifier every frame.
        -- Hide the original geometry independently so fading cannot reveal it.
        if saved.Transparency == nil then saved.Transparency = inst.Transparency end
        inst.Transparency = 1
        if not record.Guards[inst] then
            local correcting=false
            record.Guards[inst]=inst:GetPropertyChangedSignal("Transparency"):Connect(function()
                if correcting or mainapi.Uninjecting or not inst.Parent or inst.Transparency==1 then return end
                correcting=true
                inst.Transparency=1
                correcting=false
            end)
        end
    end
end
local function hideOriginalTripmineVisual(object)
    hidePlacedPart(object, object)
    for _, descendant in ipairs(object:GetDescendants()) do hidePlacedPart(object, descendant) end
    local record = placedRecord(object)
    if not record.Connection then
        record.Connection = object.DescendantAdded:Connect(function(descendant)
            if not mainapi.Uninjecting then hidePlacedPart(object, descendant) end
        end)
    end
end
mainapi:Clean(function()
    for object, record in pairs(placedVisualRecords) do
        if record.Connection then record.Connection:Disconnect() end
        for _, connection in pairs(record.Guards) do connection:Disconnect() end
        for inst, saved in pairs(record.Properties) do
            for property, value in pairs(saved) do
                pcall(function() inst[property] = value end)
            end
        end
        pcall(function()
            for _, visual in ipairs(object:GetChildren()) do
                if visual.Name=="__LionPlacedSkin" then visual:Destroy() end
            end
            if object:GetAttribute("ViewModelName") == record.AppliedName then
                object:SetAttribute("ViewModelName", record.ViewModelName)
            end
        end)
    end
    table.clear(placedVisualRecords)
end)
local function setPlacedSkinName(object, skinName)
    local record = placedRecord(object)
    record.AppliedName = skinName
    object:SetAttribute("ViewModelName", skinName)
end

local function prunePlacedTripmineVisualToCustomMesh(visual)
    if typeof(visual) ~= "Instance" then return end
    local primaryPart
    for _, descendant in ipairs(visual:GetDescendants()) do
        if descendant:IsA("BasePart") then
            if descendant:GetAttribute("__LionCustomTripmineMeshPart") then
                primaryPart = primaryPart or descendant
            else
                descendant:Destroy()
            end
        end
    end
    if visual:IsA("Model") and primaryPart then
        visual.PrimaryPart = primaryPart
    end
end

local function isInsideCustomTripmineMeshPart(inst)
    local current = inst
    while current do
        if current:IsA("BasePart") and current:GetAttribute("__LionCustomTripmineMeshPart") then
            return true
        end
        current = current.Parent
    end
    return false
end

local function forcePlacedSkinVisualVisible(visual)
    if typeof(visual) ~= "Instance" then return end

    local function show(inst)
        if inst:IsA("BasePart") and inst:GetAttribute("__LionCustomTripmineMeshPart") then
            inst.Transparency = 0
            inst.LocalTransparencyModifier = 0
        elseif (inst:IsA("Decal") or inst:IsA("Texture")) and isInsideCustomTripmineMeshPart(inst) then
            inst.Transparency = 0
        end
    end

    for _, descendant in ipairs(visual:GetDescendants()) do
        show(descendant)
    end

    if not visual:GetAttribute("__LionShowPlacedSkinLoop") then
        visual:SetAttribute("__LionShowPlacedSkinLoop", true)
        local connection
        connection = visual.DescendantAdded:Connect(function(descendant)
            task.defer(show, descendant)
        end)
        task.spawn(function()
            for _ = 1, 100 do
                if not visual.Parent then break end
                for _, descendant in ipairs(visual:GetDescendants()) do
                    show(descendant)
                end
                task.wait(0.1)
            end
            if connection then
                connection:Disconnect()
            end
            if visual.Parent then
                visual:SetAttribute("__LionShowPlacedSkinLoop", nil)
            end
        end)
    end
end

local function pivotPlacedTripmineVisual(visual, hitbox, profile)
    if not (visual and visual:IsA("Model") and hitbox and hitbox:IsA("BasePart")) then return end
    local boundsCFrame, boundsSize = visual:GetBoundingBox()
    local centerOffset = visual:GetPivot():ToObjectSpace(boundsCFrame)
    local groundOffset = profile and profile.WorldGroundOffset or 0
    local targetCenterOffsetY = (-hitbox.Size.Y * 0.5) + (boundsSize.Y * 0.5) + groundOffset
    local targetBoundsCFrame = hitbox.CFrame * CFrame.new(0, targetCenterOffsetY, 0)
    visual:PivotTo(targetBoundsCFrame * centerOffset:Inverse())
end

local function placedVisualAnchor(object)
    if not object or not object.Parent then return nil end
    local hitbox = object:FindFirstChild("Hitbox", true)
    if hitbox and hitbox:IsA("BasePart") then return hitbox end
    if object:IsA("BasePart") then return object end
    if object:IsA("Model") then
        if object.PrimaryPart and object.PrimaryPart:IsA("BasePart") then return object.PrimaryPart end
        return object:FindFirstChildWhichIsA("BasePart", true)
    end
    return object:FindFirstChildWhichIsA("BasePart", true)
end

local function matchPlacedTripmineScale(visual, object)
    if not visual:IsA("Model") or not object:IsA("Model") then return end
    -- Held templates are currently scaled to 0.34, planted models to 0.6.
    -- Read the native scale rather than hard-coding either value.
    local scale = object:GetScale()
    if scale > 0 and scale < math.huge then visual:ScaleTo(scale) end
end

local function replacePlacedModelVisual(object, source, weapon)
    if typeof(object) ~= "Instance" or typeof(source) ~= "Instance" or not object.Parent then return false end
    local existing = object:FindFirstChild("__LionPlacedSkin")
    local anchor = placedVisualAnchor(object)
    if not anchor then return false end

    local visual = source:Clone()
    if visual:IsA("Folder") then
        local model = Instance.new("Model")
        model.Name = visual.Name
        for _, child in ipairs(visual:GetChildren()) do child.Parent = model end
        visual:Destroy()
        visual = model
    elseif visual:IsA("BasePart") then
        local model = Instance.new("Model")
        model.Name = visual.Name
        visual.Parent = model
        model.PrimaryPart = visual
        visual = model
    end
    if not visual:IsA("Model") then
        visual:Destroy()
        return false
    end

    if weapon == "Subspace Tripmine" then matchPlacedTripmineScale(visual, object) end
    visual.Name = "__LionPlacedSkin"
    visual:SetAttribute("__LionPlacedSkin", true)
    for _, descendant in ipairs(visual:GetDescendants()) do
        if descendant:IsA("BasePart") then
            descendant.Anchored = false
            descendant.CanCollide = false
            descendant.CanTouch = false
            descendant.CanQuery = false
            descendant.Massless = true
            descendant.LocalTransparencyModifier = 0
        end
    end

    local targetCFrame = anchor.CFrame
    if object:IsA("Model") then
        pcall(function() targetCFrame = object:GetPivot() end)
    end
    if weapon == "Subspace Tripmine" then
        pivotPlacedTripmineVisual(visual, anchor)
    else
        visual:PivotTo(targetCFrame)
    end
    for _, oldVisual in ipairs(object:GetChildren()) do
        if oldVisual.Name=="__LionPlacedSkin" then oldVisual:Destroy() end
    end
    visual.Parent = object
    hideOriginalTripmineVisual(object)

    for _, part in ipairs(visual:GetDescendants()) do
        if part:IsA("BasePart") then
            local weld = Instance.new("WeldConstraint")
            weld.Name = "PlexPlacedVisualWeld"
            weld.Part0 = anchor
            weld.Part1 = part
            weld.Parent = part
        end
    end
    return true
end

-- These dependencies are requested by an explicit cosmetic action, including
-- config auto-load, after the startup dependency deadline may have expired.
local function placedRequire(module)
    if not module then return nil end
    local ok, result = pcall(require, module)
    if not ok then warn("[Plex Skins] World effect dependency: "..tostring(result)) end
    return ok and result or nil
end

local function installPlacedCosmeticHooks()
    local components = lps.Modules:FindFirstChild("GameComponents")
    if not components then return end

    pcall(function()
        local jumpPads = placedRequire(components:WaitForChild("JumpPads", 10))
        if type(jumpPads) ~= "table" or type(jumpPads._ObjectAdded) ~= "function" then return end
        local oldObjectAdded = cosmeticMethodOriginal(jumpPads, "_ObjectAdded")
        cosmeticStartup.QueueMethod(jumpPads, "_ObjectAdded", function(self, object)
            local skinName = getWorldSkinName("Jump Pad")
            local replaceLocal = skinName and isLocalPlacedObject(object, "Jump Pad")
            if replaceLocal then
                setPlacedSkinName(object, skinName)
            end
            local result = oldObjectAdded(self, object)
            if replaceLocal then
                task.defer(function()
                    if not object.Parent then return end
                    local misc = lps.Assets and lps.Assets:FindFirstChild("Misc")
                    local assets = misc and misc:FindFirstChild("JumpPads")
                    local source = assets and (assets:FindFirstChild(skinName) or findDescendantByName(assets, skinName))
                    if source then
                        replacePlacedModelVisual(object, source)
                    end
                end)
            end
            return result
        end)
    end)

    pcall(function()
        local tripmines = placedRequire(components:WaitForChild("SubspaceTripmines", 10))
        if type(tripmines) ~= "table" or type(tripmines._ObjectAdded) ~= "function" then return end
        local oldObjectAdded = cosmeticMethodOriginal(tripmines, "_ObjectAdded")
        local sources = {}
        local function sourceFor(name, allowViewModel)
            local cached = sources[name]
            if cached and cached.Parent then return cached end
            local throwables = lps.Assets and lps.Assets:FindFirstChild("Throwables")
            local viewModels = allowViewModel and lps.Assets and lps.Assets:FindFirstChild("ViewModels")
            local source = (throwables and findDescendantByName(throwables, name))
                or (viewModels and findDescendantByName(viewModels, name))
            if source then sources[name] = source end
            return source
        end
        local prepared
        local uses = {}
        local function prepareMine()
            local name = getWorldSkinName("Subspace Tripmine")
            if not name then prepared = nil; table.clear(uses); return nil end
            if prepared and prepared.Name == name and prepared.Source and prepared.Source.Parent then return prepared end
            local placedName = name == "RNG Dice" and DICE_TRIPMINE_SKIN or name
            local profile = TRIPMINE_MESH_SKIN_OVERRIDES[placedName]
            prepared = name and {Name = name, Profile = profile,
                Source = sourceFor(profile and (profile.BaseAssetName or "Subspace Tripmine") or name, true)} or nil
            return prepared
        end
        cosmeticStartup.WorldPreparers["Subspace Tripmine"] = prepareMine
        local items = lps.Modules:FindFirstChild("Items")
        local class = placedRequire(items and items:FindFirstChild("Subspace Tripmine"))
        cosmeticStartup.ObserveWorldEffectUse(class, "StartShooting", "Subspace Tripmine", prepareMine, function(item, data)
            local id = item:Get("ObjectID")
            local now = os.clock()
            for key, use in pairs(uses) do if use.Expires < now then uses[key] = nil end end
            if id then uses[id] = {Data = data, Expires = now + 5} end
        end)
        mainapi:Clean(function() table.clear(uses); table.clear(sources); prepared = nil end)
        local function applyPlacedSkin(object, data)
            if mainapi.Uninjecting or not object.Parent or not data then return end
            local meshProfile = data.Profile
            local hitbox = object:FindFirstChild("Hitbox", true)
            if not hitbox or not hitbox:IsA("BasePart") then return end
            local source = data.Source
            if not source then return end
            if meshProfile then
                if object:FindFirstChild("__LionPlacedSkin") then return end
        local visual = source:Clone()
        if not applyTripmineMeshProfile(visual, meshProfile, true) then
            visual:Destroy()
            return
        end
        prunePlacedTripmineVisualToCustomMesh(visual)
        if visual:IsA("BasePart") then
            local model = Instance.new("Model")
            model.Name = visual.Name
            visual.Parent = model
            model.PrimaryPart = visual
            visual = model
        end
        if not visual:IsA("Model") then visual:Destroy(); return end
        for _, descendant in pairs(visual:GetDescendants()) do
            if descendant.Name == "_right_arm" or descendant.Name == "_left_arm" or descendant.Name == "_fake" then
                descendant:Destroy()
            end
        end
        visual.Name = "__LionPlacedSkin"
