                    local localObjectId = item and item.Get and item:Get("ObjectID")
                    local cloudObjectId = rawget(cloud, "ObjectID") or rawget(cloud, "_object_id")
                    if localObjectId ~= nil and cloudObjectId == localObjectId then
                        ownerObject = model
                    end
                end
                if not ownerObject or typeof(model) ~= "Instance" or not model.Parent then return end
                if model:FindFirstChild("__LionSmokeSkin") then return end

                for _, descendant in pairs(model:GetDescendants()) do
                    if descendant:IsA("BasePart") then
                        descendant.LocalTransparencyModifier = 1
                    end
                end

                local throwables = lps.Assets:FindFirstChild("Throwables")
                local source = throwables and throwables:FindFirstChild(skinName)
                if not source then return end

                local visual = source:Clone()
                visual.Name = "__LionSmokeSkin"
                local anchor = model:IsA("BasePart") and model or model:FindFirstChildWhichIsA("BasePart", true)
                if not anchor then
                    anchor = Instance.new("Part")
                    anchor.Name = "__LionSmokeAnchor"
                    anchor.Size = Vector3.new(0.1, 0.1, 0.1)
                    anchor.Transparency = 1
                    anchor.Anchored = true
                    anchor.CanCollide = false
                    anchor.CanTouch = false
                    anchor.CanQuery = false
                    anchor.CFrame = model:IsA("Model") and model:GetPivot() or CFrame.new()
                    anchor.Parent = model
                end

                visual.Parent = model
                visual:PivotTo(anchor.CFrame)
                for _, part in pairs(visual:GetDescendants()) do
                    if part:IsA("BasePart") then
                        part.Anchored = false
                        part.CanCollide = false
                        part.CanTouch = false
                        part.CanQuery = false
                        part.Massless = true
                        local weld = Instance.new("WeldConstraint")
                        weld.Part0 = anchor
                        weld.Part1 = part
                        weld.Parent = part
                    end
                end
            end)
            return cloud
        end
    end)
end

-- Confirmed live contracts: Tightrope.new(controller, part), Portal.new(model),
-- Vortexes:_ObjectAdded(part), and ClientEntity:_FreezeEffect(duration, theme).
-- These remain local visual choices; no input/replication payload is changed.
cosmeticStartup.EnsurePlacedHooks = function()
    if cosmeticStartup.PlacedHooksReady or mainapi.Uninjecting then return end
    cosmeticStartup.PlacedHooksReady = true
    installPlacedCosmeticHooks()
    local modules = lps.Modules
    local misc = lps.Assets and lps.Assets:FindFirstChild("Misc")
    local components = modules:FindFirstChild("GameComponents")
    local function ownedTemplate(object, weapon, assets)
        if mainapi.Uninjecting or typeof(object) ~= "Instance" or not isLocalPlacedObject(object, weapon) then return end
        local skinName = getWorldSkinName(weapon)
        if skinName and assets and assets:FindFirstChild(skinName) then setPlacedSkinName(object, skinName) end
    end
    pcall(function()
        local tightrope = placedRequire(modules:FindFirstChild("Tightrope"))
        if type(tightrope) ~= "table" or type(tightrope.new) ~= "function" then return end
        local original = tightrope.new
        local templates = lps.Assets and lps.Assets:FindFirstChild("SpearTightropes")
        cosmeticStartup.QueueMethod(tightrope, "new", function(controller, part, ...)
            if typeof(part) == "Instance" and part:GetAttribute("IsSpear") then ownedTemplate(part, "Spear", templates) end
            return original(controller, part, ...)
        end)
    end)
    pcall(function()
        local module = components and components:FindFirstChild("Vortexes")
        local vortexes = placedRequire(module)
        if type(vortexes) ~= "table" or type(vortexes._ObjectAdded) ~= "function" then return end
        local original = vortexes._ObjectAdded
        local templates = misc and misc:FindFirstChild("Vortexes")
        cosmeticStartup.QueueMethod(vortexes, "_ObjectAdded", function(self, object, ...)
            ownedTemplate(object, "Distortion", templates)
            return original(self, object, ...)
        end)
    end)
    pcall(function()
        local root = components and components:FindFirstChild("PortalModels")
        local model = root and root:FindFirstChild("PortalModel")
        local portal = placedRequire(model and model:FindFirstChild("Portal"))
        if type(portal) ~= "table" or type(portal.new) ~= "function" then return end
        local original = portal.new
        local templates = misc and misc:FindFirstChild("Portals")
        cosmeticStartup.QueueMethod(portal, "new", function(object, ...)
            ownedTemplate(object, "Warper", templates)
            return original(object, ...)
        end)
    end)
    pcall(function()
        local classes = modules:FindFirstChild("ClientReplicatedClasses")
        local entity = placedRequire(classes and classes:FindFirstChild("ClientEntity"))
        local templates = misc and misc:FindFirstChild("FreezeEffects")
        if type(entity) ~= "table" or type(entity._FreezeEffect) ~= "function" or not templates then return end
        local original = entity._FreezeEffect
        local themes = {
            ["Temporal Permafrost"] = "Temporal", ["Starforge Permafrost"] = "Starforge",
            ["Permasand"] = "SandBucket", ["Xenofrost"] = "Cocoon", ["Permafrost.rbxm"] = "Selection",
            ["Temporal Ray"] = "Temporal", ["Bubble Ray"] = "Bubble", ["Gum Ray"] = "Gum",
            ["Spider Ray"] = "Cocoon", ["Wrapped Freeze Ray"] = "Wrapped",
        }
        local prepared = {}
        local lastUse
        local function freezeData(weapon)
            local name = getWorldSkinName(weapon)
            local cached = prepared[weapon]
            if cached and cached.Name == name then return cached end
            local selected = name and (themes[name] or (templates:FindFirstChild(name) and name) or "Default")
            local data = selected and templates:FindFirstChild(selected) and {Name = name, Theme = selected, Weapon = weapon} or nil
            prepared[weapon] = data
            return data
        end
        for _, weapon in ipairs({"Freeze Ray", "Permafrost"}) do
            cosmeticStartup.WorldPreparers[weapon] = function() return freezeData(weapon) end
            local items = modules:FindFirstChild("Items")
            local class = placedRequire(items and items:FindFirstChild(weapon))
            local function snapshot() return freezeData(weapon) end
            local function remember(item, data)
                local lifetime = tonumber(item.Info and item.Info.ProjectileLifetime) or 5
                lastUse = {Data = data, Expires = os.clock() + math.clamp(lifetime, 0, 10) + 1}
            end
            cosmeticStartup.ObserveWorldEffectUse(class, "StartShooting", weapon, snapshot, remember)
            if weapon == "Permafrost" then cosmeticStartup.ObserveWorldEffectUse(class, "StartAiming", weapon, snapshot, remember) end
            freezeData(weapon)
        end
        mainapi:Clean(function() table.clear(prepared); lastUse = nil end)
        cosmeticStartup.QueueMethod(entity, "_FreezeEffect", function(self, duration, theme, ...)
            if not mainapi.Uninjecting then
                local data
                if lastUse and lastUse.Expires >= os.clock() and getWorldSkinName(lastUse.Data.Weapon) then data = lastUse.Data end
                if not data then
                    local fighter = fctrl and fctrl.LocalFighter
                    local item = fighter and fighter.EquippedItem
                    local weapon = item and (item.Info and item.Info.Name or item.Name)
                    if weapon == "Permafrost" or weapon == "Freeze Ray" then data = freezeData(weapon) end
                end
                if data then theme = data.Theme end
            end
            return original(self, duration, theme, ...)
        end)
    end)
end

