(function()
    local original = cosmeticMethodOriginal(cent, "_PlayFinisher")
    local classes, failures = {}, {}
    local active = setmetatable({}, {__mode = "k"})
    local function report(name, reason)
        if failures[name] == tostring(reason) then return end
        failures[name] = tostring(reason)
        warn("[Plex Finishers] "..tostring(name)..": "..tostring(reason))
    end
    local function release(entity)
        local record = active[entity]
        active[entity] = nil
        if not record then return end
        if record.Worker then pcall(task.cancel, record.Worker) end
        if entity._current_finisher == record.Effect then entity._current_finisher = nil end
        pcall(record.Effect.Destroy, record.Effect)
    end
    mainapi:Clean(function()
        for entity in pairs(active) do release(entity) end
        table.clear(classes)
        table.clear(failures)
    end)
    local observed = {}
    local listeners, fighterListeners = {}, {}
    local observing, lastUse = false, nil
    local function disconnect(list)
        for _, connection in ipairs(list) do connection:Disconnect() end
        table.clear(list)
    end
    local function watchItem(item)
        if not item or not unlockAllEnabled or mainapi.Uninjecting then return end
        local weapon = (item.Info and item.Info.Name) or item.Name
        local items = lps.Modules:FindFirstChild("Items")
        local module = items and items:FindFirstChild(weapon)
        if not module then return end
        local ok, class = pcall(require, module)
        if not ok or type(class) ~= "table" then return end
        local methods = observed[class]
        if not methods then methods = {}; observed[class] = methods end
        local function snapshot(current)
            if not unlockAllEnabled then return nil end
            local name = (current.Info and current.Info.Name) or current.Name
            local slots = equip[name]
            -- Keep a record even without an override: a later unconfigured
            -- attack must supersede the previous weapon's finisher choice.
            return {Weapon = name, Name = slots and slots.Finisher and slots.Finisher.Name or fcache[name]}
        end
        local function remember(current, data)
            local lifetime = tonumber(current.Info and current.Info.ProjectileLifetime) or 5
            data.Expires = os.clock() + math.clamp(lifetime + 1, 1.5, 11)
            lastUse = data
        end
        for _, method in ipairs({"StartShooting", "StartAiming"}) do
            if not methods[method] and type(class[method]) == "function" then
                methods[method] = true
                cosmeticStartup.ObserveWorldEffectUse(class, method, weapon, snapshot, remember)
            end
        end
    end
    local function bindFighter(fighter)
        disconnect(fighterListeners)
        if not fighter or fighter.Player ~= lp then return end
        for _, item in pairs(fighter.Items or {}) do watchItem(item) end
        watchItem(fighter.EquippedItem)
        table.insert(fighterListeners, fighter.EquippedItemChanged:Connect(function() watchItem(fighter.EquippedItem) end))
        table.insert(fighterListeners, fighter.ItemAdded:Connect(watchItem))
    end
    function cosmeticStartup.StartFinisherObservers()
        if observing or not unlockAllEnabled or not fctrl then return end
        local configured = false
        for _, slots in pairs(equip) do if slots.Finisher then configured = true; break end end
        if not configured then return end
        observing = true
        bindFighter(fctrl.LocalFighter)
        table.insert(listeners, fctrl.ObjectAdded:Connect(function(fighter)
            if fighter.Player == lp then lastUse = nil; bindFighter(fighter) end
        end))
    end
    function cosmeticStartup.StopFinisherObservers()
        disconnect(listeners)
        disconnect(fighterListeners)
        observing, lastUse = false, nil
    end
    mainapi:Clean(function()
        cosmeticStartup.StopFinisherObservers()
        table.clear(observed)
    end)
    local function simulate(entity, name, isFinal, eliminator)
        local subject = entity.Humanoid or entity.RootPart
        if typeof(subject) ~= "Instance" or not subject:IsDescendantOf(workspace) then return false end
        local folder = rmods:FindFirstChild("Finishers")
        local module = folder and folder:FindFirstChild(name)
        if not module or not module:IsA("ModuleScript") then report(name, "Native finisher module unavailable"); return false end
        local cached = classes[name]
        if not cached or cached.Module ~= module then
            local ok, class = pcall(require, module)
            if not ok or type(class) ~= "table" then report(name, class); return false end
            cached = {Module = module, Class = class}
            classes[name] = cached
        end
        local class = cached.Class
        if type(class.new) ~= "function" or type(class.Simulate) ~= "function" then
            report(name, "Native local simulation unavailable")
            return false
        end
        local ok, effect = pcall(class.new, subject, isFinal, eliminator)
        if not ok or type(effect) ~= "table" then report(name, effect); return false end
        release(entity)
        local previous = entity._current_finisher
        if previous and previous ~= effect then pcall(previous.Destroy, previous) end
        entity._current_finisher = effect
        local record = {Effect = effect}
        active[entity] = record
        -- Simulate runs the native setup and client phases with their local
        -- simulation flag. The server's different finisher serial is not reused.
        local worker = task.spawn(function()
            local played, err = pcall(effect.Simulate, effect, 0)
            record.Worker = nil
            if not played and not mainapi.Uninjecting then report(name, err) end
        end)
        if coroutine.status(worker) ~= "dead" then record.Worker = worker end
        return true
    end
    cosmeticStartup.QueueMethod(cent, "_PlayFinisher", function(self, fname, isFinal, eliminator, serial, ...)
        if mainapi.Uninjecting then return original(self, fname, isFinal, eliminator, serial, ...) end
        local selected
        if eliminator == lp and unlockAllEnabled then
            if lastUse and lastUse.Expires >= os.clock() then
                selected = lastUse.Name
            else
                local weapon = getewep() or lwep
                local slots = weapon and equip[weapon]
                selected = slots and slots.Finisher and slots.Finisher.Name or (weapon and fcache[weapon])
            end
        elseif eliminator and eliminator ~= lp then
            local fighter = fctrl and fctrl:GetFighter(eliminator)
            local item = fighter and fighter.EquippedItem
            local weapon = item and ((item.Info and item.Info.Name) or item.Name)
            local cosmetics = weapon and cosmeticsForPlayer(eliminator, weapon)
            selected = cosmetics and cosmetics.Finisher and cosmetics.Finisher.Name
        end
        if selected and selected ~= fname then
            if customCosmeticsRuntime:PlayFinisher(self, selected) then return true end
            if simulate(self, selected, isFinal, eliminator) then return true end
        end
        return original(self, fname, isFinal, eliminator, serial, ...)
    end)
end)()
end


