    local function saveCustomGunOverrides(reset)
        local definition = customCosmeticsRuntime.Definitions[state.customKeys.Skin]
        if not definition then mainapi:Notify({Text="Choose a created custom skin first",Duration=3}) return end
        local raw = table.clone(definition)
        raw.Animations, raw.Sounds = table.clone(definition.Animations or {}), table.clone(definition.Sounds or {})
        if reset then
            raw.Animations, raw.Sounds = {}, {}
            raw.AnimationSpeed, raw.SoundVolume, raw.SoundPitch = nil, nil, nil
        else
            local action = state.customGunAction
            if not action then mainapi:Notify({Text="Choose a weapon action",Duration=3}) return end
            raw.Animations[action] = animationBox.Text:match("%S") and animationBox.Text or nil
            raw.Sounds[action] = soundBox.Text:match("%S") and soundBox.Text or nil
            raw.AnimationSpeed, raw.SoundVolume, raw.SoundPitch = animationSpeedBox.Text, soundVolumeBox.Text, soundPitchBox.Text
        end
        task.spawn(function()
            local ok, why = customCosmeticsRuntime:Register(raw)
            if not ok then mainapi:Notify({Text="Gun overrides: " .. tostring(why),Duration=4}) return end
            if scheduleSkinAutoSave then scheduleSkinAutoSave() end
            refreshCustomGunFields()
            mainapi:Notify({Text=reset and "Restored native gun animations and sounds" or "Saved custom gun animations and sounds",Duration=3})
        end)
    end
