    local gunAnimationState = getgenv().__PlexGunAnimationSwap
    if type(gunAnimationState) ~= "table" then
        gunAnimationState = {
            Enabled = false,
            Source = "",
            Target = "",
            Originals = {},
            Slots = {equip=true,idle=true,aim=true,reload=true,shoot=true},
        }
        getgenv().__PlexGunAnimationSwap = gunAnimationState
    end
    gunAnimationState.Originals = gunAnimationState.Originals or {}
    gunAnimationState.Slots = gunAnimationState.Slots or {equip=true,idle=true,aim=true,reload=true,shoot=true}

    local function cloneAnimationValue(value, seen)
        if type(value) ~= "table" then return value end
        seen = seen or {}
        if seen[value] then return seen[value] end
        local copy = {}
        seen[value] = copy
        for key, nested in pairs(value) do copy[key] = cloneAnimationValue(nested, seen) end
        return copy
    end

    local function replaceAnimationTable(target, source)
        for key in pairs(target) do target[key] = nil end
        for key, value in pairs(source or {}) do target[key] = cloneAnimationValue(value) end
    end

    local function animationCategory(key)
        local name = tostring(key or ""):lower():gsub("[%s_%-]", "")
        if name:find("reload",1,true) then return "reload" end
        if name:find("shoot",1,true) or name:find("fire",1,true) then return "shoot" end
        if name:find("aim",1,true) or name:find("ads",1,true) or name:find("scope",1,true) then return "aim" end
        if name:find("equip",1,true) or name:find("draw",1,true) or name:find("pullout",1,true) then return "equip" end
        if name:find("idle",1,true) or name:find("hold",1,true) then return "idle" end
        return nil
    end

    local function restoreGunAnimations()
        for vmName, original in pairs(gunAnimationState.Originals) do
            local info = ilib.ViewModels and ilib.ViewModels[vmName]
            if info and info.Animations == original then
                -- State left by the older swapper stored the live table itself.
                -- It cannot restore a snapshot, so retain it and start tracking cleanly.
            elseif info and type(info.Animations) == "table" and type(original) == "table" then
                replaceAnimationTable(info.Animations, original)
            elseif info then
                info.Animations = cloneAnimationValue(original)
            end
        end
        table.clear(gunAnimationState.Originals)
    end

    local function animationTargetNames(weapon)
        local names = {}
        if weapon and weapon ~= "" then
            table.insert(names, weapon)
            local ok, resolved = pcall(resolveViewModelName, weapon, equip[weapon] or {})
            if ok and resolved and resolved ~= weapon then table.insert(names, resolved) end
        end
        return names
    end

    local function findAnimationInfo(weapon)
        for _, name in ipairs(animationTargetNames(weapon)) do
            local info = ilib.ViewModels and ilib.ViewModels[name]
            if info and type(info.Animations) == "table" then return info, name end
        end
        return nil
    end

    local function refreshAnimationWeapon(weapon)
        if not weapon then return end
        task.defer(function()
            pcall(forceCosmeticUpdate, weapon, "Skin")
        end)
    end

    local function applyGunAnimationSwap()
        local target = gunAnimationState.Target ~= "" and gunAnimationState.Target or nil
        restoreGunAnimations()
        if not gunAnimationState.Enabled or not target then
            refreshAnimationWeapon(target)
            return
        end

        local sourceName = gunAnimationState.Source
        local sourceInfo, resolvedSourceName
        if sourceName ~= "" then
            sourceInfo, resolvedSourceName = findAnimationInfo(sourceName)
        end
        local sourceAnimations = sourceInfo and sourceInfo.Animations
        if type(sourceAnimations) ~= "table" then
            mainapi:Notify({Text="No viewmodel animations found for "..tostring(sourceName),Duration=2})
            return
        end

        local sourceByCategory = {}
        local sourceKeyByCategory = {}
        for key, value in pairs(sourceAnimations) do
            local category = animationCategory(key)
            if category and gunAnimationState.Slots[category] and sourceByCategory[category] == nil then
                sourceByCategory[category] = cloneAnimationValue(value)
                sourceKeyByCategory[category] = key
            end
        end

        local applied = 0
        for _, vmName in ipairs(animationTargetNames(target)) do
            local targetInfo = ilib.ViewModels and ilib.ViewModels[vmName]
            if targetInfo and type(targetInfo.Animations) == "table" then
                if gunAnimationState.Originals[vmName] == nil then
                    gunAnimationState.Originals[vmName] = cloneAnimationValue(targetInfo.Animations)
                end
                local merged = cloneAnimationValue(targetInfo.Animations)
                local usedCategories = {}
                for key in pairs(merged) do
                    local category = animationCategory(key)
                    if category and sourceByCategory[category] ~= nil then
                        merged[key] = cloneAnimationValue(sourceByCategory[category])
                        usedCategories[category] = true
                        applied += 1
                    end
                end
                for category, value in pairs(sourceByCategory) do
                    if not usedCategories[category] then
                        merged[sourceKeyByCategory[category]] = cloneAnimationValue(value)
                        applied += 1
                    end
                end
                replaceAnimationTable(targetInfo.Animations, merged)
            end
        end

        refreshAnimationWeapon(target)
        if applied == 0 then
            mainapi:Notify({Text="That gun has no compatible selected animation entries",Duration=2})
        else
            mainapi:Notify({Text="Spoofed "..tostring(applied).." animation slots from "..tostring(resolvedSourceName or sourceName),Duration=2})
        end
    end

    local animationSub = menu.subs.skins["gun animations"]
    if animationSub then
        local targetGroup = ui.group(animationSub.L, "Target gun", {simple=true})
        local targetRefresh = targetGroup:list("Gun to change", {
            height=220,
            placeholder="Search target guns",
            items=weaponItems,
            selected=function() return gunAnimationState.Target end,
            onSelect=function(name)
                gunAnimationState.Target = name
                applyGunAnimationSwap()
            end,
        })
        table.insert(state.refreshers, targetRefresh)
        targetGroup:button("Use weapon in hand as target", function()
            local held = getewep()
            if held then
                gunAnimationState.Target = held
                targetRefresh()
                applyGunAnimationSwap()
            end
        end)

        local sourceGroup = ui.group(animationSub.R, "Source gun", {simple=true})
        local sourceRefresh = sourceGroup:list("Copy animations from", {
            height=220,
            placeholder="Search source guns",
            items=weaponItems,
            selected=function() return gunAnimationState.Source end,
            onSelect=function(name)
                gunAnimationState.Source = name
                applyGunAnimationSwap()
            end,
        })
        table.insert(state.refreshers, sourceRefresh)
        sourceGroup:button("Use weapon in hand as source", function()
            local held = getewep()
            if held then
                gunAnimationState.Source = held
                sourceRefresh()
                applyGunAnimationSwap()
            end
        end)

        local optionsGroup = ui.group(animationSub.R, "Animation types", {simple=true})
        ui.cfg.PlexDisableAnimatedWraps = ui.cfg.PlexDisableAnimatedWraps == true
        disableAnimatedWraps = ui.cfg.PlexDisableAnimatedWraps
        optionsGroup:toggle("disable animated wrap animations", "PlexDisableAnimatedWraps", {onChange=function(enabled)
            disableAnimatedWraps = enabled == true
            if disableAnimatedWraps then cosmeticStartup.ActivateMethods() end
            task.defer(refreshAnimatedWrapState)
        end})
        ui.cfg.PlexGunAnimationSwap = gunAnimationState.Enabled == true
        optionsGroup:toggle("animation swapper", "PlexGunAnimationSwap", {onChange=function(enabled)
            gunAnimationState.Enabled = enabled == true
            applyGunAnimationSwap()
        end})
        for _, slot in ipairs({
            {"equip","equip / draw"},
            {"idle","idle / hold"},
            {"aim","aim / ads"},
            {"reload","reload"},
            {"shoot","shoot / fire"},
        }) do
            local key = "PlexGunAnim_"..slot[1]
            ui.cfg[key] = gunAnimationState.Slots[slot[1]] ~= false
            optionsGroup:toggle(slot[2], key, {onChange=function(enabled)
                gunAnimationState.Slots[slot[1]] = enabled == true
                applyGunAnimationSwap()
            end})
        end
        optionsGroup:button("Apply animation swap", function()
            applyGunAnimationSwap()
        end, colors.accent, {primary=true})
        optionsGroup:button("Restore animations", function()
            gunAnimationState.Enabled = false
            ui.cfg.PlexGunAnimationSwap = false
            restoreGunAnimations()
            refreshAnimationWeapon(gunAnimationState.Target ~= "" and gunAnimationState.Target or nil)
            ui.refilter()
        end)
        optionsGroup:note("Target and source are selected only on this Gun Animations sub-tab.")
    end

    local selectedEmoteSlot = 1
    local wheelGroup = ui.group(menu.subs.skins.emotes.L, "Emote wheel", {simple=true})
    local refreshWheel = wheelGroup:list("Wheel slots", {
        height=228, placeholder="Pick a wheel slot",
        items=function()
            local slots = customCosmeticsRuntime:GetEmoteSlots()
            local items = {}
            for slot = 1, 8 do
                local entry = slots[tostring(slot)]
                table.insert(items, {id=tostring(slot), label="Slot "..slot,
                    sub=entry and entry.Name or "empty", color=slot==selectedEmoteSlot and colors.accent or colors.text})
            end
            return items
        end,
        selected=function() return tostring(selectedEmoteSlot) end,
        onSelect=function(id)
            selectedEmoteSlot=tonumber(id) or 1
            refreshLists()
        end,
    })
    table.insert(state.refreshers, refreshWheel)
    table.insert(state.scopedRefreshers.Emote, refreshWheel)
    wheelGroup:button("Play selected now", function()
        local slots=customCosmeticsRuntime:GetEmoteSlots()
        local entry=slots[tostring(selectedEmoteSlot)]
        local name=entry and entry.Name
        if not name then
            mainapi:Notify({Text="That emote slot is empty",Duration=2})
            return
        end
        local ok,why=shared.LionCosmeticChanger.PlayEmote(name)
        if not ok then
            mainapi:Notify({Text="Could not play "..tostring(name)..": "..tostring(why or "unknown error"),Duration=3})
        end
    end, colors.accent, {primary=true})
    wheelGroup:button("Restore original wheel", function()
        table.clear(emoteWheelSlots)
        emoteWheelCustom=false
        syncUnlockMask()
        if scheduleSkinAutoSave then scheduleSkinAutoSave() end
        refreshLists()
    end)
    local emotesGroup = ui.group(menu.subs.skins.emotes.R, "Emotes", {simple=true})
    local refreshEmotes = emotesGroup:list("Choose for selected slot", {
        height=300, placeholder="Search emotes",
        items=function()
            local items = {{id="__empty", label="Unequip this slot", color=colors.muted}}
            for _, emoteName in ipairs(unlockEmoteNames()) do
                local cosmetic = coss[emoteName]
                table.insert(items, {id=emoteName, label=displayName(emoteName, cosmetic),
                    image=cosmetic.Image, sub=tostring(cosmetic.Rarity or ""), color=rarityColors[tostring(cosmetic.Rarity)] or colors.text})
            end
            return items
        end,
        selected=function()
            local slots = customCosmeticsRuntime:GetEmoteSlots()
            local entry = slots[tostring(selectedEmoteSlot)]
            return entry and entry.Name or "__empty"
        end,
        onSelect=function(id)
            if id ~= "__empty" and not (coss[id] and coss[id].Type == "Emote") then return end
            if id ~= "__empty" and customCosmeticsRuntime.Locked[id] then
                mainapi:Notify({Text="Unlock this emote in Skins / Emotes → Unlock All first",Duration=3}) return
            end
            if id ~= "__empty" and not unlockAllEnabled and not customCosmeticsRuntime.Definitions[id] then
                local ok, why = customCosmeticsRuntime:SetSpecificOwnership({["Cosmetic|"..id]=true},true)
                if not ok then mainapi:Notify({Text=tostring(why),Duration=3}) return end
            end
            emoteWheelSlots[selectedEmoteSlot] = id == "__empty" and false or id
            emoteWheelCustom = true
            syncUnlockMask()
            if shared.LionCosmeticChanger.InstallEmoteHook then
                task.defer(shared.LionCosmeticChanger.InstallEmoteHook)
            end
            if scheduleSkinAutoSave then scheduleSkinAutoSave() end
            refreshLists()
        end,
    })
    table.insert(state.refreshers, refreshEmotes)
    table.insert(state.scopedRefreshers.Emote, refreshEmotes)
    local configGroup = ui.group(menu.subs.skins.skin.L, "Skin configs", {simple=true})
    local configNameBox = configGroup:field("config name", "Skin config name", skinConfig.State.LastConfig)
    local refreshConfigList = configGroup:list("saved skin configs", {
        height=112, placeholder="Search skin configs",
        items=function()
            local items={}
            for _, name in ipairs(skinConfig:List()) do
                table.insert(items,{id=name,label=name,color=colors.text})
            end
            return items
        end,
        selected=function() return skinConfig.State.LastConfig end,
        onSelect=function(name)
            skinConfig.State.LastConfig=name
            configNameBox.Text=name
            skinConfig:SaveState()
        end,
    })
    ui.cfg.PlexSkinAutoLoad=skinConfig.State.AutoLoad
    configGroup:toggle("auto load skin config", "PlexSkinAutoLoad", {onChange=function(enabled)
        skinConfig.State.AutoLoad=enabled==true
        skinConfig:SaveState()
    end})
    ui.cfg.PlexSkinAutoSave=skinConfig.State.AutoSave
    configGroup:toggle("auto save skins", "PlexSkinAutoSave", {onChange=function(enabled)
        skinConfig.State.AutoSave=enabled==true
        skinConfig:SaveState()
    end})
    configGroup:button("save skin config", function()
        local ok,err=skinConfig:Save(configNameBox.Text)
        if not ok then mainapi:Notify({Text=tostring(err),Duration=3}) return end
        refreshConfigList()
        mainapi:Notify({Text="Saved skin config "..skinConfig.State.LastConfig,Duration=2})
    end)
    configGroup:button("load skin config", function()
        local ok,err=skinConfig:Load(configNameBox.Text)
        if not ok then mainapi:Notify({Text=tostring(err),Duration=3}) return end
        refreshLists()
        mainapi:Notify({Text="Loaded skin config "..skinConfig.State.LastConfig,Duration=2})
    end)
    shared.LionCosmeticChanger.RefreshTab = refreshLists
    ui.refilter()
end
cosmeticStartup.Stage("building cosmetic controls")
shared.LionCosmeticChanger.BuildNativeTab()
cosmeticStartup.Stage("ready")
end)()

end)

