-- BEGIN PLEX SOURCE: shared/012_weapons_and_trigger.lua
run(function()
    local Triggerbot
    local TriggerMode
    local ReactionTime
    local ReactionOffset
    local ForgetTime
    local ShootDelay
    local DistanceMode
    local MaxDistance
    local VisibleCheck
    local WallCheck
    local TeamCheck
    local ProtectedCheck
    local KatanaCheck
    local ShieldCheck
    local CrosshairRadius
    local PartBlacklist
    local Settings
    local ScopedWeapons

    local players = cloneref(game:GetService("Players"))
    local rs = cloneref(game:GetService("ReplicatedStorage"))
    local runService = cloneref(game:GetService("RunService"))
    local workspace = cloneref(game:GetService("Workspace"))
    local lplr = players.LocalPlayer
    local camera = workspace.CurrentCamera
    local enums
    local fighterController
    pcall(function() enums = require(rs.Modules.EnumLibrary) end)
    pcall(function() fighterController = require(lplr.PlayerScripts.Controllers.FighterController) end)

    local R15Parts = {
        "Head", "UpperTorso", "LowerTorso", "HumanoidRootPart",
        "LeftUpperArm", "LeftLowerArm", "LeftHand",
        "RightUpperArm", "RightLowerArm", "RightHand",
        "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
        "RightUpperLeg", "RightLowerLeg", "RightFoot",
        "HitboxHead", "HitboxHeadSmall", "PhysicalHitboxHead",
        "HitboxBody", "HitboxBodySmall", "FakeMass",
    }

    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    rayParams.IgnoreWater = true

    local lockedTarget
    local lockedPart
    local candidateTarget
    local candidateSince = 0
    local lastSeen = 0
    local lastShot = 0
    local shooting = false
    local fallbackScanExpires = 0
    local fallbackScanReady = false
    local fallbackTarget
    local fallbackPart

    local function getFighter()
        if not fighterController then
            pcall(function()
                fighterController = require(lplr.PlayerScripts.Controllers.FighterController)
            end)
        end
        if not fighterController then return nil end
        return fighterController.LocalFighter or (fighterController.GetFighter and fighterController:GetFighter(lplr))
    end

    local function getItemName(item)
        if not item then return "" end
        local name = item.Name or ""
        pcall(function()
            name = item:Get("Name") or name
        end)
        pcall(function()
            name = item.Info and item.Info.Name or name
        end)
        return tostring(name)
    end

    local function isScopedEnough(item)
        return mainapi:IsCombatScopeAllowed(Triggerbot,item)
    end

    local function isEnemyCharacter(char)
        if not char or char == lplr.Character then return false end
        local player = players:GetPlayerFromCharacter(char)
        if player == lplr or (not player and not isTrainingDummy(char)) then return false end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return false end
        if TeamCheck and TeamCheck.Enabled and player and player.Team and lplr.Team and not player.Neutral and not lplr.Neutral and player.Team == lplr.Team then return false end
        return true
    end

    local function partAllowed(part)
        if not part or not part:IsA("BasePart") then return false end
        local blacklist = PartBlacklist and PartBlacklist.Value or {}
        return not blacklist[part.Name]
    end

    local function getCharacterFromPart(part)
        local node = part
        while node and node ~= workspace do
            if node:IsA("Model") and node:FindFirstChildOfClass("Humanoid") then
                return node
            end
            node = node.Parent
        end
    end

    local function isKatanaBlocked(char)
        if not KatanaCheck or not KatanaCheck.Enabled then return false end
        local blocker = rawget(_G, "ShouldBlockShotForKatana")
        if type(blocker) == "function" then
            local ok, blocked = pcall(blocker, char)
            if ok and blocked then return true end
        end
        local player=players:GetPlayerFromCharacter(char)
        local deflecting=rawget(_G,"LionSilentDeflecting")
        local expires=type(deflecting)=="table" and player and deflecting[player.UserId]
        if expires and expires>tick() then return true end
        return false
    end

    local function isProtected(char)
        if not ProtectedCheck or not ProtectedCheck.Enabled then return false end
        if char:FindFirstChild("InvincibilityParticles",true) then return true end
        local root=char:FindFirstChild("HumanoidRootPart")
        if root then for _,object in ipairs(root:GetChildren()) do
            if object:IsA("Attachment") and object.Name=="Attachment" then return true end
        end end
        return false
    end

    local shieldPresenceCache = setmetatable({}, {__mode = "k"})
    local function isShieldBlocked(char)
        if not ShieldCheck or not ShieldCheck.Enabled then return false end
        local now = os.clock()
        local cached = shieldPresenceCache[char]
        local holdingShield = cached and now < cached.Expires and cached.Holding
        if not cached or now >= cached.Expires then
            holdingShield = char:FindFirstChild("Riot Shield", true) ~= nil or char:FindFirstChild("RiotShield", true) ~= nil
            shieldPresenceCache[char] = {Holding = holdingShield, Expires = now + 1}
        end
        if not holdingShield then return false end
        local root=char:FindFirstChild("HumanoidRootPart")
        local myRoot=lplr.Character and lplr.Character:FindFirstChild("HumanoidRootPart")
        if not root or not myRoot then return false end
        local direction=myRoot.Position-root.Position
        return direction.Magnitude>0 and root.CFrame.LookVector:Dot(direction.Unit)>0
    end

    local function inDistance(char)
        if not DistanceMode or DistanceMode.Value~="limit distance" then return true end
        local targetRoot=char:FindFirstChild("HumanoidRootPart")
        local myRoot=lplr.Character and lplr.Character:FindFirstChild("HumanoidRootPart")
        return targetRoot and myRoot and (targetRoot.Position-myRoot.Position).Magnitude<=MaxDistance.Value or false
    end

    local function onScreen(part)
        local point,visible=camera:WorldToViewportPoint(part.Position)
        return visible and point.Z>0
    end

    local function hasLineOfSight(char,part)
        if not WallCheck or not WallCheck.Enabled then return true end
        local direction=part.Position-camera.CFrame.Position
        local filter={lplr.Character,camera,char}
        local viewModels=workspace:FindFirstChild("ViewModels")
        if viewModels then table.insert(filter,viewModels) end
        rayParams.FilterDescendantsInstances=filter
        local hit=workspace:Raycast(camera.CFrame.Position,direction,rayParams)
        return hit==nil
    end

    local function computeTargetAllowed(char,part)
        if not isEnemyCharacter(char) or not partAllowed(part) then return false end
        if VisibleCheck and VisibleCheck.Enabled and not onScreen(part) then return false end
        if not inDistance(char) or isProtected(char) or isKatanaBlocked(char) or isShieldBlocked(char) then return false end
        return hasLineOfSight(char,part)
    end

    local allowedDecisionCache = setmetatable({}, {__mode = "k"})
    local function targetAllowed(char, part)
        if not char or not part then return false end
        local now = os.clock()
        local cached = allowedDecisionCache[char]
        if cached and cached.Part == part and now < cached.Expires then return cached.Allowed end
        local allowed = computeTargetAllowed(char, part)
        allowedDecisionCache[char] = {Part = part, Allowed = allowed, Expires = now + 0.075}
        return allowed
    end

    local triggerPartCache = setmetatable({}, {__mode = "k"})
    local function getTriggerParts(char)
        local now = os.clock()
        local cached = triggerPartCache[char]
        if cached and now < cached.Expires then
            local valid = true
            for _, part in ipairs(cached.Parts) do
                if not part.Parent or not part:IsDescendantOf(char) then valid = false break end
            end
            if valid then return cached.Parts end
        end

        local parts = {}
        for _, partName in ipairs(R15Parts) do
            local part = char:FindFirstChild(partName)
            if part and part:IsA("BasePart") then parts[#parts + 1] = part end
        end
        triggerPartCache[char] = {Parts = parts, Expires = now + 1}
        return parts
    end

    local function getTarget()
        camera = workspace.CurrentCamera or camera
        if not camera or not lplr.Character then return nil, nil end

        local viewport = camera.ViewportSize
        local origin2d = mainapi:GetCombatPointer(TriggerMode and TriggerMode.Value or "Auto", camera)
        local ray = camera:ViewportPointToRay(origin2d.X, origin2d.Y)
        local filter = {lplr.Character, camera}
        local viewModels = workspace:FindFirstChild("ViewModels")
        if viewModels then
            table.insert(filter, viewModels)
        end
        rayParams.FilterDescendantsInstances = filter

        local rayDistance=DistanceMode and DistanceMode.Value=="limit distance" and MaxDistance.Value or 10000
        local result=workspace:Raycast(ray.Origin,ray.Direction*rayDistance,rayParams)
        local direct=result and result.Instance
        local char=direct and getCharacterFromPart(direct)
        if char and targetAllowed(char,direct) then return char,direct end

        local now = os.clock()
        if fallbackScanReady and now < fallbackScanExpires then
            if fallbackTarget and fallbackPart and fallbackTarget.Parent and fallbackPart.Parent
                and targetAllowed(fallbackTarget, fallbackPart) then
                local point, visible = camera:WorldToViewportPoint(fallbackPart.Position)
                local radius = CrosshairRadius and CrosshairRadius.Value or 12
                if visible and point.Z > 0
                    and (Vector2.new(point.X, point.Y) - origin2d).Magnitude < radius then
                    return fallbackTarget, fallbackPart
                end
            end
            return nil, nil
        end

        fallbackScanReady = true
        fallbackScanExpires = now + 0.18
        fallbackTarget = nil
        fallbackPart = nil
        local bestChar,bestPart,bestPixels=nil,nil,CrosshairRadius and CrosshairRadius.Value or 12
        for _,candidate in ipairs(getCombatTargetModels()) do
            if candidate and isEnemyCharacter(candidate) and inDistance(candidate) then
                for _,part in ipairs(getTriggerParts(candidate)) do
                    if part and partAllowed(part) then
                        local point,visible=camera:WorldToViewportPoint(part.Position)
                        if visible and point.Z>0 then
                            local pixels=(Vector2.new(point.X,point.Y)-origin2d).Magnitude
                            if pixels<bestPixels and targetAllowed(candidate,part) then
                                bestChar,bestPart,bestPixels=candidate,part,pixels
                            end
                        end
                    end
                end
            end
        end
        fallbackTarget, fallbackPart = bestChar, bestPart
        return bestChar,bestPart
    end

    local function getStableTarget()
        camera = workspace.CurrentCamera or camera
        if not camera then return nil, nil end
        local now = tick()
        if lockedTarget and lockedPart and lockedTarget.Parent and lockedPart.Parent
            and lockedPart:IsDescendantOf(lockedTarget) then
            local hum = lockedTarget:FindFirstChildOfClass("Humanoid")
            if hum and hum.Health > 0 and targetAllowed(lockedTarget,lockedPart) then
                local point, visible = camera:WorldToViewportPoint(lockedPart.Position)
                local viewport = camera.ViewportSize
                local radius = CrosshairRadius and CrosshairRadius.Value or 12
                if visible and point.Z > 0
                    and (Vector2.new(point.X,point.Y) - mainapi:GetCombatPointer(TriggerMode and TriggerMode.Value or "Auto", camera)).Magnitude < radius then
                    lastSeen = now
                    return lockedTarget, lockedPart
                end
            end
        end

        lockedTarget = nil
        lockedPart = nil
        local target, part = getTarget()
        if target then
            if target ~= candidateTarget then
                candidateTarget = target
                candidateSince = now
            end

            local offset = ReactionOffset and ReactionOffset.Value or 0
            local reaction = math.max(0, (ReactionTime and ReactionTime.Value or 0) + offset) / 1000
            local settings = Settings and Settings.Value or {}
            local recentlyLocked = lastSeen > 0 and now - lastSeen < (ForgetTime and ForgetTime.Value or 0)
            if (settings["no delay between targets"] and recentlyLocked) or now - candidateSince >= reaction then
                lockedTarget = target
                lockedPart = part
                lastSeen = now
            end
        else
            candidateTarget = nil
        end

        if lockedTarget and lockedPart then
            return lockedTarget, lockedPart
        end

        lockedTarget = nil
        lockedPart = nil
        return nil, nil
    end


    local function tryShoot()
        if shooting then return false end
        local fighter = getFighter()
        local item = fighter and fighter.EquippedItem
        if not item or not isScopedEnough(item) then return false end

        shooting = true
        local fired = mainapi:FireCombatShot(TriggerMode and TriggerMode.Value or "Auto", Triggerbot, fighter)
        task.delay(0.05, function()
            shooting = false
        end)
        return fired
    end

-- END PLEX SOURCE: shared/012_weapons_and_trigger.lua
-- BEGIN PLEX SOURCE: modules/triggerbot.lua
    Triggerbot = Combat:AddModule({
        Name = "Triggerbot",
        Function = function(callback)
            mainapi:ReleaseCombatShot(Triggerbot)
            shooting = false
            lockedTarget = nil
            lockedPart = nil
            candidateTarget = nil
            lastSeen = 0
            fallbackScanExpires = 0
            fallbackScanReady = false
            fallbackTarget = nil
            fallbackPart = nil
            if callback then
                local nextTargetScan = 0
                Triggerbot:Clean(runService.Heartbeat:Connect(function()
                    if not Triggerbot.Enabled or mainapi.Uninjecting then return end
                    if mainapi.ClickGuiStatus or not mainapi:IsCombatScopeAllowed(Triggerbot) then
                        mainapi:ReleaseCombatShot(Triggerbot)
                        lockedTarget, lockedPart, candidateTarget = nil, nil, nil
                        fallbackScanReady, fallbackTarget, fallbackPart = false, nil, nil
                        lastSeen = 0
                        return
                    end
                    local now = os.clock()
                    if now < nextTargetScan then return end
                    nextTargetScan = now + 1 / 25
                    if mainapi:IsCombatFiring() then return end
                    local target = getStableTarget()
                    if not target then return end
                    local delay = (ShootDelay and ShootDelay.Value or 0) / 1000
                    if tick() - lastShot < delay then return end
                    if tryShoot() then lastShot = tick() end
                end))
            end
        end
    })

    TriggerMode = Triggerbot:AddDropdown({Name = "mode", List = {"Auto", "Camera", "Mouse"}, Default = "Auto",
        Function = function()
            mainapi:ReleaseCombatShot(Triggerbot)
            lockedTarget, lockedPart, candidateTarget = nil, nil, nil
            fallbackScanReady, fallbackTarget, fallbackPart = false, nil, nil
        end})

    ReactionTime = Triggerbot:AddSlider({
        Name = "reaction time",
        Min = 0,
        Max = 300,
        Default = 100,
        Suffix = "ms"
    })

    ReactionOffset = Triggerbot:AddSlider({
        Name = "reaction time offset",
        Min = 0,
        Max = 100,
        Default = 0,
        Suffix = "ms"
    })

    ForgetTime = Triggerbot:AddSlider({
        Name = "forget time",
        Min = 0,
        Max = 10,
        Default = 0.5,
        Decimal = 10,
        Suffix = "s"
    })

    ShootDelay = Triggerbot:AddSlider({
        Name = "shoot delay",
        Min = 0,
        Max = 300,
        Default = 0,
        Suffix = "ms"
    })

    VisibleCheck = Triggerbot:AddToggle({
        Name = "visible check",
        Tab = "targeting",
        SeparateGroup = true,
        Default = true
    })

    WallCheck = Triggerbot:AddToggle({
        Name = "behind wall check",
        Tab = "targeting",
        SeparateGroup = true,
        Default = true
    })

    TeamCheck = Triggerbot:AddToggle({
        Name = "team check",
        Tab = "targeting",
        SeparateGroup = true,
        Default = true
    })

    ProtectedCheck = Triggerbot:AddToggle({
        Name = "ignore protected",
        Tab = "targeting",
        SeparateGroup = true,
        Default = true
    })

    KatanaCheck = Triggerbot:AddToggle({
        Name = "katana check",
        Tab = "targeting",
        SeparateGroup = true,
        Default = true
    })

    ShieldCheck = Triggerbot:AddToggle({
        Name = "riot shield check",
        Tab = "targeting",
        SeparateGroup = true,
        Default = true
    })

    DistanceMode = Triggerbot:AddDropdown({
        Name = "distance mode",
        Tab = "targeting",
        SeparateGroup = true,
        List = {"no distance", "limit distance"},
        Default = "no distance"
    })

    MaxDistance = Triggerbot:AddSlider({
        Name = "max distance",
        Tab = "targeting",
        SeparateGroup = true,
        Min = 25,
        Max = 2000,
        Default = 100,
        Suffix = " studs"
    })

    CrosshairRadius = Triggerbot:AddSlider({
        Name = "through wall crosshair radius",
        Tab = "targeting",
        SeparateGroup = true,
        Min = 4,
        Max = 40,
        Default = 12,
        Suffix = " px"
    })

    PartBlacklist = Triggerbot:AddDropdown({
        Name = "part blacklist",
        List = R15Parts,
        Default = {},
        Multi = true
    })

    Settings = Triggerbot:AddDropdown({
        Name = "settings",
        List = {"no delay between targets"},
        Default = {["no delay between targets"] = true},
        Multi = true
    })

    ScopedWeapons = mainapi:AddCombatScopeCheck(Triggerbot,{Sniper=true,Crossbow=true})
end)

-- END PLEX SOURCE: modules/triggerbot.lua
-- BEGIN PLEX SOURCE: shared/013_weapons_and_trigger.lua
run(function()

    local Weapons
    local NoSpread
    local FastShootToggle
    local FastProjectile
    local FullAuto
    local AlwaysBackstab
    local MeleeSpeed
    local MeleeSpeedValue
    local MeleeInstantImpact
    local MeleeReach
    local MeleeReachValue
    local MeleeHitbox
    local MeleeHitboxSize
    local MeleeTeamCheck
    local MeleeDummies
    local GrenadeOptions
    local FireRate
    local Players = cloneref(game:GetService("Players"))
    local LocalPlayer = Players.LocalPlayer
    local ReplicatedStorage = cloneref(game:GetService("ReplicatedStorage"))
    local UserInputService = cloneref(game:GetService("UserInputService"))

    local weaponState = getgenv().__LionWeaponOptionsState
    if weaponState and weaponState.Restore then
        pcall(weaponState.Restore)
    end
    if weaponState and weaponState.UseItemRemote and weaponState.OriginalFireServer and hookfunction then
        pcall(function()
            hookfunction(weaponState.UseItemRemote.FireServer, weaponState.OriginalFireServer)
        end)
    end

    weaponState = {
        Enabled = false,
        Installed = false,
        NoSpread = false,
        FastShoot = false,
        FastProjectile = false,
        FullAuto = false,
        AlwaysBackstab = false,
        MeleeSpeed = false,
        MeleeSpeedValue = 100,
        MeleeInstantImpact = false,
        MeleeReach = false,
        MeleeReachValue = 12,
        MeleeHitbox = false,
        MeleeHitboxSize = 8,
        MeleeTeamCheck = true,
        MeleeDummies = true,
        HitboxOriginals = setmetatable({}, {__mode = "k"}),
        HitboxProxies = setmetatable({}, {__mode = "k"}),
        GrenadeOptions = {},
        FireRate = 100,
        InfoCache = setmetatable({}, {__mode = "k"}),
        MeleeRegistry = setmetatable({}, {__mode = "k"}),
        ProjectileReloadCache = setmetatable({}, {__mode = "k"}),
        FullAutoItems = setmetatable({}, {__mode = "k"}),
        Connections = {},
    }
    getgenv().__LionWeaponOptionsState = weaponState

    local function stopBackstabCameraLoop(loopId)
        if _G.CurrentCameraLoopID == loopId then
            _G.CurrentCameraLoopID = (_G.CurrentCameraLoopID or 0) + 1
        end
    end

    local function startBackstabCameraLoop(duration, targetRoot)
        if not weaponState.Utility or not weaponState.CameraController or not weaponState.UpdateCameraRotation then return end
        if not targetRoot or not targetRoot.Parent then return end

        _G.CurrentCameraLoopID = (_G.CurrentCameraLoopID or 0) + 1
        local myLoopID = _G.CurrentCameraLoopID
        task.spawn(function()
            while _G.CurrentCameraLoopID == myLoopID
                and weaponState.Enabled
                and weaponState.AlwaysBackstab
                and targetRoot.Parent do
                local pitch, yaw = targetRoot.CFrame:ToOrientation()
                local cameraRotation = Vector2.new(pitch, yaw)
                local encodedRotation = weaponState.Utility:EncodeCameraRotation(cameraRotation)
                weaponState.UpdateCameraRotation:FireServer(encodedRotation, nil)
                task.wait(0.03)
            end
        end)

        task.delay(duration or 0.35, function()
            stopBackstabCameraLoop(myLoopID)
        end)
    end

    local function optionEnabled(name)
        if not weaponState.Enabled or not weaponState.GrenadeOptions then return false end
        if weaponState.GrenadeOptions[name] == true then return true end
        for _, value in pairs(weaponState.GrenadeOptions) do
            if value == name then
                return true
            end
        end
        return false
    end

    local function hasInfoOptions()
        return weaponState.FastShoot
            or weaponState.FireRate ~= 100
            or weaponState.MeleeSpeed
            or weaponState.MeleeReach
            or weaponState.MeleeInstantImpact
    end

    local function rememberInfo(info, key)
        if type(info) ~= "table" or info[key] == nil then return nil end
        local cache = weaponState.InfoCache[info]
        if not cache then
            cache = {}
            weaponState.InfoCache[info] = cache
        end
        if cache[key] == nil then
            cache[key] = info[key]
        end
        return cache[key]
    end

    local function isMeleeInfo(info)
        if type(info) ~= "table" then return false end
        if info.Class == "Melee" or info.Type == "Melee" or info.ItemType == "Melee" then
            return true
        end
        return info.AttackReach ~= nil
            or info.HeavyAttackReach ~= nil
            or info.AttackCooldown ~= nil
            or info.HeavyAttackCooldown ~= nil
    end

    local function applyInfoOptions(item)
        local info = item and item.Info
        if type(info) ~= "table" then return end

        local fireRate = math.max((weaponState.FireRate or 100) / 100, 0.01)
        local fastShoot = weaponState.Enabled and weaponState.FastShoot

        local recoil = rememberInfo(info, "ShootRecoil")
        if recoil ~= nil then info.ShootRecoil = fastShoot and 0 or recoil end

        local spread = rememberInfo(info, "ShootSpread")
        if spread ~= nil then info.ShootSpread = fastShoot and 0 or spread end

        local projectileSpeed = rememberInfo(info, "ProjectileSpeed")
        local reach = tonumber(weaponState.MeleeReachValue) or 12
        local meleeInfo = isMeleeInfo(info)
        if not meleeInfo then
            local descriptor = tostring(info.Type or info.ItemType or info.Category or info.Slot or info.WeaponType or ""):lower()
            meleeInfo = descriptor:find("melee", 1, true) ~= nil or descriptor:find("knife", 1, true) ~= nil
        end
        if not meleeInfo then
            for key, value in pairs(info) do
                if type(key) == "string" and type(value) == "number" then
                    local lower = key:lower()
                    if lower:find("melee", 1, true)
                        or lower:find("swing", 1, true)
                        or lower:find("heavyattack", 1, true)
                        or lower:find("attackcooldown", 1, true)
                        or lower:find("attackdelay", 1, true) then
                        meleeInfo = true
                        break
                    end
                end
            end
        end
        if meleeInfo then
            for key, value in pairs(info) do
                if type(key) == "string" and type(value) == "number" then
                    local lower = key:lower()
                    if lower:find("range", 1, true)
                        or lower:find("reach", 1, true)
                        or lower:find("distance", 1, true) then
                        local original = rememberInfo(info, key)
                        if type(original) == "number" then
                            info[key] = weaponState.MeleeReach and math.max(original, reach) or original
                        end
                    end
                end
            end
        end
        if projectileSpeed ~= nil and fastShoot then
            info.ProjectileSpeed = 99999999
        elseif projectileSpeed ~= nil then
            info.ProjectileSpeed = projectileSpeed
        end

        for _, key in ipairs({
            "ShootCooldown",
            "QuickShotCooldown",
            "SpinCooldown",
            "DashCooldown",
            "Cooldown",
            "BuildCooldown",
            "AttackCooldown",
            "HeavyAttackCooldown",
            "AttackDelay",
            "HeavyAttackDelay",
            "HitDelay",
            "ImpactDelay",
            "BurstCooldown",
            "InternalHoldCooldown",
        }) do
            local original = rememberInfo(info, key)
            if original ~= nil then
                if fastShoot then
                    info[key] = 0
                elseif weaponState.MeleeInstantImpact and (key == "AttackDelay" or key == "HeavyAttackDelay" or key == "HitDelay" or key == "ImpactDelay") then
                    info[key] = 0
                elseif weaponState.MeleeSpeed and (key == "AttackCooldown"
                    or key == "HeavyAttackCooldown"
                    or key == "BurstCooldown"
                    or key == "InternalHoldCooldown") then
                    info[key] = original / math.max((weaponState.MeleeSpeedValue or 100) / 100, 0.01)
                elseif fireRate ~= 1 and (key == "ShootCooldown" or key == "QuickShotCooldown" or key == "BurstCooldown" or key == "AttackCooldown") then
                    info[key] = original / fireRate
                else
                    info[key] = original
                end
            end
        end

        if meleeInfo then
            local speed = math.max((weaponState.MeleeSpeedValue or 100) / 100, 0.01)
            for key, value in pairs(info) do
                if type(key) == "string" and type(value) == "number" then
                    local lower = key:lower()
                    local meleeTiming = lower:find("attack", 1, true)
                        or lower:find("melee", 1, true)
                        or lower:find("swing", 1, true)
                        or lower:find("hit", 1, true)
                        or lower == "cooldown"
                    local original = meleeTiming and rememberInfo(info, key) or nil
                    if type(original) == "number" then
                        if lower:find("speed", 1, true) and weaponState.MeleeSpeed then
                            info[key] = original * speed
                        elseif lower:find("cooldown", 1, true)
                            or lower:find("delay", 1, true)
                            or lower:find("windup", 1, true)
                            or lower:find("recovery", 1, true)
                            or lower:find("impact", 1, true) then
                            if fastShoot then
                                info[key] = 0
                            elseif weaponState.MeleeInstantImpact and (
                                lower:find("delay", 1, true)
                                or lower:find("windup", 1, true)
                                or lower:find("impact", 1, true)
                            ) then
                                info[key] = 0
                            elseif weaponState.MeleeSpeed and (
                                lower:find("cooldown", 1, true)
                                or lower:find("delay", 1, true)
                                or lower:find("windup", 1, true)
                                or lower:find("recovery", 1, true)
                            ) then
                                info[key] = original / speed
                            end
                        end
                    end
                end
            end
        end
    end

    local function eachLiveMeleeInfo(callback)
        local seen = {}
        local function visit(info, item)
            if type(info) ~= "table" or seen[info] or not isMeleeInfo(info) then return end
            seen[info] = true
            callback(info, item)
        end
        local function visitItem(item)
            if type(item) == "table" then visit(item.Info, item) end
        end

        local itemLibrary = weaponState.ItemLibrary
        if not itemLibrary then
            local ok, result = pcall(require, ReplicatedStorage.Modules.ItemLibrary)
            if ok and type(result) == "table" then
                itemLibrary = result
                weaponState.ItemLibrary = result
            end
        end
        for _, info in pairs(itemLibrary and itemLibrary.Items or {}) do
            visit(info)
        end

        local fighterController = weaponState.FighterController
        if not fighterController then
            pcall(function()
                fighterController = require(LocalPlayer.PlayerScripts.Controllers.FighterController)
                weaponState.FighterController = fighterController
            end)
        end
        local fighter = fighterController and fighterController.LocalFighter
        if type(fighter) == "table" then
            for _, item in pairs(fighter.Items or {}) do
                visitItem(item)
            end
            -- This is an item-keyed set with boolean values in native fighters.
            for key, value in pairs(fighter._equipped_client_items or {}) do
                visitItem(type(key) == "table" and key or value)
            end
            visitItem(fighter.EquippedItem)
        end
    end

    local function refreshMeleeRegistry()
        eachLiveMeleeInfo(function(info, item)
            weaponState.MeleeRegistry[info] = true
            applyInfoOptions({Info = info})
            if item and weaponState.Enabled and weaponState.MeleeSpeed then
                local now = tick()
                if type(item._attack_cooldown) == "number" and item._attack_cooldown > now then
                    item._attack_cooldown = now
                end
                if type(item._hold_cooldown) == "number" and item._hold_cooldown > now then
                    item._hold_cooldown = now
                end
            end
        end)
    end

    weaponState.FetchEquippedMelee = function()
        local controller = weaponState.FighterController
        local fighter = controller and controller.LocalFighter
        local item = fighter and fighter.EquippedItem
        return type(item) == "table" and isMeleeInfo(item.Info) and item or nil
    end
    weaponState.RefreshMeleeRegistry = refreshMeleeRegistry

    local function refreshCachedInfo()
        for info in pairs(weaponState.InfoCache) do
            applyInfoOptions({Info = info})
        end
    end

    local function restoreInfo()
        for info, values in pairs(weaponState.InfoCache) do
            if type(info) == "table" then
                for key, value in pairs(values) do
                    pcall(function()
                        info[key] = value
                    end)
                end
            end
        end
    end

    local function restoreFastProjectile()
        for item, reloadLength in pairs(weaponState.ProjectileReloadCache) do
            if type(item) == "table" then
                pcall(rawset, item, "ReloadLength", reloadLength)
            end
        end
    end

    local function applyFastProjectile()
        if not (weaponState.Enabled and weaponState.FastProjectile) then
            restoreFastProjectile()
            return
        end

        pcall(function()
            local ItemLibrary = require(ReplicatedStorage.Modules.ItemLibrary)
            local Items = rawget(ItemLibrary, "Items")
            if not Items then return end

            local whitelistedItems = {"Bow", "Daggers", "Slingshot"}
            for _, item in Items do
                local name = item.Name
                if table.find(whitelistedItems, name) and rawget(item, "ReloadLength") ~= nil then
                    if weaponState.ProjectileReloadCache[item] == nil then
                        weaponState.ProjectileReloadCache[item] = rawget(item, "ReloadLength")
                    end
                    rawset(item, "ReloadLength", name == "Daggers" and 0.09 or 0)
                end
            end
        end)
    end

    local function isLocalItem(item)
        local fighter = item and item.ClientFighter
        if not fighter then return false end
        if fighter.IsLocalPlayer == true then return true end
        return fighter.Player == LocalPlayer
    end

    local meleeHitboxNames = {
        Head = true,
        HumanoidRootPart = true,
        UpperTorso = true,
        LowerTorso = true,
        HitboxHead = true,
        HitboxHeadSmall = true,
        HitboxBody = true,
        HitboxBodySmall = true,
    }

    local function restoreMeleeHitboxes()
        for model, proxy in pairs(weaponState.HitboxProxies) do
            if proxy and proxy.Parent then
                pcall(function() proxy:Destroy() end)
            end
            weaponState.HitboxProxies[model] = nil
        end
        for part, saved in pairs(weaponState.HitboxOriginals) do
            if part and part.Parent and saved then
                pcall(function()
                    part.Size = saved.Size
                    part.Transparency = saved.Transparency
                    part.CanCollide = saved.CanCollide
                    part.CanTouch = saved.CanTouch
                    if saved.CanQuery ~= nil then
                        part.CanQuery = saved.CanQuery
                    end
                end)
            end
            weaponState.HitboxOriginals[part] = nil
        end
    end

    local function validMeleeTargetModel(model)
        if not model or not model:IsA("Model") or model == LocalPlayer.Character then return false end
        local player = Players:GetPlayerFromCharacter(model)
        if player then
            if weaponState.MeleeTeamCheck and not LocalPlayer.Neutral and not player.Neutral and player.Team == LocalPlayer.Team then
                return false
            end
            return true
        end
        if not weaponState.MeleeDummies then return false end
        return model:FindFirstChildOfClass("Humanoid") ~= nil
            or model:GetAttribute("IsDummy") == true
            or model.Name:lower():find("dummy", 1, true) ~= nil
    end

    local function applyMeleeHitboxPart(part)
        if not (weaponState.Enabled and weaponState.MeleeHitbox) or not part:IsA("BasePart") then return end
        if part:GetAttribute("PlexMeleeHitboxProxy") then return end
        local partName = part.Name:lower()
        if not meleeHitboxNames[part.Name] and not partName:find("hitbox", 1, true) then return end

        local model = part.Parent
        while model and model ~= workspace do
            if model:IsA("Model") and validMeleeTargetModel(model) then
                break
            end
            model = model.Parent
        end
        if not model or model == workspace or not validMeleeTargetModel(model) then return end

        local anchor = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart or part
        local size = math.max(tonumber(weaponState.MeleeHitboxSize) or 8, 1)
        local proxy = weaponState.HitboxProxies[model]
        if not (proxy and proxy.Parent == model) then
            proxy = Instance.new("Part")
            proxy.Name = "PlexMeleeHitbox"
            proxy:SetAttribute("PlexMeleeHitboxProxy", true)
            proxy.Transparency = 1
            proxy.CastShadow = false
            proxy.CanCollide = false
            proxy.CanTouch = false
            proxy.CanQuery = true
            proxy.Massless = true
            proxy.Anchored = false
            proxy.CFrame = anchor.CFrame
            proxy.Parent = model
            local weld = Instance.new("WeldConstraint")
            weld.Name = "PlexMeleeHitboxWeld"
            weld.Part0 = anchor
            weld.Part1 = proxy
            weld.Parent = proxy
            weaponState.HitboxProxies[model] = proxy
        end
        proxy.Size = Vector3.new(size, size, size)
        proxy.CFrame = anchor.CFrame
    end

    local lastMeleeHitboxSettings, nextMeleeHitboxRefresh = nil, 0
    local function refreshMeleeHitboxes()
        if not (weaponState.Enabled and weaponState.MeleeHitbox) then
            restoreMeleeHitboxes()
            lastMeleeHitboxSettings = nil
            return
        end
        local settingsKey = tostring(weaponState.MeleeHitboxSize) .. ":"
            .. tostring(weaponState.MeleeTeamCheck) .. ":" .. tostring(weaponState.MeleeDummies)
        if settingsKey ~= lastMeleeHitboxSettings then
            restoreMeleeHitboxes()
            lastMeleeHitboxSettings = settingsKey
        elseif os.clock() < nextMeleeHitboxRefresh then
            return
        end
        nextMeleeHitboxRefresh = os.clock() + 0.25
        local visited = {}
        local function applyTargets(models)
            for _, model in ipairs(models) do
                if visited[model] then continue end
                visited[model] = true
                if validMeleeTargetModel(model) then
                    for _, object in ipairs(model:GetDescendants()) do
                        if object:IsA("BasePart") then applyMeleeHitboxPart(object) end
                    end
                end
            end
        end
        applyTargets(weaponState.MeleeDummies and getCombatTargetModels()
            or getCombatTargetModels({WorkingDummy = false, RangeTargets = false}))
        if weaponState.MeleeDummies then
            applyTargets(getCombatTargetModels({WorkingDummy = false, RangeTargets = true}))
        end
    end

    local function actionName(item, action)
        local name = tostring(action)
        pcall(function()
            if item and type(item.FromEnum) == "function" then
                name = tostring(item:FromEnum(action))
            elseif weaponState.Enums and type(weaponState.Enums.FromEnum) == "function" then
                name = tostring(weaponState.Enums:FromEnum(action))
            end
        end)
        return name
    end

    local function getEquippedItemByObjectId(objectId)
        local fighter = nil
        pcall(function()
            fighter = weaponState.FighterController.LocalFighter or weaponState.FighterController:GetFighter(LocalPlayer)
        end)
        if not fighter then return nil end
        if fighter.EquippedItem and fighter.EquippedItem.Get and fighter.EquippedItem:Get("ObjectID") == objectId then
            return fighter.EquippedItem
        end
        for _, item in pairs(fighter.Items or {}) do
            if item.Get and item:Get("ObjectID") == objectId then
                return item
            end
        end
        return nil
    end

    -- Melee reach is checked from the attack camera payload, not from Item.Info.
    -- Keep the original payload intact so other attack hooks can still inspect it.
    local function decodeMeleeCFrame(encoded)
        if type(encoded) ~= "table" then return nil end
        local values = {}
        for index = 0, 5 do
            local value = encoded[utf8.char(index)]
            if type(value) ~= "number" or value ~= value then return nil end
            values[index] = value
        end
        return CFrame.new(values[0], values[1], values[2])
            * CFrame.fromOrientation(values[3], values[4], values[5])
    end

    local function nearestMeleeTarget(origin, maxDistance)
        local best, distance = nil, maxDistance
        local seen = {}
        local function consider(model)
            if seen[model] or not validMeleeTargetModel(model) then return end
            seen[model] = true
            local root = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
            if not root then return end
            local separation = (root.Position - origin).Magnitude
            if separation < distance then
                best, distance = root, separation
            end
        end
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer and player.Character then consider(player.Character) end
        end
        if weaponState.MeleeDummies then
            local now = os.clock()
            if now >= (weaponState.MeleeTargetCacheUntil or 0) then
                weaponState.MeleeTargetCache = getCombatTargetModels()
                weaponState.MeleeTargetCacheUntil = now + 0.5
            end
            for _, model in ipairs(weaponState.MeleeTargetCache or {}) do consider(model) end
        end
        return best
    end

    local function redirectMeleeAttack(objectId, action, cameraData)
        if not (weaponState.Enabled and weaponState.MeleeReach) then return cameraData end
        if type(cameraData) ~= "table" then return cameraData end
        local actionNameValue = actionName(nil, action)
        if actionNameValue ~= "StartShooting" and actionNameValue ~= "StartAiming" then
            return cameraData
        end
        local item = getEquippedItemByObjectId(objectId)
        if not item or not isLocalItem(item) then return cameraData end
        local info = item.Info
        local isMelee = item.__type == "Melee"
            or (type(info) == "table" and (info.AttackCooldown ~= nil or info.MeleeRange ~= nil or info.MeleeReach ~= nil))
        if not isMelee then return cameraData end
        local directPayload = type(cameraData[utf8.char(0)]) == "table"
        local aimData = directPayload and cameraData or cameraData[utf8.char(1)]
        if type(aimData) ~= "table" then return cameraData end
        local look = decodeMeleeCFrame(aimData[utf8.char(0)])
        if not look then return cameraData end
        local target = nearestMeleeTarget(look.Position, math.max(tonumber(weaponState.MeleeReachValue) or 12, 3))
        if not target then return cameraData end
        local replacement = weaponState.Utility:EncodeCFrame(
            CFrame.new(target.Position) * CFrame.fromOrientation(-math.pi / 2, 0, 0)
        )
        local newAimData = table.clone(aimData)
        newAimData[utf8.char(0)] = replacement
        newAimData[utf8.char(1)] = replacement
        if directPayload then return newAimData end
        local newCameraData = table.clone(cameraData)
        newCameraData[utf8.char(1)] = newAimData
        return newCameraData
    end

    local function isThrowableItem(item)
        local info = item and item.Info
        if type(info) ~= "table" then return false end
        return info.DetonateDelay ~= nil
            or info.ThrowForceMin ~= nil
            or info.LobForceMin ~= nil
    end

    local function estimateImpactFuse(item, action, cameraCFrame, charge)
        if typeof(cameraCFrame) ~= "CFrame" or type(item) ~= "table" or type(item.Info) ~= "table" then
            return nil
        end

        local info = item.Info
        local name = actionName(item, action)
        local isLob = name == "FinishAiming"
        local minForce = isLob and info.LobForceMin or info.ThrowForceMin
        local maxForce = isLob and info.LobForceMax or info.ThrowForceMax
        local gravity = isLob and info.LobGravity or info.ThrowGravity
        if type(minForce) ~= "number" or type(maxForce) ~= "number" then
            return nil
        end

        local power = math.clamp(tonumber(charge) or 1, 0, 1)
        local speed = minForce + (maxForce - minForce) * power
        local velocity = cameraCFrame.LookVector * speed
        local position = cameraCFrame.Position
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        rayParams.FilterDescendantsInstances = {LocalPlayer.Character, workspace:FindFirstChild("ViewModels")}
        local last = position
        local grav = Vector3.new(0, -(gravity or workspace.Gravity), 0)

        for t = 0.03, 5, 0.03 do
            local nextPos = position + velocity * t + grav * (0.5 * t * t)
            local result = workspace:Raycast(last, nextPos - last, rayParams)
            if result then
                return math.max(t - 0.015, 0)
            end
            last = nextPos
        end

        return nil
    end

    local function getFullAutoDelay(item)
        local remaining = type(item._shoot_cooldown) == "number"
            and math.max(item._shoot_cooldown - tick(), 0)
            or 0
        if remaining > 0 then
            return math.clamp(remaining, 0.01, 1)
        end

        local info = item.Info
        local cooldown = info and tonumber(info.ShootCooldown) or 0
        if info and tonumber(info.BurstCount) and info.BurstCount > 1 then
            cooldown = tonumber(info.BurstCooldown) or cooldown
        end
        return math.clamp(cooldown > 0 and cooldown or (1 / 60), 1 / 60, 1)
    end

    local function startFullAuto(item, input)
        if weaponState.FullAutoItems[item] then return end
        weaponState.FullAutoItems[item] = true
        task.spawn(function()
            while weaponState.Enabled
                and not mainapi.ClickGuiStatus
                and weaponState.FullAuto
                and item
                and isLocalItem(item)
                and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
                task.wait(getFullAutoDelay(item))
                if not (weaponState.Enabled
                    and not mainapi.ClickGuiStatus
                    and weaponState.FullAuto
                    and isLocalItem(item)
                    and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)) then
                    break
                end
                pcall(function()
                    weaponState.OriginalInput(item, input)
                end)
            end
            weaponState.FullAutoItems[item] = nil
        end)
    end

    local function installWeaponHooks()
        if weaponState.Installed then return end

        local PlayerScripts = LocalPlayer:WaitForChild("PlayerScripts")
        local modules = PlayerScripts:WaitForChild("Modules")
        local itemTypes = modules:WaitForChild("ItemTypes")

        weaponState.ClientItem = require(modules.ClientReplicatedClasses.ClientFighter.ClientItem)
        weaponState.GunItem = require(itemTypes:WaitForChild("Gun"))
        weaponState.GrenadeItem = require(itemTypes:FindFirstChild("Throwable") or itemTypes:FindFirstChild("Grenade"))
        weaponState.MeleeItem = require(itemTypes:FindFirstChild("Melee") or itemTypes:FindFirstChild("Knife"))
        weaponState.KnifeItem = require(modules.Items:WaitForChild("Knife"))
        weaponState.Utility = require(ReplicatedStorage.Modules.Utility)
        weaponState.CameraController = require(PlayerScripts.Controllers.CameraController)
        weaponState.Enums = require(ReplicatedStorage.Modules.EnumLibrary)
        weaponState.FighterController = require(PlayerScripts.Controllers.FighterController)
        weaponState.UseItemRemote = ReplicatedStorage.Remotes.Replication.Fighter.UseItem
        weaponState.UpdateCameraRotation = ReplicatedStorage.Remotes.Replication.Fighter.UpdateCameraRotation

        local localFighter = weaponState.FighterController.LocalFighter
        if localFighter and localFighter.EquippedItemChanged and localFighter.EquippedItemChanged.Connect then
            table.insert(weaponState.Connections, localFighter.EquippedItemChanged:Connect(function()
                task.defer(refreshMeleeRegistry)
            end))
        end

        if hookfunction then
            weaponState.OriginalFireServer = hookfunction(weaponState.UseItemRemote.FireServer, newcclosure(function(self, objectId, action, cameraData, ...)
                if self == weaponState.UseItemRemote then
                    local ok, redirected = pcall(redirectMeleeAttack, objectId, action, cameraData)
                    if ok and redirected then cameraData = redirected end
                end
                return weaponState.OriginalFireServer(self, objectId, action, cameraData, ...)
            end))
        end

        table.insert(weaponState.Connections, workspace.DescendantAdded:Connect(function(object)
            if weaponState.Enabled and weaponState.MeleeHitbox and object:IsA("BasePart")
                and (meleeHitboxNames[object.Name] or object.Name:lower():find("hitbox", 1, true)) then
                task.defer(applyMeleeHitboxPart, object)
            end
        end))

        weaponState.OriginalInput = weaponState.ClientItem.Input
        weaponState.ClientItem.Input = function(self, input, ...)
            if hasInfoOptions() and isLocalItem(self) then
                applyInfoOptions(self)
            end
            local result = {weaponState.OriginalInput(self, input, ...)}
            if weaponState.Enabled and weaponState.FullAuto and input == "StartShooting" and isLocalItem(self) then
                startFullAuto(self, input)
            end
            return unpack(result)
        end

        weaponState.OriginalGunStartShooting = weaponState.GunItem.StartShooting
        weaponState.GunItem.StartShooting = function(self, ...)
            if hasInfoOptions() and isLocalItem(self) then
                applyInfoOptions(self)
            end
            local result = {weaponState.OriginalGunStartShooting(self, ...)}
            if weaponState.Enabled and weaponState.NoSpread and isLocalItem(self) and typeof(result[3]) == "table" then
                result[4] = true
            end
            return unpack(result)
        end

        weaponState.OriginalMeleeStartShooting = weaponState.MeleeItem.StartShooting
        weaponState.MeleeItem.StartShooting = function(self, ...)
            if hasInfoOptions() and isLocalItem(self) then
                applyInfoOptions(self)
            end
            if weaponState.Enabled and weaponState.MeleeHitbox and isLocalItem(self) then
                refreshMeleeHitboxes()
            end
            if weaponState.Enabled and weaponState.AlwaysBackstab and isLocalItem(self) then
                local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                local target = root and nearestMeleeTarget(root.Position, 20)
                startBackstabCameraLoop(math.max((self.Info and (self.Info.AttackDelay or self.Info.HeavyAttackDelay)) or 0.35, 0.35), target)
            end
            return weaponState.OriginalMeleeStartShooting(self, ...)
        end

        local function applyGrenadeResultOptions(self, result)
            if not (weaponState.Enabled and isLocalItem(self) and isThrowableItem(self) and result[1]) then
                return result
            end

            local action = result[2]
            if action ~= "FinishShooting" and action ~= "FinishAiming" then
                return result
            end

            if optionEnabled("Explode On Throw") then
                result[5] = 0.15
            elseif optionEnabled("Explode On Impact") then
                result[5] = estimateImpactFuse(self, action, result[3], result[4]) or result[5]
            elseif optionEnabled("Remove Fuse") then
                result[5] = 999999
            end

            return result
        end

        weaponState.OriginalGrenadeFinishShooting = weaponState.GrenadeItem.FinishShooting
        weaponState.GrenadeItem.FinishShooting = function(self, ...)
            local result = {weaponState.OriginalGrenadeFinishShooting(self, ...)}
            result = applyGrenadeResultOptions(self, result)
            return unpack(result)
        end

        weaponState.OriginalGrenadeFinishAiming = weaponState.GrenadeItem.FinishAiming
        weaponState.GrenadeItem.FinishAiming = function(self, ...)
            local result = {weaponState.OriginalGrenadeFinishAiming(self, ...)}
            result = applyGrenadeResultOptions(self, result)
            return unpack(result)
        end

        weaponState.OriginalKnifeStartAiming = weaponState.KnifeItem.StartAiming
        weaponState.KnifeItem.StartAiming = function(self, ...)
            if hasInfoOptions() and isLocalItem(self) then
                applyInfoOptions(self)
            end
            if weaponState.Enabled and weaponState.AlwaysBackstab and isLocalItem(self) then
                local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                local target = root and nearestMeleeTarget(root.Position, 20)
                startBackstabCameraLoop(math.max((self.Info and self.Info.AttackDelay) or 0.35, 0.35), target)
            end
            return weaponState.OriginalKnifeStartAiming(self, ...)
        end

        weaponState.Restore = function()
            weaponState.Enabled = false
            _G.CurrentCameraLoopID = (_G.CurrentCameraLoopID or 0) + 1
            restoreInfo()
            restoreFastProjectile()
            restoreMeleeHitboxes()
            for _, conn in pairs(weaponState.Connections) do
                pcall(function() conn:Disconnect() end)
            end
            if weaponState.ClientItem and weaponState.OriginalInput then
                weaponState.ClientItem.Input = weaponState.OriginalInput
            end
            if weaponState.GunItem and weaponState.OriginalGunStartShooting then
                weaponState.GunItem.StartShooting = weaponState.OriginalGunStartShooting
            end
            if weaponState.MeleeItem and weaponState.OriginalMeleeStartShooting then
                weaponState.MeleeItem.StartShooting = weaponState.OriginalMeleeStartShooting
            end
            if weaponState.GrenadeItem and weaponState.OriginalGrenadeFinishShooting then
                weaponState.GrenadeItem.FinishShooting = weaponState.OriginalGrenadeFinishShooting
            end
            if weaponState.GrenadeItem and weaponState.OriginalGrenadeFinishAiming then
                weaponState.GrenadeItem.FinishAiming = weaponState.OriginalGrenadeFinishAiming
            end
            if weaponState.KnifeItem and weaponState.OriginalKnifeStartAiming then
                weaponState.KnifeItem.StartAiming = weaponState.OriginalKnifeStartAiming
            end
            if weaponState.UseItemRemote and weaponState.OriginalFireServer and hookfunction then
                pcall(function()
                    hookfunction(weaponState.UseItemRemote.FireServer, weaponState.OriginalFireServer)
                end)
            end
        end

        weaponState.Installed = true
    end

    local function updateWeaponState()
        weaponState.NoSpread = NoSpread and NoSpread.Enabled or false
        weaponState.FastShoot = FastShootToggle and FastShootToggle.Enabled or false
        weaponState.FastProjectile = FastProjectile and FastProjectile.Enabled or false
        weaponState.FullAuto = FullAuto and FullAuto.Enabled or false
        weaponState.AlwaysBackstab = AlwaysBackstab and AlwaysBackstab.Enabled or false
        weaponState.MeleeSpeed = MeleeSpeed and MeleeSpeed.Enabled or false
        weaponState.MeleeSpeedValue = MeleeSpeedValue and MeleeSpeedValue.Value or 100
        weaponState.MeleeInstantImpact = MeleeInstantImpact and MeleeInstantImpact.Enabled or false
        weaponState.MeleeReach = MeleeReach and MeleeReach.Enabled or false
        weaponState.MeleeReachValue = MeleeReachValue and MeleeReachValue.Value or 12
        weaponState.MeleeHitbox = MeleeHitbox and MeleeHitbox.Enabled or false
        weaponState.MeleeHitboxSize = MeleeHitboxSize and MeleeHitboxSize.Value or 8
        weaponState.MeleeTeamCheck = not MeleeTeamCheck or MeleeTeamCheck.Enabled
        weaponState.MeleeDummies = not MeleeDummies or MeleeDummies.Enabled
        weaponState.GrenadeOptions = GrenadeOptions and GrenadeOptions.Value or {}
        weaponState.FireRate = FireRate and FireRate.Value or 100

        local enabled = weaponState.NoSpread
            or weaponState.FastShoot
            or weaponState.FastProjectile
            or weaponState.FullAuto
            or weaponState.AlwaysBackstab
            or weaponState.MeleeSpeed
            or weaponState.MeleeInstantImpact
            or weaponState.MeleeReach
            or weaponState.MeleeHitbox
            or next(weaponState.GrenadeOptions) ~= nil
            or weaponState.FireRate ~= 100

        if Weapons and Weapons.Enabled ~= enabled then
            Weapons:Toggle(enabled)
        elseif enabled then
            installWeaponHooks()
            weaponState.Enabled = true
            refreshCachedInfo()
            refreshMeleeRegistry()
            applyFastProjectile()
            refreshMeleeHitboxes()
        else
            weaponState.Enabled = false
            _G.CurrentCameraLoopID = (_G.CurrentCameraLoopID or 0) + 1
            restoreInfo()
            restoreFastProjectile()
            restoreMeleeHitboxes()
        end
    end

-- END PLEX SOURCE: shared/013_weapons_and_trigger.lua
-- BEGIN PLEX SOURCE: modules/weapons.lua
    Weapons = Combat:AddModule({
        Name = "Weapons",
        HideEnabled = true,
        Function = function(callback)
            weaponState.Enabled = callback == true
            if callback then
                installWeaponHooks()
                refreshCachedInfo()
                applyFastProjectile()
                refreshMeleeHitboxes()
            else
                _G.CurrentCameraLoopID = (_G.CurrentCameraLoopID or 0) + 1
                restoreInfo()
                restoreFastProjectile()
                restoreMeleeHitboxes()
            end
        end
    })

    NoSpread = Weapons:AddToggle({Name = "no spread", Function = updateWeaponState})
    FastShootToggle = Weapons:AddToggle({Name = "fastshoot", Function = updateWeaponState})
    FastProjectile = Weapons:AddToggle({Name = "fast projectile", Function = updateWeaponState})
    FullAuto = Weapons:AddToggle({Name = "full auto", Function = updateWeaponState})
    GrenadeOptions = Weapons:AddDropdown({
        Name = "grenade options",
        List = {"Explode On Impact", "Explode On Throw", "Remove Fuse"},
        Default = {},
        Multi = true,
        Function = updateWeaponState
    })
    FireRate = Weapons:AddSlider({
        Name = "firerate",
        Min = 1,
        Max = 100,
        Default = 100,
        Suffix = "%",
