    })

-- END PLEX SOURCE: modules/weapons.lua
-- BEGIN PLEX SOURCE: modules/melee_combat.lua
    local MeleeCombat = Combat:AddModule({Name = "Melee Combat", HideEnabled = true})
    AlwaysBackstab = MeleeCombat:AddToggle({Name = "always backstab", Function = updateWeaponState})
    MeleeInstantImpact = MeleeCombat:AddToggle({Name = "instant impact", Function = updateWeaponState})

-- END PLEX SOURCE: modules/melee_combat.lua
-- BEGIN PLEX SOURCE: modules/melee_speed.lua
    local MeleeSpeedGroup = Combat:AddModule({Name = "Melee Speed", HideEnabled = true})
    MeleeSpeed = MeleeSpeedGroup:AddToggle({Name = "attack speed", Function = updateWeaponState})
    MeleeSpeedValue = MeleeSpeedGroup:AddSlider({Name = "speed", Min = 25, Max = 500, Default = 100, Suffix = "%", Function = updateWeaponState})
    MeleeSpeedGroup:AddLabel({Text = "Updates melee cooldowns in ItemLibrary and equipped items."})

-- END PLEX SOURCE: modules/melee_speed.lua
-- BEGIN PLEX SOURCE: modules/melee_reach.lua
    local MeleeReachGroup = Combat:AddModule({Name = "Melee Reach", HideEnabled = true})
    MeleeReach = MeleeReachGroup:AddToggle({Name = "distance expander", Function = updateWeaponState})
    MeleeReachValue = MeleeReachGroup:AddSlider({Name = "reach distance", Min = 3, Max = 50, Default = 12, Suffix = " studs", Function = updateWeaponState})
    MeleeHitbox = MeleeReachGroup:AddToggle({Name = "hitbox expander", Function = updateWeaponState})
    MeleeHitboxSize = MeleeReachGroup:AddSlider({Name = "hitbox size", Min = 2, Max = 30, Default = 8, Suffix = " studs", Function = updateWeaponState})
    MeleeReachGroup:AddLabel({Text = "Updates ItemLibrary and the equipped melee item."})

-- END PLEX SOURCE: modules/melee_reach.lua
-- BEGIN PLEX SOURCE: modules/melee_targets.lua
    local MeleeTargets = Combat:AddModule({Name = "Melee Targets", HideEnabled = true})
    MeleeTeamCheck = MeleeTargets:AddToggle({Name = "team check", Default = true, Function = updateWeaponState})
    MeleeDummies = MeleeTargets:AddToggle({Name = "include dummies", Default = true, Function = updateWeaponState})
    MeleeTargets:AddLabel({Text = "Hitboxes are invisible and restored when disabled."})
end)

