run(function()
    shared.PlexStartupDiag("visual_module_enter", "index="..tostring(mainapi.FeatureLoadIndex))
    local VisualState = getgenv().__LionVisualsExtendedState or {
        Hooked = false,
        ShootHooked = false,
        TracerHooked = false,
        HitSoundHooked = false,
        DamageIndicatorHooked = false,
        DamageNumberHooked = false,
        ViewmodelHooked = false,
        AimingHooked = false,
        OriginalDamageEffect = nil,
        OriginalDamageNumberEffect = nil,
        OriginalShootEffect = nil,
        OriginalStartShooting = nil,
        OriginalTracers = nil,
        OriginalPlayHitmarkerSound = nil,
        OriginalEliminationCreate = nil,
        EliminationSoundHooked = false,
        DeathSoundConnections = {},
        OriginalDamageIndicatorCreate = nil,
        OriginalViewmodelUpdate = nil,
        OriginalViewmodelMuzzleFlash = nil,
        OriginalViewmodelPlayAnimation = nil,
        OriginalViewmodelSetAiming = nil,
        OriginalAnimatorPlayAnimation = nil,
        OriginalGunStartAiming = nil,
        OriginalGunGetAimSpeed = nil,
        CrosshairDrawings = {},
        TargetDrawings = {},
        IndicatorDrawings = {},
        OriginalStatuses = {},
        OriginalCrosshairEnabled = nil,
        LastHitTime = 0,
        Version = 8,
    }
    if VisualState.Version ~= 10 then
        if VisualState.DeathCharacterAdded then pcall(function() VisualState.DeathCharacterAdded:Disconnect() end) end
        for _,connection in pairs(VisualState.DeathSoundConnections or {}) do
            pcall(function() connection:Disconnect() end)
        end
        VisualState.DeathCharacterAdded = nil
        VisualState.DeathSoundConnections = {}
        VisualState.Hooked = false
        VisualState.DamageIndicatorHooked = false
        VisualState.DamageNumberHooked = false
        VisualState.ShootHooked = false
        VisualState.ViewmodelHooked = false
        VisualState.AimingHooked = false
        VisualState.EliminationSoundHooked = false
        VisualState.Version = 10
    end
    getgenv().__LionVisualsExtendedState = VisualState
    if VisualState.ViewmodelFolderAdded then VisualState.ViewmodelFolderAdded:Disconnect() end
    if VisualState.ViewmodelFolderRemoving then VisualState.ViewmodelFolderRemoving:Disconnect() end
    VisualState.ViewmodelFolder = nil
    VisualState.CachedViewmodels = nil
    shared.PlexStartupDiag("visual_checkpoint", "state_ready version="..tostring(VisualState.Version))

    local Players = cloneref(game:GetService("Players"))
    local RunService = cloneref(game:GetService("RunService"))
    local SoundService = cloneref(game:GetService("SoundService"))
    local UserInputService = cloneref(game:GetService("UserInputService"))
    local Debris = cloneref(game:GetService("Debris"))
    local LocalPlayer = Players.LocalPlayer
    local Camera = workspace.CurrentCamera
    shared.PlexStartupDiag(
        "visual_checkpoint",
        "services_ready player="..tostring(LocalPlayer and LocalPlayer.Name)
        .." camera="..tostring(Camera)
    )

    -- Keep UI controls in one table so this large visual scope stays well below Luau's 200-local register limit.
    local V = {}
    if type(VisualState.RestoreHitHooks)=="function" then pcall(VisualState.RestoreHitHooks) end
    -- Old runtimes left hit parsers installed after their toggles were disabled.
    local function restoreLegacyHit(owner,key,originalKey)
        local fn=owner and owner[key]
        local original=VisualState[originalKey]
        if type(fn)~="function" or type(original)~="function" or not debug.getupvalues then return end
        local ok,upvalues=pcall(debug.getupvalues,fn)
        if ok then
            for _,value in pairs(upvalues) do
                if value==VisualState then owner[key]=original; return end
            end
        end
    end
    if VisualState.Hooked or VisualState.DamageNumberHooked or VisualState.DamageIndicatorHooked or VisualState.HitSoundHooked then
        pcall(function()
            local modules=LocalPlayer.PlayerScripts.Modules
            restoreLegacyHit(require(modules.ClientReplicatedClasses.ClientFighter.ClientItem.ItemInterface),"DamageEffect","OriginalDamageEffect")
