    -- Yield only after a group has spent a frame's budget. Most groups are
    -- cheap enough to build together without adding a whole frame each.
    local lastVisualYield = os.clock()
    local function visualInitYield(stage)
        if os.clock() - lastVisualYield < 0.008 then return end
        stage = tostring(stage or "components")
        shared.PlexStartupDiag("visual_stage_before", stage)

        if StartupLoader and StartupLoader.Alive then
            local total = math.max(#mainapi.FeatureQueue, 1)
            local progress = 0.14 + (math.min(mainapi.FeatureLoadIndex, total) / total) * 0.76
            StartupLoader:Set("loading visuals · "..stage, progress)
        end

        RunService.Heartbeat:Wait()
        lastVisualYield = os.clock()
        shared.PlexStartupDiag("visual_stage_after", stage)
    end

