    local function getWireframeColor(obj)
        local part = obj
        if obj and obj:IsA("SpecialMesh") then
            part = obj.Parent
        end
        if part and part:IsA("BasePart") then
            return part.Color
        end
        return Color3.fromRGB(0, 0, 0)
