    local MAX_WIREFRAME_POOL = 96

    local function getWireframeParent()
        return LocalPlayer:FindFirstChildOfClass("PlayerGui") or Camera or workspace
    end

    local function acquireWireframe(name, buildKey, adornee)
        VisualState.WireframePool = VisualState.WireframePool or {}
        VisualState.WireframePoolCount = VisualState.WireframePoolCount or {}

        local poolKey = name .. "|" .. tostring(buildKey or "")
        local bucket = VisualState.WireframePool[poolKey]
        local wire
        if bucket and #bucket > 0 then
            wire = table.remove(bucket)
            VisualState.WireframePoolCount[poolKey] = math.max((VisualState.WireframePoolCount[poolKey] or 1) - 1, 0)
        else
            local ok, created = pcall(function()
                return Instance.new("WireframeHandleAdornment")
            end)
            if not ok or not created then return nil end
            wire = created
        end

        wire.Name = name
        pcall(function() wire.Adornee = adornee end)
        pcall(function() wire.AlwaysOnTop = true end)
        pcall(function() wire.ZIndex = 10 end)
        pcall(function() wire.Thickness = 1 end)
        pcall(function() wire.Transparency = 0 end)
        pcall(function() wire.Visible = true end)
        pcall(function() wire.Parent = getWireframeParent() end)
        return wire
    end

    local function releaseWireframe(wire)
        if not wire then return end
        local buildKey
        pcall(function()
            buildKey = wire:GetAttribute("LionWireBuildKey")
        end)
        if not buildKey then
            pcall(function() wire:Destroy() end)
            return
        end

        VisualState.WireframePool = VisualState.WireframePool or {}
        VisualState.WireframePoolCount = VisualState.WireframePoolCount or {}
        local poolKey = wire.Name .. "|" .. tostring(buildKey)
        local count = VisualState.WireframePoolCount[poolKey] or 0
        if count >= MAX_WIREFRAME_POOL then
            pcall(function() wire:Destroy() end)
            return
        end

        pcall(function() wire.Visible = false end)
        pcall(function() wire.Adornee = nil end)
        pcall(function() wire.Parent = nil end)
        VisualState.WireframePool[poolKey] = VisualState.WireframePool[poolKey] or {}
        table.insert(VisualState.WireframePool[poolKey], wire)
        VisualState.WireframePoolCount[poolKey] = count + 1
    end

    local function updateWireframe(part, enabled, color)
        VisualState.PrimitiveWireframes = VisualState.PrimitiveWireframes or setmetatable({}, {__mode = "k"})
        local buildKey = "box|" .. tostring(part.Size)
        local wire = VisualState.PrimitiveWireframes[part]
        if not enabled and not wire then return end
        local oldWire = part:FindFirstChild("__LionVMWireframe")
        local oldBox = part:FindFirstChild("__LionVMWireframeBox")
        if (oldWire or oldBox) and not wire then
            if oldWire then oldWire:Destroy() end
            if oldBox then oldBox:Destroy() end
        end
        if enabled then
            if wire and not wire:IsA("WireframeHandleAdornment") then
                releaseWireframe(wire)
                wire = nil
            end
            if not wire then
                wire = acquireWireframe("__LionVMWireframe", buildKey, part)
                if wire then
                    VisualState.PrimitiveWireframes[part] = wire
                else
                    return
                end
            end
            if wire then
                local c = color or Color3.fromRGB(255, 255, 255)
                if wire.Color3 ~= c then
                    pcall(function() wire.Color3 = c end)
                end
                if wire:GetAttribute("LionWireBuildKey") ~= buildKey then
                    pcall(function() wire:Clear() end)
                    local half = part.Size * 0.5
                    local corners = {
                        Vector3.new(-half.X, -half.Y, -half.Z), Vector3.new( half.X, -half.Y, -half.Z),
                        Vector3.new(-half.X,  half.Y, -half.Z), Vector3.new( half.X,  half.Y, -half.Z),
                        Vector3.new(-half.X, -half.Y,  half.Z), Vector3.new( half.X, -half.Y,  half.Z),
                        Vector3.new(-half.X,  half.Y,  half.Z), Vector3.new( half.X,  half.Y,  half.Z),
                    }
                    local edges = {{1,2},{2,4},{4,3},{3,1},{5,6},{6,8},{8,7},{7,5},{1,5},{2,6},{3,7},{4,8}}
                    for _, edge in ipairs(edges) do
                        pcall(function()
                            wire:AddLine(corners[edge[1]], corners[edge[2]])
                        end)
                    end
                    pcall(function()
                        wire:SetAttribute("LionWireBuildKey", buildKey)
                    end)
                end
            end
        else
            releaseWireframe(wire)
            VisualState.PrimitiveWireframes[part] = nil
        end
    end

    local function contentFromMeshId(meshId)
        meshId = tostring(meshId or "")
        if meshId == "" then return nil end
        local id = meshId:match("rbxassetid://(%d+)") or meshId:match("[?&]id=(%d+)") or meshId:match("(%d+)")
        if Content and Content.fromAssetId and id then
            local ok, content = pcall(Content.fromAssetId, tonumber(id))
            if ok and content then return content, "asset:" .. id end
        end
        if Content and Content.fromUri then
            local ok, content = pcall(Content.fromUri, meshId)
            if ok and content then return content, meshId end
        end
        return nil, nil
    end

    local function contentFromMeshObject(obj)
        if obj:IsA("SpecialMesh") then
            return contentFromMeshId(obj.MeshId)
        end
        if obj:IsA("MeshPart") then
            local okContent, meshContent = pcall(function()
                return obj.MeshContent
            end)
            if okContent and meshContent then
                return meshContent, tostring(meshContent)
            end
            local okMeshId, meshId = pcall(function()
                return obj.MeshId
            end)
            if okMeshId then
                return contentFromMeshId(meshId)
            end
        end
        return nil, nil
    end

    local function getMeshWireData(obj)
        VisualState.WireframeMeshLines = VisualState.WireframeMeshLines or {}
        local content, key = contentFromMeshObject(obj)
        if not content or not key then return nil end
        if VisualState.WireframeMeshLines[key] ~= nil then
            return VisualState.WireframeMeshLines[key] ~= false and VisualState.WireframeMeshLines[key] or nil
        end

        local ok, editable = pcall(function()
            return game:GetService("AssetService"):CreateEditableMeshAsync(content)
        end)
        if not ok or not editable then
            VisualState.WireframeMeshLines[key] = false
            return nil
        end

        local lines, seen = {}, {}
        local okSize, meshSize = pcall(function()
            return editable:GetSize()
        end)
        if not okSize or not meshSize then
            meshSize = Vector3.new(1, 1, 1)
        end
        local okFaces, faces = pcall(function()
            return editable:GetFaces()
        end)
        if okFaces and type(faces) == "table" then
            for _, faceId in ipairs(faces) do
                local okVerts, verts = pcall(function()
                    return editable:GetFaceVertices(faceId)
                end)
                if okVerts and type(verts) == "table" and #verts >= 2 then
                    for i = 1, #verts do
                        local aId, bId = verts[i], verts[(i % #verts) + 1]
                        local edgeKey = tostring(math.min(aId, bId)) .. ":" .. tostring(math.max(aId, bId))
                        if not seen[edgeKey] then
                            seen[edgeKey] = true
                            local okA, a = pcall(function() return editable:GetPosition(aId) end)
                            local okB, b = pcall(function() return editable:GetPosition(bId) end)
                            if okA and okB and a and b then
                                table.insert(lines, {a, b})
                            end
                        end
                    end
                end
                if #lines > 1800 then break end
            end
        end
        pcall(function() editable:Destroy() end)

        local data = #lines > 0 and {Lines = lines, Size = meshSize, Key = key} or false
        VisualState.WireframeMeshLines[key] = data
        return data ~= false and data or nil
    end

    local function transformMeshWirePoint(mesh, point, data)
        if mesh and mesh:IsA("SpecialMesh") then
            local scale = mesh.Scale
            local offset = mesh.Offset
            return Vector3.new(point.X * scale.X, point.Y * scale.Y, point.Z * scale.Z) + offset
        end
        if mesh and mesh:IsA("MeshPart") and data and data.Size then
            local size = data.Size
            local sx = math.abs(size.X) > 1e-4 and mesh.Size.X / size.X or 1
            local sy = math.abs(size.Y) > 1e-4 and mesh.Size.Y / size.Y or 1
            local sz = math.abs(size.Z) > 1e-4 and mesh.Size.Z / size.Z or 1
            return Vector3.new(point.X * sx, point.Y * sy, point.Z * sz)
        end
        return point
    end

    local function updateMeshWireframe(obj, enabled, color)
        local adornee = obj:IsA("SpecialMesh") and obj.Parent or obj
        if not (adornee and adornee:IsA("BasePart")) then return end
        VisualState.MeshWireframes = VisualState.MeshWireframes or setmetatable({}, {__mode = "k"})
        local wire = VisualState.MeshWireframes[adornee]
        if not enabled and not wire then return end
        local old = adornee:FindFirstChild("__LionVMMeshWireframe")
        if old and not wire then old:Destroy() end
        if not enabled then
            releaseWireframe(wire)
            VisualState.MeshWireframes[adornee] = nil
            return
        end

        local data = getMeshWireData(obj)
        if not data then
            updateWireframe(adornee, false)
            return
        end
        updateWireframe(adornee, false)

        local buildKey = data.Key
        if obj:IsA("SpecialMesh") then
            buildKey ..= "|" .. tostring(obj.Scale) .. "|" .. tostring(obj.Offset)
        elseif obj:IsA("MeshPart") then
            buildKey ..= "|" .. tostring(obj.Size)
        end

        if not wire then
            wire = acquireWireframe("__LionVMMeshWireframe", buildKey, adornee)
            if not wire then return end
            VisualState.MeshWireframes[adornee] = wire
        end

        local c = color or Color3.fromRGB(0, 0, 0)
        if wire.Color3 ~= c then
            pcall(function() wire.Color3 = c end)
        end
        if wire:GetAttribute("LionWireBuildKey") ~= buildKey then
            pcall(function() wire:Clear() end)
            for _, line in ipairs(data.Lines) do
                pcall(function()
                    wire:AddLine(transformMeshWirePoint(obj, line[1], data), transformMeshWirePoint(obj, line[2], data))
                end)
            end
            pcall(function()
                wire:SetAttribute("LionWireBuildKey", buildKey)
            end)
        end
    end

    visualInitYield("helpers 2")

    local function getLocalFighter()
        local now = os.clock()
        if VisualState.CachedFighterAt and now - VisualState.CachedFighterAt < 0.25 then
            return VisualState.CachedFighter
        end
        local ok, controller = pcall(function()
            return require(LocalPlayer.PlayerScripts.Controllers.FighterController)
        end)
        local fighter = ok and controller and (controller.LocalFighter or controller:GetFighter(LocalPlayer)) or nil
        VisualState.CachedFighter = fighter
        VisualState.CachedFighterAt = now
        return fighter
    end

    local function getLocalViewmodels()
        local folder = workspace:FindFirstChild("ViewModels")
        if VisualState.ViewmodelFolder ~= folder then
            if VisualState.ViewmodelFolderAdded then VisualState.ViewmodelFolderAdded:Disconnect() end
            if VisualState.ViewmodelFolderRemoving then VisualState.ViewmodelFolderRemoving:Disconnect() end
            VisualState.ViewmodelFolder = folder
            VisualState.CachedViewmodels = nil
            if folder then
                local function invalidateViewmodels(object)
                    if not object:IsA("Model") then return end
                    local prefix=LocalPlayer.Name .. " - "
                    if object.Name:sub(1,#prefix)~=prefix and object.Name~="FirstPerson" then return end
                    VisualState.CachedViewmodels = nil
                    VisualState.ViewmodelDirty = true
                end
                VisualState.ViewmodelFolderAdded = folder.DescendantAdded:Connect(invalidateViewmodels)
                VisualState.ViewmodelFolderRemoving = folder.DescendantRemoving:Connect(invalidateViewmodels)
                mainapi:Clean(VisualState.ViewmodelFolderAdded)
                mainapi:Clean(VisualState.ViewmodelFolderRemoving)
            end
        end
        if VisualState.CachedViewmodels then return VisualState.CachedViewmodels end
        local out = {}
        if not folder then return out end
        local prefix = LocalPlayer.Name .. " - "
        local firstPerson = folder:FindFirstChild("FirstPerson")
        -- FirstPerson is a Folder in current Rivals; collect only this player's rigs.
        for _, model in ipairs(folder:GetDescendants()) do
            if model:IsA("Model") and model.Name:sub(1, #prefix) == prefix then
                table.insert(out, model)
            end
        end
        if #out == 0 and firstPerson and firstPerson:IsA("Model") then
            table.insert(out, firstPerson)
        end
        VisualState.CachedViewmodels = out
        return out
    end

    local function markViewmodelDirty()
        VisualState.ViewmodelDirty = true
        VisualState.ViewmodelAppliedAt = nil
        if VisualState.WakeUpdates then VisualState.WakeUpdates() end
    end

    local function isViewmodelAppearanceObject(object)
        if object.Name:sub(1,8)=="__LionVM" then return false end
        return object:IsA("BasePart") or object:IsA("Decal") or object:IsA("Texture")
            or object:IsA("SpecialMesh") or object:IsA("SurfaceAppearance")
            or object:IsA("Shirt") or object:IsA("Pants") or object:IsA("ShirtGraphic")
    end

    local function getViewmodelDescendants(model)
        VisualState.ViewmodelDescendantCache = VisualState.ViewmodelDescendantCache or setmetatable({}, {__mode = "k"})
        local cache = VisualState.ViewmodelDescendantCache[model]
        if not cache then
            cache = {Dirty = true, Objects = {}}
            VisualState.ViewmodelDescendantCache[model] = cache
            cache.Added = model.DescendantAdded:Connect(function(object)
                if not isViewmodelAppearanceObject(object) then return end
                cache.Dirty = true
                markViewmodelDirty()
            end)
            cache.Removing = model.DescendantRemoving:Connect(function(object)
                if not isViewmodelAppearanceObject(object) then return end
                cache.Dirty = true
                markViewmodelDirty()
            end)
            mainapi:Clean(cache.Added)
            mainapi:Clean(cache.Removing)
        end
        if cache.Dirty then
            cache.Objects = model:GetDescendants()
            cache.Dirty = false
        end
        return cache.Objects
    end

    local function getActiveWireframeRoots()
        local roots, keyParts = {}, {}
        local function rootKey(root)
            local ok, id = pcall(function()
                return root:GetDebugId(0)
            end)
            return ok and id or root:GetFullName()
        end
        pcall(function()
            local fighter = getLocalFighter()
            local item = fighter and fighter.EquippedItem
            local viewmodel = item and item.ViewModel
            local model = viewmodel and viewmodel.Model
            local itemModel = viewmodel and viewmodel.ItemModel
            local itemVisual = model and model:FindFirstChild("ItemVisual")
            for _, root in ipairs({itemModel, itemVisual}) do
                if typeof(root) == "Instance" and root:IsDescendantOf(workspace) then
                    roots[root] = true
                    table.insert(keyParts, rootKey(root))
                end
            end
        end)
        if next(roots) == nil then
            local models = getLocalViewmodels()
            local model = models[#models]
            local itemVisual = model and model:FindFirstChild("ItemVisual")
            if itemVisual then
                roots[itemVisual] = true
                table.insert(keyParts, rootKey(itemVisual))
            end
        end
        table.sort(keyParts)
        return roots, table.concat(keyParts, "|")
    end

    local function isInRootSet(obj, roots)
        if not obj or not roots then return false end
        for root in pairs(roots) do
            if obj == root or obj:IsDescendantOf(root) then
                return true
            end
        end
        return false
    end

    local function getMuzzleWorld()
        local now = os.clock()
        if VisualState.CachedMuzzleAt and now - VisualState.CachedMuzzleAt < 0.012 and typeof(VisualState.CachedMuzzle) == "Vector3" then
            return VisualState.CachedMuzzle
        end
        local muzzle
        local fighter = getLocalFighter()
        local item = fighter and fighter.EquippedItem
        pcall(function()
            if item and item.ViewModel and item.ViewModel.GetMuzzlePosition then
                muzzle = item.ViewModel:GetMuzzlePosition()
            end
        end)
        if not muzzle then
            for _, model in ipairs(getLocalViewmodels()) do
                local part = model:FindFirstChild("Muzzle", true) or model:FindFirstChild("Barrel", true) or model:FindFirstChild("Handle", true)
                if part and part:IsA("Attachment") then muzzle = part.WorldPosition break end
                if part and part:IsA("BasePart") then muzzle = part.Position break end
            end
        end
        muzzle = muzzle or (Camera and Camera.CFrame.Position or nil)
        if typeof(muzzle) == "Vector3" then
            VisualState.CachedMuzzle = muzzle
            VisualState.CachedMuzzleAt = now
        end
        return muzzle
    end

    local function worldToScreen(pos)
        Camera = workspace.CurrentCamera
        if not (Camera and pos) then return nil, false end
        local screen, visible = Camera:WorldToViewportPoint(pos)
        return Vector2.new(screen.X, screen.Y), visible and screen.Z > 0
    end

    local function getClosestTarget()
        local now = tick()
        if VisualState.CachedTargetAt and now - VisualState.CachedTargetAt < 0.05 then
            return VisualState.CachedTarget, VisualState.CachedTargetPart
        end
        Camera = workspace.CurrentCamera
        if not Camera then return nil end
        local center = Camera.ViewportSize / 2
        local best, bestPart, bestDist = nil, nil, math.huge
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer and plr.Character then
                local hum = plr.Character:FindFirstChildOfClass("Humanoid")
                local part = plr.Character:FindFirstChild("Head") or plr.Character:FindFirstChild("HumanoidRootPart")
                if hum and hum.Health > 0 and part then
                    local screen, visible = worldToScreen(part.Position)
                    if visible then
                        local dist = (screen - center).Magnitude
                        if dist < bestDist then
                            best, bestPart, bestDist = plr, part, dist
                        end
                    end
                end
            end
        end
        VisualState.CachedTarget = best
        VisualState.CachedTargetPart = bestPart
        VisualState.CachedTargetAt = now
        return best, bestPart
    end

    local function playSound(name, volume, speed, startAt, customId)
        name = tostring(name or "disable"):lower()
        local id = soundIds[name] or ""
        if name == "custom" then
            id = tostring(customId or (V.ShootCustomId and V.ShootCustomId.Value) or "")
        end
        if id == "" or name == "disable" then return end
        if not id:find("rbxassetid://", 1, true) then
            id = "rbxassetid://" .. id:gsub("%D", "")
        end

        VisualState.CustomSoundPool = VisualState.CustomSoundPool or {}
        VisualState.CustomSoundPoolIndex = ((VisualState.CustomSoundPoolIndex or 0) % 12) + 1
        local sound = VisualState.CustomSoundPool[VisualState.CustomSoundPoolIndex]
        if not sound or not sound.Parent then
            sound = Instance.new("Sound")
            sound.Name = "__LionCustomSound"
            pcall(function()
                sound:SetAttribute("__LionCustomSound", true)
            end)
            sound.Parent = SoundService
            VisualState.CustomSoundPool[VisualState.CustomSoundPoolIndex] = sound
        else
            pcall(function()
                sound:Stop()
            end)
        end

        sound.SoundId = id
        sound.Volume = math.clamp(tonumber(volume) or 0.5, 0, 10)
        sound.PlaybackSpeed = math.clamp(tonumber(speed) or 1, 0.1, 5)
        sound.TimePosition = math.max(tonumber(startAt) or 0, 0)
        sound:Play()
    end

    local function getShootSoundRoots()
        local roots = {SoundService}
        local viewmodels = workspace:FindFirstChild("ViewModels")
        if viewmodels then table.insert(roots, viewmodels) end
        local camera = workspace.CurrentCamera
        if camera then table.insert(roots, camera) end
        return roots
    end

    local function collectShootSounds()
        local now = os.clock()
        if VisualState.ShootSoundSnapshot and now - (VisualState.ShootSoundSnapshotAt or 0) < 0.08 then
            return VisualState.ShootSoundSnapshot
        end

        local sounds = {}
        local list = {}
        for _, root in ipairs(getShootSoundRoots()) do
            for _, obj in ipairs(root:GetDescendants()) do
                if obj:IsA("Sound") then
                    list[#list + 1] = obj
                    sounds[obj] = {
                        Playing = obj.Playing,
                        TimePosition = obj.TimePosition,
                    }
                end
            end
        end
        VisualState.ShootSoundList = list
        VisualState.ShootSoundSnapshot = sounds
        VisualState.ShootSoundSnapshotAt = now
        return sounds
    end

    local function suppressDefaultShootSounds(snapshot)
        snapshot = snapshot or {}
        local list = VisualState.ShootSoundList
        if not list then
            collectShootSounds()
            list = VisualState.ShootSoundList or {}
        end

        for i = #list, 1, -1 do
            local obj = list[i]
            if not obj or not obj.Parent then
                table.remove(list, i)
            elseif obj:IsA("Sound") and not obj:GetAttribute("__LionCustomSound") then
                local previous = snapshot[obj]
                local fresh = previous == nil
                pcall(function()
                    local restarted = previous
                        and obj.Playing
                        and (not previous.Playing or obj.TimePosition + 0.02 < previous.TimePosition or obj.TimePosition <= 0.08)
                    fresh = fresh or restarted or (obj.Playing and obj.TimePosition <= 0.25 and obj:IsDescendantOf(workspace:FindFirstChild("ViewModels") or workspace))
                end)
                if fresh then
                    pcall(function()
                        obj.Volume = 0
                        obj:Stop()
                    end)
                end
            end
        end
    end

    local function stopDefaultShootSound(obj)
        if obj and obj:IsA("Sound") and not obj:GetAttribute("__LionCustomSound") then
            pcall(function()
                obj.Volume = 0
                obj:Stop()
            end)
        end
    end

    local function clearShootSoundWatch()
        if os.clock() < (VisualState.SuppressShootSoundUntil or 0) then
            task.delay(0.1, clearShootSoundWatch)
            return
        end
        for _, connection in ipairs(VisualState.ShootSoundConnections or {}) do
            pcall(function()
                connection:Disconnect()
            end)
        end
        VisualState.ShootSoundConnections = nil
    end

    local function beginShootSoundSuppression(snapshot, duration)
        duration = duration or 0.35
        VisualState.SuppressShootSoundUntil = math.max(VisualState.SuppressShootSoundUntil or 0, os.clock() + duration)
        suppressDefaultShootSounds(snapshot or {})
        if VisualState.ShootSoundConnections then return end
        VisualState.ShootSoundConnections = {}
        local function watch(root)
            if not root then return end
            table.insert(VisualState.ShootSoundConnections, root.DescendantAdded:Connect(function(obj)
                if obj:IsA("Sound") and os.clock() <= (VisualState.SuppressShootSoundUntil or 0) then
                    VisualState.ShootSoundList = VisualState.ShootSoundList or {}
                    table.insert(VisualState.ShootSoundList, obj)
                    task.defer(stopDefaultShootSound, obj)
                end
            end))
        end
        for _, root in ipairs(getShootSoundRoots()) do
            watch(root)
        end
        task.delay(duration + 0.1, clearShootSoundWatch)
    end

    visualInitYield("helpers 3")

    local function makeLine(key)
        if not Drawing then return nil end
        local line = VisualState.CrosshairDrawings[key]
        if not line then
            line = Drawing.new("Line")
            VisualState.CrosshairDrawings[key] = line
        end
        return line
    end

    local function hideDrawingSet(set)
        for _, obj in pairs(set) do
            pcall(function()
                obj.Visible = false
            end)
        end
    end

    local function hideWireframeDrawings(fromIndex)
        local drawings = VisualState.WireframeDrawings
        if not drawings then return end
        for i = fromIndex or 1, #drawings do
            pcall(function()
                drawings[i].Visible = false
            end)
        end
    end

    local function destroyWireframeAdornments()
        for _, set in ipairs({VisualState.PrimitiveWireframes, VisualState.MeshWireframes}) do
            if set then
                for key, obj in pairs(set) do
                    releaseWireframe(obj)
                    set[key] = nil
                end
            end
        end
        local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if playerGui then
            for _, obj in ipairs(playerGui:GetDescendants()) do
                if obj.Name == "__LionVMWireframe"
                    or obj.Name == "__LionVMMeshWireframe"
                    or obj.Name == "__LionVMWireframeBox" then
                    releaseWireframe(obj)
                end
            end
        end
    end

    local function destroyStaleWireframeAdornments(activeParts)
        for _, set in ipairs({VisualState.PrimitiveWireframes, VisualState.MeshWireframes}) do
            if set then
                for part, wire in pairs(set) do
                    if not activeParts[part] or not part.Parent or not part:IsDescendantOf(workspace) then
                        releaseWireframe(wire)
                        set[part] = nil
                    end
                end
            end
        end
    end

    local function getWireframeDrawing(index)
        if not Drawing then return nil end
        VisualState.WireframeDrawings = VisualState.WireframeDrawings or {}
        local line = VisualState.WireframeDrawings[index]
        if not line then
            line = Drawing.new("Line")
            line.Thickness = 1
            line.Transparency = 1
            VisualState.WireframeDrawings[index] = line
        end
        return line
    end

    local function updateDrawingWireframe(parts, color)
        if not Drawing then
            hideWireframeDrawings(1)
            return
        end
        Camera = workspace.CurrentCamera
        if not Camera then
            hideWireframeDrawings(1)
            return
        end

        local edges = {
            {1, 2}, {2, 4}, {4, 3}, {3, 1},
            {5, 6}, {6, 8}, {8, 7}, {7, 5},
            {1, 5}, {2, 6}, {3, 7}, {4, 8},
        }
        local index = 1
        for _, part in ipairs(parts) do
            local cf, half = part.CFrame, part.Size * 0.5
            local corners = {
                cf * Vector3.new(-half.X, -half.Y, -half.Z),
                cf * Vector3.new( half.X, -half.Y, -half.Z),
                cf * Vector3.new(-half.X,  half.Y, -half.Z),
                cf * Vector3.new( half.X,  half.Y, -half.Z),
                cf * Vector3.new(-half.X, -half.Y,  half.Z),
                cf * Vector3.new( half.X, -half.Y,  half.Z),
                cf * Vector3.new(-half.X,  half.Y,  half.Z),
                cf * Vector3.new( half.X,  half.Y,  half.Z),
            }
            local points = {}
            for i, point in ipairs(corners) do
                local screen = Camera:WorldToViewportPoint(point)
                points[i] = {Vector2.new(screen.X, screen.Y), screen.Z > 0}
            end
            for _, edge in ipairs(edges) do
                local a, b = points[edge[1]], points[edge[2]]
                local line = getWireframeDrawing(index)
                if line then
                    line.From = a[1]
                    line.To = b[1]
                    line.Color = color or Color3.fromRGB(255, 255, 255)
                    line.Visible = a[2] and b[2]
                end
                index += 1
            end
        end
        hideWireframeDrawings(index)
    end

    local function updateCrosshair()
        if not (V.CrosshairEnabled and V.CrosshairEnabled.Enabled and Drawing) then
            hideDrawingSet(VisualState.CrosshairDrawings)
            return
        end
        Camera = workspace.CurrentCamera
        if not Camera then return end

        local center = Camera.ViewportSize / 2
        if V.CrosshairPosition and V.CrosshairPosition.Value == "position on target" then
            local _, targetPart = getClosestTarget()
            if targetPart then
                local screen, visible = worldToScreen(targetPart.Position)
                if visible then center = screen end
            end
        elseif V.CrosshairPosition and V.CrosshairPosition.Value == "position on barrel" then
            local screen, visible = worldToScreen(getMuzzleWorld())
            if visible then center = screen end
        end

        local length = V.CrosshairLength and V.CrosshairLength.Value or 20
        local gap = V.CrosshairOffset and V.CrosshairOffset.Value or 5
        local thickness = V.CrosshairThickness and V.CrosshairThickness.Value or 2
        local rot = math.rad((V.CrosshairRotation and V.CrosshairRotation.Value or 0) + tick() * 360 * (V.CrosshairSpeed and V.CrosshairSpeed.Value or 0))
        local bounce = V.CrosshairBounce and V.CrosshairBounce.Value or 0
        if bounce > 0 then
            gap += math.sin(tick() * 8 * (V.CrosshairSpeedMult and V.CrosshairSpeedMult.Value or 1)) * bounce
        end
        local color = V.CrosshairEnabled.Value or Color3.fromRGB(255, 255, 255)
        local outlineColor = V.CrosshairOutline and V.CrosshairOutline.Value or Color3.fromRGB(0, 0, 0)

        local dirs = {Vector2.new(0, -1), Vector2.new(1, 0), Vector2.new(0, 1), Vector2.new(-1, 0)}
        for i, dir in ipairs(dirs) do
            local rdir = Vector2.new(dir.X * math.cos(rot) - dir.Y * math.sin(rot), dir.X * math.sin(rot) + dir.Y * math.cos(rot))
            local from = center + rdir * gap
            local to = center + rdir * (gap + length)
            local outline = makeLine("outline" .. i)
            if outline then
                outline.From = from
                outline.To = to
                outline.Color = outlineColor
                outline.Thickness = thickness + 2
                outline.Transparency = 1
                outline.Visible = V.CrosshairOutline and V.CrosshairOutline.Enabled or false
            end
            local line = makeLine("line" .. i)
            if line then
                line.From = from
                line.To = to
                line.Color = color
                line.Thickness = thickness
                line.Transparency = 1
                line.Visible = true
            end
        end
    end

    local function updateViewmodelHighlight(part, name, enabled, colors, fillTransparency, outlineTransparency)
        if not part or not part:IsA("BasePart") then return end
        local highlight = part:FindFirstChild(name)
        if not enabled then
            if highlight then highlight:Destroy() end
            return
        end
        if not highlight then
            highlight = Instance.new("Highlight")
            highlight.Name = name
            highlight.Adornee = part
            highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            highlight.Parent = part
        end
        highlight.FillColor = (colors and colors[1]) or Color3.fromRGB(255,255,255)
        highlight.OutlineColor = (colors and colors[2]) or Color3.fromRGB(255,255,255)
        highlight.FillTransparency = math.clamp((fillTransparency or 50) / 100, 0, 1)
        highlight.OutlineTransparency = math.clamp((outlineTransparency or 0) / 100, 0, 1)
    end

    local function applyViewmodelOptions()
        local disable = V.VMDisabled and V.VMDisabled.Value or {}
        local now = tick()
        local vmInvisibleEnabled = V.VMInvisible and V.VMInvisible.Enabled
        local vmAppearanceEnabled = V.ViewmodelAppearance and V.ViewmodelAppearance.Enabled
        local vmChamsEnabled = V.VMChams and V.VMChams.Enabled
        local weaponHighlightEnabled = V.WeaponHighlight and V.WeaponHighlight.Enabled
        local armInvisibleEnabled = V.ArmInvisible and V.ArmInvisible.Enabled
        local armChamsEnabled = V.ArmChams and V.ArmChams.Enabled
        local armHighlightEnabled = V.ArmHighlight and V.ArmHighlight.Enabled
        local vmWireframeEnabled = V.VMWireframe and V.VMWireframe.Enabled and not vmInvisibleEnabled
        local vmDisableTexturesEnabled = V.VMDisableTextures and V.VMDisableTextures.Enabled
        local armAppearanceEnabled = V.ArmAppearance and V.ArmAppearance.Enabled
        local armDisableClothesEnabled = V.ArmDisableClothes and V.ArmDisableClothes.Enabled
        local offsetEnabled = V.VMOffset and V.VMOffset.Enabled
        local fpsEnabled = V.VMOverrideFps and V.VMOverrideFps.Enabled

        if fpsEnabled and setfpscap then
            local fps = V.VMFps and V.VMFps.Value or 60
            if VisualState.LastFpsCap ~= fps then
                VisualState.LastFpsCap = fps
                pcall(setfpscap, fps)
            end
        end

        local disableSig = ""
        if type(disable) == "table" then
            for _, name in ipairs(viewmodelDisableList) do
                if multiHas(disable, name) then
                    disableSig ..= name .. ";"
                end
            end
        end
        local viewmodelSig = table.concat({
            tostring(disableSig),
            tostring(fpsEnabled and (V.VMFps and V.VMFps.Value or 60) or ""),
            tostring(offsetEnabled and (V.VMOffsetX and V.VMOffsetX.Value or 0) or ""),
            tostring(offsetEnabled and (V.VMOffsetY and V.VMOffsetY.Value or 0) or ""),
            tostring(offsetEnabled and (V.VMOffsetZ and V.VMOffsetZ.Value or 0) or ""),
            tostring(vmInvisibleEnabled),
            tostring(vmAppearanceEnabled),
            tostring(V.VMColor and V.VMColor.Value or ""),
            tostring(V.VMMaterial and V.VMMaterial.Value or ""),
            tostring(V.VMTransparency and V.VMTransparency.Value or ""),
            tostring(vmChamsEnabled),
            tostring(V.VMChams and V.VMChams.Value or ""),
            tostring(V.VMChamFill and V.VMChamFill.Value or ""),
            tostring(V.VMChamMaterial and V.VMChamMaterial.Value or ""),
            tostring(weaponHighlightEnabled),
            tostring(V.WeaponHighlight and V.WeaponHighlight.Value or ""),
            tostring(V.WeaponHighlightFill and V.WeaponHighlightFill.Value or ""),
            tostring(V.WeaponHighlightOutline and V.WeaponHighlightOutline.Value or ""),
            tostring(armChamsEnabled),
            tostring(V.ArmChams and V.ArmChams.Value or ""),
            tostring(V.ArmChamMaterial and V.ArmChamMaterial.Value or ""),
            tostring(V.ArmChamTransparency and V.ArmChamTransparency.Value or ""),
            tostring(V.ArmInvisible and V.ArmInvisible.Enabled or false),
            tostring(armHighlightEnabled),
            tostring(V.ArmHighlight and V.ArmHighlight.Value or ""),
            tostring(V.ArmHighlightFill and V.ArmHighlightFill.Value or ""),
            tostring(V.ArmHighlightOutline and V.ArmHighlightOutline.Value or ""),
            tostring(vmWireframeEnabled),
            tostring(vmDisableTexturesEnabled),
            tostring(armAppearanceEnabled),
            tostring(V.ArmColor and V.ArmColor.Value or ""),
            tostring(V.ArmMaterial and V.ArmMaterial.Value or ""),
            tostring(V.ArmTransparency and V.ArmTransparency.Value or ""),
            tostring(armDisableClothesEnabled),
        }, "|")
        local viewmodelActive = disableSig ~= ""
            or offsetEnabled
            or vmInvisibleEnabled
            or vmAppearanceEnabled
            or vmChamsEnabled
            or weaponHighlightEnabled
            or armChamsEnabled
            or armInvisibleEnabled
            or armHighlightEnabled
            or vmWireframeEnabled
            or vmDisableTexturesEnabled
            or armAppearanceEnabled
            or armDisableClothesEnabled

        local activeWireframeRoots, activeWireframeKey
        if vmWireframeEnabled then
            activeWireframeRoots, activeWireframeKey = getActiveWireframeRoots()
            if VisualState.ActiveWireframeKey ~= activeWireframeKey then
                destroyWireframeAdornments()
                VisualState.ActiveWireframeKey = activeWireframeKey
            end
        elseif VisualState.ActiveWireframeKey then
            VisualState.ActiveWireframeKey = nil
        end

        if not VisualState.ViewmodelDirty
            and VisualState.ViewmodelSig == viewmodelSig
            and VisualState.ViewmodelAppliedAt
            and ((not viewmodelActive) or now - VisualState.ViewmodelAppliedAt < 0.5) then
            return
        end
        VisualState.ViewmodelSig = viewmodelSig
        VisualState.ViewmodelAppliedAt = now
        VisualState.ViewmodelDirty = false

        pcall(function()
            local cam = require(LocalPlayer.PlayerScripts.Controllers.CameraController)
            if multiHas(disable, "sway") and cam._sway_spring then cam._sway_spring.Value = Vector2.zero cam._sway_spring.Target = Vector2.zero end
            if multiHas(disable, "bobbing") then
                if cam._bobbing_speed_spring then cam._bobbing_speed_spring.Value = 0 cam._bobbing_speed_spring.Target = 0 end
                if cam._bobbing_value_spring then cam._bobbing_value_spring.Value = 0 cam._bobbing_value_spring.Target = 0 end
            end
            if multiHas(disable, "tilt") and cam._tilt_spring then cam._tilt_spring.Value = 0 cam._tilt_spring.Target = 0 end
        end)

        restoreHiddenSurfaceAppearances()

        for part, state in pairs(VisualState.InvisibilityGuards or {}) do
            local active = state.IsArm and armInvisibleEnabled or (not state.IsArm and vmInvisibleEnabled)
            if not active or not part.Parent then
                if state.TransparencyConnection then state.TransparencyConnection:Disconnect() end
                if state.LocalConnection then state.LocalConnection:Disconnect() end
                VisualState.InvisibilityGuards[part] = nil
            end
        end

        hideWireframeDrawings(1)
        local wireframeWasEnabled = VisualState.WireframeWasEnabled == true
        if not vmWireframeEnabled and wireframeWasEnabled then
            destroyWireframeAdornments()
        end
        VisualState.WireframeWasEnabled = vmWireframeEnabled == true

        local activeWireframeParts = {}
        for _, model in ipairs(getLocalViewmodels()) do
            for _, obj in ipairs(getViewmodelDescendants(model)) do
                if obj:IsA("BasePart") then
                    if obj:GetAttribute("PlexCustomHiddenRig") then
                        obj.Transparency, obj.LocalTransparencyModifier = 1, 1
                        continue
                    end
                    local isArm = isArmInstance(obj)
                    local isWeapon = isWeaponViewmodelInstance(obj)
                    local isWireWeapon = activeWireframeRoots ~= nil and isInRootSet(obj, activeWireframeRoots)
                    restoreVisual(obj)
                    if (isWeapon and (vmInvisibleEnabled or vmAppearanceEnabled or vmChamsEnabled or weaponHighlightEnabled or vmDisableTexturesEnabled))
                        or (isArm and (armInvisibleEnabled or armAppearanceEnabled or armChamsEnabled or armHighlightEnabled or armDisableClothesEnabled)) then
                        getOriginalVisual(obj)
                    end
                    if vmAppearanceEnabled and isWeapon then
                        obj.Color = (V.VMColor and V.VMColor.Value) or obj.Color
                        obj.Material = getMaterial(V.VMMaterial and V.VMMaterial.Value)
                        obj.Transparency = math.clamp(1 - ((V.VMTransparency and V.VMTransparency.Value or 100) / 100), 0, 1)
                        pcall(function()
                            obj.MaterialVariant = ""
                        end)
                    end
                    if vmChamsEnabled and isWeapon then
                        obj.Material = getMaterial(V.VMChamMaterial and V.VMChamMaterial.Value or "Neon")
                        obj.Color = (V.VMChams.Value or Color3.fromRGB(255, 255, 255))
                        obj.Transparency = math.clamp((V.VMChamFill and V.VMChamFill.Value or 0) / 100, 0, 1)
                        pcall(function() obj.MaterialVariant = "" end)
                    end
                    -- Rivals and viewmodel animations can rewrite local transparency after
                    -- the visual pass. Guard both properties while enabled so the gun stays hidden.
                    if (vmInvisibleEnabled and isWeapon) or (armInvisibleEnabled and isArm) then
                        VisualState.InvisibilityGuards = VisualState.InvisibilityGuards or setmetatable({}, {__mode = "k"})
                        if not VisualState.InvisibilityGuards[obj] then
                            VisualState.InvisibilityGuards[obj] = {IsArm = isArm and armInvisibleEnabled or false}
                            local function enforceInvisible()
                                local state = VisualState.InvisibilityGuards and VisualState.InvisibilityGuards[obj]
                                if not state or state.Updating or not obj.Parent then return end
                                local option = state.IsArm and V.ArmInvisible or V.VMInvisible
                                if not (option and option.Enabled) then return end
                                state.Updating = true
                                if obj.Transparency < 1 then obj.Transparency = 1 end
                                if obj.LocalTransparencyModifier < 1 then obj.LocalTransparencyModifier = 1 end
                                state.Updating = false
                            end
                            local state = VisualState.InvisibilityGuards[obj]
                            state.TransparencyConnection = obj:GetPropertyChangedSignal("Transparency"):Connect(enforceInvisible)
                            state.LocalConnection = obj:GetPropertyChangedSignal("LocalTransparencyModifier"):Connect(enforceInvisible)
                            mainapi:Clean(state.TransparencyConnection)
                            mainapi:Clean(state.LocalConnection)
                        end
                        obj.Transparency, obj.LocalTransparencyModifier = 1, 1
                    end
                    updateViewmodelHighlight(
                        obj,
                        "__LionVMWeaponHighlight",
                        isWeapon and weaponHighlightEnabled and not vmInvisibleEnabled,
                        V.WeaponHighlight and V.WeaponHighlight.Colors,
                        V.WeaponHighlightFill and V.WeaponHighlightFill.Value,
                        V.WeaponHighlightOutline and V.WeaponHighlightOutline.Value
                    )
                    if armAppearanceEnabled and isArm then
                        obj.Color = (V.ArmColor and V.ArmColor.Value) or obj.Color
                        obj.Material = getMaterial(V.ArmMaterial and V.ArmMaterial.Value)
                        obj.Transparency = math.clamp(1 - ((V.ArmTransparency and V.ArmTransparency.Value or 100) / 100), 0, 1)
                        pcall(function()
                            obj.MaterialVariant = ""
                        end)
                    end
                    if armChamsEnabled and isArm then
                        obj.Color = (V.ArmChams.Value or Color3.fromRGB(255,255,255))
                        obj.Material = getMaterial(V.ArmChamMaterial and V.ArmChamMaterial.Value or "Neon")
                        obj.Transparency = (V.ArmInvisible and V.ArmInvisible.Enabled) and 1
                            or math.clamp((V.ArmChamTransparency and V.ArmChamTransparency.Value or 0) / 100, 0, 1)
                        pcall(function() obj.MaterialVariant = "" end)
                    end
                    if armInvisibleEnabled and isArm then
                        obj.Transparency, obj.LocalTransparencyModifier = 1, 1
                    end
                    updateViewmodelHighlight(
                        obj,
                        "__LionVMArmHighlight",
                        isArm and armHighlightEnabled and not armInvisibleEnabled,
                        V.ArmHighlight and V.ArmHighlight.Colors,
                        V.ArmHighlightFill and V.ArmHighlightFill.Value,
                        V.ArmHighlightOutline and V.ArmHighlightOutline.Value
                    )
                    if vmWireframeEnabled and isWireWeapon then
                        activeWireframeParts[obj] = true
                        getOriginalVisual(obj)
                        obj.Transparency = 1
                    end
                    if obj:IsA("MeshPart") and ((isWeapon and (vmDisableTexturesEnabled or vmAppearanceEnabled)) or ((armDisableClothesEnabled or armAppearanceEnabled) and isArm)) then
                        obj.TextureID = ""
                    end
                    if vmWireframeEnabled and isWireWeapon and obj:IsA("MeshPart") then
                        updateMeshWireframe(obj, true, getWireframeColor(obj))
                    elseif vmWireframeEnabled and isWireWeapon and not obj:FindFirstChildOfClass("SpecialMesh") then
                        updateWireframe(obj, true, getWireframeColor(obj))
                    elseif vmWireframeEnabled then
                        if obj:IsA("MeshPart") then
                            updateMeshWireframe(obj, false)
                        end
                        updateWireframe(obj, false)
                    end
                elseif obj:IsA("Texture") or obj:IsA("Decal") then
                    restoreVisual(obj)
                    if (isWeaponViewmodelInstance(obj) and (vmInvisibleEnabled or vmDisableTexturesEnabled or vmAppearanceEnabled)) or ((armDisableClothesEnabled or armAppearanceEnabled) and isArmInstance(obj)) then
                        getOriginalVisual(obj)
                        obj.Transparency = 1
                    end
                elseif obj:IsA("SpecialMesh") then
                    local isArm = isArmInstance(obj)
                    local isWeapon = isWeaponViewmodelInstance(obj)
                    local isWireWeapon = activeWireframeRoots ~= nil and isInRootSet(obj, activeWireframeRoots)
                    restoreVisual(obj)
                    if (isWeapon and (vmDisableTexturesEnabled or vmAppearanceEnabled)) or (isArm and (armAppearanceEnabled or armDisableClothesEnabled)) then
                        getOriginalVisual(obj)
                    end
                    if isWeapon and (vmDisableTexturesEnabled or vmAppearanceEnabled) then
                        obj.TextureId = ""
                    end
                    if isArm and (armDisableClothesEnabled or armAppearanceEnabled) then
                        obj.TextureId = ""
                    end
                    if isArm and armAppearanceEnabled and V.ArmColor then
                        local c = V.ArmColor.Value or Color3.fromRGB(255, 255, 255)
                        obj.VertexColor = Vector3.new(c.R, c.G, c.B)
                    elseif isWeapon and vmAppearanceEnabled and V.VMColor then
                        local c = V.VMColor.Value or Color3.fromRGB(255, 255, 255)
                        obj.VertexColor = Vector3.new(c.R, c.G, c.B)
                    end
                    if vmWireframeEnabled then
                        if isWireWeapon and obj.Parent and obj.Parent:IsA("BasePart") then
                            activeWireframeParts[obj.Parent] = true
                        end
                        updateMeshWireframe(obj, isWireWeapon, getWireframeColor(obj))
                    end
                elseif obj:IsA("SurfaceAppearance") then
                    if (isWeaponViewmodelInstance(obj) and (vmDisableTexturesEnabled or vmAppearanceEnabled)) or ((armDisableClothesEnabled or armAppearanceEnabled) and isArmInstance(obj)) then
                        hideSurfaceAppearance(obj)
                    end
                elseif obj:IsA("Shirt") or obj:IsA("Pants") or obj:IsA("ShirtGraphic") then
                    restoreVisual(obj)
                    if armDisableClothesEnabled then
                        getOriginalVisual(obj)
                        pcall(function()
                            if obj:IsA("Shirt") then
                                obj.ShirtTemplate = ""
                            elseif obj:IsA("Pants") then
                                obj.PantsTemplate = ""
                            elseif obj:IsA("ShirtGraphic") then
                                obj.Graphic = ""
                            end
                        end)
                    end
                elseif obj:IsA("ParticleEmitter") or obj:IsA("Beam") or obj:IsA("Trail") then
                    if multiHas(disable, "muzzle flash") then obj.Enabled = false end
                end
            end
        end
        if vmWireframeEnabled then
            destroyStaleWireframeAdornments(activeWireframeParts)
        end
    end

    visualInitYield("helpers 4")

    local function restoreViewmodelTransforms()
        for model,state in pairs(VisualState.TransformPivots or {}) do
            pcall(function()
                if model.Parent and model:GetPivot()==state.Output then model:PivotTo(state.Base) end
            end)
        end
        VisualState.TransformPivots=nil
    end

    local function applyViewmodelOffset()
        local legacy=V.VMOffset and V.VMOffset.Enabled
        local transform=V.TransformGroup and V.TransformGroup.Enabled
        if not legacy and not transform then restoreViewmodelTransforms();return end
        local function axis(old,new)
            return (legacy and V[old] and V[old].Value or 0)+(transform and V[new] and V[new].Value or 0)
        end
        local offset=CFrame.new(axis("VMOffsetX","TransformX"),axis("VMOffsetY","TransformY"),axis("VMOffsetZ","TransformZ"))
            * CFrame.Angles(0,0,math.rad(transform and V.TransformRoll and V.TransformRoll.Value or 0))
        VisualState.TransformPivots=VisualState.TransformPivots or setmetatable({}, {__mode="k"})
        for _,model in ipairs(getLocalViewmodels()) do
            pcall(function()
                local pivot=model:GetPivot()
                local state=VisualState.TransformPivots[model]
                -- Preserve the renderer's latest pose; reuse the base only when our output is unchanged.
                local base=state and pivot==state.Output and state.Base or pivot
                local output=base*offset
                state=state or {}
                state.Base,state.Output=base,output
                VisualState.TransformPivots[model]=state
                model:PivotTo(output)
            end)
        end
    end

    local function disableSelected(name)
        return multiHas(V.VMDisabled and V.VMDisabled.Value or {}, name)
    end

    local function shouldBlockAnimationKey(key)
        local lower = tostring(key or ""):lower()
        if lower == "" then return false end
        if disableSelected("idle animation") and lower:find("idle", 1, true) then return true end
        if disableSelected("jump animation") and lower:find("jump", 1, true) then return true end
        if disableSelected("slide animation") and lower:find("slide", 1, true) then return true end
        if disableSelected("equip animation") and lower:find("equip", 1, true) then return true end
        if disableSelected("reload animation") and lower:find("reload", 1, true) then return true end
        if disableSelected("shoot animation") and (lower:find("shoot", 1, true) or lower:find("fire", 1, true) or lower:find("attack", 1, true)) then return true end
        if disableSelected("sprint animation") and (lower:find("sprint", 1, true) or lower:find("run", 1, true)) then return true end
        return false
    end

    local function zeroSpring(spring, value)
        if not spring then return end
        pcall(function()
            spring.Value = value
            spring.Target = value
        end)
    end

    local function forceViewmodelAimValue(vm, enabled)
        if not vm then return end
        local value = enabled and 1 or 0
        vm.IsAiming = enabled == true
        vm.Aiming = enabled == true
        vm._is_aiming = enabled == true
        if vm.CurrentAimValue ~= nil then
            vm.CurrentAimValue = value
        end
    end

    local function applyViewmodelDisableToObject(vm)
        if not vm then return end
        if disableSelected("sway") then zeroSpring(vm._sway_spring, Vector2.zero) end
        if disableSelected("tilt") then
            zeroSpring(vm._tilt_spring, Vector2.zero)
            zeroSpring(vm._raycast_tilt_spring, 0)
        end
        if disableSelected("bobbing") then
            zeroSpring(vm._bobbing_speed_spring, 0)
            zeroSpring(vm._bobbing_value_spring, Vector2.zero)
            vm._bobbing_tick = 0
        end
        if disableSelected("jump animation") then
            zeroSpring(vm._jump_spring, 0)
            vm.CurrentJumpValue = 0
        end
        if disableSelected("sprint animation") then
            zeroSpring(vm._sprinting_spring, 0)
        end
        if disableSelected("aiming animation") then
            local item = vm.ClientItem
            local isAiming = vm.IsAiming == true or vm.Aiming == true or vm._is_aiming == true
            pcall(function()
                if item and item.Get then
                    isAiming = isAiming or item:Get("IsAiming") == true
                end
            end)
            if isAiming and vm.CurrentAimValue ~= nil then
                forceViewmodelAimValue(vm, true)
            end
        end
        if V.VMRecoil then
            local scale = math.clamp((V.VMRecoil.Value or 100) / 100, 0, 1)
            if typeof(vm.CurrentRecoilValue) == "Vector3" then
                vm.CurrentRecoilValue *= scale
            end
        end
    end

    local function installAimingHooks()
        if VisualState.AimingHooked then return end
        local success, gunModule = pcall(function()
            return require(LocalPlayer.PlayerScripts.Modules.ItemTypes.Gun)
        end)
        if not success or not gunModule then return end

        if gunModule.StartAiming then
            VisualState.OriginalGunStartAiming = VisualState.OriginalGunStartAiming or gunModule.StartAiming
            gunModule.StartAiming = function(self, ...)
                if not disableSelected("aiming animation") then
                    return VisualState.OriginalGunStartAiming(self, ...)
                end

                self:SetReplicate("IsAiming", true)
                self.StopSprinting:Fire()
                self.ViewModel:SetAiming(true)
                self:SetReplicate("FOVOffset", self.Info.AimFOVOffset)

                if self.ViewModel and self.ViewModel.CurrentAimValue ~= nil then
                    self.ViewModel.CurrentAimValue = 1
                end

                return true, "StartAiming"
            end
        end

        if gunModule.GetAimSpeed then
            VisualState.OriginalGunGetAimSpeed = VisualState.OriginalGunGetAimSpeed or gunModule.GetAimSpeed
            gunModule.GetAimSpeed = function(self)
                if disableSelected("aiming animation") then
                    return 999
                end
                return VisualState.OriginalGunGetAimSpeed(self)
            end
        end

        VisualState.AimingHooked = true
    end

    local function installViewmodelHooks()
        if VisualState.ViewmodelHooked then return end
        local ok, viewmodelModule = pcall(function()
            return require(LocalPlayer.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem.ClientViewModel)
        end)
        if ok and type(viewmodelModule) == "table" then
            if type(viewmodelModule.Update) == "function" then
                VisualState.OriginalViewmodelUpdate = VisualState.OriginalViewmodelUpdate or viewmodelModule.Update
                viewmodelModule.Update = function(self, ...)
                    applyViewmodelDisableToObject(self)
                    local result = {VisualState.OriginalViewmodelUpdate(self, ...)}
                    applyViewmodelDisableToObject(self)
                    return unpack(result)
                end
            end
            if type(viewmodelModule.MuzzleFlash) == "function" then
                VisualState.OriginalViewmodelMuzzleFlash = VisualState.OriginalViewmodelMuzzleFlash or viewmodelModule.MuzzleFlash
                viewmodelModule.MuzzleFlash = function(self, ...)
                    if disableSelected("muzzle flash") then return end
                    return VisualState.OriginalViewmodelMuzzleFlash(self, ...)
                end
            end
            if type(viewmodelModule.SetAiming) == "function" then
                VisualState.OriginalViewmodelSetAiming = VisualState.OriginalViewmodelSetAiming or viewmodelModule.SetAiming
                viewmodelModule.SetAiming = function(self, enabled, ...)
                    local result = {VisualState.OriginalViewmodelSetAiming(self, enabled, ...)}
                    if disableSelected("aiming animation") then
                        forceViewmodelAimValue(self, enabled == true)
                    end
                    return unpack(result)
                end
            end
            if type(viewmodelModule.PlayAnimation) == "function" then
                VisualState.OriginalViewmodelPlayAnimation = VisualState.OriginalViewmodelPlayAnimation or viewmodelModule.PlayAnimation
                viewmodelModule.PlayAnimation = function(self, key, ...)
                    if shouldBlockAnimationKey(key) then return nil end
                    return VisualState.OriginalViewmodelPlayAnimation(self, key, ...)
                end
            end
        end

        pcall(function()
            local animatorModule = require(LocalPlayer.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem.ClientViewModel.ViewModelAnimator)
            if type(animatorModule) == "table" and type(animatorModule.PlayAnimation) == "function" then
                VisualState.OriginalAnimatorPlayAnimation = VisualState.OriginalAnimatorPlayAnimation or animatorModule.PlayAnimation
                animatorModule.PlayAnimation = function(self, key, ...)
                    if shouldBlockAnimationKey(key) then return nil end
                    return VisualState.OriginalAnimatorPlayAnimation(self, key, ...)
                end
            end
        end)

        VisualState.ViewmodelHooked = true
    end

    local function applyItemStatus()
        if not (V.OverrideWeaponStatus and V.OverrideWeaponStatus.Enabled) then return end
        local selected = V.WeaponStatus and V.WeaponStatus.Value or "Prime"
        local now = tick()
        if VisualState.ItemStatusValue == selected
            and VisualState.ItemStatusAppliedAt
            and now - VisualState.ItemStatusAppliedAt < 1 then
            return
        end
        VisualState.ItemStatusValue = selected
        VisualState.ItemStatusAppliedAt = now
        pcall(function()
            local itemLibrary = require(ReplicatedStorage.Modules.ItemLibrary)
            for name, info in pairs(itemLibrary.Items or {}) do
                if type(info) == "table" then
                    VisualState.OriginalStatuses[name] = VisualState.OriginalStatuses[name] or info.Status
                    info.Status = selected
                end
            end
        end)
    end

    local function safeTableGet(tab, key)
        if typeof(tab) ~= "table" then return nil end

        local okRaw, rawValue = pcall(rawget, tab, key)
        if okRaw then
            return rawValue
        end
        return nil
    end

    local function findInTableValues(tab, callback, budget)
        local found
        budget=budget or {Remaining=64,Seen={}}
        if budget.Seen[tab] then return nil end
        budget.Seen[tab]=true
        pcall(function()
            for _, value in pairs(tab) do
                if budget.Remaining<=0 then return end
                budget.Remaining-=1
                found = callback(value)
                if found ~= nil then
                    return
                end
            end
        end)
        return found
    end

    local function getDamageValue(data, depth, budget)
        if depth > 6 or typeof(data) ~= "table" then return nil end
        local direct = safeTableGet(data, utf8.char(0))
            or safeTableGet(data, "Damage")
            or safeTableGet(data, "damage")
            or safeTableGet(data, "Amount")
            or safeTableGet(data, "amount")
        if type(direct) == "number" and direct > 0 then return direct end
        budget=budget or {Remaining=64,Seen={}}
        return findInTableValues(data, function(value)
            if typeof(value) == "table" then
                local found = getDamageValue(value, depth + 1,budget)
                if found then return found end
            end
        end,budget)
    end

    local function createDamageText(position, damage)
        if not position then return end
        local part = Instance.new("Part")
        part.Name = "LionHitDamageText"
        part.Anchored = true
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.Transparency = 1
        part.Size = Vector3.new(0.1, 0.1, 0.1)
        part.Position = position + Vector3.new(0, 1.5, 0)
        part.Parent = workspace

        local gui = Instance.new("BillboardGui")
        gui.AlwaysOnTop = true
        gui.Size = UDim2.fromOffset(100, 32)
        gui.StudsOffset = Vector3.new(0, 0.5, 0)
        gui.Parent = part

        local label = Instance.new("TextLabel")
        label.BackgroundTransparency = 1
        label.Size = UDim2.fromScale(1, 1)
        label.Font = Enum.Font.SourceSansBold
        label.TextSize = 24
        label.TextStrokeTransparency = 0
        label.TextColor3 = (V.HitEffectEnabled and V.HitEffectEnabled.Value) or Color3.fromRGB(255, 255, 255)
        label.Text = tostring(damage or "")
        label.Parent = gui

        task.spawn(function()
            local start = tick()
            while part.Parent and tick() - start < 0.7 do
                part.Position += Vector3.new(0, 0.035, 0)
                label.TextTransparency = math.clamp((tick() - start) / 0.7, 0, 1)
                label.TextStrokeTransparency = label.TextTransparency
                task.wait()
            end
        end)
        Debris:AddItem(part, 1)
    end

    local function createHitEffect(position, damage, hitPart)
        if not (V.HitEffectEnabled and V.HitEffectEnabled.Enabled and position) then return end
        local part = Instance.new("Part")
        part.Name = "LionHitEffect"
        part.Anchored = not (V.HitEffectWeld and V.HitEffectWeld.Enabled and hitPart and hitPart:IsA("BasePart"))
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.Size = Vector3.new(0.25, 0.25, 0.25)
        part.Transparency = 1
        part.CFrame = CFrame.new(position)
        part.Parent = workspace
        if not part.Anchored then
            local weld = Instance.new("WeldConstraint")
            weld.Part0 = part
            weld.Part1 = hitPart
            weld.Parent = part
        end

        local color = (V.HitEffectEnabled and V.HitEffectEnabled.Value) or Color3.fromRGB(255, 255, 255)
        local emitter = Instance.new("ParticleEmitter")
        emitter.Color = ColorSequence.new(color)
        emitter.LightEmission = 1
        emitter.Rate = 0
        emitter.Lifetime = NumberRange.new(0.35, 0.7)
        emitter.Speed = NumberRange.new(6, 16)
        emitter.SpreadAngle = Vector2.new(360, 360)
        emitter.Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.25),
            NumberSequenceKeypoint.new(1, 0)
        })
        emitter.Texture = "rbxassetid://243660364"
        emitter.Parent = part
        emitter:Emit(18)

        local selected = V.HitEffectsSelected and V.HitEffectsSelected.Value or {}
        if type(selected) ~= "table" then selected = {} end
        if next(selected) == nil or multiHas(selected, "Ring") or multiHas(selected, "Filled Circle") or multiHas(selected, "Ripple") then
            local orb = Instance.new("Part")
            orb.Name = "LionHitRing"
            orb.Shape = Enum.PartType.Ball
            orb.Anchored = true
            orb.CanCollide = false
            orb.CanQuery = false
            orb.CanTouch = false
            orb.Material = getMaterial(V.HitEffectMaterial and V.HitEffectMaterial.Value)
            orb.Color = color
            orb.Transparency = multiHas(selected, "Filled Circle") and 0.35 or 0.65
            orb.Size = Vector3.new(0.25, 0.25, 0.25)
            orb.Position = position
            orb.Parent = workspace
            task.spawn(function()
                local start = tick()
                while orb.Parent and tick() - start < 0.45 do
                    local alpha = (tick() - start) / 0.45
                    local size = 0.25 + alpha * 4
                    orb.Size = Vector3.new(size, size, size)
                    orb.Transparency = math.clamp(0.35 + alpha * 0.65, 0, 1)
                    task.wait()
                end
            end)
            Debris:AddItem(orb, 0.55)
        end

        if multiHas(selected, "Blades") or multiHas(selected, "slashes") or multiHas(selected, "Zap") then
            for i = 1, 4 do
                local slash = Instance.new("Part")
                slash.Name = "LionHitSlash"
                slash.Anchored = true
                slash.CanCollide = false
                slash.CanQuery = false
                slash.CanTouch = false
                slash.Material = Enum.Material.Neon
                slash.Color = color
                slash.Size = Vector3.new(0.06, 0.06, 2.5)
                slash.CFrame = CFrame.new(position) * CFrame.Angles(math.random() * math.pi, math.random() * math.pi, math.random() * math.pi)
                slash.Parent = workspace
                Debris:AddItem(slash, 0.25)
            end
        end

        if damage and (multiHas(selected, "fortnite damage") or multiHas(selected, "phantom forces")) then
            createDamageText(position, damage)
        end

        Debris:AddItem(part, 2)
    end

    visualInitYield("helpers 5")

    local function getTracerColor()
        if V.CustomTracerColor and typeof(V.CustomTracerColor.Value) == "Color3" then
            return V.CustomTracerColor.Value
        end
        if V.CustomTracers and V.CustomTracers.Value then
            return V.CustomTracers.Value
        end
        return Color3.fromRGB(97, 131, 255)
    end

    local tracerNumber
    local function tracerColorSequence()
        local mode = V.CustomTracerColorMode and tostring(V.CustomTracerColorMode.Value or "solid"):lower() or "solid"
        local color = getTracerColor()
        if mode == "rainbow" then
            local speed = math.max(0.1, tracerNumber(V.CustomTracerRainbowSpeed, 6))
            color = Color3.fromHSV((os.clock() * speed / 10) % 1, 0.9, 1)
            local finish = Color3.fromHSV(((os.clock() * speed / 10) + 0.18) % 1, 0.9, 1)
            return ColorSequence.new(color, finish), color
        end
        if mode == "gradient" and V.CustomTracerEndColor and typeof(V.CustomTracerEndColor.Value) == "Color3" then
            return ColorSequence.new(color, V.CustomTracerEndColor.Value), color
        end
        return ColorSequence.new(color), color
    end

    local tracerDedup = {}
    local tracerPacketDedup = setmetatable({}, {__mode = "k"})
    local tracerQueue = {}
    local tracerQueueHead, tracerQueueCount = 1, 0
    local tracerSettings, tracerSettingsRevision = nil, 0
    local tracerDedupCursor = 0
    local tracerHooksActive = true
    local function invalidateTracerSettings()
        tracerSettings = nil
    end
    tracerNumber = function(option, fallback)
        local value = option and tonumber(option.Value)
        return value or fallback
    end

    local function tracerTransparency()
        local alpha = math.clamp(tracerNumber(V.CustomTracerTransparency, 0) / 100, 0, 1)
        local fade = V.CustomTracerFade and tostring(V.CustomTracerFade.Value or "none"):lower() or "none"
        if fade == "tail" then return NumberSequence.new(1, alpha) end
        if fade == "tip" then return NumberSequence.new(alpha, 1) end
        if fade == "both" then
            return NumberSequence.new({
                NumberSequenceKeypoint.new(0, 1),
                NumberSequenceKeypoint.new(0.5, alpha),
                NumberSequenceKeypoint.new(1, 1),
            })
        end
        return NumberSequence.new(alpha)
    end

    local function tracerTexture()
        local value = V.CustomTracerTexture and tostring(V.CustomTracerTexture.Value or "") or ""
        local id = value:match("%d+")
        return id and ("rbxassetid://" .. id) or ""
    end

    local function tracerOrigin(startPos)
        local mode = V.CustomTracerOrigin and tostring(V.CustomTracerOrigin.Value or "muzzle"):lower() or "muzzle"
        if mode == "camera" and Camera then return Camera.CFrame.Position end
        if mode == "character" then
            local character = LocalPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if root then return root.Position + Vector3.new(0, 1.4, 0) end
        end
        return startPos
    end

    local function refreshTracerSettings()
        if tracerSettings then return tracerSettings end
        tracerSettingsRevision += 1
        local colorSequence, color = tracerColorSequence()
        local settings = {
            Revision = tracerSettingsRevision,
            Color = color, ColorSequence = colorSequence,
            Rainbow = V.CustomTracerColorMode and V.CustomTracerColorMode.Value == "rainbow",
            Transparency = tracerTransparency(), Texture = tracerTexture(),
            Width0 = math.max(0.01, tracerNumber(V.CustomTracerWidth, 0.18)),
            Width1 = math.max(0.01, tracerNumber(V.CustomTracerEndWidth, 0.05)),
            Life = math.clamp(tracerNumber(V.CustomTracerLife, 0.65), 0.05, 5),
            Style = V.CustomTracerStyle and tostring(V.CustomTracerStyle.Value or "glow"):lower() or "glow",
            Brightness = math.clamp(tracerNumber(V.CustomTracerBrightness, 6), 0, 20),
            FaceCamera = not V.CustomTracerFaceCamera or V.CustomTracerFaceCamera.Enabled,
            Curve = tracerNumber(V.CustomTracerCurve, 0),
            Segments = math.clamp(math.floor(tracerNumber(V.CustomTracerSegments, 8)), 1, 24),
            TextureSpeed = tracerNumber(V.CustomTracerTextureSpeed, 0),
            TextureLength = math.max(0.1, tracerNumber(V.CustomTracerTextureLength, 1)),
            Impact = V.CustomTracerImpact and V.CustomTracerImpact.Enabled,
            ImpactSize = math.max(0.05, tracerNumber(V.CustomTracerImpactSize, 0.25)),
            ImpactShape = V.CustomTracerImpactShape and tostring(V.CustomTracerImpactShape.Value):lower() == "block" and Enum.PartType.Block or Enum.PartType.Ball,
            ImpactAlpha = math.clamp(tracerNumber(V.CustomTracerTransparency, 0) / 100, 0, 0.9),
            MinDistance = math.max(0.5, tracerNumber(V.CustomTracerMinDistance, 0)),
            MaxDistance = math.max(tracerNumber(V.CustomTracerMinDistance, 0), tracerNumber(V.CustomTracerMaxDistance, 5000)),
            StartOffset = math.max(0, tracerNumber(V.CustomTracerStartOffset, 0)),
            EndOffset = math.max(0, tracerNumber(V.CustomTracerEndOffset, 0)),
        }
        tracerSettings = settings
        return settings
    end

    local function acquireTracerEntry(now)
        VisualState.TracerPool = VisualState.TracerPool or {}
        local pool = VisualState.TracerPool
        local selected, oldest = nil, math.huge
        for index, entry in ipairs(pool) do
            if not entry.ExpiresAt or entry.ExpiresAt <= now then selected = index; break end
            if entry.ExpiresAt < oldest then oldest = entry.ExpiresAt; selected = index end
        end
        if #pool < 24 and (not selected or (pool[selected].ExpiresAt or 0) > now) then
            selected = #pool + 1
        end
        selected = selected or 1
        VisualState.TracerPoolCursor = selected
        return pool[selected]
    end

    local function createTracerBeam(startPos, endPos)
        if not (V.CustomTracers and V.CustomTracers.Enabled) then return end
        if typeof(startPos) ~= "Vector3" or typeof(endPos) ~= "Vector3" then return end
        startPos = tracerOrigin(startPos)
        local delta = endPos - startPos
        local distance = delta.Magnitude
        local settings = refreshTracerSettings()
        if distance < settings.MinDistance or distance > settings.MaxDistance then return end
        local direction = delta.Unit
        local startOffset = math.min(distance * 0.45, settings.StartOffset)
        local endOffset = math.min(distance * 0.45, settings.EndOffset)
        startPos += direction * startOffset
        endPos -= direction * endOffset

        local now = os.clock()
        -- A bounded endpoint ring catches fallback packets that use a different table.
        local sx, sy, sz = math.floor(startPos.X * 2), math.floor(startPos.Y * 2), math.floor(startPos.Z * 2)
        local ex, ey, ez = math.floor(endPos.X * 2), math.floor(endPos.Y * 2), math.floor(endPos.Z * 2)
        for _, previous in ipairs(tracerDedup) do
            if now - previous.At < 0.04 and previous.SX == sx and previous.SY == sy and previous.SZ == sz
                and previous.EX == ex and previous.EY == ey and previous.EZ == ez then return false end
        end
        tracerDedupCursor = (tracerDedupCursor % 24) + 1
        local previous = tracerDedup[tracerDedupCursor] or {}
        previous.SX, previous.SY, previous.SZ = sx, sy, sz
        previous.EX, previous.EY, previous.EZ, previous.At = ex, ey, ez, now
        tracerDedup[tracerDedupCursor] = previous
        local entry = acquireTracerEntry(now)

        if not entry or not entry.P0 or not entry.P0.Parent or not entry.P1 or not entry.P1.Parent
            or not entry.Beam or not entry.Beam.Parent then
            if entry then
                pcall(function() if entry.P0 then entry.P0:Destroy() end end)
                pcall(function() if entry.P1 then entry.P1:Destroy() end end)
            end

            local p0 = Instance.new("Part")
            p0.Name = "LionCustomTracerStart"
            p0.Anchored = true
            p0.CanCollide = false
            p0.CanQuery = false
            p0.CanTouch = false
            p0.CastShadow = false
            p0.Transparency = 1
            p0.Size = Vector3.new(0.05, 0.05, 0.05)
            p0.Parent = workspace

            local p1 = p0:Clone()
            p1.Name = "LionCustomTracerEnd"
            p1.Parent = workspace

            local a0 = Instance.new("Attachment")
            a0.Parent = p0
            local a1 = Instance.new("Attachment")
            a1.Parent = p1

            local beam = Instance.new("Beam")
            beam.Attachment0 = a0
            beam.Attachment1 = a1
            beam.Parent = p0

            entry = {
                P0 = p0,
                P1 = p1,
                Beam = beam,
                Generation = 0,
            }
            VisualState.TracerPool[VisualState.TracerPoolCursor] = entry
        end

        local p0, p1, beam = entry.P0, entry.P1, entry.Beam
        p0.Position, p1.Position = startPos, endPos
        local colorSequence, color = settings.ColorSequence, settings.Color
        if settings.Rainbow then colorSequence, color = tracerColorSequence() end
        if entry.Revision ~= settings.Revision then
            beam.Width0, beam.Width1 = settings.Width0, settings.Width1
            beam.LightEmission = math.clamp(settings.Brightness, 0, 1)
            beam.Brightness, beam.FaceCamera = settings.Brightness, settings.FaceCamera
            beam.Transparency, beam.Color = settings.Transparency, colorSequence
            beam.CurveSize0, beam.CurveSize1 = settings.Curve, -settings.Curve
            beam.Segments = settings.Segments
            beam.Texture, beam.TextureSpeed, beam.TextureLength = settings.Texture, settings.TextureSpeed, settings.TextureLength
            if settings.Style == "laser" then beam.Width1 = settings.Width0; beam.LightEmission = 1
            elseif settings.Style == "soft" then
                beam.Width0, beam.Width1 = settings.Width0 * 1.65, settings.Width1 * 1.65
                beam.Brightness = math.min(settings.Brightness, 3)
            elseif settings.Style == "taper" then beam.Width1 = math.max(0.01, settings.Width1 * 0.35)
            elseif settings.Style == "pulse" then beam.Width0, beam.Width1 = settings.Width0 * 1.35, settings.Width1 * 0.65
            elseif settings.Style == "electric" then beam.Segments = math.max(8, settings.Segments); beam.LightEmission = 1 end
            entry.Revision = settings.Revision
        end
        if settings.Rainbow then beam.Color = colorSequence end
        if settings.Style == "electric" and math.abs(settings.Curve) < 0.01 then
            beam.CurveSize0 = math.random(-30, 30) / 10
            beam.CurveSize1 = -beam.CurveSize0
        end
        if settings.Impact and (not entry.Impact or not entry.Impact.Parent) then
            local impact = Instance.new("Part")
            impact.Name = "LionCustomTracerImpact"
            impact.Anchored, impact.CanCollide, impact.CanQuery, impact.CanTouch = true, false, false, false
            impact.CastShadow, impact.Material = false, Enum.Material.Neon
            impact.Transparency = 1
            impact.Parent = p1
            entry.Impact = impact
            entry.ImpactRevision = nil
        end
        local impact = entry.Impact
        if impact then
            if settings.Impact then
                impact.Position = endPos
                if entry.ImpactRevision ~= settings.Revision then
                    impact.Size = Vector3.new(settings.ImpactSize, settings.ImpactSize, settings.ImpactSize)
                    impact.Shape, impact.Color = settings.ImpactShape, color
                    entry.ImpactRevision = settings.Revision
                end
                if settings.Rainbow then impact.Color = color end
                impact.Transparency = settings.ImpactAlpha
            else impact.Transparency = 1 end
        end
        entry.ExpiresAt = now + settings.Life
        beam.Enabled = true
        return true
    end

    local function isLocalItem(self)
        local clientItem = self and (self.ClientItem or self)
        local fighter = clientItem and clientItem.ClientFighter or (self and self.ClientFighter)
        if not fighter then
            pcall(function()
                fighter = self and self.Fighter
            end)
        end
        if not fighter then return false end
        return fighter.IsLocalPlayer == true or fighter.Player == LocalPlayer or fighter.LocalPlayer == LocalPlayer
    end

    local tracerVectorFields = {"Position","EndPosition","HitPosition","Point","Location","Origin","StartPosition","Start"}
    local function vectorFrom(value)
        if typeof(value) == "Vector3" then return value end
        if typeof(value) == "CFrame" then return value.Position end
        if typeof(value) == "RaycastResult" then return value.Position end
        if typeof(value) == "Instance" and value:IsA("BasePart") then return value.Position end
        if type(value) ~= "table" then return nil end
        for _, key in ipairs(tracerVectorFields) do
            local got = value[key]
            if typeof(got) == "Vector3" then return got end
            if typeof(got) == "CFrame" then return got.Position end
            if typeof(got) == "RaycastResult" then return got.Position end
        end
        return nil
    end

    local function rayEndpoints(ray, fallbackStart)
        if typeof(ray) == "RaycastResult" then return fallbackStart, ray.Position end
        if type(ray) ~= "table" then return fallbackStart, vectorFrom(ray) end
        local startPos = vectorFrom(ray.StartPosition) or vectorFrom(ray.Start) or vectorFrom(ray.Origin) or fallbackStart
        local endPos = vectorFrom(ray.Position) or vectorFrom(ray.EndPosition) or vectorFrom(ray.HitPosition)
            or vectorFrom(ray.Result) or vectorFrom(ray.RaycastResult) or vectorFrom(ray.Hit)
        if not endPos and typeof(ray.Direction) == "Vector3" and startPos then
            endPos = startPos + ray.Direction
        end
        return startPos, endPos
    end

    local function drawTracerFromShootData(self, data)
        if type(data) ~= "table" then return false end
        local muzzle = getMuzzleWorld()
        if not muzzle then
            pcall(function()
                muzzle = self and self.ViewModel and self.ViewModel.GetMuzzlePosition and self.ViewModel:GetMuzzlePosition()
            end)
        end
        if typeof(muzzle) ~= "Vector3" then return false end

        local drawn = false
        local rays = data.RaycastResults or data.RaycastResult or data.Results or data.Rays or data.Raycasts or data.Hits
        if type(rays) == "table" then
            local hadArray = false
            local drawnCount = 0
            for _, ray in pairs(rays) do
                if drawnCount >= 6 then break end
                hadArray = true
                local startPos, endPos = rayEndpoints(ray, muzzle)
                if startPos and endPos then
                    createTracerBeam(startPos, endPos)
                    drawn = true
                    drawnCount += 1
                end
            end
            if not hadArray then
                local startPos, endPos = rayEndpoints(rays, muzzle)
                if startPos and endPos then
                    createTracerBeam(startPos, endPos)
                    drawn = true
                end
            end
        end

        if not drawn then
            local endPos = vectorFrom(data.Position) or vectorFrom(data.EndPosition) or vectorFrom(data.HitPosition)
                or vectorFrom(data.Result) or vectorFrom(data.RaycastResult) or vectorFrom(data.Hit)
            if not endPos and typeof(data.Direction) == "Vector3" then
                endPos = muzzle + data.Direction
            end
            if endPos then
                createTracerBeam(muzzle, endPos)
                drawn = true
            end
        end
        return drawn
    end

    local function queueTracerShot(self, data)
        if type(data) ~= "table" then return end
        local now = os.clock()
        if tracerPacketDedup[data] and now - tracerPacketDedup[data] < 0.04 then return end
        tracerPacketDedup[data] = now
        local index = ((tracerQueueHead + tracerQueueCount - 1) % 24) + 1
        if tracerQueueCount == 24 then
            index = tracerQueueHead
            tracerQueueHead = (tracerQueueHead % 24) + 1
        else tracerQueueCount += 1 end
        local packet = tracerQueue[index] or {}
        packet.Item, packet.Data, packet.At = self, data, now
        tracerQueue[index] = packet
        if VisualState.WakeUpdates then VisualState.WakeUpdates() end
    end

    local function clearTracerQueue()
        for _, packet in pairs(tracerQueue) do packet.Item, packet.Data = nil, nil end
        tracerQueueHead, tracerQueueCount = 1, 0
        table.clear(tracerPacketDedup)
        table.clear(tracerDedup)
        tracerDedupCursor = 0
    end

    local function updateTracerExpiry(now)
        if not (V.CustomTracers and V.CustomTracers.Enabled) then return end
        -- Limit burst work as well as the queue; remaining packets drain next Heartbeat.
        for _ = 1, math.min(tracerQueueCount, 4) do
            local packet = tracerQueue[tracerQueueHead]
            tracerQueueHead = (tracerQueueHead % 24) + 1
            tracerQueueCount -= 1
            local item, data, at = packet.Item, packet.Data, packet.At
            packet.Item, packet.Data = nil, nil
            if now - at < 0.25 then pcall(drawTracerFromShootData, item, data) end
        end
        for _, entry in ipairs(VisualState.TracerPool or {}) do
            if entry.ExpiresAt and now >= entry.ExpiresAt then
                entry.ExpiresAt = nil
                entry.Beam.Enabled = false
                if entry.Impact then entry.Impact.Transparency = 1 end
            end
        end
    end

    local function isLocalTracerShot(self, data)
        if isLocalItem(self) then return true end
        if type(data) == "table" then
            if data.IsLocal == true or data.Local == true then return true end
            local owner = data.Player or data.Owner or data.Shooter
            if owner == LocalPlayer then return true end
        end
        return false
    end

    local function installTracerHook()
        if VisualState.TracerHooked then return end
        local ok, gunModule = pcall(function()
            return require(LocalPlayer.PlayerScripts.Modules.ItemTypes.Gun)
        end)
        if not ok or type(gunModule) ~= "table" then return end

        local hooked = false
        local ownedTracers, ownedShootEffect, previousTracers, previousShootEffect
        if type(gunModule._Tracers) == "function" then
            local currentTracers = gunModule._Tracers
            VisualState.OriginalTracers = VisualState.OriginalTracers or currentTracers
            previousTracers = currentTracers
            ownedTracers = function(self, data, ...)
                if not tracerHooksActive or not (V.CustomTracers and V.CustomTracers.Enabled) then
                    return currentTracers(self, data, ...)
                end
                local result = table.pack(pcall(currentTracers, self, data, ...))
                if not result[1] then warn("[Custom Tracers] _Tracers error:", result[2]) end
                if isLocalTracerShot(self, data) then queueTracerShot(self, data) end
                if result[1] then return unpack(result, 2, result.n) end
            end
            gunModule._Tracers = ownedTracers
            hooked = true
        end

        -- Newer RIVALS builds may skip _Tracers for some weapons. _ShootEffect
        -- still receives the local shot packet, so keep a fallback there too.
        if type(gunModule._ShootEffect) == "function" and not VisualState.TracerShootFallbackHooked then
            local originalShootEffect = gunModule._ShootEffect
            previousShootEffect = originalShootEffect
            ownedShootEffect = function(self, data, ...)
                if not tracerHooksActive or not (V.CustomTracers and V.CustomTracers.Enabled) then
                    return originalShootEffect(self, data, ...)
                end
                local result = table.pack(originalShootEffect(self, data, ...))
                if isLocalTracerShot(self, data) then queueTracerShot(self, data) end
                return unpack(result, 1, result.n)
            end
            gunModule._ShootEffect = ownedShootEffect
            VisualState.TracerShootFallbackHooked = true
            hooked = true
        end

        VisualState.TracerHooked = hooked
        if hooked then
            mainapi:Clean(function()
                tracerHooksActive = false
                clearTracerQueue()
                -- Restore only methods still owned by this runtime; a later wrapper
                -- may retain ours, which must then act as a native pass-through.
                if gunModule._Tracers == ownedTracers then gunModule._Tracers = previousTracers end
                if gunModule._ShootEffect == ownedShootEffect then gunModule._ShootEffect = previousShootEffect end
            end)
        end
    end

    visualInitYield("helpers 6")

    local function installShootHook(enabled)
        if enabled == false then return end
        if VisualState.ShootHooked then return end
        local ok, gunModule = pcall(function()
            return require(LocalPlayer.PlayerScripts.Modules.ItemTypes.Gun)
        end)
        if not ok or not gunModule or type(gunModule._ShootEffect) ~= "function" then return end
        VisualState.OriginalShootEffect = VisualState.OriginalShootEffect or gunModule._ShootEffect
        gunModule._ShootEffect = function(self, data, ...)
            local suppressDefault = isLocalItem(self) and V.ShootSound and V.ShootSound.Enabled
            local snapshot = suppressDefault and collectShootSounds() or nil
            if suppressDefault then
                beginShootSoundSuppression(snapshot, 0.4)
            end
            local result = {VisualState.OriginalShootEffect(self, data, ...)}
            if isLocalItem(self) then
                if V.ShootSound and V.ShootSound.Enabled then
                    if snapshot then
                        suppressDefaultShootSounds(snapshot)
                        task.delay(0.03, beginShootSoundSuppression, snapshot, 0.25)
                        task.delay(0.08, beginShootSoundSuppression, snapshot, 0.25)
                    end
                    local now = os.clock()
                    if now - (VisualState.LastCustomShootSoundAt or 0) > 0.05 then
                        VisualState.LastCustomShootSoundAt = now
                        playSound(V.ShootSoundMode and V.ShootSoundMode.Value or "disable", V.ShootSoundVolume and V.ShootSoundVolume.Value or 0.3, V.ShootSoundSpeed and V.ShootSoundSpeed.Value or 1, V.ShootSoundStart and V.ShootSoundStart.Value or 0)
                    end
                end
            end
            return unpack(result)
        end
        if type(gunModule.StartShooting) == "function" then
            VisualState.OriginalStartShooting = VisualState.OriginalStartShooting or gunModule.StartShooting
            gunModule.StartShooting = function(self, ...)
                local suppressDefault = isLocalItem(self) and V.ShootSound and V.ShootSound.Enabled
                local snapshot = suppressDefault and collectShootSounds() or nil
                if suppressDefault then
                    beginShootSoundSuppression(snapshot, 0.4)
                end
                local result = {VisualState.OriginalStartShooting(self, ...)}
                if suppressDefault then
                    suppressDefaultShootSounds(snapshot)
                    task.delay(0.03, beginShootSoundSuppression, snapshot, 0.25)
                    local now = os.clock()
                    -- StartShooting returns nil on some current weapon classes even
                    -- when the shot succeeds. Only an explicit false means it was
                    -- rejected by cooldown/ammo checks.
                    if result[1] ~= false and now - (VisualState.LastCustomShootSoundAt or 0) > 0.05 then
                        VisualState.LastCustomShootSoundAt = now
                        playSound(V.ShootSoundMode and V.ShootSoundMode.Value or "disable", V.ShootSoundVolume and V.ShootSoundVolume.Value or 0.3, V.ShootSoundSpeed and V.ShootSoundSpeed.Value or 1, V.ShootSoundStart and V.ShootSoundStart.Value or 0)
                    end
                end
                return unpack(result)
            end
        end
        VisualState.ShootHooked = true
    end

    local function installEliminationSoundHook(enabled)
        if enabled == false then return end
        if VisualState.EliminationSoundHooked then return end
        local ok, slots = pcall(function()
            return require(LocalPlayer.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.FighterInterface.EliminationSlots)
        end)
        if not ok or type(slots) ~= "table" or type(slots.Create) ~= "function" then return end
        VisualState.OriginalEliminationCreate = VisualState.OriginalEliminationCreate or slots.Create
        slots.Create = function(self, eliminatedPlayer, assisted, ...)
            if eliminatedPlayer ~= LocalPlayer and V.EliminationSound and V.EliminationSound.Enabled then
                playSound(
                    V.EliminationSoundMode and V.EliminationSoundMode.Value or "neverlose",
                    V.EliminationSoundVolume and V.EliminationSoundVolume.Value or 0.7,
                    V.EliminationSoundSpeed and V.EliminationSoundSpeed.Value or 1,
                    0,
                    V.EliminationCustomId and V.EliminationCustomId.Value
                )
            end
            return VisualState.OriginalEliminationCreate(self, eliminatedPlayer, assisted, ...)
        end
        VisualState.EliminationSoundHooked = true
    end

    local function installDeathSoundHook(enabled)
        if enabled == false then return end
        VisualState.DeathSoundConnections = VisualState.DeathSoundConnections or {}
        local function hookCharacter(character)
            if not character or VisualState.DeathSoundConnections[character] then return end
            local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 10)
            if not humanoid then return end
            VisualState.DeathSoundConnections[character] = humanoid.Died:Connect(function()
                if V.DeathSound and V.DeathSound.Enabled then
                    playSound(
                        V.DeathSoundMode and V.DeathSoundMode.Value or "rust",
                        V.DeathSoundVolume and V.DeathSoundVolume.Value or 0.7,
                        V.DeathSoundSpeed and V.DeathSoundSpeed.Value or 1,
                        0,
                        V.DeathCustomId and V.DeathCustomId.Value
                    )
                end
            end)
        end
        hookCharacter(LocalPlayer.Character)
        if not VisualState.DeathCharacterAdded then
            VisualState.DeathCharacterAdded = LocalPlayer.CharacterAdded:Connect(function(character)
                task.defer(hookCharacter, character)
            end)
        end
    end

    local function installHitSoundHook(enabled)
        if enabled == false then return end
        if VisualState.HitSoundHooked then return end
        local ok, viewmodelModule = pcall(function()
            return require(LocalPlayer.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem.ClientViewModel)
        end)
        if not ok or type(viewmodelModule) ~= "table" or type(viewmodelModule.PlayHitmarkerSound) ~= "function" then return end
        local original=viewmodelModule.PlayHitmarkerSound
        VisualState.OriginalPlayHitmarkerSound=original
        local replacement=function(self,crit,divisor,...)
            if not hitHookScope.Alive then return original(self,crit,divisor,...) end
            if V.HitSoundEnabled and V.HitSoundEnabled.Enabled then
                playSound(V.HitSoundName and V.HitSoundName.Value or "neverlose", V.HitSoundVolume and V.HitSoundVolume.Value or 0.5, 1, 0, V.HitCustomId and V.HitCustomId.Value)
            end
            if V.RemoveHitSound and V.RemoveHitSound.Enabled then
                return
            end
            return original(self, crit, divisor, ...)
        end
        ownHitHook(viewmodelModule,"PlayHitmarkerSound",original,replacement)
        VisualState.HitSoundHooked = true
    end

    local findHitPosition
    local findHitPart

    local function installDamageIndicatorHook(enabled)
        if enabled == false then return end
        if VisualState.DamageIndicatorHooked then return end
        local ok, damageIndicators = pcall(function()
            return require(LocalPlayer.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.FighterInterface.DamageIndicators)
        end)
        if not ok or type(damageIndicators) ~= "table" or type(damageIndicators.Create) ~= "function" then return end
        local original=damageIndicators.Create
        VisualState.OriginalDamageIndicatorCreate=original
        local replacement=function(self,...)
            if not hitHookScope.Alive or not ((V.HitEffectEnabled and V.HitEffectEnabled.Enabled) or (V.DisableDamageNumbers and V.DisableDamageNumbers.Enabled)) then
                return original(self,...)
            end
            local args = table.pack(...)
            if V.HitEffectEnabled and V.HitEffectEnabled.Enabled and args.n > 0 then
                local data = args[1]
                local source = typeof(data) == "table"
                    and (safeTableGet(data, utf8.char(2))
                        or safeTableGet(data, "Source")
                        or safeTableGet(data, "Position")
                        or safeTableGet(data, "HitPart"))
                    or nil
                local hitPart = typeof(source) == "Instance" and (source:IsA("BasePart") and source or source:FindFirstChildWhichIsA("BasePart", true)) or nil
                local hitPos = hitPart and hitPart.Position or (typeof(source) == "Vector3" and source or findHitPosition(data, 0))
                local now = tick()
                if hitPos and now - (VisualState.LastIndicatorHitTime or 0) > 0.03 then
                    VisualState.LastIndicatorHitTime = now
                    createHitEffect(hitPos, getDamageValue(data, 0), hitPart)
                end
            end
            if V.DisableDamageNumbers and V.DisableDamageNumbers.Enabled then
                return
            end
            return original(self, ...)
        end
        ownHitHook(damageIndicators,"Create",original,replacement)
        VisualState.DamageIndicatorHooked = true
    end

    findHitPosition = function(data, depth, budget)
        if depth > 5 then return nil end
        if typeof(data) == "Instance" and data:IsA("BasePart") then return data.Position end
        if typeof(data) ~= "table" then return nil end
        local direct = safeTableGet(data, "Position")
            or safeTableGet(data, "HitPosition")
            or safeTableGet(data, "EndPosition")
        if typeof(direct) == "Vector3" then return direct end
        budget=budget or {Remaining=64,Seen={}}
        return findInTableValues(data, function(value)
            local pos = findHitPosition(value, depth + 1,budget)
            if pos then return pos end
        end,budget)
    end

    findHitPart = function(data, depth, budget)
        if depth > 6 then return nil end
        if typeof(data) == "Instance" then
            if data:IsA("BasePart") then return data end
            return data:FindFirstChildWhichIsA("BasePart")
        end
        if typeof(data) ~= "table" then return nil end
        local direct = safeTableGet(data, "HitPart")
            or safeTableGet(data, "Hitbox")
            or safeTableGet(data, "Instance")
            or safeTableGet(data, "Part")
            or safeTableGet(data, "TargetPart")
            or safeTableGet(data, "Target")
        if typeof(direct) == "Instance" then
            if direct:IsA("BasePart") then return direct end
            local found = direct:FindFirstChildWhichIsA("BasePart")
            if found then return found end
        end
        budget=budget or {Remaining=64,Seen={}}
        return findInTableValues(data, function(value)
            local part = findHitPart(value, depth + 1,budget)
            if part then return part end
        end,budget)
    end

    local function installHitHook(enabled)
        if enabled==false then return end
        local effects=V.HitEffectEnabled and V.HitEffectEnabled.Enabled
        local markers=V.DisableHitMarker and V.DisableHitMarker.Enabled
        local sounds=(V.HitSoundEnabled and V.HitSoundEnabled.Enabled) or (V.RemoveHitSound and V.RemoveHitSound.Enabled)
        if not (effects or markers or sounds) then return end
        if effects and not VisualState.DamageIndicatorHooked then installDamageIndicatorHook() end
        if not VisualState.Hooked then
            local ok,itemInterface=pcall(function()
                return require(LocalPlayer.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem.ItemInterface)
            end)
            if ok and itemInterface and type(itemInterface.DamageEffect)=="function" then
                local original=itemInterface.DamageEffect
                VisualState.OriginalDamageEffect=original
                local replacement=function(self,data,...)
                    local effectsOn=V.HitEffectEnabled and V.HitEffectEnabled.Enabled
                    local block=V.DisableHitMarker and V.DisableHitMarker.Enabled
                    local soundOn=V.HitSoundEnabled and V.HitSoundEnabled.Enabled
                    if not hitHookScope.Alive or not (effectsOn or block or soundOn) then return original(self,data,...) end
                    local result=not block and table.pack(original(self,data,...)) or {n=0}
                    local now=tick()
                    if now-(VisualState.LastHitTime or 0)>0.03 then
                        VisualState.LastHitTime=now
                        if soundOn and ((V.RemoveHitSound and V.RemoveHitSound.Enabled) or not VisualState.HitSoundHooked) then
                            playSound(V.HitSoundName and V.HitSoundName.Value or "neverlose",V.HitSoundVolume and V.HitSoundVolume.Value or 0.5,1,0,V.HitCustomId and V.HitCustomId.Value)
                        end
                        if effectsOn then
                            local hitPart=findHitPart(data,0)
                            local hitPos=hitPart and hitPart.Position or findHitPosition(data,0)
                            if hitPos then createHitEffect(hitPos,getDamageValue(data,0),hitPart) end
                        end
                    end
                    return unpack(result,1,result.n)
                end
                ownHitHook(itemInterface,"DamageEffect",original,replacement)
                VisualState.Hooked=true
            end
        end
        if effects and not VisualState.DamageNumberHooked then
            pcall(function()
                local controller=require(LocalPlayer.PlayerScripts.Controllers.FighterController)
                local fighter=controller.LocalFighter or controller:GetFighter(LocalPlayer)
                local class=fighter and getmetatable(fighter)
                class=class and class.__index
                if type(class)~="table" or type(class._DamageNumberEffect)~="function" then return end
                local original=class._DamageNumberEffect
                VisualState.OriginalDamageNumberEffect=original
                local replacement=function(...)
                    if not hitHookScope.Alive or not (V.HitEffectEnabled and V.HitEffectEnabled.Enabled) then return original(...) end
                    local now=tick()
                    if now-(VisualState.LastHitTime or 0)>0.03 then
                        local args=table.pack(...)
                        local hitPart,damage
                        for i=1,args.n do
                            if args[i]~=fighter then
                                hitPart=hitPart or findHitPart(args[i],0)
                                damage=damage or getDamageValue(args[i],0)
                            end
                            if hitPart and damage then break end
                        end
                        if hitPart then
                            VisualState.LastHitTime=now
                            createHitEffect(hitPart.Position,damage,hitPart)
                        end
                    end
                    return original(...)
                end
                ownHitHook(class,"_DamageNumberEffect",original,replacement)
                VisualState.DamageNumberHooked=true
            end)
        end
    end

    visualInitYield("helpers 7")

    local function updateTargetVisuals()
        hideDrawingSet(VisualState.TargetDrawings)
        if not Drawing then return end
        if not ((V.TargetTracer and V.TargetTracer.Enabled) or (V.TargetHighlight and V.TargetHighlight.Enabled)) then return end
        local _, part = getClosestTarget()
        if not part then return end
        local screen, visible = worldToScreen(part.Position)
        if not visible and (V.TargetCulling and V.TargetCulling.Value) ~= "AlwaysOnTop" then return end
        if V.TargetTracer and V.TargetTracer.Enabled then
            local line = VisualState.TargetDrawings.tracer or Drawing.new("Line")
            VisualState.TargetDrawings.tracer = line
            local muzzle, muzzleVisible = worldToScreen(getMuzzleWorld())
            line.From = muzzleVisible and muzzle or (workspace.CurrentCamera.ViewportSize / 2)
            line.To = screen
            line.Color = V.TargetTracer.Value or Color3.fromRGB(255, 255, 255)
            line.Thickness = 2
            line.Visible = true
        end
        if V.TargetHighlight and V.TargetHighlight.Enabled then
            local box = VisualState.TargetDrawings.highlight or Drawing.new("Square")
            VisualState.TargetDrawings.highlight = box
            box.Size = Vector2.new(22, 22)
            box.Position = screen - Vector2.new(11, 11)
            box.Color = V.TargetHighlight.Value or Color3.fromRGB(255, 255, 255)
            box.Thickness = 2
            box.Filled = false
            box.Visible = true
        end
    end

    local function updateIndicators()
        local texts = {}
        if V.IndicatorManipulated and V.IndicatorManipulated.Enabled then table.insert(texts, "manipulated") end
        if V.IndicatorRagebot and V.IndicatorRagebot.Enabled then table.insert(texts, "ragebot") end
        if V.IndicatorAmmo and V.IndicatorAmmo.Enabled then
            local fighter = getLocalFighter()
            local item = fighter and fighter.EquippedItem
            local ammo = item and item.Get and item:Get("Ammo") or "?"
            local reserve = item and item.Get and item:Get("AmmoReserve") or "?"
            table.insert(texts, tostring(ammo) .. ", " .. tostring(reserve))
        end
        if #texts == 0 then
            hideDrawingSet(VisualState.IndicatorDrawings)
            return
        end
        if not Drawing then return end
        hideDrawingSet(VisualState.IndicatorDrawings)
        local origin = UserInputService and UserInputService:GetMouseLocation() or (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize / 2) or Vector2.new(500, 500)
        if V.IndicatorPosition and V.IndicatorPosition.Value == "position on target" then
            local _, part = getClosestTarget()
            if part then
                local screen, visible = worldToScreen(part.Position)
                if visible then origin = screen end
            end
        elseif V.IndicatorPosition and V.IndicatorPosition.Value == "position on barrel" then
            local screen, visible = worldToScreen(getMuzzleWorld())
            if visible then origin = screen end
        end
        origin += Vector2.new(V.IndicatorOffsetX and V.IndicatorOffsetX.Value or 0, V.IndicatorOffsetY and V.IndicatorOffsetY.Value or 25)
        local previous = VisualState.IndicatorOrigin
        local lerp = math.clamp(V.IndicatorLerp and V.IndicatorLerp.Value or 1, 0, 1)
        if previous and lerp < 1 then
            origin = previous:Lerp(origin, lerp)
        end
        VisualState.IndicatorOrigin = origin
        for i, text in ipairs(texts) do
            local obj = VisualState.IndicatorDrawings[i] or Drawing.new("Text")
            VisualState.IndicatorDrawings[i] = obj
            obj.Text = (V.IndicatorTextStyle and V.IndicatorTextStyle.Value == "upper") and text:upper() or text:lower()
            obj.Position = origin + Vector2.new(0, (i - 1) * 14)
            obj.Color = Color3.fromRGB(255, 255, 255)
            obj.Size = 13
            obj.Center = true
            obj.Outline = true
            obj.Visible = true
        end
    end

    local gameCrosshairTargets = {}
    local gameCrosshairAdded
    local gameCrosshairRoot
    local gameCrosshairSuppressing = false
    local function clearGameCrosshairOverrides()
        gameCrosshairSuppressing = false
        if gameCrosshairAdded then gameCrosshairAdded:Disconnect(); gameCrosshairAdded = nil end
        for object, record in pairs(gameCrosshairTargets) do
            record.Connection:Disconnect()
            pcall(function()
                if object[record.Property] == false then object[record.Property] = record.Original end
            end)
        end
        table.clear(gameCrosshairTargets)
        gameCrosshairRoot = nil
    end
    mainapi:Clean(clearGameCrosshairOverrides)
    local function watchGameCrosshair(object)
        if not gameCrosshairSuppressing or gameCrosshairTargets[object]
            or not object.Name:lower():find("crosshair", 1, true) then return end
        local property = object:IsA("ScreenGui") and "Enabled" or object:IsA("GuiObject") and "Visible"
        if not property then return end
        local record = {Property=property, Original=object[property]}
        gameCrosshairTargets[object] = record
        record.Connection = object:GetPropertyChangedSignal(property):Connect(function()
            if gameCrosshairSuppressing and object[property] ~= false then
                record.Original = object[property]
                object[property] = false
            end
        end)
        object[property] = false
    end
    local function setGameCrosshairDisabled(disabled)
        if not disabled then clearGameCrosshairOverrides(); return end
        local gui = LocalPlayer:FindFirstChild("PlayerGui")
        if not gui then return end
        if gameCrosshairRoot == gui and gameCrosshairAdded then return end
        clearGameCrosshairOverrides()
        gameCrosshairRoot = gui
        gameCrosshairSuppressing = true
        gameCrosshairAdded = gui.DescendantAdded:Connect(watchGameCrosshair)
        for _, object in ipairs(gui:GetDescendants()) do watchGameCrosshair(object) end
    end

    local function reapplyGameCrosshairDisabled()
        if V.DisableGameCrosshair and V.DisableGameCrosshair.Enabled then
            VisualState.GameCrosshairDisabled = true
            setGameCrosshairDisabled(true)
        end
    end

    local visualTimers = {
        hookCheck = 0,
        viewmodelUpdate = 0,
        itemStatusUpdate = 0,
        targetUpdate = 0,
        indicatorUpdate = 0,
        idleVisualUpdate = 0,
        crosshairDisableApply = 0,
    }

    local function dropdownHasAny(option)
        local value = option and option.Value
        if type(value) ~= "table" then return false end
        for _, enabled in pairs(value) do
            if enabled then return true end
        end
        return false
    end

    local function updateAll()
        local now = os.clock()
        local transformActive=V.TransformGroup and V.TransformGroup.Enabled
        updateTracerExpiry(now)
        local viewmodelLoopActive = VisualState.ViewmodelDirty
            or VisualState.WireframeWasEnabled
            or dropdownHasAny(V.VMDisabled)
            or (V.VMOffset and V.VMOffset.Enabled)
            or (V.VMOverrideFps and V.VMOverrideFps.Enabled)
            or (V.ViewmodelAppearance and V.ViewmodelAppearance.Enabled)
            or (V.VMInvisible and V.VMInvisible.Enabled)
            or (V.VMChams and V.VMChams.Enabled)
            or (V.WeaponHighlight and V.WeaponHighlight.Enabled)
            or (V.ArmChams and V.ArmChams.Enabled)
            or (V.ArmInvisible and V.ArmInvisible.Enabled)
            or (V.ArmHighlight and V.ArmHighlight.Enabled)
            or (V.VMWireframe and V.VMWireframe.Enabled)
            or (V.VMDisableTextures and V.VMDisableTextures.Enabled)
            or (V.ArmAppearance and V.ArmAppearance.Enabled)
            or (V.ArmDisableClothes and V.ArmDisableClothes.Enabled)

        local realtimeVisualsActive = (V.CrosshairEnabled and V.CrosshairEnabled.Enabled)
            or (V.TargetTracer and V.TargetTracer.Enabled)
            or (V.TargetHighlight and V.TargetHighlight.Enabled)
            or (V.IndicatorManipulated and V.IndicatorManipulated.Enabled)
            or (V.IndicatorRagebot and V.IndicatorRagebot.Enabled)
            or (V.IndicatorAmmo and V.IndicatorAmmo.Enabled)

        local hookFeaturesActive = viewmodelLoopActive
            or (V.ShootSound and V.ShootSound.Enabled)
            or (V.CustomTracers and V.CustomTracers.Enabled)
            or (V.HitSoundEnabled and V.HitSoundEnabled.Enabled)
            or (V.RemoveHitSound and V.RemoveHitSound.Enabled)
            or (V.DisableDamageNumbers and V.DisableDamageNumbers.Enabled)
            or (V.HitEffectEnabled and V.HitEffectEnabled.Enabled)
            or (V.DisableHitMarker and V.DisableHitMarker.Enabled)

        local passiveActive = (V.OverrideWeaponStatus and V.OverrideWeaponStatus.Enabled)
            or (V.DisableGameCrosshair and V.DisableGameCrosshair.Enabled)

        if not realtimeVisualsActive and not hookFeaturesActive and not passiveActive and not transformActive
            and not VisualState.CrosshairWasVisible and not VisualState.TargetWasVisible and not VisualState.IndicatorsWereVisible then
            return
        end

        if hookFeaturesActive and now >= visualTimers.hookCheck then
            visualTimers.hookCheck = now + 0.75
            if viewmodelLoopActive then
                installViewmodelHooks()
                if disableSelected("aiming animation") then installAimingHooks() end
            end
            if V.ShootSound and V.ShootSound.Enabled then installShootHook() end
            if V.CustomTracers and V.CustomTracers.Enabled then installTracerHook() end
            if (V.HitSoundEnabled and V.HitSoundEnabled.Enabled) or (V.RemoveHitSound and V.RemoveHitSound.Enabled) then installHitSoundHook() end
            if V.DisableDamageNumbers and V.DisableDamageNumbers.Enabled then installDamageIndicatorHook() end
            if (V.HitEffectEnabled and V.HitEffectEnabled.Enabled)
                or (V.DisableHitMarker and V.DisableHitMarker.Enabled)
                or (V.DisableDamageNumbers and V.DisableDamageNumbers.Enabled)
                or (V.RemoveHitSound and V.RemoveHitSound.Enabled) then
                installHitHook()
            end
        end

        if transformActive or (V.VMOffset and V.VMOffset.Enabled) then applyViewmodelOffset()
        elseif VisualState.TransformPivots then restoreViewmodelTransforms() end
        if viewmodelLoopActive then
            if VisualState.ViewmodelDirty or now >= visualTimers.viewmodelUpdate then
                visualTimers.viewmodelUpdate = now + 0.5
                applyViewmodelOptions()
            end
        end

        if V.OverrideWeaponStatus and V.OverrideWeaponStatus.Enabled and now >= visualTimers.itemStatusUpdate then
            visualTimers.itemStatusUpdate = now + 0.75
            applyItemStatus()
        end

        if not mainapi.ClickGuiStatus and V.CrosshairEnabled and V.CrosshairEnabled.Enabled then
            VisualState.CrosshairWasVisible = true
            updateCrosshair()
        elseif VisualState.CrosshairWasVisible then
            VisualState.CrosshairWasVisible = false
            hideDrawingSet(VisualState.CrosshairDrawings)
        end

        local targetActive = not mainapi.ClickGuiStatus and ((V.TargetTracer and V.TargetTracer.Enabled) or (V.TargetHighlight and V.TargetHighlight.Enabled))
        if targetActive and now >= visualTimers.targetUpdate then
            visualTimers.targetUpdate = now + (1 / 60)
            VisualState.TargetWasVisible = true
            updateTargetVisuals()
        elseif not targetActive and VisualState.TargetWasVisible then
            VisualState.TargetWasVisible = false
            hideDrawingSet(VisualState.TargetDrawings)
        end

        local indicatorsActive = (V.IndicatorManipulated and V.IndicatorManipulated.Enabled)
            or (V.IndicatorRagebot and V.IndicatorRagebot.Enabled)
            or (V.IndicatorAmmo and V.IndicatorAmmo.Enabled)
        indicatorsActive = indicatorsActive and not mainapi.ClickGuiStatus
        if indicatorsActive and now >= visualTimers.indicatorUpdate then
            visualTimers.indicatorUpdate = now + (1 / 30)
            VisualState.IndicatorsWereVisible = true
            updateIndicators()
        elseif not indicatorsActive and VisualState.IndicatorsWereVisible then
            VisualState.IndicatorsWereVisible = false
            hideDrawingSet(VisualState.IndicatorDrawings)
        end

        local crosshairDisabled = V.DisableGameCrosshair and V.DisableGameCrosshair.Enabled or false
        if VisualState.GameCrosshairDisabled ~= crosshairDisabled then
            VisualState.GameCrosshairDisabled = crosshairDisabled
            setGameCrosshairDisabled(crosshairDisabled)
        end
    end

