    VisualState.ViewmodelDirty = false
    VisualState.WireframeWasEnabled = false
    visualTimers.hookCheck = os.clock() + 1
    visualTimers.viewmodelUpdate = os.clock() + 1
    local function enabled(name) return V[name] and V[name].Enabled == true end
    local function frameWorkActive()
        if VisualState.CrosshairWasVisible or VisualState.TargetWasVisible or VisualState.IndicatorsWereVisible then return true end
        if mainapi.ClickGuiStatus then return false end
        if enabled("CrosshairEnabled") or enabled("TransformGroup") or enabled("VMOffset")
            or enabled("IndicatorManipulated") or enabled("IndicatorRagebot") or enabled("IndicatorAmmo") then return true end
        if #entitylib.List > 0 and (enabled("TargetTracer") or enabled("TargetHighlight")) then return true end
        if enabled("CustomTracers") then
            if tracerQueueCount > 0 then return true end
            for _,entry in ipairs(VisualState.TracerPool or {}) do if entry.ExpiresAt then return true end end
        end
        return false
    end
    local function maintenanceActive()
        if VisualState.ViewmodelDirty or VisualState.WireframeWasEnabled or dropdownHasAny(V.VMDisabled) then return true end
        for _,name in ipairs({"VMOverrideFps","ViewmodelAppearance","VMInvisible","VMChams","WeaponHighlight",
