            "ArmDisableClothes","ShootSound","CustomTracers","HitSoundEnabled","RemoveHitSound",
            "DisableDamageNumbers","HitEffectEnabled","DisableHitMarker","OverrideWeaponStatus","DisableGameCrosshair"}) do
            if enabled(name) then return true end
        end
        return false
    end
    local frameWorker=mainapi:CreateIdleWorker("VisualFrames",{IsActive=frameWorkActive,Update=updateAll})
    local maintenanceWorker=mainapi:CreateIdleWorker("VisualMaintenance",{Interval=0.5,IsActive=maintenanceActive,
        Update=function() if not frameWorker.Running then updateAll() end end})
    VisualState.WakeUpdates=function() frameWorker:Wake();maintenanceWorker:Wake() end
    for _,event in ipairs({"EntityAdded","EntityRemoved","LocalAdded","LocalRemoved"}) do
        mainapi:Clean(entitylib:GetEvent(event):Connect(VisualState.WakeUpdates))
    end
    mainapi:Clean(function() VisualState.WakeUpdates=nil end)
    shared.PlexStartupDiag("visual_module_ready", "idle_workers_ready=true")
    mainapi:Clean(function()
        restoreViewmodelTransforms()
        hideDrawingSet(VisualState.CrosshairDrawings)
        hideDrawingSet(VisualState.TargetDrawings)
        hideDrawingSet(VisualState.IndicatorDrawings)
        hideWireframeDrawings(1)
        destroyWireframeAdornments()
        if VisualState.DeathCharacterAdded then
            pcall(function() VisualState.DeathCharacterAdded:Disconnect() end)
            VisualState.DeathCharacterAdded = nil
        end
        for character, connection in pairs(VisualState.DeathSoundConnections or {}) do
            pcall(function() connection:Disconnect() end)
            VisualState.DeathSoundConnections[character] = nil
        end
        clearTracerQueue()
        for _, entry in ipairs(VisualState.TracerPool or {}) do
            pcall(function() if entry.P0 then entry.P0:Destroy() end end)
            pcall(function() if entry.P1 then entry.P1:Destroy() end end)
        end
        table.clear(VisualState.TracerPool or {})
        for _, sound in ipairs(VisualState.CustomSoundPool or {}) do
            pcall(function() sound:Destroy() end)
        end
        table.clear(VisualState.CustomSoundPool or {})
    end)
end)

