run(function()
    local BODY={Head=true,Torso=true,["Left Arm"]=true,["Right Arm"]=true,["Left Leg"]=true,["Right Leg"]=true,
        UpperTorso=true,LowerTorso=true,LeftUpperArm=true,LeftLowerArm=true,LeftHand=true,RightUpperArm=true,
        RightLowerArm=true,RightHand=true,LeftUpperLeg=true,LeftLowerLeg=true,LeftFoot=true,
        RightUpperLeg=true,RightLowerLeg=true,RightFoot=true}

    local function newLocalCosmetic(kind)
        local runtime={Options={},Alive=false,Parts={},Connections={},CharacterConnections={},Hue=0}
        local function disconnect(list)
            for _,connection in ipairs(list) do connection:Disconnect() end
            table.clear(list)
        end
        local function value(key,default)
            local option=runtime.Options[key]
            if option and option.Value~=nil then return option.Value end
            return default
        end
        local function color()
            local mode=value("Mode","Femboy")
            if mode=="Solid" then return Color3.fromRGB(value("Red",244),value("Green",159),value("Blue",199)) end
            if mode=="Rainbow" then return Color3.fromHSV(runtime.Hue,kind=="aura" and 0.6 or 0.55,1) end
            return Color3.fromHSV(0.92+runtime.Hue*0.06,kind=="aura" and 0.5 or 0.45,1)
        end
        local function restore(part,original)
            pcall(function()
                part.Color=original.Color
                part.Material=original.Material
                part.Transparency=original.Transparency
            end)
        end
        local function restoreBody()
            for part,original in pairs(runtime.Parts) do restore(part,original) end
            table.clear(runtime.Parts)
        end
        local function paint()
            local tint=color()
            if runtime.Emitter then runtime.Emitter.Color=ColorSequence.new(tint) end
            for part,original in pairs(runtime.Parts) do
                if part.Parent==runtime.Character then
                    if part.Color~=tint then part.Color=tint end
                    local material=value("Material","Keep")
                    local desiredMaterial=material=="Keep" and original.Material or Enum.Material[material]
                    if part.Material~=desiredMaterial then part.Material=desiredMaterial end
                    local transparency=value("Transparency",0)
                    local desiredTransparency=transparency>0 and transparency or original.Transparency
                    if part.Transparency~=desiredTransparency then part.Transparency=desiredTransparency end
                end
            end
        end
        function runtime:Refresh()
            if not self.Alive then return end
            if self.Emitter then
                self.Emitter.Rate=value("Rate",20)
                self.Emitter.Lifetime=NumberRange.new(value("Lifetime",1.2))
                self.Emitter.Speed=NumberRange.new(value("Spread",2))
                self.Emitter.Size=NumberSequence.new(value("Size",0.5))
            end
            paint()
            local animate=value("Mode","Femboy")~="Solid"
            if self.ColorConnection and not animate then self.ColorConnection:Disconnect();self.ColorConnection=nil end
            if animate and not self.ColorConnection then
                local elapsed=0
                self.ColorConnection=RunService.Heartbeat:Connect(function(dt)
                    elapsed+=dt
                    if elapsed<1/12 then return end
                    self.Hue=(self.Hue+elapsed*value("Speed",kind=="aura" and 0.5 or 0.35))%1
                    elapsed=0
                    paint()
                end)
            end
        end
        function runtime:Bind(character)
            disconnect(self.CharacterConnections)
            restoreBody()
            self.Character=character
            if self.Attachment then self.Attachment.Parent=nil end
            if not character then return end
            local function added(object)
                if not self.Alive or self.Character~=character then return end
                if kind=="aura" then
                    if object.Name=="HumanoidRootPart" and object:IsA("BasePart") then self.Attachment.Parent=object end
                elseif object.Parent==character and object:IsA("BasePart") and BODY[object.Name]
                    and not object:FindFirstChildOfClass("SurfaceAppearance") then
                    self.Parts[object]={Color=object.Color,Material=object.Material,Transparency=object.Transparency}
                    paint()
                end
            end
            local function removing(object)
                if self.Parts[object] then restore(object,self.Parts[object]);self.Parts[object]=nil end
                if self.Attachment and self.Attachment.Parent==object then self.Attachment.Parent=nil end
            end
            table.insert(self.CharacterConnections,character.ChildAdded:Connect(added))
            table.insert(self.CharacterConnections,character.ChildRemoved:Connect(removing))
            for _,object in ipairs(character:GetChildren()) do added(object) end
        end
        function runtime:Stop()
            self.Alive=false
            if self.ColorConnection then self.ColorConnection:Disconnect();self.ColorConnection=nil end
            disconnect(self.Connections)
            disconnect(self.CharacterConnections)
            restoreBody()
            if self.Attachment then self.Attachment:Destroy();self.Attachment=nil;self.Emitter=nil end
            self.Character=nil
        end
        function runtime:Start(module)
            self:Stop()
            self.Alive=true
            module:Clean(function() self:Stop() end)
            if kind=="aura" then
                self.Attachment=Instance.new("Attachment")
                self.Attachment.Name="PlexCosmeticAura"
                self.Emitter=Instance.new("ParticleEmitter")
                self.Emitter.Name="PlexCosmeticAura"
                self.Emitter.Texture="rbxasset://textures/particles/sparkles_main.dds"
                self.Emitter.SpreadAngle=Vector2.new(180,180)
                self.Emitter.Transparency=NumberSequence.new(0.25)
                self.Emitter.LightEmission=1
                self.Emitter.Parent=self.Attachment
            end
            table.insert(self.Connections,LocalPlayer.CharacterAdded:Connect(function(character) self:Bind(character) end))
            table.insert(self.Connections,LocalPlayer.CharacterRemoving:Connect(function(character)
                if self.Character==character then self:Bind(nil) end
            end))
            self:Bind(LocalPlayer.Character)
            self:Refresh()
        end
        return runtime
    end

    local function addCosmeticColors(module,runtime,label,speed)
        local options=runtime.Options
        local function refresh() runtime:Refresh() end
        options.Mode=module:AddDropdown({Name=label,List={"Femboy","Rainbow","Solid"},Default="Femboy",Function=refresh})
        for _,entry in ipairs({{"Red","solid red",244},{"Green","solid green",159},{"Blue","solid blue",199}}) do
            options[entry[1]]=module:AddSlider({Name=entry[2],Min=0,Max=255,Default=entry[3],Function=refresh})
        end
        options.Speed=module:AddSlider({Name="rainbow speed",Min=0.05,Max=5,Default=speed,Decimal=100,Function=refresh})
    end

-- END PLEX SOURCE: shared/015a_local_cosmetics.lua
-- BEGIN PLEX SOURCE: modules/cosmetic_aura.lua
    do
        local runtime=newLocalCosmetic("aura")
        local module
        module=Render:AddModule({Name="Cosmetic Aura",Function=function(enabled)
            if enabled then runtime:Start(module) else runtime:Stop() end
        end})
        addCosmeticColors(module,runtime,"color",0.5)
        local function refresh() runtime:Refresh() end
        runtime.Options.Rate=module:AddSlider({Name="particle rate",Min=1,Max=100,Default=20,Function=refresh})
        runtime.Options.Lifetime=module:AddSlider({Name="particle lifetime (s)",Min=0.2,Max=4,Default=1.2,Decimal=100,Function=refresh})
        runtime.Options.Size=module:AddSlider({Name="particle size",Min=0.05,Max=2,Default=0.5,Decimal=100,Function=refresh})
        runtime.Options.Spread=module:AddSlider({Name="particle speed",Min=0,Max=20,Default=2,Decimal=10,Function=refresh})
    end

-- END PLEX SOURCE: modules/cosmetic_aura.lua
-- BEGIN PLEX SOURCE: modules/character_appearance.lua
    do
        local runtime=newLocalCosmetic("body")
        local module
        module=Player:AddModule({Name="Character Appearance",Function=function(enabled)
            if enabled then runtime:Start(module) else runtime:Stop() end
        end})
        addCosmeticColors(module,runtime,"color mode",0.35)
        local function refresh() runtime:Refresh() end
        runtime.Options.Material=module:AddDropdown({Name="material",List={"Keep","Plastic","SmoothPlastic","Neon","Marble","Metal","Ice"},Default="Keep",Function=refresh})
        runtime.Options.Transparency=module:AddSlider({Name="body transparency",Min=0,Max=0.9,Default=0,Decimal=100,Function=refresh})
    end
end)

