-- BEGIN PLEX SOURCE: shared/015b_movement_recording.lua
run(function()
    local movement={Recording=nil}
    local recordModule,replayModule,recordRate,recordDuration,replayRelative,replayLoop,replaySpeed,replayRestore
    local function rootPart()
        local character=LocalPlayer.Character
        return character and character:FindFirstChild("HumanoidRootPart"),character
    end
    local function refuse(module,text)
        module:Toggle(false)
        mainapi:Notify({Title="Movement recording",Text=text,Duration=4})
    end
    local function startRecording()
        if replayModule.Enabled then replayModule:Toggle(false) end
        local root,character=rootPart()
        if not root then refuse(recordModule,"Character root unavailable.");return end
        local origin=root.CFrame
        local recording={Place=game.PlaceId,Origin=origin,Samples={{Time=0,Frame=CFrame.identity}}}
        movement.Recording=recording
        local elapsed,lastSample=0,0
        recordModule:Clean(LocalPlayer.CharacterRemoving:Connect(function(old)
            if old==character then recordModule:Toggle(false) end
        end))
        recordModule:Clean(RunService.Heartbeat:Connect(function(dt)
            if root.Parent~=character then recordModule:Toggle(false);return end
            elapsed+=dt
            local duration=math.clamp(recordDuration.Value,1,300)
            local finished=elapsed>=duration
            if elapsed-lastSample>=1/math.clamp(recordRate.Value,5,60) or finished then
                lastSample=elapsed
                table.insert(recording.Samples,{Time=elapsed,Frame=origin:ToObjectSpace(root.CFrame)})
            end
            if finished or #recording.Samples>=18000 then
                recordModule:Toggle(false)
                mainapi:Notify({Title="Movement recording",Text="Recorded "..#recording.Samples.." movement samples.",Duration=4})
            end
        end))
    end
    local function startReplay()
        if recordModule.Enabled then recordModule:Toggle(false) end
        local recording=movement.Recording
        if not recording or #recording.Samples<2 then refuse(replayModule,"Record movement first (at least two samples).");return end
        if recording.Place~=game.PlaceId then refuse(replayModule,"This recording belongs to another place.");return end
        local root,character=rootPart()
        if not root then refuse(replayModule,"Character root unavailable.");return end
        local initial,linear,angular=root.CFrame,root.AssemblyLinearVelocity,root.AssemblyAngularVelocity
        local anchor=replayRelative.Enabled and initial or recording.Origin
        local samples=recording.Samples
        local elapsed,index=0,1
        replayModule:Clean(function()
            if root.Parent==character then
                if replayRestore.Enabled then root.CFrame=initial end
                root.AssemblyLinearVelocity=linear
                root.AssemblyAngularVelocity=angular
            end
        end)
        replayModule:Clean(LocalPlayer.CharacterRemoving:Connect(function(old)
            if old==character then replayModule:Toggle(false) end
        end))
        replayModule:Clean(RunService.Heartbeat:Connect(function(dt)
            if root.Parent~=character then replayModule:Toggle(false);return end
            elapsed+=dt*math.clamp(replaySpeed.Value,0.1,5)
            local duration=samples[#samples].Time
            if elapsed>=duration then
                if replayLoop.Enabled then elapsed%=duration;index=1
                else
                    root.CFrame=anchor*samples[#samples].Frame
                    replayModule:Toggle(false)
                    return
                end
            end
            while index<#samples-1 and samples[index+1].Time<elapsed do index+=1 end
            local first,second=samples[index],samples[index+1]
            local alpha=math.clamp((elapsed-first.Time)/(second.Time-first.Time),0,1)
            root.CFrame=anchor*first.Frame:Lerp(second.Frame,alpha)
            root.AssemblyLinearVelocity=Vector3.zero
            root.AssemblyAngularVelocity=Vector3.zero
        end))
    end

