run(function()
    local AutoQueue, GameMode
    local queueLookup = {
        ["1v1"] = "1v1",
        ["2v2_beginner"] = "2v2_beginner",
    }
    local queueLoopRunning = false
    local wasEnabled = false
    local ReplicatedStorage = cloneref(game:GetService("ReplicatedStorage"))

    local function getQueueData()
        local list = {}
        local ok, duelLibrary = pcall(function()
            return require(ReplicatedStorage.Modules.DuelLibrary)
        end)
        if ok and duelLibrary then
            for _, queueName in pairs(duelLibrary.MatchmakingQueueOrder or {}) do
                local info = duelLibrary.MatchmakingQueues and duelLibrary.MatchmakingQueues[queueName]
                local display = info and info.DisplayName or queueName
                table.insert(list, display)
                queueLookup[display] = queueName
            end
        end
        if #list == 0 then
            list = {"1v1", "2v2_beginner"}
        end
        return list
    end

    local function queueIntoSelected()
        local queueName = queueLookup[GameMode and GameMode.Value or "1v1"] or (GameMode and GameMode.Value) or "1v1"
        local ok, controller = pcall(function()
            return require(LocalPlayer.PlayerScripts.Controllers.MatchmakingController)
        end)
        if ok and controller and controller.QueueInto then
            return controller:QueueInto(queueName)
        end

        local remotes = ReplicatedStorage:FindFirstChild("Remotes")
        local matchmaking = remotes and remotes:FindFirstChild("Matchmaking")
        local joinQueue = matchmaking and matchmaking:FindFirstChild("JoinQueue")
        if joinQueue and joinQueue.InvokeServer then
            return joinQueue:InvokeServer(queueName)
        end
    end

    local function leaveQueue()
        local remotes = ReplicatedStorage:FindFirstChild("Remotes")
        local matchmaking = remotes and remotes:FindFirstChild("Matchmaking")
        local leaveRemote = matchmaking and matchmaking:FindFirstChild("LeaveQueue")
        if leaveRemote and leaveRemote.FireServer then
            pcall(function()
                leaveRemote:FireServer()
            end)
        end
    end

-- END PLEX SOURCE: shared/016_spoofers.lua
-- BEGIN PLEX SOURCE: modules/auto_queue.lua
    AutoQueue = Other:AddModule({
        Name = "auto queue",
        Function = function(callback)
            if callback then
                wasEnabled = true
                if queueLoopRunning then return end
                queueLoopRunning = true
                task.spawn(function()
                    while AutoQueue.Enabled do
                        pcall(queueIntoSelected)
                        task.wait(5)
                    end
                    queueLoopRunning = false
                end)
            else
                -- UI constructors call default callbacks during startup. Do not
                -- touch matchmaking unless auto queue was actually enabled first.
                if wasEnabled then
                    wasEnabled = false
                    leaveQueue()
                end
            end
        end
    })

    -- Do not require DuelLibrary while the startup loader is initializing modules.
    -- Start with a safe list and refresh it only after startup has completed.
    GameMode = AutoQueue:AddDropdown({
        Name = "Game Mode",
        List = {"1v1", "2v2_beginner"},
        Default = "1v1",
        Function = function()
            if AutoQueue.Enabled then
                pcall(queueIntoSelected)
            end
        end
    })

    task.spawn(function()
        while not mainapi.FeatureLoadComplete and not mainapi.Uninjecting do
            task.wait(0.1)
        end
        if mainapi.Uninjecting then return end

        task.wait(0.25)
        local ok, list = pcall(getQueueData)
        if ok and type(list) == "table" and #list > 0 and GameMode then
            if GameMode.SetList then
                GameMode:SetList(list)
            elseif GameMode.SetValues then
                GameMode:SetValues(list)
            else
                GameMode.List = list
            end
        end
    end)
end)

-- END PLEX SOURCE: modules/auto_queue.lua
-- BEGIN PLEX SOURCE: shared/017_spoofers.lua
run(function()
    local service = game:GetService("Players")
    local ownPlayer = service.LocalPlayer
    local alive, refreshing = true, false
    local originals, records, playerConnections = {}, {}, {}
    local objectCache = setmetatable({}, {__mode = "k"})
    local objectConnections = setmetatable({}, {__mode = "k"})
    local humanoidCache = setmetatable({}, {__mode = "k"})
    local customPictureFrames = setmetatable({}, {__mode = "k"})
    local appearance = {}
    local rootConnections, tokens = {}, {}
    local presentationSurfaces = setmetatable({}, {__mode = "k"})
    local ownName, ownAvatar, enemy, advancedAvatar
    local peerConfigs = setmetatable({}, {__mode = "k"})
    local function allSpoofConfigs()
        local configs = {}
        for _, config in ipairs({ownName, ownAvatar, enemy, advancedAvatar}) do
            if config then table.insert(configs, config) end
        end
        for _, config in pairs(peerConfigs) do
            table.insert(configs, config)
        end
        return configs
    end
    local updateCustomPicture
    local spoofFolder = workspace:FindFirstChild("__PlexAvatarSpoofs")
    if spoofFolder and not spoofFolder:IsA("Folder") then
        pcall(function() spoofFolder:Destroy() end)
        spoofFolder = nil
    end
    if not spoofFolder then
        spoofFolder = Instance.new("Folder")
        spoofFolder.Name = "__PlexAvatarSpoofs"
        spoofFolder.Archivable = false
        spoofFolder.Parent = workspace
    end

    -- Hooks persist across reloads, but their active records are replaced.
    local hookState = getgenv().__LionIdentitySpoofState
    if not hookState then
        hookState = {}
        getgenv().__LionIdentitySpoofState = hookState
    end

    hookState.Records = hookState.Records or {}
    hookState.AvatarCharacters = hookState.AvatarCharacters or setmetatable({}, {__mode = "k"})
    hookState.AvatarObjects = hookState.AvatarObjects or setmetatable({}, {__mode = "k"})
    hookState.AvatarDescriptionsByUserId = hookState.AvatarDescriptionsByUserId or {}
    hookState.AvatarDescriptionsByCharacter = hookState.AvatarDescriptionsByCharacter or setmetatable({}, {__mode = "k"})

    if hookState.Version ~= 3 and hookmetamethod and getnamecallmethod then
        hookState.Version = 3

        local oldIndex
        oldIndex = hookmetamethod(game, "__index", newcclosure(function(object, key)
            local record = hookState.Records[object]
            if record and (not checkcaller or not checkcaller()) then
                if key == "Name" and record.Username ~= "" then return record.Username end
                if key == "DisplayName" and record.DisplayName ~= "" then return record.DisplayName end
                if key == "CharacterAppearanceId" and record.AvatarSourceUserId then
                    return record.AvatarSourceUserId
                end
            end
            return oldIndex(object, key)
        end))
        hookState.ReadOriginal = function(object, key) return oldIndex(object, key) end

        local function cloneDescription(description)
            if typeof(description) ~= "Instance" then return nil end
            local okClass, className = pcall(oldIndex, description, "ClassName")
            if not okClass or className ~= "HumanoidDescription" then return nil end
            local okClone, cloneMethod = pcall(oldIndex, description, "Clone")
            if not okClone or type(cloneMethod) ~= "function" then return nil end
            local clonedOK, cloned = pcall(cloneMethod, description)
            return clonedOK and cloned or nil
        end

        local function destroyDirect(instance)
            if typeof(instance) ~= "Instance" then return end
            local okDestroy, destroyMethod = pcall(oldIndex, instance, "Destroy")
            if okDestroy and type(destroyMethod) == "function" then
                pcall(destroyMethod, instance)
            end
        end

        local spoofed_methods = {
            GetAppliedDescription = true, ApplyDescription = true, ApplyDescriptionReset = true,
            ApplyDescriptionClientServer = true, RemoveAccessories = true, Destroy = true, Remove = true,
            GetHumanoidDescriptionFromUserIdAsync = true, GetHumanoidDescriptionFromUserId = true,
            GetUserThumbnailAsync = true,
        }
        local oldNamecall
        oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(object, ...)
            local method = getnamecallmethod()
            if not spoofed_methods[method] then return oldNamecall(object, ...) end
            local external = not checkcaller or not checkcaller()

            if external and typeof(object) == "Instance" then
                local className
                local okClass, resolvedClass = pcall(oldIndex, object, "ClassName")
                if okClass then className = resolvedClass end

                if className == "Humanoid" then
                    local character
                    local okParent, resolvedParent = pcall(oldIndex, object, "Parent")
                    if okParent then character = resolvedParent end
                    local spoofDescription = hookState.AvatarDescriptionsByCharacter[character]

                    if spoofDescription then
                        if method == "GetAppliedDescription" then
                            local cloned = cloneDescription(spoofDescription)
                            if cloned then return cloned end
                        elseif method == "ApplyDescription"
                            or method == "ApplyDescriptionReset"
                            or method == "ApplyDescriptionClientServer" then
                            local args = table.pack(...)
                            local cloned = cloneDescription(spoofDescription)
                            if cloned then
                                args[1] = cloned
                                local okMethod, applyMethod = pcall(oldIndex, object, method)
                                if okMethod and type(applyMethod) == "function" then
                                    local results = table.pack(pcall(applyMethod, object, table.unpack(args, 1, args.n)))
                                    destroyDirect(cloned)
                                    if results[1] then
                                        return table.unpack(results, 2, results.n)
                                    end
                                else
                                    destroyDirect(cloned)
                                end
                            end
                            -- A failed replacement must not fall through and
                            -- apply the game's original/default description.
                            return nil
                        elseif method == "RemoveAccessories" then
                            return nil
                        end
                    end
                elseif hookState.AvatarObjects[object]
                    and (method == "Destroy" or method == "Remove") then
                    return nil
                end
            end

            if object == service and external then
                local args = table.pack(...)
                local requestedUserId = tonumber(args[1])
                local spoofDescription = requestedUserId
                    and hookState.AvatarDescriptionsByUserId[requestedUserId]

                if spoofDescription
                    and (method == "GetHumanoidDescriptionFromUserIdAsync"
                        or method == "GetHumanoidDescriptionFromUserId") then
                    local cloned = cloneDescription(spoofDescription)
                    if cloned then return cloned end
                end

                if method == "GetUserThumbnailAsync" then
                    for player, record in pairs(hookState.Records) do
                        if player.UserId == args[1] and record.Picture and record.SourceUserId then
                            args[1] = record.SourceUserId
                            return oldNamecall(object, table.unpack(args, 1, args.n))
                        end
                    end
                end
            end

            return oldNamecall(object, ...)
        end))
    end

    hookState.Records = records
    if getgenv().__LionNameSpoofState then getgenv().__LionNameSpoofState.Enabled = false end

    local function readOriginal(player, key)
        if hookState.ReadOriginal then return hookState.ReadOriginal(player, key) end
        return player[key]
    end

    local function remember(player)
        if not originals[player] then
            originals[player] = {
                Username = tostring(readOriginal(player, "Name") or player.Name or ""),
                DisplayName = tostring(readOriginal(player, "DisplayName") or player.DisplayName or player.Name or ""),
                Thumbnails = {},
            }
        end
        return originals[player]
    end

    local function isEnemy(player)
        return player ~= ownPlayer and (ownPlayer.Neutral or player.Neutral or player.Team ~= ownPlayer.Team)
    end

    local function targets(config)
        if not config.Enemies then return {ownPlayer} end
        local result = {}
        for _, player in ipairs(service:GetPlayers()) do
            if player ~= ownPlayer and (config.Target == "All enemies" and isEnemy(player)
                or config.Target == remember(player).Username .. " (" .. player.UserId .. ")") then
                table.insert(result, player)
            end
        end
        return result
    end

    local function configTargetsPlayer(config, player)
        if not config or not player then return false end
        if not config.Enemies then return player == ownPlayer end
        if player == ownPlayer then return false end
        if config.Target == "All enemies" then return isEnemy(player) end
        return config.Target == remember(player).Username .. " (" .. player.UserId .. ")"
    end

    local function replaceNames(text)
        if #tokens == 0 then return text end
        local containsName = false
        for _, token in ipairs(tokens) do
            if text:find(token[1], 1, true) then containsName = true; break end
        end
        if not containsName then return text end
        local result, cursor = {}, 1
        while cursor <= #text do
            local matched = false
            for _, token in ipairs(tokens) do
                local last = cursor + #token[1] - 1
                if text:sub(cursor, last) == token[1]
                    and not text:sub(cursor - 1, cursor - 1):match("[%w_]")
                    and not text:sub(last + 1, last + 1):match("[%w_]") then
                    table.insert(result, token[2])
                    cursor, matched = last + 1, true
                    break
                end
            end
            if not matched then
                table.insert(result, text:sub(cursor, cursor))
                cursor += 1
            end
        end
        return table.concat(result)
    end

    local function pictureFor(image)
        local id = tonumber(image:match("[Uu]ser[Ii]d=(%d+)"))
        for player, record in pairs(records) do
            if record.Picture and record.SourceUserId then
                if id == player.UserId then
                    return image:gsub("([Uu]ser[Ii]d=)%d+", "%1" .. record.SourceUserId)
                end
                if originals[player].Thumbnails[image] then
                    return "rbxthumb://type=AvatarHeadShot&id=" .. record.SourceUserId .. "&w=420&h=420"
                end
                if image:find("rbxthumb://", 1, true) and tonumber(image:match("[&?]id=(%d+)")) == player.UserId
                    and image:find("type=Avatar", 1, true) then
                    return image:gsub("([&?]id=)%d+", "%1" .. record.SourceUserId)
                end
            end
        end
        return image
    end

    local function applyObject(object)
        if not alive or refreshing then return end
        local property = (object:IsA("TextLabel") or object:IsA("TextButton")) and "Text"
            or (object:IsA("ImageLabel") or object:IsA("ImageButton")) and "Image"
        if not property then return end
        if property == "Text" and #tokens == 0 then return end
        pcall(function()
            local current = object[property]
            local entry = objectCache[object]
            if not entry then
                entry = { Property = property, Original = current }
                objectCache[object] = entry
            elseif entry.Writing then return
            elseif current ~= entry.Applied then entry.Original = current end
            local updated = property == "Text" and replaceNames(entry.Original) or pictureFor(entry.Original)
            entry.Applied = updated
            if updated ~= current then
                entry.Writing = true
                object[property] = updated
                entry.Writing = false
            end
            if property == "Image" and updateCustomPicture then
                updateCustomPicture(object, entry.Original)
            end
            if not objectConnections[object] then
                objectConnections[object] = object:GetPropertyChangedSignal(property):Connect(function()
                    if next(records) then applyObject(object) end
                end)
            end
        end)
    end

    local presentationSurfaceNames = {
        EliminatedEffect=true, EliminatedCard=true, ViewProfile=true,
        Profile=true, Leaderboard=true, PlayerList=true, FinalResults=true,
        Winners=true, DuelerProfile=true,
    }
    local function rememberPresentationSurface(object)
        if presentationSurfaceNames[object.Name] then presentationSurfaces[object] = true end
    end

    local function scanCharacterNametags()
        for player in pairs(records) do
            local character=player.Character
            local nametag=character and character:FindFirstChild("NametagGui",true)
            if nametag then
                applyObject(nametag)
                for _,object in ipairs(nametag:GetDescendants()) do applyObject(object) end
            end
        end
    end

    local function scan()
        -- UI identity spoofing only needs UI trees. Scanning all of Workspace here
        -- caused large, unpredictable frame spikes on maps with many descendants.
        local roots = {game:GetService("CoreGui")}
        local playerGui = ownPlayer:FindFirstChildOfClass("PlayerGui")
        if playerGui then table.insert(roots, playerGui) end

        for _, root in ipairs(roots) do
            if root then
                if not rootConnections[root] then
                    rootConnections[root] = root.DescendantAdded:Connect(function(object)
                        rememberPresentationSurface(object)
                        if next(records) then task.defer(applyObject, object) end
                    end)
                end
                for _, object in ipairs(root:GetDescendants()) do
                    rememberPresentationSurface(object)
                    applyObject(object)
                end
            end
        end

        -- Still catch newly-created world-space nameplates without doing a full
        -- Workspace:GetDescendants() pass.
        if not rootConnections[workspace] then
            rootConnections[workspace] = workspace.DescendantAdded:Connect(function(object)
                if not next(records) then return end
                if object:IsA("TextLabel") or object:IsA("TextButton")
                    or object:IsA("ImageLabel") or object:IsA("ImageButton") then
                    task.defer(applyObject, object)
                end
            end)
        end
        scanCharacterNametags()
    end

    -- Rivals detaches and later repopulates these small presentation trees.
    -- A bounded refresh catches reused cards without returning to expensive
    -- full-PlayerGui scans on every frame.
    local function refreshPresentationSurfaces()
        if not next(records) then return end
        for object in pairs(presentationSurfaces) do
            if not object.Parent then
                presentationSurfaces[object] = nil
            else
                local visible = true
                if object:IsA("GuiObject") then visible = object.Visible end
                if object:IsA("LayerCollector") then visible = object.Enabled end
                if visible then
                    applyObject(object)
                    for _, descendant in ipairs(object:GetDescendants()) do applyObject(descendant) end
                end
            end
        end
    end

    local function restoreUI()
        refreshing = true
        for object, entry in pairs(objectCache) do
            pcall(function()
                if object[entry.Property] == entry.Applied then object[entry.Property] = entry.Original end
            end)
        end
        table.clear(objectCache)
        for imageObject, state in pairs(customPictureFrames) do
            pcall(function()
                if state.TransparencyConnection then state.TransparencyConnection:Disconnect() end
                if state.Viewport then state.Viewport:Destroy() end
                if imageObject and imageObject.Parent then
                    imageObject.ImageTransparency = state.OriginalTransparency
                end
            end)
        end
        table.clear(customPictureFrames)
        for humanoid, original in pairs(humanoidCache) do
            pcall(function() humanoid.DisplayName = original end)
        end
        table.clear(humanoidCache)
        refreshing = false
    end

    local syncViewModelArms

    local function restoreAvatar(player)
        local saved = appearance[player]
        if not saved then return end
        appearance[player] = nil
        if saved.Character then
            hookState.AvatarCharacters[saved.Character] = nil
            hookState.AvatarDescriptionsByCharacter[saved.Character] = nil
        end

        if saved.NativeDescription and saved.OriginalDescription and saved.Character and saved.Character.Parent then
            local humanoid = saved.Character:FindFirstChildOfClass("Humanoid")
            if humanoid then
                local description = saved.OriginalDescription
                pcall(function() humanoid:ApplyDescriptionReset(description) end)
            end
            pcall(function() saved.OriginalDescription:Destroy() end)
            saved.OriginalDescription = nil
        end

        if saved.Connection then pcall(function() saved.Connection:Disconnect() end) end
        if saved.Connections then
            for _, connection in ipairs(saved.Connections) do
                pcall(function() connection:Disconnect() end)
            end
        end

        if saved.FaceConnection then saved.FaceConnection:Disconnect();saved.FaceConnection=nil end
        if saved.Donor then saved.Donor:Destroy();saved.Donor=nil end

        if saved.HiddenHeads then
            for head, original in pairs(saved.HiddenHeads) do
                if head and head.Parent then
                    pcall(function()
                        head.Transparency = original.Transparency
                        head.LocalTransparencyModifier = original.LocalTransparencyModifier
                    end)
                end
            end
        elseif saved.HeadHidden and saved.Head and saved.Head.Parent then
            pcall(function()
                saved.Head.Transparency = saved.HeadTransparency
                saved.Head.LocalTransparencyModifier = saved.HeadLocalTransparency
            end)
        end

        for _, object in ipairs(saved.Added or {}) do
            pcall(function()
                if object then
                    hookState.AvatarObjects[object] = nil
                    for _, descendant in ipairs(object:GetDescendants()) do
                        hookState.AvatarObjects[descendant] = nil
                    end
                    if object.Parent then object:Destroy() end
                end
            end)
        end

        for _, entry in ipairs(saved.Removed or {}) do
            pcall(function()
                if entry.Object and entry.Parent and entry.Parent.Parent then
                    entry.Object.Parent = entry.Parent
                end
            end)
        end

        if player == ownPlayer then task.defer(syncViewModelArms) end
    end

    -- The local first-person viewmodel (arms/hands/fingers) is spawned from
    -- the real account appearance, so the avatar spoof must mirror the
    -- spoofed shirt/skin onto it. Without this the spoof only shows on the
    -- full character rig, lobby preview, and ESP snapshot.
    local viewmodelArmCache = setmetatable({}, {__mode = "k"}) -- part -> {Color, Decals}
    local viewmodelSyncNext = 0

    local function viewmodelArmParts()
        local folder = workspace:FindFirstChild("ViewModels")
        if not folder then return {} end
        local parts = {}
        for _, descendant in ipairs(folder:GetDescendants()) do
            if descendant:IsA("BasePart") and (descendant.Name == "LeftArm" or descendant.Name == "RightArm") then
                parts[#parts + 1] = descendant
            end
        end
        return parts
    end

    local function toAssetId(value)
        if type(value) == "number" and value > 0 then return value end
        if type(value) == "string" then
            local id = tonumber(value:match("(%d+)"))
            if id and id > 0 then return id end
        end
        return nil
    end

    local function firstPartColor(character, names)
        for _, name in ipairs(names) do
            local part = character:FindFirstChild(name)
            if part and part:IsA("BasePart") then return part.Color end
        end
        return nil
    end

    syncViewModelArms = function()
        if not alive then return end
        local saved = appearance[ownPlayer]
        if not saved then
            if next(viewmodelArmCache) then
                for part, original in pairs(viewmodelArmCache) do
                    pcall(function()
                        if part and part.Parent then part.Color = original.Color end
                        for decal, texture in pairs(original.Decals) do
                            if decal and decal.Parent then decal.Texture = texture end
                        end
                    end)
                end
                table.clear(viewmodelArmCache)
            end
            return
        end

        local config = saved.Config
        local description = config and config.Description
        local character = ownPlayer.Character

        local shirtTemplate
        local characterShirt = character and character:FindFirstChildOfClass("Shirt")
        if characterShirt and characterShirt.ShirtTemplate and characterShirt.ShirtTemplate ~= "" then
            shirtTemplate = characterShirt.ShirtTemplate
        else
            local id = description and toAssetId(description.Shirt)
            if id then shirtTemplate = "rbxassetid://" .. tostring(id) end
        end

        local leftColor, rightColor
        if description then
            pcall(function()
                leftColor = typeof(description.LeftArmColor) == "Color3" and description.LeftArmColor or leftColor
                rightColor = typeof(description.RightArmColor) == "Color3" and description.RightArmColor or rightColor
            end)
        end
        if character then
            leftColor = leftColor or firstPartColor(character, {"LeftUpperArm", "LeftLowerArm", "LeftArm", "LeftHand"})
            rightColor = rightColor or firstPartColor(character, {"RightUpperArm", "RightLowerArm", "RightArm", "RightHand"})
        end

        for _, part in ipairs(viewmodelArmParts()) do
            pcall(function()
                local original = viewmodelArmCache[part]
                if not original then
                    original = {Color = part.Color, Decals = {}}
                    viewmodelArmCache[part] = original
                    for _, decal in ipairs(part:GetDescendants()) do
                        if decal:IsA("Decal") then original.Decals[decal] = decal.Texture end
                    end
                end
                local color = part.Name == "RightArm" and rightColor or leftColor
                if color then part.Color = color end
                if shirtTemplate then
                    for _, decal in ipairs(part:GetDescendants()) do
                        if decal:IsA("Decal") and decal.Texture ~= shirtTemplate then
                            decal.Texture = shirtTemplate
                        end
                    end
                end
            end)
        end
    end

    do
        local RunService = game:GetService("RunService")
        local connection = RunService.Heartbeat:Connect(function()
            local now = os.clock()
            if now < viewmodelSyncNext then return end
            viewmodelSyncNext = now + 0.5
            syncViewModelArms()
        end)
        table.insert(rootConnections, connection)
    end

    local function warnFailure(config, message)
        warn("[Spoofer] " .. config.Label .. ": " .. tostring(message))
    end

    local function clearAvatarTemplates(config)
        for _, model in pairs(config.Templates or {}) do
            pcall(function() model:Destroy() end)
        end
        config.Templates = {}
        config.TemplatePending = {}
    end

    local function avatarOutfitComplete(model, description, headless)
        if not model or not model:FindFirstChild("Head") then return false end
        local expected, actual = {}, 0
        for _, field in ipairs({"HatAccessory","HairAccessory","FaceAccessory","NeckAccessory","ShouldersAccessory","FrontAccessory","BackAccessory","WaistAccessory"}) do
            for id in tostring(description[field] or ""):gmatch("%d+") do if tonumber(id)>0 then expected[id]=true end end
        end
        local count=0
        for _ in pairs(expected) do count+=1 end
        for _, object in ipairs(model:GetChildren()) do if object:IsA("Accessory") then actual+=1 end end
        if actual<count then return false end
        if not headless and tonumber(description.Face) and description.Face>0 then
            local face=model.Head:FindFirstChildOfClass("Decal")
            if not face or face.Texture=="" then return false end
        end
        return true
    end

    local function getAvatarTemplate(config, rigType, generation, cutscene)
        if not config.Description then return nil end
        config.Templates = config.Templates or {}
        config.TemplatePending = config.TemplatePending or {}
        local key = cutscene and "Cutscene" or tostring(rigType)
        if config.Templates[key] then return config.Templates[key] end
        if config.TemplatePending[key] then
            local deadline = os.clock() + 12
            while config.TemplatePending[key] and os.clock() < deadline do task.wait(0.1) end
            return config.Templates[key]
        end
        local pending = {}
        config.TemplatePending[key] = pending
        local description = config.Description:Clone()
        if cutscene then
            description.Torso = 15365012259
            description.LeftArm = 15365010034
            description.RightArm = 15365012263
            description.LeftLeg = 15365010038
            description.RightLeg = 15365010030
        end
        local ok, model = pcall(function()
            return service:CreateHumanoidModelFromDescriptionAsync(description, rigType)
        end)
        if ok then
            local checked,complete=pcall(avatarOutfitComplete,model,description,config.Headless)
            if not checked or not complete then
                model:Destroy()
                ok,model=false,checked and "Avatar assets are incomplete; keeping the existing outfit. Try apply / refresh again." or tostring(complete)
            end
        end
        description:Destroy()
        if config.TemplatePending[key] == pending then config.TemplatePending[key] = nil end
        if not ok then
            if alive and config.Enabled and config.Generation == generation then warnFailure(config, model) end
            return nil
        end
        if not alive or not config.Enabled or config.Generation ~= generation then
            model:Destroy()
            return nil
        end
        model.Archivable = true
        config.Templates[key] = model
        return model
    end

    local function customPictureRecord(image)
        local lower = tostring(image or ""):lower()
        for player, record in pairs(records) do
            if record.CustomPicture and record.AvatarDescription and record.AvatarConfig then
                local directId = tonumber(lower:match("userid=(%d+)")) or tonumber(lower:match("[&?]id=(%d+)"))
                local original = originals[player]
                if (directId == player.UserId and (lower:find("avatar", 1, true) or lower:find("headshot", 1, true)))
                    or (original and original.Thumbnails[image]) then
                    return player, record
                end
            end
        end
    end

    updateCustomPicture = function(imageObject, image)
        if not imageObject or not imageObject.Parent
            or not (imageObject:IsA("ImageLabel") or imageObject:IsA("ImageButton")) then
            return
        end

        local player, record = customPictureRecord(image)
        local existing = customPictureFrames[imageObject]
        local current, visible = imageObject, true
        while current do
            if current:IsA("GuiObject") and not current.Visible then visible = false break end
            if current:IsA("LayerCollector") and not current.Enabled then visible = false break end
            current = current.Parent
        end
        if not visible then
            if existing then
                pcall(function()
                    if existing.TransparencyConnection then existing.TransparencyConnection:Disconnect() end
                    if existing.Viewport then existing.Viewport:Destroy() end
                    imageObject.ImageTransparency = existing.OriginalTransparency
                end)
                customPictureFrames[imageObject] = nil
            end
            return
        end
        if not player or not record then
            if existing then
                pcall(function()
                    if existing.TransparencyConnection then existing.TransparencyConnection:Disconnect() end
                    if existing.Viewport then existing.Viewport:Destroy() end
                    imageObject.ImageTransparency = existing.OriginalTransparency
                end)
                customPictureFrames[imageObject] = nil
            end
            return
        end

        local config = record.AvatarConfig
        local revision = record.AvatarRevision or 0
        if existing and existing.Config == config and existing.Revision == revision
            and existing.Viewport and existing.Viewport.Parent == imageObject then
            return
        end

        local originalTransparency = existing and existing.OriginalTransparency or imageObject.ImageTransparency
        if existing then
            pcall(function()
                if existing.TransparencyConnection then existing.TransparencyConnection:Disconnect() end
                if existing.Viewport then existing.Viewport:Destroy() end
            end)
        end

        local viewport = Instance.new("ViewportFrame")
        viewport.Name = "__PlexAvatarPicture"
        viewport.BackgroundTransparency = 1
        viewport.BorderSizePixel = 0
        viewport.Size = UDim2.fromScale(1, 1)
        viewport.Position = UDim2.fromScale(0, 0)
        viewport.ZIndex = imageObject.ZIndex + 1
        viewport.ClipsDescendants = true
        viewport.Ambient = Color3.fromRGB(200, 200, 200)
        viewport.LightColor = Color3.fromRGB(255, 255, 255)
        viewport.Parent = imageObject

        local camera = Instance.new("Camera")
        camera.FieldOfView = math.clamp(tonumber(config.PfpFov) or 28, 10, 90)
        camera.Parent = viewport
        viewport.CurrentCamera = camera

        local world = Instance.new("WorldModel")
        world.Name = "AvatarPictureWorld"
        world.Parent = viewport

        local state = {
            Viewport = viewport,
            OriginalTransparency = originalTransparency,
            Config = config,
            Revision = revision,
        }
        customPictureFrames[imageObject] = state
        local writingTransparency = false
        local function hideOriginalPicture()
            if writingTransparency or customPictureFrames[imageObject] ~= state or not imageObject.Parent then return end
            if imageObject.ImageTransparency ~= 1 then
                writingTransparency = true
                imageObject.ImageTransparency = 1
                writingTransparency = false
            end
        end
        hideOriginalPicture()
        state.TransparencyConnection = imageObject:GetPropertyChangedSignal("ImageTransparency"):Connect(hideOriginalPicture)

        task.spawn(function()
            local template = getAvatarTemplate(config, Enum.HumanoidRigType.R15, config.Generation, false)
            if not template or not alive or not config.Enabled
                or (config.AvatarRevision or 0) ~= revision
                or customPictureFrames[imageObject] ~= state
                or not viewport.Parent then
                return
            end

            local model = template:Clone()
            model.Name = "AvatarPictureModel"
            model.Parent = world
            if config.Headless then
                local head = model:FindFirstChild("Head", true)
                if head and head:IsA("BasePart") then
                    head.Transparency, head.LocalTransparencyModifier = 1, 1
                    for _, object in ipairs(head:GetDescendants()) do
                        if object:IsA("Decal") or object:IsA("Texture") then object.Transparency = 1 end
                    end
                end
            end

            for _, object in ipairs(model:GetDescendants()) do
                if object:IsA("BasePart") then
                    object.Anchored = true
                    object.CanCollide = false
                    object.CanTouch = false
                    object.CanQuery = false
                end
            end

            local yaw = math.rad(tonumber(config.PfpYaw) or 0)
            pcall(function() model:PivotTo(CFrame.Angles(0, yaw, 0)) end)

            local function framePortrait()
                if not viewport.Parent or customPictureFrames[imageObject] ~= state then return end
                local head = model:FindFirstChild("Head", true)
                local torso = model:FindFirstChild("UpperTorso", true) or model:FindFirstChild("Torso", true)
                local focusPart = head or torso or model:FindFirstChild("HumanoidRootPart", true)
                    or model:FindFirstChildWhichIsA("BasePart", true)
                local focus = focusPart and focusPart.Position or model:GetPivot().Position
                if head or torso then focus += Vector3.new(0, -0.35, 0) end
                local frame = Vector3.new(
                    (tonumber(config.PfpOffsetX) or 0) / 50,
                    (tonumber(config.PfpOffsetY) or 0) / 50,
                    0
                )
                local target = focus + frame
                local zoom = math.clamp(tonumber(config.PfpZoom) or 100, 25, 300) / 100
                -- Use a fixed portrait distance even while an emote moves limbs.
                -- Bounding-box fitting makes wide emotes shrink into a tiny PFP.
                local distance = 3.15 / zoom
                local pitch = math.rad(math.clamp(tonumber(config.PfpPitch) or 0, -60, 60))
                local cameraOffset = Vector3.new(0, math.sin(pitch) * distance, -math.cos(pitch) * distance)
                camera.CFrame = CFrame.lookAt(target + cameraOffset, target)
            end

            -- Show the correctly-sized portrait while the animation asset loads.
            framePortrait()

            local animationId = tostring(config.PfpAnimationId or ""):match("%d+")
            if animationId then
                pcall(function()
                    local humanoid = model:FindFirstChildOfClass("Humanoid")
                    if not humanoid then return end
                    local animator = humanoid:FindFirstChildOfClass("Animator") or Instance.new("Animator")
                    animator.Parent = humanoid
                    local animation = Instance.new("Animation")
                    animation.Name = "PlexPicturePose"
                    animation.AnimationId = "rbxassetid://" .. animationId
                    animation.Parent = model
                    local track = animator:LoadAnimation(animation)
                    track:Play(0, 1, 1)
                    local deadline = os.clock() + 3
                    while track.Length <= 0 and os.clock() < deadline and viewport.Parent do
                        task.wait()
                    end
                    if track.Length > 0 then
                        local pose = math.clamp(tonumber(config.PfpPosePosition) or 50, 0, 100) / 100
                        track.TimePosition = math.min(track.Length * pose, math.max(track.Length - 0.001, 0))
                    end
                    track:AdjustSpeed(0)
                    local runService = game:GetService("RunService")
                    runService.Heartbeat:Wait()
                    runService.Heartbeat:Wait()
                end)
            end
            -- Reframe after Motor6D transforms from the frozen pose have settled.
            framePortrait()
        end)
    end

    local function watchAvatarFace(player, saved, face, texture)
        if saved.FaceConnection then saved.FaceConnection:Disconnect();saved.FaceConnection=nil end
        if not face then return end
        local correcting=false
        saved.FaceConnection=face:GetPropertyChangedSignal("Texture"):Connect(function()
            if correcting or appearance[player]~=saved or not face.Parent or face.Texture==texture then return end
            correcting=true
            face.Texture=texture
            correcting=false
        end)
    end

    -- Render a local avatar on the existing rig, preserving its game controllers.
     -- Apply the spoofed outfit to the existing character rig.
    -- This follows the supplied source: replace clothing/accessories/face locally
    -- instead of welding a second full avatar body on top of the live character.
    local applyAvatar
    local avatarApplyBusy, avatarApplyQueued = {}, {}
    local function applyAvatarNow(player, config, generation, forceAppearance)
        if not alive or not config.Enabled or config.Generation ~= generation then return end
        local character = player.Character
        if not character then return end

        local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 10)
        if not humanoid or not humanoid:IsA("Humanoid") then return end
        if player == ownPlayer then
            local root = character:FindFirstChild("HumanoidRootPart") or character:WaitForChild("HumanoidRootPart", 10)
            if not root or humanoid.Health <= 0 then return end
        end
        if not alive or not config.Enabled or config.Generation ~= generation or player.Character ~= character then return end

        local existing = appearance[player]
        if not forceAppearance and existing and existing.Config == config and existing.Character == character
            and existing.SourceUserId == config.SourceUserId
            and existing.AvatarRevision == (config.AvatarRevision or 0) then
            if not config.NativeApplyUnavailable then
                hookState.AvatarDescriptionsByCharacter[character] = config.Description
            end
            return
        end

        local template = getAvatarTemplate(config, humanoid.RigType, generation, false)
        if not template then return end
        if not alive or not config.Enabled or config.Generation ~= generation or player.Character ~= character then return end

        if config.Description and not config.NativeApplyUnavailable then
            restoreAvatar(player)

            local originalDescription
            pcall(function()
                originalDescription = humanoid:GetAppliedDescription()
            end)

            hookState.AvatarCharacters[character] = true
            hookState.AvatarDescriptionsByCharacter[character] = config.Description

            local spoofDescription = config.Description:Clone()
            local applied, applyError = pcall(function()
                humanoid:ApplyDescriptionReset(spoofDescription)
            end)
            spoofDescription:Destroy()
            if not alive or not config.Enabled or config.Generation ~= generation or player.Character ~= character then
                hookState.AvatarCharacters[character]=nil
                hookState.AvatarDescriptionsByCharacter[character]=nil
                if originalDescription then
                    if player.Character==character then pcall(function() humanoid:ApplyDescriptionReset(originalDescription) end) end
                    originalDescription:Destroy()
                end
                return
            end
            if applied then
                local expectedFace=template.Head:FindFirstChildOfClass("Decal")
                local actualHead=character:FindFirstChild("Head")
                local actualFace=actualHead and actualHead:FindFirstChildOfClass("Decal")
                local wrongFace=not config.Headless and expectedFace and (not actualFace or actualFace.Texture~=expectedFace.Texture)
                if wrongFace or not avatarOutfitComplete(character, config.Description, config.Headless) then
                    applied, applyError = false, "Native avatar apply returned an incomplete outfit"
                end
            end

            if applied then
                appearance[player] = {
                    Added = {},
                    Removed = {},
                    Connections = {},
                    Config = config,
                    Character = character,
                    SourceUserId = config.SourceUserId,
                    AvatarRevision = config.AvatarRevision or 0,
                    NativeDescription = true,
                    OriginalDescription = originalDescription,
                }
                local saved=appearance[player]
                local targetFace=character:FindFirstChild("Head")
                targetFace=targetFace and targetFace:FindFirstChildOfClass("Decal")
                if not config.Headless and targetFace then watchAvatarFace(player,saved,targetFace,targetFace.Texture) end
                saved.Connections[#saved.Connections+1]=character.DescendantRemoving:Connect(function(object)
                    if appearance[player]~=saved or saved.RepairQueued then return end
                    if not object:IsA("Accessory") and not (object:IsA("Decal") and object.Parent==character:FindFirstChild("Head")) then return end
                    saved.RepairQueued=true
                    task.defer(function()
                        saved.RepairQueued=false
                        if alive and config.Enabled and appearance[player]==saved and player.Character==character then
                            applyAvatar(player,config,config.Generation,true)
                        end
                    end)
                end)
                if player == ownPlayer then task.defer(syncViewModelArms) end
                return
            end

            hookState.AvatarCharacters[character] = nil
            hookState.AvatarDescriptionsByCharacter[character] = nil
            if originalDescription then
                pcall(function() humanoid:ApplyDescriptionReset(originalDescription) end)
                pcall(function() originalDescription:Destroy() end)
            end
            local errorText = tostring(applyError)
            if errorText:lower():find("backend server", 1, true) then
                config.NativeApplyUnavailable = true
                if not config.NativeFallbackWarned then
                    config.NativeFallbackWarned = true
                    warnFailure(config, "The game blocks client avatar data; using the R6 appearance fallback")
                end
            elseif not config.NativeFallbackWarned then
                config.NativeFallbackWarned = true
                warnFailure(config, "Native avatar apply failed, using R6 fallback: " .. errorText)
            end
        end

        local donor = template:Clone()

        if not alive or not config.Enabled or config.Generation ~= generation or player.Character ~= character then
            donor:Destroy()
            return
        end

        restoreAvatar(player)

        local saved = {
            Added = {},
            Removed = {},
            Connections = {},
            Config = config,
            Character = character,
            SourceUserId = config.SourceUserId,
            AvatarRevision = config.AvatarRevision or 0,
        }
        saved.Donor=donor
        saved.OutfitSlots={}
        appearance[player] = saved
        hookState.AvatarCharacters[character] = true
        if player == ownPlayer then task.defer(syncViewModelArms) end

        local function isAppearanceObject(object)
            return object:IsA("Accessory")
                or object:IsA("Shirt")
                or object:IsA("Pants")
                or object:IsA("ShirtGraphic")
                or (object:IsA("CharacterMesh") and object.BodyPart == Enum.BodyPart.Head)
        end

        local function isOurObject(object)
            return object:GetAttribute("__PlexAvatarSpoof") == true
        end

        local function isHairAccessory(object)
            if not object:IsA("Accessory") then return false end
            local okType, accessoryType = pcall(function() return object.AccessoryType end)
            if okType and accessoryType == Enum.AccessoryType.Hair then return true end

            local handle = object:FindFirstChild("Handle")
            if handle and handle:FindFirstChild("HairAttachment") then return true end

            -- Older R6 hair can report AccessoryType.Unknown. Names are the final
            -- fallback after the type and attachment checks.
            return object.Name:lower():find("hair", 1, true) ~= nil
        end

        local function rememberRemoved(object, parent)
            for _, entry in ipairs(saved.Removed) do
                if entry.Object == object then return end
            end
            saved.Removed[#saved.Removed + 1] = {Object = object, Parent = parent}
        end

        local function removeOriginal(object)
            if not object or isOurObject(object) then return end
            if isAppearanceObject(object) and object.Parent == character then
                rememberRemoved(object, character)
                object.Parent = nil
                return
            end

            local head = character:FindFirstChild("Head")
            if head and (object:IsA("Decal") or object:IsA("SpecialMesh")) and object.Parent == head then
                rememberRemoved(object, head)
                object.Parent = nil
            end
        end

        local function addSpoofObject(object, parent)
            local copy = object:Clone()
            copy:SetAttribute("__PlexAvatarSpoof", true)
            hookState.AvatarObjects[copy] = true

            for _, descendant in ipairs(copy:GetDescendants()) do
                hookState.AvatarObjects[descendant] = true
                if descendant:IsA("BasePart") then
                    descendant.Anchored = false
                    descendant.CanCollide = false
                    descendant.CanTouch = false
                    descendant.CanQuery = false
                    descendant.Massless = true
                end
            end

            copy.Parent = parent
            saved.Added[#saved.Added + 1] = copy
            return copy
        end

        local function attachAccessory(copy)
            if not copy:IsA("Accessory") then return end
            local handle = copy:FindFirstChild("Handle")
            if not handle then return end

            local old = handle:FindFirstChild("AccessoryWeld")
            if old then old:Destroy() end

            local attachment = handle:FindFirstChildOfClass("Attachment")
            local target = attachment and character:FindFirstChild(attachment.Name, true)

            if target and target:IsDescendantOf(copy) then target = nil end
            if not target and attachment then
                for _, part in ipairs(character:GetChildren()) do
                    if part:IsA("BasePart") then
                        target = part:FindFirstChild(attachment.Name)
                        if target then break end
                    end
                end
            end
            if target and not target:IsA("Attachment") then target = nil end

            local head = character:FindFirstChild("Head")
            if target or head then
                local bodyPart = target and target.Parent or head
                local bodyOffset = target and target.CFrame or CFrame.new(0, 0.5, 0)
                local handleOffset = attachment and attachment.CFrame or copy.AttachmentPoint
                -- Align the loose handle before welding it. Otherwise the physics
                -- solver can pull the live character toward the donor rig's origin.
                handle.CFrame = bodyPart.CFrame * bodyOffset * handleOffset:Inverse()
                handle.AssemblyLinearVelocity = Vector3.zero
                handle.AssemblyAngularVelocity = Vector3.zero
                local weld = Instance.new("Weld")
                weld.Name = "PlexAvatarAccessoryWeld"
                weld.Part0 = bodyPart
                weld.Part1 = handle
                weld.C0 = bodyOffset
                weld.C1 = handleOffset
                weld.Parent = handle
            end
        end

        local function hideR6Head(head)
            if not config.Headless or appearance[player] ~= saved
                or not head or not head:IsA("BasePart") or head.Name ~= "Head" then
                return
            end

            saved.HiddenHeads = saved.HiddenHeads or setmetatable({}, {__mode = "k"})
            if saved.HiddenHeads[head] then return end

            local original = {
                Transparency = head.Transparency,
                LocalTransparencyModifier = head.LocalTransparencyModifier,
            }
            saved.HiddenHeads[head] = original

            local correctingHead = false
            local function keepHeadHidden()
                if correctingHead or appearance[player] ~= saved or not head.Parent then return end
                correctingHead = true
                if head.Transparency ~= 1 then head.Transparency = 1 end
                if head.LocalTransparencyModifier ~= 1 then head.LocalTransparencyModifier = 1 end
                correctingHead = false
            end
            keepHeadHidden()
            saved.Connections[#saved.Connections + 1] = head:GetPropertyChangedSignal("Transparency"):Connect(keepHeadHidden)
            saved.Connections[#saved.Connections + 1] = head:GetPropertyChangedSignal("LocalTransparencyModifier"):Connect(keepHeadHidden)
        end

        local function buildOutfit()
            if appearance[player] ~= saved or player.Character ~= character then return false end

            for _, object in ipairs(character:GetChildren()) do
                removeOriginal(object)
            end

            local head = character:FindFirstChild("Head")
            if head then
                for _, object in ipairs(head:GetChildren()) do
                    removeOriginal(object)
                end

                if config.Headless then
                    hideR6Head(head)
                end
            end

            local function ensureObject(source,parent)
                local old=saved.OutfitSlots[source]
                if old and old.Parent==parent then return end
                if old then
                    hookState.AvatarObjects[old]=nil
                    for _, child in ipairs(old:GetDescendants()) do hookState.AvatarObjects[child]=nil end
                    local index=table.find(saved.Added,old)
                    if index then table.remove(saved.Added,index) end
                    pcall(function()old:Destroy()end)
                end
                local copy=addSpoofObject(source,parent)
                saved.OutfitSlots[source]=copy
                if copy:IsA("Decal") then watchAvatarFace(player,saved,copy,source.Texture) end
                if copy:IsA("Accessory") then attachAccessory(copy) end
            end
            for _, object in ipairs(donor:GetChildren()) do
                if isAppearanceObject(object) and not (config.NoHair and isHairAccessory(object)) then ensureObject(object,character) end
            end
            local sourceHead=donor:FindFirstChild("Head")
            if head and sourceHead and not config.Headless then
                for _, object in ipairs(sourceHead:GetChildren()) do
                    if object:IsA("Decal") or object:IsA("SpecialMesh") then ensureObject(object,head) end
                end
            end

            return true
        end

        local built, failure = pcall(buildOutfit)

        if not built or failure == false then
            restoreAvatar(player)
            warnFailure(config, built and "Could not apply spoofed outfit" or failure)
            return
        end

        local function queueOutfitRepair()
            if saved.RepairQueued or appearance[player]~=saved then return end
            saved.RepairQueued=true
            task.defer(function()
                if alive and config.Enabled and appearance[player]==saved and player.Character==character then
                    local ok,err=pcall(buildOutfit)
                    if not ok then warnFailure(config,err) end
                end
                saved.RepairQueued=false
            end)
        end
        saved.Connections[#saved.Connections+1]=character.DescendantRemoving:Connect(function(object)
            if isOurObject(object) or object.Name=="Head" then queueOutfitRepair() end
        end)
        saved.Connection = character.DescendantAdded:Connect(function(object)
            if appearance[player] ~= saved or isOurObject(object) then return end
            if object:IsA("BasePart") and object.Name=="Head" then queueOutfitRepair() end
            if config.Headless and object:IsA("BasePart") and object.Name == "Head" then
                task.defer(hideR6Head, object)
                return
            end
            local head = character:FindFirstChild("Head")
            if not isAppearanceObject(object)
                and not ((object:IsA("Decal") or object:IsA("SpecialMesh")) and object.Parent == head) then
                return
            end
            task.defer(function()
                if appearance[player] == saved then pcall(removeOriginal, object) end
            end)
        end)
    end

    applyAvatar = function(player, config, generation, forceAppearance)
        local request={Config=config,Generation=generation,Force=forceAppearance,Character=player.Character}
        local active=avatarApplyBusy[player]
        if active then
            -- ApplyDescription can emit the same appearance events we observe.
            -- Only a newer setting or character needs a follow-up application.
            if active.Config~=config or active.Generation~=generation or active.Character~=request.Character then
                avatarApplyQueued[player]=request
            end
            return
        end
        repeat
            avatarApplyBusy[player]=request
            avatarApplyQueued[player]=nil
            local ok,err=pcall(applyAvatarNow,player,request.Config,request.Generation,request.Force)
            if not ok and alive then warnFailure(request.Config,err) end
            request=avatarApplyQueued[player]
        until not request or not alive
        avatarApplyQueued[player]=nil
        avatarApplyBusy[player]=nil
    end

    local function rebuildRecords()
        restoreUI()
        table.clear(records)
        table.clear(tokens)
        table.clear(hookState.AvatarDescriptionsByUserId)
        table.clear(hookState.AvatarDescriptionsByCharacter)
        for _, config in ipairs(allSpoofConfigs()) do
            if config.Enabled then
                for _, player in ipairs(targets(config)) do
                    local original = remember(player)
                    local shownUsername = config.Anonymous and "Anonymous" or tostring(config.Username or "")
                    local shownDisplayName = config.Anonymous and "Anonymous" or tostring(config.DisplayName or "")
                    local record = records[player] or {Username = "", DisplayName = "", Picture = false}
                    records[player] = record
                    if shownUsername ~= "" then record.Username = shownUsername end
                    if shownDisplayName ~= "" then record.DisplayName = shownDisplayName end
                    if config.Picture and (config.Anonymous or config.SourceUserId) then
                        record.SourceUserId = config.Anonymous and 1 or config.SourceUserId
                        record.Picture = true
                    end
                    if config.Avatar and config.Description then
                        if config.SourceUserId then record.AvatarSourceUserId = config.SourceUserId end
                        record.AvatarDescription = config.Description
                        record.AvatarConfig = config
                        record.AvatarRevision = config.AvatarRevision or 0
                        record.CustomPicture = config.CustomPicture == true
                        hookState.AvatarDescriptionsByUserId[player.UserId] = config.Description
                        if player.Character and not config.NativeApplyUnavailable then
                            hookState.AvatarDescriptionsByCharacter[player.Character] = config.Description
                        end
                    end
                    if shownUsername ~= "" then
                        table.insert(tokens, {"@" .. original.Username, "@" .. shownUsername})
                        table.insert(tokens, {original.Username, shownUsername})
                    end
                    if shownDisplayName ~= "" and (original.DisplayName ~= original.Username or shownUsername == "") then
                        table.insert(tokens, {original.DisplayName, shownDisplayName})
                    end
                    local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
                    if humanoid and shownDisplayName ~= "" then
                        humanoidCache[humanoid] = humanoid.DisplayName
                        humanoid.DisplayName = shownDisplayName
                    end
                end
            end
        end
        table.sort(tokens, function(a, b) return #a[1] > #b[1] end)
        if next(records) then scan() end
    end

    local function applyPeerDescriptionOverrides(description, values, headless, noHair)
        if not description then return end
        values = type(values) == "table" and values or {}
        local single = {sh="Shirt", pa="Pants", ts="GraphicTShirt", fa="Face", he="Head"}
        local lists = {ha="HatAccessory", hr="HairAccessory", fc="FaceAccessory", ne="NeckAccessory",
            so="ShouldersAccessory", fr="FrontAccessory", ba="BackAccessory", wa="WaistAccessory"}
        for key, property in pairs(single) do
            local value = values[key]
            if value ~= nil and tostring(value) ~= "" then
                local number = tonumber(tostring(value):match("%d+")) or 0
                pcall(function() description[property] = math.floor(number) end)
            end
        end
        for key, property in pairs(lists) do
            local value = values[key]
            if value ~= nil then
                local ids = {}
                for id in tostring(value):gmatch("%d+") do ids[#ids + 1] = id end
                pcall(function() description[property] = table.concat(ids, ",") end)
            end
        end
        if headless then
            pcall(function() description.Head = 134082579 end)
            pcall(function() description.Face = 0 end)
        end
        if noHair then pcall(function() description.HairAccessory = "" end) end
    end

    local function refresh(config, forceAvatar)
        if not alive then return end
        config.Generation += 1
        local generation = config.Generation
        local source = config.Anonymous and "1" or tostring(config.Source or ""):match("^%s*(.-)%s*$")
        if source == "" and config.Headless then source = tostring(ownPlayer.UserId) end
        local sourceChanged = config.ResolvedSource ~= source
        config.ResolvedSource = source

        if not config.Enabled or source == "" then
            for player, saved in pairs(appearance) do
                if saved.Config == config then restoreAvatar(player) end
            end
            if config.Description then config.Description:Destroy() end
            clearAvatarTemplates(config)
            config.SourceUserId, config.Description = nil, nil
            rebuildRecords()
            return
        end

        if sourceChanged or forceAvatar == true then
            config.AvatarRevision = (config.AvatarRevision or 0) + 1
            if config.Description then config.Description:Destroy() end
            clearAvatarTemplates(config)
            config.SourceUserId, config.Description = nil, nil
        end

        if not config.Avatar then
            for player, saved in pairs(appearance) do
                if saved.Config == config then restoreAvatar(player) end
            end
        end

        rebuildRecords()
        task.spawn(function()
            local id = config.SourceUserId
            if not id then
                local ok, result = pcall(function()
                    local numeric = tonumber(source)
                    if numeric and numeric > 0 and numeric % 1 == 0 then return numeric end
                    return service:GetUserIdFromNameAsync(source:gsub("^@", ""))
                end)
                if not alive or config.Generation ~= generation or not config.Enabled then return end
                if not ok then
                    for player, saved in pairs(appearance) do
                        if saved.Config == config then restoreAvatar(player) end
                    end
                    warnFailure(config, "Could not find avatar account: " .. tostring(result))
                    return
                end
                id = result
                config.SourceUserId = id
            end

            if config.Avatar and not config.Description then
                local descOK, description = pcall(function()
                    return service:GetHumanoidDescriptionFromUserIdAsync(id)
                end)
                if not alive or config.Generation ~= generation or not config.Enabled then
                    if descOK then description:Destroy() end
                    return
                end
                if descOK then
                    if config.PeerValues or config.Headless or config.NoHair then
                        applyPeerDescriptionOverrides(description, config.PeerValues, config.Headless, config.NoHair)
                    end
                    config.Description = description
                else
                    for player, saved in pairs(appearance) do
                        if saved.Config == config then restoreAvatar(player) end
                    end
                    warnFailure(config, description)
                end
            end

            if config.Avatar and config.Description then
                task.spawn(getAvatarTemplate, config, Enum.HumanoidRigType.R15, generation, true)
            end

            rebuildRecords()
            local wanted = {}
            for _, player in ipairs(targets(config)) do
                wanted[player] = true
                if config.Picture then
                    task.spawn(function()
                        local original = remember(player)
                        for _, size in ipairs({Enum.ThumbnailSize.Size100x100, Enum.ThumbnailSize.Size150x150, Enum.ThumbnailSize.Size420x420}) do
                            local thumbOK, url = pcall(function()
                                return service:GetUserThumbnailAsync(player.UserId, Enum.ThumbnailType.HeadShot, size)
                            end)
                            if thumbOK then original.Thumbnails[url] = true end
                        end
                        if alive and config.Enabled and config.Generation == generation then scan() end
                    end)
                end
                if config.Avatar and config.Description then
                    task.spawn(function()
                        applyAvatar(player, config, generation)
                    end)
                end
            end

            for player, saved in pairs(appearance) do
                if saved.Config == config and not wanted[player] then restoreAvatar(player) end
            end
        end)
    end

    local function playerList()
        local names = {"All enemies"}
        for _, player in ipairs(service:GetPlayers()) do
            if player ~= ownPlayer then table.insert(names, remember(player).Username .. " (" .. player.UserId .. ")") end
        end
        table.sort(names, function(a, b) if a == "All enemies" then return true elseif b == "All enemies" then return false end return a < b end)
        return names
    end

    local function createConfig(label, enemies, kind)
        local config = {
            Label = label, Enabled = false, Username = "", DisplayName = "", Source = "",
            Picture = kind ~= "name", Avatar = kind ~= "name", Anonymous = false, Enemies = enemies,
            Generation = 0, Target = "All enemies",
        }

-- END PLEX SOURCE: shared/017_spoofers.lua
-- BEGIN PLEX SOURCE: modules/target_player.lua
        config.Module = Other:AddModule({ Name = label, Function = function(enabled)
            config.Enabled = enabled == true
            if config.Enabled and label == "Avatar Spoofer"
                and advancedAvatar and advancedAvatar.Enabled and advancedAvatar.Module then
                advancedAvatar.Module:Toggle(false)
            end
            refresh(config)
        end })
        config.Module:AddLabel({Text = "Changes appear only on your client."})
        if enemies then
            config.Selector = config.Module:AddDropdown({ Name = "target player", List = playerList(), Default = "All enemies",
                Function = function(value) config.Target = value refresh(config) end })
            config.Module:AddToggle({ Name = "opsec (anonymous mode)", Default = false,
                Function = function(value)
                    config.Anonymous = value == true
                    refresh(config, true)
                end })
        end
        if kind ~= "avatar" then
            config.Module:AddInputBox({ Name = "username", Default = "", Placeholder = "Blank keeps the original",
                Function = function(value) config.Username = tostring(value or "") rebuildRecords() end })
            config.Module:AddInputBox({ Name = "display name", Default = "", Placeholder = "Blank keeps the original",
                Function = function(value) config.DisplayName = tostring(value or "") rebuildRecords() end })
        end
        if kind ~= "name" then
            config.Module:AddInputBox({ Name = "avatar account", Default = "", Placeholder = "Roblox username or user ID",
                Function = function(value)
                    config.Source = tostring(value or ""):match("^%s*(.-)%s*$")
                    config.InputVersion = (config.InputVersion or 0) + 1
                    local version = config.InputVersion
                    task.delay(0.4, function()
                        if alive and config.InputVersion == version then refresh(config) end
                    end)
                end })
        end
        if kind == "avatar" then
            config.Module:AddToggle({Name = "headless", Default = false, Function = function(value)
                config.Headless = value == true
                config.CustomPicture = config.Headless
                refresh(config, true)
            end})
        end
        config.Module:AddButton({ Name = "apply / refresh", Function = function() refresh(config, true) end })
        config.Module:AddButton({ Name = "restore original", Function = function()
            config.Enabled = false
            if config.Module.Enabled then config.Module:Toggle(false) else refresh(config) end
        end })
        return config
    end

    local function createAdvancedAvatarConfig()
        local config = {
            Label = "Advanced Avatar Spoofer",
            Enabled = false,
            Avatar = true,
            Picture = false,
            CustomPicture = true,
            Headless = false,
            NoHair = false,
            PfpAnimationId = "",
            PfpPosePosition = 50,
            PfpZoom = 100,
            PfpFov = 28,
            PfpOffsetX = 0,
            PfpOffsetY = 0,
            PfpYaw = 0,
            PfpPitch = 0,
            Anonymous = false,
            Enemies = false,
            Generation = 0,
            Target = "All enemies",
            Values = {},
            Templates = {},
            TemplatePending = {},
            Dirty = false,
            -- Prefer HumanoidDescription, then fall back to changing appearance
            -- objects on the existing R6 rig when this game blocks client applies.
        }

        local singleFields = {
            Shirt = "Shirt",
            Pants = "Pants",
            GraphicTShirt = "GraphicTShirt",
            Face = "Face",
            Head = "Head",
        }

        local accessoryFields = {
            HatAccessory = "HatAccessory",
            HairAccessory = "HairAccessory",
            FaceAccessory = "FaceAccessory",
            NeckAccessory = "NeckAccessory",
            ShoulderAccessory = "ShouldersAccessory",
            FrontAccessory = "FrontAccessory",
            BackAccessory = "BackAccessory",
            WaistAccessory = "WaistAccessory",
        }

        local function trim(value)
            return tostring(value or ""):match("^%s*(.-)%s*$")
        end

        local function parseSingle(value)
            local text = trim(value)
            if text == "" then return nil end
            if text:lower() == "none" or text == "0" then return 0 end
            local id = tonumber(text:match("%d+"))
            return id and math.floor(id) or nil
        end

        local function parseList(value)
            local text = trim(value)
            if text == "" then return nil end
            if text:lower() == "none" or text == "0" then return "" end
            local ids = {}
            for id in text:gmatch("%d+") do
                local number = tonumber(id)
                if number and number > 0 then ids[#ids + 1] = tostring(math.floor(number)) end
            end
            return #ids > 0 and table.concat(ids, ",") or nil
        end

        local function clearBuilt()
            if config.Description then
                pcall(function() config.Description:Destroy() end)
                config.Description = nil
            end
            clearAvatarTemplates(config)
        end

        local function buildDescription()
            if not config.BaseDescription then return nil end
            local description = config.BaseDescription:Clone()

            for key, property in pairs(singleFields) do
                local value = parseSingle(config.Values[key])
                if value ~= nil then pcall(function() description[property] = value end) end
            end

            for key, property in pairs(accessoryFields) do
                local value = parseList(config.Values[key])
                if value ~= nil then pcall(function() description[property] = value end) end
            end

            if config.Headless then
                pcall(function() description.Head = 134082579 end)
                pcall(function() description.Face = 0 end)
            end
            if config.NoHair then
                pcall(function() description.HairAccessory = "" end)
            end

            return description
        end

        local function refreshAdvanced(forceBase)
            if not alive then return end
            config.Generation += 1
            local generation = config.Generation

            if not config.Enabled then
                for player, saved in pairs(appearance) do
                    if saved.Config == config then restoreAvatar(player) end
                end
                clearBuilt()
                if config.BaseDescription then
                    pcall(function() config.BaseDescription:Destroy() end)
                    config.BaseDescription = nil
                end
                config.Dirty = false
                rebuildRecords()
                return
            end

            task.spawn(function()
                if forceBase or not config.BaseDescription then
                    local current = appearance[ownPlayer]
                    if current and current.Config == config then
                        restoreAvatar(ownPlayer)
                    end

                    -- R6's live applied description can omit hair or head accessories
                    -- after the game edits the rig. Start from the account profile so
                    -- blank fields reliably keep the complete original appearance.
                    local base
                    local okProfile, profile = pcall(function()
                        return service:GetHumanoidDescriptionFromUserIdAsync(ownPlayer.UserId)
                    end)
                    if okProfile then base = profile end

                    if not base then
                        local character = ownPlayer.Character
                        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                        if humanoid then
                            local okApplied, applied = pcall(function()
                                return humanoid:GetAppliedDescription()
                            end)
                            if okApplied then base = applied end
                        end
                    end

                    if not base or not alive or not config.Enabled or config.Generation ~= generation then
                        if base then pcall(function() base:Destroy() end) end
                        return
                    end

                    if config.BaseDescription then pcall(function() config.BaseDescription:Destroy() end) end
                    config.BaseDescription = base
                end

                if not alive or not config.Enabled or config.Generation ~= generation then return end

                for player, saved in pairs(appearance) do
                    if saved.Config == config then restoreAvatar(player) end
                end

                clearBuilt()
                local description = buildDescription()
                if not description then return end

                config.Description = description
                config.AvatarRevision = (config.AvatarRevision or 0) + 1
                config.Dirty = false
                rebuildRecords()

                task.spawn(getAvatarTemplate, config, Enum.HumanoidRigType.R15, generation, true)

                task.spawn(function()
                    local original = remember(ownPlayer)
                    for _, size in ipairs({
                        Enum.ThumbnailSize.Size48x48,
                        Enum.ThumbnailSize.Size100x100,
                        Enum.ThumbnailSize.Size150x150,
                        Enum.ThumbnailSize.Size420x420,
                    }) do
                        local thumbOK, url = pcall(function()
                            return service:GetUserThumbnailAsync(ownPlayer.UserId, Enum.ThumbnailType.HeadShot, size)
                        end)
                        if thumbOK and url then original.Thumbnails[url] = true end
                    end
                    if alive and config.Enabled and config.Generation == generation then scan() end
                end)

                task.spawn(applyAvatar, ownPlayer, config, generation)
            end)
        end

        local function addInput(name, key, placeholder)
            config.Module:AddInputBox({
                Name = name,
                Default = "",
                Placeholder = placeholder,
                Function = function(value)
                    config.Values[key] = tostring(value or "")
                    config.Dirty = true
                end
            })
        end

        local function schedulePictureRefresh()
            config.PictureRefreshToken = (config.PictureRefreshToken or 0) + 1
            local token = config.PictureRefreshToken
            task.delay(0.12, function()
                if not alive or not config.Enabled or config.PictureRefreshToken ~= token then return end
                config.AvatarRevision = (config.AvatarRevision or 0) + 1
                rebuildRecords()
            end)
        end

-- END PLEX SOURCE: modules/target_player.lua
-- BEGIN PLEX SOURCE: modules/advanced_avatar_spoofer.lua
        config.Module = Other:AddModule({
            Name = "Advanced Avatar Spoofer",
            Function = function(enabled)
                config.Enabled = enabled == true
                if config.Enabled and ownAvatar and ownAvatar.Enabled and ownAvatar.Module then
                    ownAvatar.Module:Toggle(false)
                end
                refreshAdvanced(config.Enabled and not config.BaseDescription)
            end
        })

        config.Module:AddLabel({Text = "Blank keeps your current item. Use 0 or none to clear a slot."})
        config.Module:AddLabel({Text = "Edits are staged. Press apply / refresh once when you are done."})

        config.Module:AddToggle({
            Name = "headless",
            Default = false,
            Function = function(value)
                config.Headless = value == true
                config.Dirty = true
                if config.Enabled then refreshAdvanced(false) end
            end
        })
        config.Module:AddToggle({
            Name = "no hair",
            Default = false,
            Function = function(value)
                config.NoHair = value == true
                config.Dirty = true
                if config.Enabled then refreshAdvanced(false) end
            end
        })

        config.Module:AddLabel({Text = "Classic Clothing"})
        addInput("shirt id", "Shirt", "asset id")
        addInput("pants id", "Pants", "asset id")
        addInput("graphic t-shirt id", "GraphicTShirt", "asset id")

        config.Module:AddLabel({Text = "R6 Head"})
        addInput("face id", "Face", "asset id")
        addInput("head id", "Head", "asset id")

        config.Module:AddLabel({Text = "Head Accessories"})
        addInput("hat accessory ids", "HatAccessory", "comma separated ids")
        addInput("hair accessory ids", "HairAccessory", "comma separated ids")
        addInput("face accessory ids", "FaceAccessory", "comma separated ids")

        config.Module:AddLabel({Text = "Rigid Accessories"})
        addInput("neck accessory ids", "NeckAccessory", "comma separated ids")
        addInput("shoulder accessory ids", "ShoulderAccessory", "comma separated ids")
        addInput("front accessory ids", "FrontAccessory", "comma separated ids")
        addInput("back accessory ids", "BackAccessory", "comma separated ids")
        addInput("waist accessory ids", "WaistAccessory", "comma separated ids")

        config.Module:AddLabel({Text = "Profile Picture Pose"})
        config.Module:AddInputBox({
            Name = "emote / animation id",
            Default = "",
            Placeholder = "animation asset id",
            Function = function(value)
                config.PfpAnimationId = tostring(value or "")
                schedulePictureRefresh()
            end
        })
        config.Module:AddSlider({Name = "pose position", Min = 0, Max = 100, Default = 50, Suffix = "%", Function = function(value)
            config.PfpPosePosition = value
            schedulePictureRefresh()
        end})
        config.Module:AddSlider({Name = "zoom", Min = 25, Max = 300, Default = 100, Suffix = "%", Function = function(value)
            config.PfpZoom = value
            schedulePictureRefresh()
        end})
        config.Module:AddSlider({Name = "field of view", Min = 10, Max = 90, Default = 28, Suffix = " deg", Function = function(value)
            config.PfpFov = value
            schedulePictureRefresh()
        end})
        config.Module:AddSlider({Name = "position x", Min = -100, Max = 100, Default = 0, Suffix = "%", Function = function(value)
            config.PfpOffsetX = value
            schedulePictureRefresh()
        end})
        config.Module:AddSlider({Name = "position y", Min = -100, Max = 100, Default = 0, Suffix = "%", Function = function(value)
            config.PfpOffsetY = value
            schedulePictureRefresh()
        end})
        config.Module:AddSlider({Name = "avatar rotation", Min = -180, Max = 180, Default = 0, Suffix = " deg", Function = function(value)
            config.PfpYaw = value
            schedulePictureRefresh()
        end})
        config.Module:AddSlider({Name = "camera pitch", Min = -60, Max = 60, Default = 0, Suffix = " deg", Function = function(value)
            config.PfpPitch = value
            schedulePictureRefresh()
        end})

        config.Module:AddButton({Name = "apply / refresh", Function = function()
            if config.Enabled then refreshAdvanced(false) end
        end})

        config.Module:AddButton({Name = "reload base avatar", Function = function()
            if config.Enabled then refreshAdvanced(true) end
        end})

        config.Module:AddButton({Name = "restore original", Function = function()
            config.Enabled = false
            if config.Module.Enabled then config.Module:Toggle(false) else refreshAdvanced(false) end
        end})

        return config
    end

    ownName = createConfig("Username Spoofer", false, "name")
    ownAvatar = createConfig("Avatar Spoofer", false, "avatar")
    enemy = createConfig("Enemy Spoofer", true, "both")
    advancedAvatar = createAdvancedAvatarConfig()

    -- Peer sync feeds the same guarded spoof pipeline as the local controls.
    -- This keeps every client responsible for rendering the other Plex user's
    -- chosen identity/avatar without trusting or mutating server-owned data.
    shared.PlexSpooferPeerSync = {
        Export = function()
            local nameConfig = ownName.Enabled and ownName or nil
            local activeRecord = records[ownPlayer]
            local avatarConfig = advancedAvatar.Enabled and advancedAvatar
                or (ownAvatar.Enabled and ownAvatar or nil)
                or (activeRecord and activeRecord.AvatarConfig or nil)
            if not nameConfig and not avatarConfig then return nil end
            local advancedValues
            if avatarConfig == advancedAvatar then
                local keys = {Shirt="sh", Pants="pa", GraphicTShirt="ts", Face="fa", Head="he",
                    HatAccessory="ha", HairAccessory="hr", FaceAccessory="fc", NeckAccessory="ne",
                    ShoulderAccessory="so", FrontAccessory="fr", BackAccessory="ba", WaistAccessory="wa"}
                advancedValues = {}
                for property, short in pairs(keys) do
                    local value = avatarConfig.Values[property]
                    if type(value) == "string" and value ~= "" then advancedValues[short] = value:sub(1, 80) end
                end
                if not next(advancedValues) then advancedValues = nil end
            end
            return {
                u = nameConfig and tostring(nameConfig.Username or "") or nil,
                d = nameConfig and tostring(nameConfig.DisplayName or "") or nil,
                s = avatarConfig and (tonumber(avatarConfig.SourceUserId)
                    or tonumber(activeRecord and (activeRecord.AvatarSourceUserId or activeRecord.SourceUserId))
                    or ownPlayer.UserId) or nil,
                p = avatarConfig and ((activeRecord and activeRecord.Picture == true)
                    or avatarConfig.Picture == true) or nil,
                a = avatarConfig and ((activeRecord and activeRecord.AvatarDescription ~= nil)
                    or avatarConfig.Avatar == true) or nil,
                v = advancedValues,
                h = avatarConfig and avatarConfig.Headless == true or nil,
                nh = avatarConfig == advancedAvatar and avatarConfig.NoHair == true or nil,
                cp = avatarConfig and avatarConfig.CustomPicture == true or nil,
                pi = avatarConfig == advancedAvatar and tostring(avatarConfig.PfpAnimationId or ""):sub(1, 40) or nil,
                pp = avatarConfig == advancedAvatar and tonumber(avatarConfig.PfpPosePosition) or nil,
                pz = avatarConfig == advancedAvatar and tonumber(avatarConfig.PfpZoom) or nil,
                pf = avatarConfig == advancedAvatar and tonumber(avatarConfig.PfpFov) or nil,
                px = avatarConfig == advancedAvatar and tonumber(avatarConfig.PfpOffsetX) or nil,
                py = avatarConfig == advancedAvatar and tonumber(avatarConfig.PfpOffsetY) or nil,
                pr = avatarConfig == advancedAvatar and tonumber(avatarConfig.PfpYaw) or nil,
                pt = avatarConfig == advancedAvatar and tonumber(avatarConfig.PfpPitch) or nil,
            }
        end,
        Apply = function(player, state)
            if not player or player == ownPlayer or type(state) ~= "table" then return end
            local previous = peerConfigs[player]
            if previous then
                previous.Enabled = false
                refresh(previous)
                if previous.Description then previous.Description:Destroy() end
                clearAvatarTemplates(previous)
            end
            local sourceUserId = tonumber(state.s) or player.UserId
            local config = {
                Enabled = true,
                Enemies = true,
                Target = remember(player).Username .. " (" .. player.UserId .. ")",
                Username = tostring(state.u or ""),
                DisplayName = tostring(state.d or ""),
                Source = tostring(sourceUserId),
                SourceUserId = sourceUserId,
                Picture = state.p == true,
                Avatar = state.a == true,
                PeerValues = type(state.v) == "table" and state.v or nil,
                Headless = state.h == true,
                NoHair = state.nh == true,
                CustomPicture = state.cp == true,
                PfpAnimationId = tostring(state.pi or ""),
                PfpPosePosition = math.clamp(tonumber(state.pp) or 50, 0, 100),
                PfpZoom = math.clamp(tonumber(state.pz) or 100, 25, 300),
                PfpFov = math.clamp(tonumber(state.pf) or 28, 10, 90),
                PfpOffsetX = math.clamp(tonumber(state.px) or 0, -100, 100),
                PfpOffsetY = math.clamp(tonumber(state.py) or 0, -100, 100),
                PfpYaw = math.clamp(tonumber(state.pr) or 0, -180, 180),
                PfpPitch = math.clamp(tonumber(state.pt) or 0, -60, 60),
                Generation = 0,
                AvatarRevision = 0,
                Label = "Plex User Sync",
            }
            peerConfigs[player] = config
            refresh(config, true)
        end,
        Remove = function(player)
            local config = peerConfigs[player]
            if not config then return end
            config.Enabled = false
            refresh(config)
            if config.Description then config.Description:Destroy() end
            clearAvatarTemplates(config)
            peerConfigs[player] = nil
            rebuildRecords()
        end,
    }

    -- EliminatedEffect fills the cloned card synchronously and then yields for
    -- its five-second lifetime. Apply identity/profile state at that first
    -- yield so the card never keeps the account thumbnail or stale stats.
    local okEliminatedEffect, eliminatedEffect = pcall(function()
        return require(ownPlayer.PlayerScripts.Modules.UserInterface.EliminatedEffect)
    end)
    if okEliminatedEffect and type(eliminatedEffect) == "table"
        and type(eliminatedEffect.Play) == "function" then
        local originalEliminatedPlay = eliminatedEffect.Play
        local wrappedEliminatedPlay
        local function applyEliminatedCard(player)
            if not alive or typeof(player) ~= "Instance" or not player:IsA("Player") then return end
            local card = rawget(eliminatedEffect, "_last_eliminated_card")
            if not card or not card.Parent then return end

            local record = records[player]
            local frame = card:FindFirstChild("Frame")
            local outerContainer = frame and frame:FindFirstChild("Container")
            local clip = outerContainer and outerContainer:FindFirstChild("Clip")
            local container = clip and clip:FindFirstChild("Container")
            -- Apply images and generic replacements first. The explicit labels
            -- below must be last because a spoofed username can equal the
            -- player's original display name and otherwise get replaced twice.
            for _, object in ipairs(card:GetDescendants()) do applyObject(object) end
            if container and record then
                local playerLabel = container:FindFirstChild("Player")
                local usernameLabel = container:FindFirstChild("Username")
                local shownName = record.DisplayName ~= "" and record.DisplayName
                    or (record.Username ~= "" and record.Username or nil)
                if playerLabel and playerLabel:IsA("TextLabel") and shownName then
                    playerLabel.Text = shownName
                end
                if usernameLabel and usernameLabel:IsA("TextLabel") and record.Username ~= "" then
                    usernameLabel.Text = "@" .. record.Username
                end
            end

            local slot = card:FindFirstChild("TeammateSlot", true)
            local level = slot and slot:FindFirstChild("Level")
            local levelTitle = level and level:FindFirstChild("Title")
            local streak = slot and slot:FindFirstChild("Streak")
            local streakValue = streak and streak:FindFirstChild("Value")
            local spoofedLevel = player:GetAttribute("Level")
            local spoofedStreak = player:GetAttribute("StatisticDuelsWinStreak")
                or player:GetAttribute("WinStreak") or player:GetAttribute("CurrentWinStreak")
            if levelTitle and levelTitle:IsA("TextLabel") and spoofedLevel ~= nil then
                levelTitle.Text = tostring(math.floor(tonumber(spoofedLevel) or 0))
            end
            if streakValue and streakValue:IsA("TextLabel") and spoofedStreak ~= nil then
                streakValue.Text = tostring(math.floor(tonumber(spoofedStreak) or 0))
            end
        end
        wrappedEliminatedPlay = function(self, player, ...)
            task.defer(function()
                task.wait()
                applyEliminatedCard(player or ownPlayer)
            end)
            return originalEliminatedPlay(self, player, ...)
        end
        eliminatedEffect.Play = wrappedEliminatedPlay
        mainapi:Clean(function()
            if eliminatedEffect.Play == wrappedEliminatedPlay then
                eliminatedEffect.Play = originalEliminatedPlay
            end
        end)
    end

    -- FinalResults.Winners asks ClientDueler for a separate cutscene model.
    -- Its preloaded model is based on the account's real user ID, so use our
    -- cached local avatar template for the selected player instead.
    local okDueler, duelClass = pcall(function()
        return require(ownPlayer.PlayerScripts.Modules.ClientReplicatedClasses.ClientDueler)
    end)
    if okDueler and type(duelClass) == "table" and type(duelClass.GetCharacterModelForCutscene) == "function" then
        local originalCutsceneModel = duelClass.GetCharacterModelForCutscene
        local wrappedCutsceneModel
        wrappedCutsceneModel = function(self, ...)
            local player = self.Player
            local config
            local selected = false
            if player == ownPlayer then
                config = (advancedAvatar and advancedAvatar.Enabled) and advancedAvatar or ownAvatar
                selected = true
            elseif peerConfigs[player] and peerConfigs[player].Enabled then
                config = peerConfigs[player]
                selected = true
            else
                config = enemy
            end
            if not selected and config and config.Enabled then
                for _, target in ipairs(targets(enemy)) do
                    if target == player then selected = true break end
                end
            end
            local template = selected and config.Enabled and config.Avatar
                and config.Templates and config.Templates.Cutscene
            if not template and selected and config.Enabled and config.Avatar and config.Description then
                template = getAvatarTemplate(config, Enum.HumanoidRigType.R15, config.Generation, true)
            end
            if not template then return originalCutsceneModel(self, ...) end
            local model = template:Clone()
            for _, part in ipairs(model:GetDescendants()) do
                if part:IsA("BasePart") then
                    part.CanCollide = false
                    part.CanTouch = false
                    part.CanQuery = false
                end
            end
            local root = model:FindFirstChild("HumanoidRootPart")
            if root then root.Anchored = true end
            return model
        end
        duelClass.GetCharacterModelForCutscene = wrappedCutsceneModel
        mainapi:Clean(function()
            if duelClass.GetCharacterModelForCutscene == wrappedCutsceneModel then
                duelClass.GetCharacterModelForCutscene = originalCutsceneModel
            end
        end)
    end

    local function watchPlayer(player)
        remember(player)
        if playerConnections[player] then return end
        playerConnections[player] = {
            player.CharacterAdded:Connect(function(character)
                -- Register the description before yielding. Character-loading code may
                -- request or reapply appearance data during the same spawn frame.
                for _, config in ipairs(allSpoofConfigs()) do
                    if config.Enabled and config.Avatar and config.Description
                        and not config.NativeApplyUnavailable
                        and configTargetsPlayer(config, player) then
                        hookState.AvatarDescriptionsByCharacter[character] = config.Description
                    end
                end
                task.defer(function()
                    if not alive or player.Character ~= character then return end
                    rebuildRecords()
                    for _, config in ipairs(allSpoofConfigs()) do
                        if config.Enabled and config.Avatar and config.Description
                            and configTargetsPlayer(config, player) then
                            if not config.NativeApplyUnavailable then
                                hookState.AvatarDescriptionsByCharacter[character] = config.Description
                            end
                            task.spawn(applyAvatar, player, config, config.Generation)
                        end
                    end
                end)
            end),
            player.CharacterAppearanceLoaded:Connect(function(character)
                if avatarApplyBusy[player] then return end
                task.defer(function()
                    if not alive or player.Character ~= character or avatarApplyBusy[player] then return end
                    rebuildRecords()
                    for _, config in ipairs(allSpoofConfigs()) do
                        if config.Enabled and config.Avatar and config.Description
                            and configTargetsPlayer(config, player) then
                            if not config.NativeApplyUnavailable then
                                hookState.AvatarDescriptionsByCharacter[character] = config.Description
                            end
                            task.spawn(applyAvatar, player, config, config.Generation, true)
                        end
                    end
                end)
            end),
            player:GetPropertyChangedSignal("Team"):Connect(function()
                if alive and enemy.Enabled and enemy.Target == "All enemies" then refresh(enemy) end
            end),
            player:GetPropertyChangedSignal("Neutral"):Connect(function()
                if alive and enemy.Enabled and enemy.Target == "All enemies" then refresh(enemy) end
            end),
        }
    end
    for _, player in ipairs(service:GetPlayers()) do watchPlayer(player) end
    local nextPresentationRefresh = 0
    mainapi:Clean(RunService.Heartbeat:Connect(function()
        if not next(records) then return end
        local now = os.clock()
        if now < nextPresentationRefresh then return end
        nextPresentationRefresh = now + 0.25
        refreshPresentationSurfaces()
    end))
    mainapi:Clean(service.PlayerAdded:Connect(function(player)
        watchPlayer(player)
        if enemy.Selector.SetList then
            enemy.Selector:SetList(playerList())
        elseif enemy.Selector.SetValues then
            enemy.Selector:SetValues(playerList())
        end
        if enemy.Enabled then refresh(enemy) end
    end))
    mainapi:Clean(service.PlayerRemoving:Connect(function(player)
        if shared.PlexSpooferPeerSync then shared.PlexSpooferPeerSync.Remove(player) end
        restoreAvatar(player)
        if playerConnections[player] then
            for _, connection in ipairs(playerConnections[player]) do connection:Disconnect() end
            playerConnections[player] = nil
        end
        originals[player], records[player] = nil, nil
        task.defer(function()
            if alive then
                if enemy.Selector.SetList then
                    enemy.Selector:SetList(playerList())
                elseif enemy.Selector.SetValues then
                    enemy.Selector:SetValues(playerList())
                end
                if enemy.Enabled then refresh(enemy) end
            end
        end)
    end))
    mainapi:Clean(function()
        alive = false
        ownName.Enabled, ownAvatar.Enabled, enemy.Enabled, advancedAvatar.Enabled = false, false, false, false
        ownName.Generation += 1
        ownAvatar.Generation += 1
        enemy.Generation += 1
        advancedAvatar.Generation += 1
        table.clear(records)
        restoreUI()
        for player in pairs(appearance) do restoreAvatar(player) end
        for _, list in pairs(playerConnections) do for _, connection in ipairs(list) do connection:Disconnect() end end
        for _, connection in pairs(rootConnections) do connection:Disconnect() end
        for _, connection in pairs(objectConnections) do connection:Disconnect() end
        if ownAvatar.Description then ownAvatar.Description:Destroy() end
        if enemy.Description then enemy.Description:Destroy() end
        if advancedAvatar.Description then advancedAvatar.Description:Destroy() end
        if advancedAvatar.BaseDescription then advancedAvatar.BaseDescription:Destroy() end
        clearAvatarTemplates(ownAvatar)
        clearAvatarTemplates(enemy)
        clearAvatarTemplates(advancedAvatar)
        for player, config in pairs(peerConfigs) do
            if config.Description then config.Description:Destroy() end
            clearAvatarTemplates(config)
            peerConfigs[player] = nil
        end
        shared.PlexSpooferPeerSync = nil
        if spoofFolder and spoofFolder.Parent then pcall(function() spoofFolder:Destroy() end) end
    end)
end)

-- END PLEX SOURCE: modules/advanced_avatar_spoofer.lua
-- BEGIN PLEX SOURCE: shared/018_spoofers.lua
run(function()
    local DeviceSpoofer
    local Mode
    local function getCurrentDevice()
        if game:GetService("VRService").VREnabled then return "VR" end
        if UserInputService.TouchEnabled then return "Touch" end
        if UserInputService.GamepadEnabled and not UserInputService.KeyboardEnabled then return "Gamepad" end
        return "MouseKeyboard"
    end

    local function setDevice(mode)
        pcall(function()
            ReplicatedStorage.Remotes.Replication.Fighter.SetControls:FireServer(mode)
        end)
    end

-- END PLEX SOURCE: shared/018_spoofers.lua
-- BEGIN PLEX SOURCE: modules/device_spoofer.lua
    DeviceSpoofer = Other:AddModule({
        Name = 'Device Spoofer',
        Function = function(callback)
            if callback then
                setDevice(Mode.Value)
            else
                setDevice(getCurrentDevice())
            end
        end
    })

    Mode = DeviceSpoofer:AddDropdown({
        Name = 'Mode',
        List = {'Touch', 'Gamepad', 'MouseKeyboard', 'VR'},
        Default = 'MouseKeyboard',
        Function = function(val)
            if DeviceSpoofer.Enabled then
                setDevice(val)
            end
        end
    })

    DeviceSpoofer:Clean(LocalPlayer.CharacterAdded:Connect(function()
        if DeviceSpoofer.Enabled then
            task.wait(0.5)
            setDevice(Mode.Value)
        end
    end))
end)

-- Extra local-display spoofers ported from the supplied reference.

-- END PLEX SOURCE: modules/device_spoofer.lua
-- BEGIN PLEX SOURCE: shared/019_spoofers.lua
run(function()
    local function requireProfileModule(module)
        local identity = getthreadidentity and getthreadidentity()
        local switched = identity ~= nil and type(setthreadidentity) == "function"
        if switched then pcall(setthreadidentity, 2) end
        local ok, result = pcall(require, module)
        if switched then pcall(setthreadidentity, identity) end
        if not ok then error(result, 0) end
        return result
    end
    local pdc = nil
    local function resolvePdc()
        if pdc then return pdc end
        pcall(function()
            pdc = requireProfileModule(LocalPlayer.PlayerScripts.Controllers.PlayerDataController)
        end)
        return pdc
    end
    local function currentData()
        local controller = resolvePdc()
        return controller and controller.CurrentData
    end
    local function currentTable()
        local current = currentData()
        return current and current.Data
    end
    local function replicate(key)
        local current = currentData()
        if current and type(current.Replicate) == "function" then
            pcall(current.Replicate, current, key)
        end
    end

    local profileHook

-- END PLEX SOURCE: shared/019_spoofers.lua
-- BEGIN PLEX SOURCE: modules/profile_stats_spoofer.lua
    local applyStats, restoreStats
    local statsApplying = false
    local stats = Other:AddModule({
        Name = "Profile Stats Spoofer",
        Function = function(enabled)
            Config.__ProfileStatsSpoof = enabled == true
            if profileHook then
                profileHook.Enabled = enabled == true
                if enabled and profileHook.Install then pcall(profileHook.Install) end
            end
            if enabled then
                if applyStats then applyStats() end
            else
                if restoreStats then restoreStats() end
                local root=LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                local gui=root and root:FindFirstChild("NametagGui")
                local level=gui and gui:FindFirstChild("Level",true)
                local title=level and level:FindFirstChild("Title")
                if title then title.Text=tostring(LocalPlayer:GetAttribute("Level") or 0) end
            end
        end
    })
    local statValues = {
        Level = 100, RankedCurrentELO = 2400, CasualWins = 500, RankedWins = 250,
        WinRate = 75, WinStreak = 25, FavoriteMap = "Arena", FavoriteWeapons = {},
    }
    local statEnabled = {}
    local statAttrs = {
        Level={"Level"}, RankedCurrentELO={"DisplayELO","RankedCurrentELO"},
        CasualWins={"CasualWins","StatisticDuelsWins","StatisticDuelsWon"},
        RankedWins={"RankedWins","StatisticRankedDuelsWon"},
        WinRate={"CasualWinPercent","RankedWinPercent","StatisticDuelsWinRate","WinRate",
            "StatisticDuelsWinPercent","StatisticRankedDuelsWinPercent"},
        WinStreak={"StatisticDuelsWinStreak","WinStreak","CurrentWinStreak"},
        FavoriteMap={"FavoriteMap"},
    }
    Config.__ProfileStatsOriginalAttrs = Config.__ProfileStatsOriginalAttrs or {}
    profileHook = getgenv().__PlexProfileRequestHook
    if not profileHook then
        profileHook = {Enabled=false}
        getgenv().__PlexProfileRequestHook = profileHook
        local oldNamecall
        oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
            if profileHook.Remote == self and getnamecallmethod() == "InvokeServer" then
                local target = select(1, ...)
                local result = oldNamecall(self, ...)
                local transform = profileHook.Transform
                if transform and type(result) == "table" and (profileHook.Enabled or profileHook.BadgesEnabled or profileHook.SelfDataEnabled
                    or profileHook.PeerStates and profileHook.PeerStates[target and target.UserId]) then
                    local ok, spoofed = pcall(transform, result, target)
                    if ok and type(spoofed) == "table" then return spoofed end
                end
                return result
            end
            return oldNamecall(self, ...)
        end))
    end
    do
        local okRemote, remoteObj = pcall(function() return ReplicatedStorage.Remotes.Misc.RequestProfile end)
        profileHook.Remote = okRemote and remoteObj or nil
    end
    profileHook.PeerStates = profileHook.PeerStates or {}
    profileHook.PeerOriginalAttrs = profileHook.PeerOriginalAttrs or setmetatable({}, {__mode = "k"})
    profileHook.PeerConnections = profileHook.PeerConnections or setmetatable({}, {__mode = "k"})
    profileHook.PeerApplying = profileHook.PeerApplying or setmetatable({}, {__mode = "k"})
    local function transformStats(result, values, enabled)
        local out = table.clone(result)
        if enabled.Level then out.Level = tonumber(values.Level) or out.Level end
        if enabled.RankedCurrentELO then out.RankedCurrentELO = tonumber(values.RankedCurrentELO) or out.RankedCurrentELO end
        if enabled.CasualWins then out.CasualWins = tonumber(values.CasualWins) or out.CasualWins end
        if enabled.RankedWins then out.RankedWins = tonumber(values.RankedWins) or out.RankedWins end
        if enabled.WinRate then
            local rate = (tonumber(values.WinRate) or 0) / 100
            out.CasualWinPercent, out.RankedWinPercent = rate, rate
        end
        if enabled.WinStreak then
            out.StatisticDuelsWinStreak = tonumber(values.WinStreak) or out.StatisticDuelsWinStreak
            out.WinStreak = tonumber(values.WinStreak) or out.WinStreak
            out.CurrentWinStreak = tonumber(values.WinStreak) or out.CurrentWinStreak
        end
        if enabled.FavoriteMap then out.FavoriteMap = tostring(values.FavoriteMap) end
        if enabled.FavoriteWeapons then
            out.FavoriteWeapons={}
            for slot,weapon in ipairs(values.FavoriteWeapons or {}) do
                local entry
                for _,nativeWeapon in ipairs(result.FavoriteWeapons or {}) do
                    if nativeWeapon.Name==weapon then entry=table.clone(nativeWeapon); break end
                end
                out.FavoriteWeapons[slot]=entry or {Name=weapon,Level=1,XP=0,Prestige=0}
            end
        end
        return out
    end
    local function transformBadges(result, state)
        if type(state) ~= "table" then return result end
        local out = table.clone(result)
        out.IsPremium = state.p == true
        out.HasVerifiedBadge = state.v == true
        out.IsInfluencer = state.i == true
        out.IsRobloxEmployee = state.a == true
        -- Some profile revisions use the shorter names in their badge rows.
        out.Premium = state.p == true
        out.Verified = state.v == true
        out.Influencer = state.i == true
        out.RobloxEmployee = state.a == true
        return out
    end
    profileHook.Transform = function(result, target)
        local peer = target and target ~= LocalPlayer and profileHook.PeerStates[target.UserId]
        local output
        if peer then
            output = transformStats(result, {
                Level=peer.l, RankedCurrentELO=peer.e, CasualWins=peer.c,
                RankedWins=peer.r, WinRate=peer.w, WinStreak=peer.s, FavoriteMap=peer.f,
            }, {
                Level=peer.l~=nil, RankedCurrentELO=peer.e~=nil, CasualWins=peer.c~=nil,
                RankedWins=peer.r~=nil, WinRate=peer.w~=nil, WinStreak=peer.s~=nil,
                FavoriteMap=peer.f~=nil,
            })
            return transformBadges(output, peer.b)
        end
        if target and target ~= LocalPlayer then return result end
        output = profileHook.Enabled and transformStats(result, statValues, statEnabled) or result
        if (not target or target == LocalPlayer) and profileHook.BadgesEnabled then
            output = transformBadges(output, profileHook.BadgeState)
        end
        if profileHook.AdvancedTransform then return profileHook.AdvancedTransform(output,target) end
        return output
    end

    local function profileTransformEnabled(target)
        return profileHook.Enabled or profileHook.BadgesEnabled or profileHook.SelfDataEnabled
            or profileHook.PeerStates and profileHook.PeerStates[target and target.UserId] ~= nil
    end

    local function findProfileFetchService(fn, depth, seen)
        if type(fn) ~= "function" or depth > 10 or seen[fn] then return nil end
        seen[fn] = true
        local children = {}
        for index, value in debug.getupvalues(fn) do
            if typeof(value) == "Instance" then
                local isReplicatedStorage = value == ReplicatedStorage
                if not isReplicatedStorage then
                    pcall(function() isReplicatedStorage = value:IsA("ReplicatedStorage") end)
                end
                if isReplicatedStorage then return fn, index end
            end
            if type(value) == "function" then children[#children + 1] = value end
        end
        for _, child in ipairs(children) do
            local found, index = findProfileFetchService(child, depth + 1, seen)
            if found then return found, index end
        end
        return nil
    end

    local function installViewProfileRequestHook()
        if profileHook.ViewProfilePatch then return true end
        local ok, page = pcall(function()
            return requireProfileModule(LocalPlayer.PlayerScripts.Modules.Pages.ViewProfile)
        end)
        if not ok or type(page) ~= "table" or type(page.Fetch) ~= "function" then
            profileHook.ViewProfilePatchError="ViewProfile unavailable"
            return false
        end
        local fetch, serviceIndex = findProfileFetchService(page.Fetch, 1, {})
        if not fetch or not serviceIndex then
            profileHook.ViewProfilePatchError="Fetch request service not ready"
            return false
        end

        local realService = debug.getupvalue(fetch, serviceIndex)
        local realRemotes = realService and realService:FindFirstChild("Remotes")
        local realMisc = realRemotes and realRemotes:FindFirstChild("Misc")
        local realRequest = realMisc and realMisc:FindFirstChild("RequestProfile")
        if not realRequest or not realRequest:IsA("RemoteFunction") then
            profileHook.ViewProfilePatchError="RequestProfile remote unavailable"
            return false
        end

        local requestProxy = {}
        requestProxy.InvokeServer = function(_, target)
            local invoke = realRequest.InvokeServer
            local result = invoke(realRequest, target)
            local transform = profileHook.Transform
            if transform and type(result) == "table" and profileTransformEnabled(target) then
                local transformedOK, transformed = pcall(transform, result, target)
                if transformedOK and type(transformed) == "table" then return transformed end
            end
            return result
        end
        local miscProxy = setmetatable({RequestProfile=requestProxy}, {
            __index=function(_, key) return realMisc:FindFirstChild(key) end,
        })
        local remotesProxy = setmetatable({Misc=miscProxy}, {
            __index=function(_, key) return realRemotes:FindFirstChild(key) end,
        })
        local serviceProxy = setmetatable({Remotes=remotesProxy}, {
            __index=function(_, key) return realService[key] end,
        })
        debug.setupvalue(fetch, serviceIndex, serviceProxy)
        profileHook.ViewProfilePatch={Function=fetch,Index=serviceIndex,Original=realService}
        profileHook.ViewProfilePatchError=nil
        return true
    end
    profileHook.Install=installViewProfileRequestHook
    local function restorePeerStats(player)
        if player then profileHook.PeerStates[player.UserId] = nil end
        local connections = player and profileHook.PeerConnections[player]
        if connections then
            for _, connection in ipairs(connections) do pcall(function() connection:Disconnect() end) end
            profileHook.PeerConnections[player] = nil
        end
        if player then profileHook.PeerApplying[player] = nil end
        local badgeHook = getgenv().__PlexBadgePropertyHook
        if player and badgeHook and badgeHook.States then badgeHook.States[player] = nil end
        local saved = player and profileHook.PeerOriginalAttrs[player]
        if saved then
            for attr, entry in pairs(saved) do
                pcall(function() player:SetAttribute(attr, entry.HadValue and entry.Value or nil) end)
            end
            profileHook.PeerOriginalAttrs[player] = nil
        end
    end

    shared.PlexProfilePeerSync = {
        Export = function()
            local out = {}
            if statEnabled.Level then out.l = statValues.Level end
            if statEnabled.RankedCurrentELO then out.e = statValues.RankedCurrentELO end
            if statEnabled.CasualWins then out.c = statValues.CasualWins end
            if statEnabled.RankedWins then out.r = statValues.RankedWins end
            if statEnabled.WinRate then out.w = statValues.WinRate end
            if statEnabled.WinStreak then out.s = statValues.WinStreak end
            if statEnabled.FavoriteMap then out.f = statValues.FavoriteMap end
            if profileHook.BadgesEnabled and type(profileHook.BadgeState) == "table" then
                out.b = table.clone(profileHook.BadgeState)
            end
            return next(out) and out or nil
        end,
        Apply = function(player, state)
            if not player or player == LocalPlayer or type(state) ~= "table" then return end
            restorePeerStats(player)
            profileHook.PeerStates[player.UserId] = state
            local saved = {}
            profileHook.PeerOriginalAttrs[player] = saved
            local values = {Level=state.l, RankedCurrentELO=state.e, CasualWins=state.c,
                RankedWins=state.r, WinRate=state.w, WinStreak=state.s, FavoriteMap=state.f}
            local enabled = {Level=state.l~=nil, RankedCurrentELO=state.e~=nil, CasualWins=state.c~=nil,
                RankedWins=state.r~=nil, WinRate=state.w~=nil, WinStreak=state.s~=nil, FavoriteMap=state.f~=nil}
            local applied = {}
            for key, attrs in pairs(statAttrs) do
                if enabled[key] then
                    for _, attr in ipairs(attrs) do
                        local original = player:GetAttribute(attr)
                        saved[attr] = {HadValue=original ~= nil, Value=original}
                        local value = values[key]
                        if key == "WinRate" and attr:match("WinPercent$") then
                            value = (tonumber(value) or 0) / 100
                        end
                        applied[attr] = value
                    end
                end
            end
            if type(state.b) == "table" then
                local badgeAttrs = {p="IsPremium",v="HasVerifiedBadge",i="IsInfluencer",a="IsRobloxEmployee"}
                for short, attr in pairs(badgeAttrs) do
                    local original = player:GetAttribute(attr)
                    saved[attr] = {HadValue=original ~= nil, Value=original}
                    applied[attr] = state.b[short] == true
                end
                local badgeHook = getgenv().__PlexBadgePropertyHook
                if badgeHook and badgeHook.States then badgeHook.States[player] = table.clone(state.b) end
            end
            local function applyPeerAttributes()
                if profileHook.PeerStates[player.UserId] ~= state or profileHook.PeerApplying[player] then return end
                profileHook.PeerApplying[player] = true
                for attr, value in pairs(applied) do
                    if player:GetAttribute(attr) ~= value then
                        pcall(function() player:SetAttribute(attr, value) end)
                    end
                end
                profileHook.PeerApplying[player] = nil
            end
            applyPeerAttributes()
            local connections = {}
            profileHook.PeerConnections[player] = connections
            for attr in pairs(applied) do
                connections[#connections + 1] = player:GetAttributeChangedSignal(attr):Connect(function()
                    if profileHook.PeerApplying[player] then return end
                    task.defer(applyPeerAttributes)
                end)
            end
        end,
        Remove = restorePeerStats,
    }
    local statOriginalData = setmetatable({}, {__mode="k"})
    local statProfilePage
    local function invalidateStatsProfile(resolve)
        pcall(function()
            if not statProfilePage and resolve then
                local controller = requireProfileModule(LocalPlayer.PlayerScripts.Controllers.UserInterfaceController)
                statProfilePage = controller:GetPage("ViewProfile")
            end
            if statProfilePage and statProfilePage._last_player_object == LocalPlayer then
                statProfilePage._last_player_object = nil
            end
        end)
    end
    local function restoreStatAttribute(attr)
        local saved = Config.__ProfileStatsOriginalAttrs[attr]
        if saved == nil then return end
        Config.__ProfileStatsOriginalAttrs[attr] = nil
        if type(saved) ~= "table" then
            pcall(LocalPlayer.SetAttribute, LocalPlayer, attr, saved)
        elseif LocalPlayer:GetAttribute(attr) == saved.Applied then
            pcall(LocalPlayer.SetAttribute, LocalPlayer, attr, saved.Value)
        end
    end
    local function restoreStatData(attr)
        for data, fields in pairs(statOriginalData) do
            local saved = fields[attr]
            if saved then
                fields[attr] = nil
                if data[attr] == saved.Applied then data[attr] = saved.Value end
            end
        end
    end
    restoreStats = function()
        for attr in pairs(Config.__ProfileStatsOriginalAttrs) do restoreStatAttribute(attr) end
        for _, attrs in pairs(statAttrs) do
            for _, attr in ipairs(attrs) do
                restoreStatData(attr)
                replicate(attr)
            end
        end
        invalidateStatsProfile(false)
    end
    applyStats = function()
        if not Config.__ProfileStatsSpoof or statsApplying then return end
        statsApplying = true
        local ok, err = pcall(function()
            profileHook.Enabled = true
            local data = currentTable()
            for key, attrs in pairs(statAttrs) do
                local enabled = statEnabled[key] == true
                for _, attr in ipairs(attrs) do
                    if enabled then
                        local value = statValues[key]
                        if key == "WinRate" and attr:match("WinPercent$") then
                            value = (tonumber(value) or 0) / 100
                        end
                        local current = LocalPlayer:GetAttribute(attr)
                        local saved = Config.__ProfileStatsOriginalAttrs[attr]
                        if type(saved) ~= "table" then
                            saved = {Value=current}
                            Config.__ProfileStatsOriginalAttrs[attr] = saved
                        elseif current ~= saved.Applied then
                            saved.Value = current
                        end
                        saved.Applied = value
                        if current ~= value then LocalPlayer:SetAttribute(attr, value) end
                        if type(data) == "table" then
                            local fields = statOriginalData[data]
                            if not fields then fields={};statOriginalData[data]=fields end
                            local original = fields[attr]
                            if not original then original={Value=data[attr]};fields[attr]=original
                            elseif data[attr] ~= original.Applied then original.Value=data[attr] end
                            original.Applied = value
                            data[attr] = value
                        end
                    else
                        restoreStatAttribute(attr)
                        restoreStatData(attr)
                    end
                end
            end
            if statEnabled.Level then
                local root=LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                local gui=root and root:FindFirstChild("NametagGui")
                local level=gui and gui:FindFirstChild("Level",true)
                local title=level and level:FindFirstChild("Title")
                if title then title.Text=tostring(math.floor(tonumber(statValues.Level) or 100)) end
            end
            for key, enabled in pairs(statEnabled) do
                if enabled then
                    replicate(key)
                    for _, attr in ipairs(statAttrs[key] or {}) do replicate(attr) end
                end
            end
            invalidateStatsProfile(true)
        end)
        statsApplying = false
        if not ok then warn("[Spoofer] Profile Stats Spoofer: "..tostring(err)) end
    end
    local function addStatToggle(label,key)
        stats:AddToggle({Name="spoof "..label,Default=false,Function=function(v) statEnabled[key]=v==true;applyStats() end})
    end
    stats:AddLabel({Text="Reopen your profile after changing stats to refresh the card."})
    addStatToggle("level","Level")
    stats:AddSlider({Name="level",Min=1,Max=1000,Default=100,Function=function(v)statValues.Level=v;applyStats()end})
    addStatToggle("ranked ELO","RankedCurrentELO")
    stats:AddInputBox({Name="ELO amount",Default="2400",Function=function(v)
        statValues.RankedCurrentELO=math.max(0,math.floor(tonumber(v) or statValues.RankedCurrentELO or 2400))
        applyStats()
    end})
    addStatToggle("casual wins","CasualWins")
    stats:AddSlider({Name="casual wins",Min=0,Max=10000,Default=500,Function=function(v)statValues.CasualWins=v;applyStats()end})
    addStatToggle("ranked wins","RankedWins")
    stats:AddSlider({Name="ranked wins",Min=0,Max=10000,Default=250,Function=function(v)statValues.RankedWins=v;applyStats()end})
    addStatToggle("win rate","WinRate")
    stats:AddSlider({Name="win rate %",Min=0,Max=100,Default=75,Function=function(v)statValues.WinRate=v;applyStats()end})
    addStatToggle("win streak","WinStreak")
    stats:AddSlider({Name="win streak",Min=0,Max=1000,Default=25,Function=function(v)statValues.WinStreak=v;applyStats()end})
    addStatToggle("favorite map","FavoriteMap")
    local mapNames={}
    local okMaps, mapLibrary=pcall(function() return requireProfileModule(ReplicatedStorage.Modules.StatisticsLibrary) end)
    if okMaps then for name in pairs(mapLibrary.Maps or {}) do mapNames[#mapNames+1]=name end end
    table.sort(mapNames)
    stats:AddDropdown({Name="favorite map",List=mapNames,Default="Arena",Function=function(v)statValues.FavoriteMap=v;applyStats()end})
    addStatToggle("favorite loadout","FavoriteWeapons")
    local weaponNames={}
    local okItems,itemLibrary=pcall(function() return requireProfileModule(ReplicatedStorage.Modules.ItemLibrary) end)
    if okItems then for name in pairs(itemLibrary.Items or {}) do weaponNames[#weaponNames+1]=name end end
    table.sort(weaponNames)
    for slot,spec in ipairs({{"primary","Assault Rifle"},{"secondary","Handgun"},{"melee","Fists"},{"utility","Grenade"}}) do
        statValues.FavoriteWeapons[slot]=spec[2]
        stats:AddDropdown({Name="favorite "..spec[1],List=weaponNames,Default=spec[2],Function=function(value)
            statValues.FavoriteWeapons[slot]=value
        end})
    end
    -- Rivals refreshes these attributes after profile replication. Reapply only
    -- the affected spoof when that happens instead of waiting for the fallback
    -- timer, preventing the real value from flashing for a frame.
    local statsGuardQueued=false
    for _,attrs in pairs(statAttrs) do
        for _,attr in ipairs(attrs) do
            mainapi:Clean(LocalPlayer:GetAttributeChangedSignal(attr):Connect(function()
                if not Config.__ProfileStatsSpoof or statsApplying or statsGuardQueued then return end
                statsGuardQueued=true
                task.defer(function()
                    statsGuardQueued=false
                    if Config.__ProfileStatsSpoof then applyStats() end
                end)
            end))
        end
    end
    mainapi:Clean(function()
        Config.__ProfileStatsSpoof=false
        restoreStats()
        profileHook.Enabled=false
        profileHook.Transform=nil
        profileHook.ViewProfileInstallGeneration=(profileHook.ViewProfileInstallGeneration or 0)+1
        local patch=profileHook.ViewProfilePatch
        if patch then
            pcall(debug.setupvalue,patch.Function,patch.Index,patch.Original)
            profileHook.ViewProfilePatch=nil
        end
        for _, player in ipairs(Players:GetPlayers()) do restorePeerStats(player) end
        shared.PlexProfilePeerSync=nil
    end)

