    local currencyState = {}
    local currency = Other:AddModule({
        Name = "Resources Spoofer",
        Function = function(enabled)
            Config.__CurrencySpoof = enabled == true
            local data=currentTable()
            if not enabled then
                for key,saved in pairs(Config.__CurrencyOriginals or {}) do
                    if data and data[key] == saved.applied then data[key]=saved.original end
                end
                Config.__CurrencyOriginals={}
            else
                task.defer(function()
                    if Config.__CurrencySpoof then
                        for key,state in pairs(currencyState or {}) do
                            if state.enabled then replicate(key) end
                        end
                    end
                end)
            end
            for _,key in ipairs({"WeaponKeys","UnlockTokens","EventCurrency","Glory","SkinTickets"}) do replicate(key) end
        end
    })
    Config.__CurrencyOriginals = Config.__CurrencyOriginals or {}
    local function applyCurrencies()
        if not Config.__CurrencySpoof then return end
        local data=currentTable()
        if type(data)~="table" then return end
        for key,state in pairs(currencyState) do
            local saved=Config.__CurrencyOriginals[key]
            if state.enabled then
                if not saved then saved={original=data[key]};Config.__CurrencyOriginals[key]=saved end
                data[key]=state.value
                saved.applied=state.value
            elseif saved then
                if data[key] == saved.applied then data[key]=saved.original end
                Config.__CurrencyOriginals[key]=nil
            end
        end
    end
    for _,spec in ipairs({{"keys","WeaponKeys"},{"tokens","UnlockTokens"},{"event currency","EventCurrency"},{"glory","Glory"},{"tickets","SkinTickets"}}) do
        local state={enabled=false,value=0};currencyState[spec[2]]=state
        currency:AddToggle({Name="override "..spec[1],Default=false,Function=function(v)state.enabled=v==true;applyCurrencies();replicate(spec[2])end})
        currency:AddSlider({Name=spec[1],Min=0,Max=10000000,Default=0,Function=function(v)state.value=v;applyCurrencies();replicate(spec[2])end})
    end
    local currencyGuardQueued=false
    local currencyGuardController=resolvePdc()
    if currencyGuardController and type(currencyGuardController.GetDataChangedSignal)=="function" then
        for key in pairs(currencyState) do
            local ok,signal=pcall(currencyGuardController.GetDataChangedSignal,currencyGuardController,key)
            if ok and signal and type(signal.Connect)=="function" then
                mainapi:Clean(signal:Connect(function()
                    if not Config.__CurrencySpoof or currencyGuardQueued then return end
                    currencyGuardQueued=true
                    task.defer(function()
                        currencyGuardQueued=false
                        if Config.__CurrencySpoof then applyCurrencies() end
                    end)
                end))
            end
        end
    end
    mainapi:CreateIdleWorker("Currency", {Interval=0.25, IsActive=function() return Config.__CurrencySpoof == true end, Update=function()
        if Config.__CurrencySpoof then
            local now=tick()
            Config.__CurrencyAt=Config.__CurrencyAt or 0
            if now-Config.__CurrencyAt>1 then
                Config.__CurrencyAt=now
                applyCurrencies()
            end
        end
    end})

