local selfDataPreview=(function()
    local state={Enabled=false,Fields={},Overrides={},Hooks={},ProfilePaths={},ProfileValues={}}
    local controller
    local function scalar(value)
        local kind=type(value)
        return kind=="number" or kind=="string" or kind=="boolean"
    end
    local function data()
        controller=controller or resolvePdc()
        return controller and controller.CurrentData
    end
    local hook
    hook=function(owner)
        if not owner or type(owner.Get)~="function" or state.Hooks[owner] then return end
        local original=owner.Get
        local wrapper=function(self,key,...)
            if state.Enabled then
                if self==controller then hook(controller.CurrentData) end
                local entry=state.Overrides[key]
                if entry then return entry.Value end
            end
            return original(self,key,...)
        end
        state.Hooks[owner]={Original=original,RawOriginal=rawget(owner,"Get"),Wrapper=wrapper}
        rawset(owner,"Get",wrapper)
    end
    function state:RefreshFields()
        local current=data()
        local native=current and current.Data
        if type(native)~="table" then return nil,"Player data is not ready." end
        local fields,list={},{}
        for key,value in pairs(native) do
            if type(key)=="string" and scalar(value) then fields[key]=type(value);list[#list+1]=key end
        end
        table.sort(list);self.Fields=fields
        return list
    end
    function state:RefreshProfileFields()
        local ok,profile=pcall(function()
            return ReplicatedStorage.Remotes.Misc.RequestProfile:InvokeServer(LocalPlayer)
        end)
        if not ok or type(profile)~="table" then return nil,"The native profile request is unavailable." end
        local paths,values,list,seen={},{},{},{}
        local function visit(value,path,depth)
            if depth>6 or #list>=512 then return end
            if scalar(value) then
                local pieces={"profile"};for _,part in ipairs(path) do pieces[#pieces+1]=tostring(part) end
                local key=table.concat(pieces,".")
                paths[key]=table.clone(path);values[key]={Value=value,Kind=type(value)};list[#list+1]=key
            elseif type(value)=="table" and not seen[value] then
                seen[value]=true
                for key,item in pairs(value) do
                    if type(key)=="string" or type(key)=="number" then
                        path[#path+1]=key;visit(item,path,depth+1);path[#path]=nil
                    end
                end
            end
        end
        visit(profile,{},0);table.sort(list)
        self.ProfilePaths=paths;self.ProfileValues=values
        return list
    end
    function state:TransformProfile(result,target)
        if not self.Enabled or target and target~=LocalPlayer then return result end
        local out=result
        for key,entry in pairs(self.Overrides) do
            local path=self.ProfilePaths[key]
            if path then
                local native=result
                for _,part in ipairs(path) do
                    if type(native)~="table" then native=nil;break end
                    native=native[part]
                end
                if type(native)==type(entry.Value) then
                    if out==result then out=table.clone(result) end
                    local branch=out
                    for index=1,#path-1 do
                        local part=path[index];branch[part]=table.clone(branch[part]);branch=branch[part]
                    end
                    branch[path[#path]]=entry.Value
                end
            end
        end
        return out
    end
    local profileTransform=function(result,target)return state:TransformProfile(result,target)end
    if profileHook then profileHook.AdvancedTransform=profileTransform end
    function state:Read(key)
        if self.ProfilePaths[key] then return self.ProfileValues[key] end
        local current=data()
        local native=current and current.Data
        if type(native)~="table" then return nil,"Player data is not ready." end
        local value=rawget(native,key)
        if not self.Fields[key] or not scalar(value) then return nil,"Refresh fields and select a supported field." end
        return {Value=value,Kind=type(value)}
    end
    function state:RefreshKey(key)
        if self.ProfilePaths[key] then return end
        local current=data()
        if current and type(current.Replicate)=="function" then pcall(current.Replicate,current,key) end
    end
    function state:SetEnabled(enabled)
        if not enabled then
            self.Enabled=false
            if profileHook then profileHook.SelfDataEnabled=false end
            for owner,entry in pairs(self.Hooks) do
                if rawget(owner,"Get")==entry.Wrapper then rawset(owner,"Get",entry.RawOriginal) end
            end
            table.clear(self.Hooks)
            for key in pairs(self.Overrides) do self:RefreshKey(key) end
            return true
        end
        local current=data()
        if not controller or type(controller.Get)~="function" or not current then return false,"Player data is not ready." end
        self.Enabled=true;hook(controller);hook(current)
        if profileHook then
            for key in pairs(self.Overrides) do
                if self.ProfilePaths[key] then
                    profileHook.SelfDataEnabled=true
                    if profileHook.Install then pcall(profileHook.Install) end
                    break
                end
            end
        end
        for key in pairs(self.Overrides) do self:RefreshKey(key) end
        return true
    end
    function state:Apply(key,text)
        if not self.Enabled then return false,"Enable Advanced Self Data first." end
        local native,err=self:Read(key)
        if not native then return false,err end
        local value
        if native.Kind=="number" then
            value=tonumber(text)
            if not value or value~=value or math.abs(value)==math.huge then return false,"Enter a finite number." end
        elseif native.Kind=="boolean" then
            local normalized=tostring(text):lower():match("^%s*(.-)%s*$")
            if normalized~="true" and normalized~="false" then return false,"Enter true or false." end
            value=normalized=="true"
        else value=tostring(text or "") end
        self.Overrides[key]={Value=value}
        if self.ProfilePaths[key] and profileHook then
            profileHook.SelfDataEnabled=true
            if profileHook.Install then pcall(profileHook.Install) end
        end
        hook(controller.CurrentData);self:RefreshKey(key)
        return true
    end
    function state:UpdateProfileEnabled()
        if not profileHook then return end
        local enabled=false
        if self.Enabled then
            for key in pairs(self.Overrides) do
                if self.ProfilePaths[key] then enabled=true;break end
            end
        end
        profileHook.SelfDataEnabled=enabled
    end
    function state:Clear(key)
        self.Overrides[key]=nil
        self:UpdateProfileEnabled()
        if self.Enabled then self:RefreshKey(key) end
    end
    function state:ClearAll()
        local keys={};for key in pairs(self.Overrides) do keys[#keys+1]=key end
        table.clear(self.Overrides)
        self:UpdateProfileEnabled()
        if self.Enabled then for _,key in ipairs(keys) do self:RefreshKey(key) end end
    end
    mainapi:Clean(function()
        state:SetEnabled(false);table.clear(state.Overrides)
        if profileHook and profileHook.AdvancedTransform==profileTransform then profileHook.AdvancedTransform=nil end
    end)
    return state
end)()

