        local ok,err=selfDataPreview:Apply(selected,value)
        mainapi:Notify({Text=ok and "Local override applied." or tostring(err),Duration=4})
    end})
    selfData:AddButton({Name="restore selected field",Function=function()selfDataPreview:Clear(selected)end})
    selfData:AddButton({Name="restore all fields",Function=function()selfDataPreview:ClearAll()end})

