-- Only display state is changed; native purchase and receipt paths remain intact.
local marketplacePreview=(function()
    local state={RobuxEnabled=false,GiftEnabled=false,Spent=0,Claimed=0,Labels={},DataHooks={},Alive=true}
    local robuxMetadata=table.freeze({balance=1000,currency="Robux",source="local",revision=0})
    function state:GetRobuxMetadata()
        return robuxMetadata
    end
    local function finite(value)
        local number=tonumber(value)
        return number and number==number and math.abs(number)<math.huge and math.clamp(math.floor(number),0,1000000000) or 0
    end
    local function restoreLabel(label)
        local record=state.Labels[label]
        if not record then return end
        state.Labels[label]=nil
        for _,connection in ipairs(record.Connections) do connection:Disconnect() end
        if record.Button then record.Button:Destroy() end
        if record.SuccessLabel then record.SuccessLabel:Destroy() end
        for _,change in ipairs(record.Changes or {}) do
            if change.Object.Parent and change.Object[change.Key]==change.Applied then
                change.Object[change.Key]=change.Original
            end
        end
        if label.Parent and label.Text==record.Applied then label.Text=record.Original end
    end
    local function applyLabel(label)
        local record=state.Labels[label]
        if not record or not state.RobuxEnabled or not label.Parent then return end
        local digits=tostring(state:GetRobuxMetadata().balance):reverse():gsub("(%d%d%d)","%1,"):reverse():gsub("^,","")
        local prefix=record.Original:match("^(.-)%d[%d,]*%s*$")
        record.Applied=(prefix or (utf8.char(0xE002).." "))..digits

        if label.Text~=record.Applied then label.Text=record.Applied end
    end
    function state:PreviewPurchase(cost)
        cost=finite(cost)
        if not self.RobuxEnabled then return false,"Enable Robux Spoofer first." end
        if cost<=0 then return false,"No valid item price is available." end
        local metadata=self:GetRobuxMetadata()
        if cost>metadata.balance then return false,"Insufficient local preview balance." end
        self:SetRobux(metadata.balance-cost)
        return true,"Local purchase preview complete. No payment or server item was created."
    end
    local function mountPreview(label,record)
        local sheet=label:FindFirstAncestor("Sheet")
        local content=sheet and sheet:FindFirstChild("Content")
        if not content or not content:IsA("GuiObject") then return end
        record.Changes={}
        local function change(object,key,value)
            for _,entry in ipairs(record.Changes) do
                if entry.Object==object and entry.Key==key then
                    entry.Applied=value;object[key]=value;return
                end
            end
            record.Changes[#record.Changes+1]={Object=object,Key=key,Original=object[key],Applied=value}
            object[key]=value
        end
        local function tryMount()
            if record.Button or not state.RobuxEnabled or not label.Parent then return end
            local buy,price,status,title,upsell,itemName
            for _,object in ipairs(content:GetDescendants()) do
                if object:IsA("TextLabel") then
                    if object.Name=="ItemName" then itemName=object end
                    if object.Name=="ItemCost" then
                        local clean=object.Text:gsub("<[^>]+>","")
                        price=finite((clean:match("[%d,]+") or ""):gsub(",",""))
                    elseif object.Name=="DisclosurePayment" then status=object
                    elseif object.Name=="RobuxAmount" and object.Parent and object.Parent.Parent==label.Parent.Parent then title=object
                    end
                    if object.Text=="Buy" then
                        local ancestor=object.Parent
                        while ancestor and ancestor~=content do
                            if ancestor:IsA("GuiButton") then buy=ancestor;break end
                            ancestor=ancestor.Parent
                        end
                    end
                elseif object.Name=="UpsellSuggestions" and object:IsA("GuiObject") then upsell=object end
            end
            if not buy or not price or price<=0 then return end
            -- Cloning copies native visuals but none of its purchase event connections.
            local ok,button=pcall(buy.Clone,buy)
            if not ok or not button then return end
            button.Name="PlexLocalBuy";record.Button=button
            for _,object in ipairs(button:GetDescendants()) do
                if object:IsA("LuaSourceContainer") then object:Destroy() end
            end
            local function buttonText(value)
                if button:IsA("TextButton") then button.Text=value end
                for _,object in ipairs(button:GetDescendants()) do
                    if object:IsA("TextLabel") then object.Text=value end
                end
            end
            buttonText("Buy")
            button.Visible=true;button.Active=true;button.Interactable=true
            button.Parent=buy.Parent
            change(buy,"Visible",false)
            if upsell then
                for _,object in ipairs(upsell:GetDescendants()) do
                    if object:IsA("GuiButton") then change(object,"Interactable",false) end
                end
            end
            record.Connections[#record.Connections+1]=buy:GetPropertyChangedSignal("Visible"):Connect(function()
                if state.RobuxEnabled and buy.Visible then buy.Visible=false end
            end)
            local purchased=false
            record.Connections[#record.Connections+1]=button.Activated:Connect(function()
                if purchased then
                    change(sheet,"Visible",false)
                    return
                end
                local success,message=state:PreviewPurchase(price)
                if success then
                    purchased=true
                    buttonText("OK")
                    if title then change(title,"Text","Purchase complete") end
                    if upsell and itemName then
                        local summary=itemName:Clone()
                        summary.Name="PlexLocalSuccess"
                        summary.AutomaticSize=Enum.AutomaticSize.None
                        summary.Position=upsell.Position;summary.Size=upsell.Size
                        summary.AnchorPoint=upsell.AnchorPoint;summary.LayoutOrder=upsell.LayoutOrder
                        summary.Text="Local preview: "..itemName.Text.." purchase complete."
                        summary.TextWrapped=true;summary.TextScaled=true
                        record.SuccessLabel=summary
                        change(upsell,"Visible",false)
                        summary.Parent=upsell.Parent
                    end
                    message="Local preview complete. No charge or server item."
                end
                if status then change(status,"Text",message) end
            end)
        end
        local queued=false
        record.Connections[#record.Connections+1]=content.DescendantAdded:Connect(function()
            if queued or record.Button then return end
            queued=true
            task.defer(function()queued=false;tryMount()end)
        end)
        tryMount()
    end
    local function observeLabel(label)
        if not state.RobuxEnabled or state.Labels[label] or not label:IsA("TextLabel") or label.Name~="RobuxPrice" then return end
        local parent=label.Parent
        local header=parent and parent.Parent
        if not header or header.Name~="ModalHeader" then return end
        local record={Original=label.Text,Connections={}}
        state.Labels[label]=record
        record.Connections[#record.Connections+1]=label:GetPropertyChangedSignal("Text"):Connect(function()
            if label.Text~=record.Applied then record.Original=label.Text;applyLabel(label) end
        end)
        record.Connections[#record.Connections+1]=label.Destroying:Connect(function()restoreLabel(label)end)
        if label.FindFirstAncestor then mountPreview(label,record) end
        applyLabel(label)
    end
    function state:SetRobux(value)
        local balance=finite(value)
        if robuxMetadata.balance~=balance then
            robuxMetadata=table.freeze({balance=balance,currency="Robux",source="local",revision=robuxMetadata.revision+1})
        end
        for label in pairs(self.Labels) do applyLabel(label) end
    end
    function state:SetRobuxEnabled(enabled)
        self.RobuxEnabled=enabled==true
        if self.RobuxConnection then self.RobuxConnection:Disconnect();self.RobuxConnection=nil end
        if not self.RobuxEnabled then
            local labels={};for label in pairs(self.Labels) do labels[#labels+1]=label end
            for _,label in ipairs(labels) do restoreLabel(label) end
            return
        end
        self.RobuxConnection=CoreGui.DescendantAdded:Connect(observeLabel)
        for _,label in ipairs(CoreGui:GetDescendants()) do observeLabel(label) end
    end
    local function displayValue(key)
        if not state.GiftEnabled then return false end
        if key=="GiftRobuxSpentProgress" then return true,state.Spent end
        if key=="GiftRobuxSpentRewardsClaimed" then return true,state.Claimed end
        return false
    end
    local function hookData(owner)
        if not owner or type(owner.Get)~="function" or state.DataHooks[owner] then return end
        local original=owner.Get
        local wrapper=function(self,key,...)
            local matched,value=displayValue(key)
            if matched then return value end
            return original(self,key,...)
        end
        state.DataHooks[owner]={Original=original,RawOriginal=rawget(owner,"Get"),Wrapper=wrapper}
        rawset(owner,"Get",wrapper)
    end
    function state:RefreshGiftDisplay()
        if not self.GiftEnabled then return end
        local controller=self.Controller
        local current=controller and controller.CurrentData
        hookData(current)
        if current and type(current.Replicate)=="function" then
            for _,key in ipairs({"GiftRobuxSpentProgress","GiftRobuxSpentRewardsClaimed"}) do pcall(current.Replicate,current,key) end
        end
    end
    function state:SetGiftValues(spent,claimed)
        if spent~=nil then self.Spent=finite(spent) end
        if claimed~=nil then self.Claimed=finite(claimed) end
        self:RefreshGiftDisplay()
    end
    function state:SetGiftEnabled(enabled)
        self.GiftEnabled=false
        for owner,record in pairs(self.DataHooks) do
            if rawget(owner,"Get")==record.Wrapper then rawset(owner,"Get",record.RawOriginal) end
        end
        table.clear(self.DataHooks)
        if not enabled then
            local current=self.Controller and self.Controller.CurrentData
            if current and type(current.Replicate)=="function" then
                for _,key in ipairs({"GiftRobuxSpentProgress","GiftRobuxSpentRewardsClaimed"}) do pcall(current.Replicate,current,key) end
            end
            self.Controller=nil
            return true
        end
        local controller=resolvePdc()
        if not controller or type(controller.Get)~="function" then return false,"Player data is not ready; join a fully loaded Rivals lobby." end
        self.Controller=controller;self.GiftEnabled=true
        local original=controller.Get
        local wrapper=function(owner,key,...)
            hookData(owner.CurrentData)
            local matched,value=displayValue(key)
            if matched then return value end
            return original(owner,key,...)
        end
        self.DataHooks[controller]={Original=original,RawOriginal=rawget(controller,"Get"),Wrapper=wrapper};rawset(controller,"Get",wrapper)
        self:RefreshGiftDisplay()
        return true
    end
    function state:Destroy()
        if not self.Alive then return end
        self.Alive=false;self:SetRobuxEnabled(false);self:SetGiftEnabled(false)
    end
    mainapi:Clean(function()state:Destroy()end)
    return state
end)()

