    local installHistoryReader
    local history = Other:AddModule({
        Name = "Duel History Spoofer",
        Function = function(enabled)
            Config.__HistorySpoof = enabled == true
            if enabled and installHistoryReader then installHistoryReader() end
            replicate("DuelHistory");replicate("LoggedELOEvents")
        end
    })
    local hist={match=1,dueler=1,mode="Ranked",result="Victory",map="Factory",s1=5,s2=0,kills=15,deaths=2,assists=6,damage=5000,elo=2000,delta=35,user="",display=""}
    local historyOriginalGet
    local historyController
    local historyWrapper
    local addedHistory={}
    local function cloneHistory(value,seen)
        if type(value)~="table" then return value end
        seen=seen or {}
        if seen[value] then return seen[value] end
        local copy={};seen[value]=copy
        for key,item in pairs(value) do copy[key]=cloneHistory(item,seen) end
        return copy
    end
    local function applyHistoryEntry(entry)
        entry.QueueName=hist.mode;entry.Map=hist.map;entry.Scores={hist.s1,hist.s2}
        entry.WinningTeamIndex=hist.result=="Victory" and 1 or 2
        local dueler=entry.Duelers and entry.Duelers[math.max(1,math.floor(hist.dueler))]
        if type(dueler)=="table" then
            if hist.user~="" then dueler.Username=hist.user end
            if hist.display~="" then dueler.DisplayName=hist.display end
            dueler.Eliminations=hist.kills;dueler.Deaths=hist.deaths;dueler.Assists=hist.assists;dueler.Damage=hist.damage
            if hist.mode=="Ranked" then dueler.DisplayELO=hist.elo end
        end
    end
    installHistoryReader=function()
        local controller=resolvePdc()
        if not controller or type(controller.Get)~="function" or historyOriginalGet then return end
        historyController=controller
        historyOriginalGet=controller.Get
        historyWrapper=function(self,key,...)
            local value=historyOriginalGet(self,key,...)
            if not Config.__HistorySpoof or (key~="DuelHistory" and key~="LoggedELOEvents") or type(value)~="table" then return value end
            local copy=cloneHistory(value)
            local entry=copy[math.max(1,math.floor(hist.match))]
            if type(entry)=="table" then
                if key=="LoggedELOEvents" then entry.CurrentELO=hist.elo;entry.ELOIncrement=hist.delta
                else applyHistoryEntry(entry) end
            end
            if key=="DuelHistory" then
                for index=#addedHistory,1,-1 do table.insert(copy,1,cloneHistory(addedHistory[index])) end
            end
            return copy
        end
        controller.Get=historyWrapper
    end
    history:AddButton({Name="add to duel history",Function=function()
        installHistoryReader()
        if not historyOriginalGet then mainapi:Notify({Text="Player data is not ready.",Duration=4});return end
        local ok,native=pcall(historyOriginalGet,historyController,"DuelHistory")
        local template=ok and type(native)=="table" and native[math.max(1,math.floor(hist.match))]
        if type(template)~="table" then
            mainapi:Notify({Text="A loaded duel record is required as the local template.",Duration=4});return
        end
        local entry=cloneHistory(template);applyHistoryEntry(entry)
        table.insert(addedHistory,1,entry)
        if not history.Enabled then history:Toggle(true) end
        replicate("DuelHistory")
        mainapi:Notify({Text="Added a local duel-history preview. Server records are unchanged.",Duration=4})
    end})
    history:AddButton({Name="open duel history",Function=function()
        local ok,err=pcall(function()
