    history:AddDropdown({Name="result",List={"Victory","Defeat"},Default="Victory",Function=function(v)hist.result=v end})
    history:AddInputBox({Name="map",Default="Factory",Function=function(v)hist.map=tostring(v or "Factory")end})
    history:AddInputBox({Name="username",Default="",Function=function(v)hist.user=tostring(v or "")end})
    history:AddInputBox({Name="display name",Default="",Function=function(v)hist.display=tostring(v or "")end})
    for _,spec in ipairs({{"match index","match",1,50},{"dueler index","dueler",1,10},{"team 1 score","s1",0,20},{"team 2 score","s2",0,20},{"kills","kills",0,100},{"deaths","deaths",0,100},{"assists","assists",0,100},{"damage","damage",0,50000},{"ELO","elo",0,10000},{"ELO change","delta",-1000,1000}})do
        history:AddSlider({Name=spec[1],Min=spec[3],Max=spec[4],Default=hist[spec[2]],Function=function(v)hist[spec[2]]=v end})
    end
    mainapi:Clean(function()
        if historyOriginalGet and historyController and historyController.Get==historyWrapper then
            historyController.Get=historyOriginalGet
        end
        table.clear(addedHistory)
    end)

    local badgeOriginal={
        DisableTeamVisuals=LocalPlayer:GetAttribute("DisableTeamVisuals"),
        IsAdministrator=LocalPlayer:GetAttribute("IsAdministrator"),
    }
    local badgeState={}
    local badgeSpecs={{"premium","IsPremium"},{"verified","HasVerifiedBadge"},{"influencer","IsInfluencer"},{"admin","IsRobloxEmployee"}}
    for _,spec in ipairs(badgeSpecs) do
        badgeOriginal[spec[2]]=LocalPlayer:GetAttribute(spec[2])
        badgeState[spec[2]]=false
    end
    local badgePropertyHook=getgenv().__PlexBadgePropertyHook or {States=setmetatable({}, {__mode="k"})}
    getgenv().__PlexBadgePropertyHook=badgePropertyHook
    local function ensureBadgeIndexHook()
        if badgePropertyHook.Installed then return end
        badgePropertyHook.Installed=true
        local originalIndex
        local ok=pcall(function()
            originalIndex=hookmetamethod(game,"__index",newcclosure(function(object,key)
                if key=="HasVerifiedBadge" or key=="MembershipType" then
                    local state=badgePropertyHook.States[object]
                    if state then
                        if key=="HasVerifiedBadge" and state.v~=nil then return state.v==true end
                        if key=="MembershipType" and state.p~=nil then
                            return state.p and Enum.MembershipType.Premium or Enum.MembershipType.None
                        end
                    end
                end
                return originalIndex(object,key)
            end))
        end)
        badgePropertyHook.Available=ok
    end
    badgePropertyHook.States=badgePropertyHook.States or setmetatable({}, {__mode="k"})

    local function compactBadgeState()
        return {
            p=badgeState.IsPremium==true,
            v=badgeState.HasVerifiedBadge==true,
            i=badgeState.IsInfluencer==true,
            a=badgeState.IsRobloxEmployee==true,
        }
    end
    local function applyBadges()
        for _,spec in ipairs(badgeSpecs) do
            local attr=spec[2]
            local value=Config.__BadgeSpoof and badgeState[attr] == true and true or badgeOriginal[attr]
            pcall(function() LocalPlayer:SetAttribute(attr,value) end)
            replicate(attr)
        end
        if Config.__BadgeSpoof then
            -- PlayerListSlot only displays local badge icons through this path.
            LocalPlayer:SetAttribute("DisableTeamVisuals", true)
            LocalPlayer:SetAttribute("IsAdministrator", false)
            local compact=compactBadgeState()
            ensureBadgeIndexHook()
            badgePropertyHook.States[LocalPlayer]=compact
            if profileHook then
                profileHook.BadgesEnabled=true
                profileHook.BadgeState=compact
            end
        else
            LocalPlayer:SetAttribute("DisableTeamVisuals", badgeOriginal.DisableTeamVisuals)
            LocalPlayer:SetAttribute("IsAdministrator", badgeOriginal.IsAdministrator)
            badgePropertyHook.States[LocalPlayer]=nil
            if profileHook then
                profileHook.BadgesEnabled=false
                profileHook.BadgeState=nil
            end
        end
    end

