    -- Battle/Season Pass spoofer.
    -- The pass page does not read a single "SeasonPassTier" attribute. It reads
    -- PlayerDataController values (and, depending on the page revision, nested
    -- season/pass tables). Hook those reads and only rewrite pass-related fields.
    local passTierValue="Prime"
    local passHooks={}
    local passDataOwner=nil
    local passOriginalValues={}
    local passAppliedValues={}
    local passSeasonLibrary=nil
    local function passTrackNumber()
        return passTierValue=="Contraband" and 3 or 2
    end
    -- Native CustomNametag listens to PlayerStatus and passes it to
    -- ApplyItemStatusToText. Own that input, not an additional GUI label.
    local passNametagState={Captured=false,Writing=false,Connection=nil}
    local function refreshPassNametag()
        local state=passNametagState
        if Config.__SeasonPassTierSpoof==true then
            if not state.Captured then
                state.Original=LocalPlayer:GetAttribute("PlayerStatus")
                state.Captured=true
                state.Connection=LocalPlayer:GetAttributeChangedSignal("PlayerStatus"):Connect(function()
                    if state.Writing or Config.__SeasonPassTierSpoof~=true then return end
                    local value=LocalPlayer:GetAttribute("PlayerStatus")
                    if value==state.Applied then return end
                    -- Preserve newer game-owned values for restoration.
                    state.Original=value
                    refreshPassNametag()
                end)
            end
            state.Applied=passTierValue
            if LocalPlayer:GetAttribute("PlayerStatus")~=state.Applied then
                state.Writing=true
                LocalPlayer:SetAttribute("PlayerStatus",state.Applied)
                state.Writing=false
            end
        else
            if state.Connection then state.Connection:Disconnect(); state.Connection=nil end
            if state.Captured and LocalPlayer:GetAttribute("PlayerStatus")==state.Applied then
                LocalPlayer:SetAttribute("PlayerStatus",state.Original)
            end
            state.Captured=false
            state.Original=nil
            state.Applied=nil
        end
    end
    local passTierKnownKeys={
        "Seasons","SeasonPass","SeasonPassData","SeasonPassProgress","SeasonPassInfo",
        "BattlePass","BattlePassData","BattlePassProgress","BattlePassInfo",
        "CurrentSeason","SeasonData","SeasonInfo",
        "SeasonPassTier","SeasonPassType","SeasonPassStatus",
        "BattlePassTier","BattlePassType","BattlePassStatus","PassTier",
        "PrimePass","HasPrimePass","OwnsPrimePass","PrimePassOwned",
        "ContrabandPass","HasContrabandPass","OwnsContrabandPass","ContrabandPassOwned",
    }

    local function passSelected(name)
        name=tostring(name or ""):lower()
        if name:find("contraband",1,true) then return passTierValue=="Contraband" end
        if name:find("prime",1,true) then return passTierValue=="Prime" or passTierValue=="Contraband" end
        return nil
    end

    local function passContextName(name)
        name=tostring(name or ""):lower()
        return name:find("pass",1,true)~=nil
            or name:find("season",1,true)~=nil
            or name:find("battle",1,true)~=nil
    end

    local function spoofPassRead(key,value)
        if Config.__SeasonPassTierSpoof~=true then return value end
        local keyName=tostring(key or "")
        local lower=keyName:lower()
        local context=passContextName(keyName)
        -- Ordinary weapon/inventory reads must never walk or clone their tables.
        if type(value)=="table" and not context then return value end
        if lower=="seasons" and type(value)=="table" then
            if not passSeasonLibrary then
                passSeasonLibrary=require(ReplicatedStorage.Modules.SeasonLibrary)
            end
            local seasonName=passSeasonLibrary.CurrentSeason and passSeasonLibrary.CurrentSeason.Name
            local season=seasonName and value[seasonName]
            local battlePass=type(season)=="table" and season.BattlePass
            if type(battlePass)=="table" and battlePass.MaxPassTrackNum~=passTrackNumber() then
                local copy=table.clone(value)
                local seasonCopy=table.clone(season)
                local battleCopy=table.clone(battlePass)
                battleCopy.MaxPassTrackNum=passTrackNumber()
                seasonCopy.BattlePass=battleCopy
                copy[seasonName]=seasonCopy
                return copy
            end
            return value
        end
        if lower=="maxpasstracknum" and type(value)=="number" then return passTrackNumber() end

        local selected=passSelected(keyName)
        if selected~=nil then
            if type(value)=="boolean" then return selected end
            if type(value)=="number" then return selected and 1 or 0 end
            if type(value)=="string" then return selected and passTierValue or value end
        end

        if context and type(value)=="string" then
            local lv=value:lower()
            if lv=="free" or lv=="standard" or lv=="prime" or lv=="contraband" then
                return passTierValue
            end
        end

        return value
    end

    local function releasePassReadHook(slot)
        local hook=passHooks[slot]
        if not hook then return end
        if hook.Owner.Get==hook.Wrapper then
            hook.Owner.Get=hook.Original
        end
        passHooks[slot]=nil
    end

    local function installPassReadHooks()
        local controller=resolvePdc()
        if not controller then return end
        local current=controller.CurrentData
        for slot,owner in pairs({Controller=controller,Current=current}) do
            local hook=passHooks[slot]
            if hook and hook.Owner~=owner then
                releasePassReadHook(slot)
                hook=nil
            end
            if not hook and owner and type(owner.Get)=="function" then
                -- Capture the original per owner; an older wrapper must never
                -- start calling a replacement data object's getter.
                local original=owner.Get
                local wrapper=function(self,key,...)
                    return spoofPassRead(key,original(self,key,...))
                end
                passHooks[slot]={Owner=owner,Original=original,Wrapper=wrapper}
                owner.Get=wrapper
            end
        end
    end

    local function applyPassExistingData()
        if Config.__SeasonPassTierSpoof~=true then return end
        installPassReadHooks()
        refreshPassNametag()
        local data=currentTable()
        local changedKeys={}
        if passDataOwner~=data then
            if passDataOwner then
                for key,original in pairs(passOriginalValues) do
                    if passDataOwner[key]==passAppliedValues[key] then
                        passDataOwner[key]=original
                    end
                end
            end
            table.clear(passOriginalValues)
            table.clear(passAppliedValues)
            passDataOwner=data
        end
        if type(data)=="table" then
            -- Update only pass/season fields that actually exist. This catches
            -- pages that read CurrentData.Data directly instead of PDC:Get().
            for _,key in ipairs(passTierKnownKeys) do
                local value=data[key]
                local spoofed=spoofPassRead(key,value)
                if spoofed~=value then
                    if passAppliedValues[key]==nil or value~=passAppliedValues[key] then
                        passOriginalValues[key]=value
                    end
                    local ok=pcall(function() data[key]=spoofed end)
                    if ok then
                        passAppliedValues[key]=spoofed
                        changedKeys[#changedKeys+1]=key
                    end
                end
            end
        end
        if #changedKeys==0 then return end
        for _,key in ipairs(changedKeys) do replicate(key) end
        pcall(function()
            local page=require(LocalPlayer.PlayerScripts.Modules.Pages.BattlePass)
            if page and page._is_open and type(page._Update)=="function" then page:_Update() end
        end)
    end

    local function restorePassExistingData()
        releasePassReadHook("Controller")
        releasePassReadHook("Current")
        refreshPassNametag()
        local data=passDataOwner
        local changedKeys={}
        if type(data)=="table" then
            for key,original in pairs(passOriginalValues) do
                if data[key]==passAppliedValues[key] then
                    if pcall(function() data[key]=original end) then
                        changedKeys[#changedKeys+1]=key
                    end
                end
            end
        end
        table.clear(passOriginalValues)
        table.clear(passAppliedValues)
        passDataOwner=nil
        if #changedKeys==0 then return end
        for _,key in ipairs(changedKeys) do replicate(key) end
        pcall(function()
            local page=require(LocalPlayer.PlayerScripts.Modules.Pages.BattlePass)
            if page and page._is_open and type(page._Update)=="function" then page:_Update() end
        end)
    end

