    local passTier=Other:AddModule({Name="Season Pass Tier Spoofer",Function=function(enabled)
        Config.__SeasonPassTierSpoof=enabled==true
        if enabled then
            applyPassExistingData()
        else
            restorePassExistingData()
        end
    end})
    passTier:AddDropdown({Name="tier",List={"Prime","Contraband"},Default="Prime",Function=function(v)
        passTierValue=(v=="Contraband") and "Contraband" or "Prime"
        if Config.__SeasonPassTierSpoof then
            applyPassExistingData()
        end
    end})
    passTier:AddButton({Name="refresh battle pass",Function=applyPassExistingData})
    passTier:AddLabel({Text="Spoofs local pass reads and the native name tag status. Updates on changes, without polling."})

    mainapi:Clean(function()
        Config.__SeasonPassTierSpoof=false
        restorePassExistingData()
    end)

