    local leaderboard = Other:AddModule({Name="Leaderboard Spoofer",Function=function(enabled)Config.__LeaderboardSpoof=enabled==true end})
    local boardValues={["Highest ELO"]=0,["Current Highest Win Streak"]=0,["Most Eliminations"]=0,["Most Wins"]=0,["Highest Level"]=0}
    local boardEnabled={}
    local boardBackups={}
    local boardController=nil
    local function deepCopyRow(row) local copy={};for k,v in pairs(row)do copy[k]=v end;return copy end
    local function restoreBoard(key)
        local saved=boardBackups[key]
        if not saved then return end
        for i=#saved.list,1,-1 do if saved.list[i]==saved.row then table.remove(saved.list,i) break end end
        if saved.original then table.insert(saved.list,math.min(saved.index,#saved.list+1),saved.original) end
        boardBackups[key]=nil
    end
    local function updateBoards()
        if not Config.__LeaderboardSpoof then
            for key in pairs(boardBackups) do restoreBoard(key) end
            return
        end
        if not boardController then
            pcall(function() boardController=require(LocalPlayer.PlayerScripts.Controllers.LeaderboardController) end)
        end
        if not boardController then return end
        for key,enabled in pairs(boardEnabled) do
            if enabled then
                local serial=boardController.LeaderboardSerials and boardController.LeaderboardSerials[key]
                local list=serial and serial.Players
                if type(list)=="table" then
                    local saved=boardBackups[key]
                    local currentValue=saved and (saved.row.value ~= nil and saved.row.value or saved.row.Value)
                    local rowPresent=false
                    if saved and saved.list==list then
                        for _,existing in ipairs(list) do
                            if existing==saved.row then rowPresent=true break end
                        end
                    end
                    -- The old five-second guard restored, reinserted and fired a
                    -- full leaderboard refresh even when nothing changed. That
                    -- rebuilt the board UI and caused the regular one-second hitch.
                    if rowPresent and tonumber(currentValue)==tonumber(boardValues[key]) then
                        continue
                    end
                    restoreBoard(key)
                    local original,index
                    for i=#list,1,-1 do
                        local row=list[i]
                        if type(row)=="table" and tonumber(row.key or row.UserId or row.UserID or row.PlayerId)==LocalPlayer.UserId then
                            original=row;index=i;table.remove(list,i)
                        end
                    end
                    local row=original and deepCopyRow(original) or {key=tostring(LocalPlayer.UserId),UserId=LocalPlayer.UserId}
                    row.value=boardValues[key];if row.Value~=nil then row.Value=boardValues[key] end
                    local rank=1
                    for i,p in ipairs(list) do if (tonumber(p.value or p.Value)or 0)>=boardValues[key] then rank=i+1 else break end end
                    table.insert(list,rank,row)
                    boardBackups[key]={list=list,row=row,original=original,index=index or #list}
                    pcall(function() if boardController.Refreshed then boardController.Refreshed:Fire(key) end end)
                end
            else
                restoreBoard(key)
            end
        end
    end
    for _,spec in ipairs({{"ELO","Highest ELO"},{"streak","Current Highest Win Streak"},{"kills","Most Eliminations"},{"wins","Most Wins"},{"level","Highest Level"}}) do
        boardEnabled[spec[2]]=false
        leaderboard:AddToggle({Name="override "..spec[1],Default=false,Function=function(v)boardEnabled[spec[2]]=v==true;updateBoards()end})
        leaderboard:AddSlider({Name=spec[1],Min=0,Max=100000,Default=0,Function=function(v)boardValues[spec[2]]=v;updateBoards()end})
    end
    mainapi:CreateIdleWorker("Leaderboard", {Interval=1, IsActive=function() return Config.__LeaderboardSpoof == true end, Update=function()
        local now=tick();Config.__BoardAt=Config.__BoardAt or 0
        if Config.__LeaderboardSpoof and now-Config.__BoardAt>5 then Config.__BoardAt=now;updateBoards() end
    end})
    mainapi:Clean(function() for key in pairs(boardBackups) do restoreBoard(key) end end)

    local seasonCfg={}
    local seasonNames={[0]="Zero",[1]="Warp",[2]="Polar",[3]="Fame"}
    local seasonByName={Zero=0,Warp=1,Polar=2,Fame=3}
    local seasonLib
    local seasonOriginal
    local seasonReplacement
    local fighterController
    local seasonRecords=setmetatable({}, {__mode="k"})

    local function seasonNumber(value)
        if type(value)=="number" then return value end
        if type(value)~="string" then return nil end
        return seasonByName[value] or tonumber(value:match("^Season (%d+)$")) or tonumber(value)
    end

    local function resolveSeasonLibrary()
        if seasonLib then return seasonLib end
        pcall(function()
            local modules=ReplicatedStorage:FindFirstChild("Modules")
            local module=modules and modules:FindFirstChild("SeasonLibrary")
            if module then seasonLib=require(module) end
        end)
        return seasonLib
    end

    local function seasonRankProfile(index)
        local lib=resolveSeasonLibrary()
        local season=lib and lib.Seasons[seasonNames[index]]
        return season and season.RankProfile
    end

    local function seasonRankChoices(index)
        local profile=seasonRankProfile(index)
        return profile and table.clone(profile.RanksOrder) or {}
    end

    local function seasonMetadata(value)
        local index=seasonNumber(value)
        local cfg=index~=nil and seasonCfg[index] or nil
        if not Config.__SeasonSpoof or not cfg or not cfg.enabled then return nil end
        local profile=seasonRankProfile(index)
        local rank=profile and profile.Ranks[cfg.rankName]
        if not rank then return nil end
        return {SeasonELO=rank.RequiredELO,
            SeasonLeaderboardRank=rank.RequiredELOLeaderboardRanking and math.clamp(math.floor(tonumber(cfg.rank) or 1),1,200) or nil}
    end

    local function recordSeasonCharm(model,season,elo,arch,hasNativeData)
        local saved=seasonRecords[model]
        if saved then return saved end
        saved={season=season,elo=elo,arch=arch,native=hasNativeData,labels={}}
        local extra=model:FindFirstChild("Extra")
        saved.extra=extra and extra:Clone()
        for _,object in ipairs(model:GetDescendants()) do
            if object:HasTag("CharmLeaderboardRank") then saved.labels[object]=object.Text end
        end
        seasonRecords[model]=saved
        return saved
    end

    local function restoreCharmRankGeometry(model,season,md)
        local rank=seasonLib:GetRank(md.SeasonELO,nil,md.SeasonLeaderboardRank or math.huge,seasonLib.Seasons[season].RankProfile.Name)
        local extra=model:FindFirstChild("Extra")
        if not extra or extra:FindFirstChild(rank) then return end
        local assets=LocalPlayer.PlayerScripts.Assets.Charms
        local template=assets:FindFirstChild(model.Name)
        local source=template and template:FindFirstChild("Extra")
        local shape=source and source:FindFirstChild(rank)
        if shape then shape:Clone().Parent=extra end
    end

    local function resolveFighterController()
        if fighterController then return fighterController end
        pcall(function()
            local scripts=LocalPlayer:FindFirstChild("PlayerScripts")
            local controllers=scripts and scripts:FindFirstChild("Controllers")
            local module=controllers and controllers:FindFirstChild("FighterController")
            if module then fighterController=require(module) end
        end)
        return fighterController
    end

    local function equippedViewmodelRoot()
        local controller=resolveFighterController()
        if not controller then return nil end
        local fighter=controller.LocalFighter
        if not fighter and type(controller.GetFighter)=="function" then
            pcall(function() fighter=controller:GetFighter(LocalPlayer) end)
        end
        local item=fighter and fighter.EquippedItem
        local vm=item and item.ViewModel
        return vm and (vm.Model or vm._model) or nil
    end

    local function installSeasonHook()
        local lib=resolveSeasonLibrary()
        if not lib or seasonOriginal or type(lib.FormatSeasonRankCharm)~="function" then return end
        local original=lib.FormatSeasonRankCharm
        local replacement=function(self,model,season,elo,arch,...)
            local md=seasonMetadata(season)
            if md then
                if typeof(model)=="Instance" and seasonRecords[model]==nil then
                    recordSeasonCharm(model,season,elo,arch,true)
                end
                restoreCharmRankGeometry(model,season,md)
                elo,arch=md.SeasonELO,md.SeasonLeaderboardRank
            end
            return original(self,model,season,elo,arch,...)
        end
        local ok=pcall(function() lib.FormatSeasonRankCharm=replacement end)
        if ok and lib.FormatSeasonRankCharm==replacement then
            seasonOriginal=original
            seasonReplacement=replacement
        end
    end

    local function restoreSeasonCharm(model,saved)
        if typeof(model)=="Instance" and model.Parent then
            if saved.extra then
                local extra=model:FindFirstChild("Extra")
                if extra then extra:Destroy() end
                saved.extra.Parent=model
                saved.extra=nil
            end
            for label,text in pairs(saved.labels or {}) do if label.Parent then label.Text=text end end
            if saved.native then pcall(seasonOriginal,seasonLib,model,saved.season,saved.elo,saved.arch) end
        end
        if saved.extra then saved.extra:Destroy() end
    end

    local function restoreSeasonCharms()
        if not seasonLib or not seasonOriginal then return end
        for model,saved in pairs(seasonRecords) do restoreSeasonCharm(model,saved) end
        table.clear(seasonRecords)
    end

    local function refreshSeasonCharms()
        if not Config.__SeasonSpoof then restoreSeasonCharms() return end
        installSeasonHook()
        if not seasonLib or not seasonOriginal then return end

        for model,saved in pairs(seasonRecords) do
            if typeof(model)=="Instance" and model.Parent then
                local md=seasonMetadata(saved.season)
                if md then
                    restoreCharmRankGeometry(model,saved.season,md)
                    pcall(seasonOriginal,seasonLib,model,saved.season,md.SeasonELO,md.SeasonLeaderboardRank)
                else
                    restoreSeasonCharm(model,saved)
                    seasonRecords[model]=nil
                end
            else
                restoreSeasonCharm(model,saved)
                seasonRecords[model]=nil
            end
        end

        local roots={equippedViewmodelRoot(),workspace.CurrentCamera,LocalPlayer.Character}
        local seen=setmetatable({}, {__mode="k"})
        local function restyle(model)
            if typeof(model)~="Instance" or not model:IsA("Model") or seen[model] then return end
            seen[model]=true
            local index=seasonNumber(model.Name)
            if index==nil then return end
            local md=seasonMetadata(index)
            if not md then return end
            local saved=seasonRecords[model]
            local season=saved and saved.season or seasonNames[index] or model.Name
            if not saved then
                recordSeasonCharm(model,season,nil,nil,false)
            end
            pcall(seasonLib.FormatSeasonRankCharm,seasonLib,model,season,md.SeasonELO,md.SeasonLeaderboardRank)
        end
        for _,root in ipairs(roots) do
            if typeof(root)=="Instance" then
                restyle(root)
                for _,model in ipairs(root:GetDescendants()) do restyle(model) end
            end
        end
    end

-- END PLEX SOURCE: modules/leaderboard_spoofer.lua
-- BEGIN PLEX SOURCE: modules/elo_charm_spoofer.lua
    local seasons = Other:AddModule({Name="ELO Charm Spoofer",Function=function(enabled)
        Config.__SeasonSpoof=enabled==true
        if enabled then
            task.defer(refreshSeasonCharms)
        else
            restoreSeasonCharms()
        end
    end})
    for i=0,3 do seasonCfg[i]={enabled=false,rankName="Archnemesis",rank=1} end
    for i=0,3 do
        local index=i
        seasons:AddToggle({Name="season "..index.." ("..seasonNames[index]..")",Default=false,Function=function(v)
            seasonCfg[index].enabled=v==true
            refreshSeasonCharms()
        end})
        local choices=seasonRankChoices(index)
        local defaultRank=table.find(choices,"Archnemesis") and "Archnemesis" or choices[#choices]
        seasonCfg[index].rankName=defaultRank
        seasons:AddDropdown({Name="season "..index.." rank",List=choices,Default=defaultRank,Function=function(v)
            seasonCfg[index].rankName=v
            refreshSeasonCharms()
        end})
        seasons:AddSlider({Name="season "..index.." leaderboard",Min=1,Max=200,Default=1,Function=function(v)
            seasonCfg[index].rank=math.clamp(math.floor(tonumber(v) or 1),1,200)
            refreshSeasonCharms()
        end})
    end
    seasons:AddButton({Name="refresh charm appearance",Function=refreshSeasonCharms})
    seasons:AddLabel({Text="Equip a Season charm. Archnemesis shows a Top 200 spot (1–200); other ranks hide it."})

    mainapi:CreateIdleWorker("SeasonCharm", {Interval=0.25, IsActive=function() return Config.__SeasonSpoof == true end, Update=function()
        if Config.__SeasonSpoof then
            local now=tick()
            Config.__SeasonAt=Config.__SeasonAt or 0
            if now-Config.__SeasonAt>1.5 then
                Config.__SeasonAt=now
                refreshSeasonCharms()
            end
        end
    end})
    mainapi:Clean(function()
        Config.__SeasonSpoof=false
        restoreSeasonCharms()
        if seasonLib and seasonOriginal and seasonReplacement and seasonLib.FormatSeasonRankCharm==seasonReplacement then
            pcall(function() seasonLib.FormatSeasonRankCharm=seasonOriginal end)
        end
    end)
end)

