    local original={}
    local originalGet=controller.Get
    local originalGetStatistic=controller.GetStatistic
    local current=controller.CurrentData
    local originalCurrentGet=current and current.Get
    local originalCurrentGetSlot=current and rawget(current,"Get")

    local function spoofValue(key,value)
        if active and values[key]~=nil then return values[key] end
        return value
    end
    local wrappedGet=function(self,key,...)
        if active and values[key]~=nil then return values[key] end
        return originalGet(self,key,...)
    end
    local wrappedStatistic=function(self,key,...)
        if active and values[key]~=nil then return values[key] end
        return originalGetStatistic(self,key,...)
    end
    local wrappedCurrentGet=originalCurrentGet and function(self,key,...)
        if active and values[key]~=nil then return values[key] end
        return originalCurrentGet(self,key,...)
    end
    controller.Get=wrappedGet
    controller.GetStatistic=wrappedStatistic
    if current and wrappedCurrentGet then rawset(current,"Get",wrappedCurrentGet) end

    local function replicate(key)
        local data=controller.CurrentData
        if data and type(data.Replicate)=="function" then pcall(data.Replicate,data,key) end
    end
    local function applyCounters()
        local data=controller.CurrentData and controller.CurrentData.Data
        if type(data)~="table" then return end
        for key,value in pairs(values) do
            if active then
                if not original[key] then
                    original[key]={table=data,raw=rawget(data,key),hadRaw=rawget(data,key)~=nil}
                end
                rawset(data,key,value)
                applied[key]=value
            elseif original[key] then
                local saved=original[key]
                if rawget(saved.table,key)==applied[key] then
                    rawset(saved.table,key,saved.hadRaw and saved.raw or nil)
                end
                original[key]=nil
                applied[key]=nil
            end
            replicate(key)
        end
    end

    local initialStatWarning=false
    local function readInitialStatistic(key)
        local data=controller.CurrentData and controller.CurrentData.Data
        if type(data)=="table" and rawget(data,key)~=nil then return rawget(data,key) end
        local ok,value=pcall(originalGetStatistic,controller,key)
        if ok then return value end
        if not initialStatWarning then
            initialStatWarning=true
            warn("[Plex] Career-stat defaults unavailable in this executor; local defaults will be used.")
        end
        return nil
    end
    mainapi:Clean(function()
        active=false
        applyCounters()
        if controller.Get==wrappedGet then controller.Get=originalGet end
        if controller.GetStatistic==wrappedStatistic then controller.GetStatistic=originalGetStatistic end
        if current and rawget(current,"Get")==wrappedCurrentGet then rawset(current,"Get",originalCurrentGetSlot) end
    end)

