    for name,item in pairs(itemLibrary.Items) do
        if type(item)=="table" and type(name)=="string" and byClass[item.Class] then
            table.insert(allWeapons,name)
            table.insert(byClass[item.Class],name)
        end
    end
    table.sort(allWeapons)
