        values[key]=default
        counters:AddDropdown({Name=label,List=list,Default=default,Function=function(value)
            if table.find(list,value) then values[key]=value; if active then applyCounters() end end
        end})
    end
    addWeapon("most played weapon","StatisticFavoriteWeapon",allWeapons)
    addWeapon("primary weapon","StatisticFavoriteWeaponPrimary",byClass.Primary)
    addWeapon("secondary weapon","StatisticFavoriteWeaponSecondary",byClass.Secondary)
    addWeapon("melee weapon","StatisticFavoriteWeaponMelee",byClass.Melee)
    addWeapon("utility weapon","StatisticFavoriteWeaponUtility",byClass.Utility)
