    values.StatisticPlaytime=playtime
    counters:AddSlider({Name="playtime hours",Min=0,Max=10000,Default=math.floor(playtime/3600*10+0.5)/10,Decimal=10,Suffix="h",Function=function(hours)
        values.StatisticPlaytime=math.floor((tonumber(hours) or 0)*3600)
        if active then applyCounters() end
    end})
    local eliminations=tonumber(readInitialStatistic("StatisticEliminations")) or 0
    values.StatisticEliminations=eliminations
    counters:AddSlider({Name="kills",Min=0,Max=1000000,Default=eliminations,Function=function(count)
        values.StatisticEliminations=math.floor(tonumber(count) or 0)
        if active then applyCounters() end
