run(function()
    local mode
    local color
    local speed
    local nametag
    local original=setmetatable({}, {__mode="k"})
    local watched=setmetatable({}, {__mode="k"})
    local lastScan=0

    local function normalizedText(value)
        return tostring(value or ""):gsub("<[^<>]->",""):gsub("^%s+",""):gsub("%s+$",""):lower()
    end

    local function ownNames()
        local names={
            [normalizedText(LocalPlayer.Name)]=true,
            [normalizedText(LocalPlayer.DisplayName)]=true,
            [normalizedText("@"..LocalPlayer.Name)]=true,
        }
        local env=getgenv and getgenv() or _G
        local state=env.__LionIdentitySpoofState
        local record=state and state.Records and state.Records[LocalPlayer]
        if record then
            for _,value in ipairs({record.Username,record.DisplayName}) do
                local name=normalizedText(value)
                if name~="" then
                    names[name]=true
                    names["@"..name]=true
                end
            end
        end
        return names
    end

    local function onSupportedSurface(label)
        local current=label.Parent
        while current do
            local name=current.Name:lower():gsub("[%s_%-]","")
            if name:find("nametag",1,true)
                or name:find("dueler",1,true)
                or name:find("duelprofile",1,true)
                or name:find("viewprofile",1,true)
                or name:find("leaderboard",1,true)
                or name:find("playerlist",1,true) then
                return true
            end
            if current:IsA("ScreenGui") or current:IsA("BillboardGui") then break end
            current=current.Parent
        end
        return false
    end

    local function isOwnNameLabel(label)
        if not label:IsA("TextLabel") then return false end
        -- Native display names can include badge glyphs or a spoofed name.
        -- Identify the local character's actual name fields independently of text.
        local character=LocalPlayer.Character
        local gui=label:FindFirstAncestor("NametagGui")
        if character and gui and gui:IsDescendantOf(character)
            and label.Parent.Name=="NameDisplay"
            and (label.Name=="DisplayName" or label.Name=="Username") then
            return true
        end
        return onSupportedSurface(label) and ownNames()[normalizedText(label.Text)]==true
    end

    local function currentTint()
        return mode.Value=="rainbow"
            and Color3.fromHSV((os.clock()*(speed.Value or 3)/10)%1,0.88,1)
            or (color.Colors and color.Colors[1]) or Color3.fromRGB(255,85,226)
    end

    local function applyLabel(label,tint)
        if not label.Parent or not isOwnNameLabel(label) then return end
        local saved=original[label]
        if not saved then
            saved={Color=label.TextColor3}
            original[label]=saved
        end
        saved.Applied=tint
        if label.TextColor3~=tint then label.TextColor3=tint end
    end

    local function restore()
        for label,saved in pairs(original) do
            if label.Parent then
                pcall(function()
                    if saved.Applied==nil or label.TextColor3==saved.Applied then
                        label.TextColor3=saved.Color
                    end
                end)
            end
            original[label]=nil
        end
    end

    local function watch(label)
        if not label:IsA("TextLabel") or watched[label] or not onSupportedSurface(label) then return end
        watched[label]=label:GetPropertyChangedSignal("Text"):Connect(function()
            if nametag.Enabled then applyLabel(label,currentTint()) end
        end)
        if nametag.Enabled then applyLabel(label,currentTint()) end
    end

    local function scan()
        local playerGui=LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if playerGui then
            for _,object in ipairs(playerGui:GetDescendants()) do watch(object) end
        end
        local root=LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        local gui=root and root:FindFirstChild("NametagGui")
        if gui then
            for _,object in ipairs(gui:GetDescendants()) do watch(object) end
        end
    end

-- END PLEX SOURCE: shared/021_spoofers.lua
-- BEGIN PLEX SOURCE: shared/021a_peer_sync.lua
-- Same-server Plex peer exchange. Roblox does not expose arbitrary client to
-- client networking, so each client publishes a bounded snapshot to the
-- configured Netlify relay. The legacy chat receiver remains for compatibility
-- with builds that still emit PX1 packets.
do
    local HttpService = game:GetService("HttpService")
    local Players = game:GetService("Players")
    local TextChatService = game:GetService("TextChatService")
    local LocalPlayer = Players.LocalPlayer
    local PREFIX = "PX1|"
    local CHUNK_SIZE = 140
    local MAX_CHUNKS = 14
    local MAX_RELAY_STATE_SIZE = 18000
    local RELAY_POLL_INTERVAL = 60
    local RELAY_HEARTBEAT_INTERVAL = 120
    local env = getgenv and getgenv() or _G
    local requestFunction = env.request or env.http_request
        or (env.syn and env.syn.request) or request or http_request

    local function topicHash(value)
        local hash = 5381
        for index = 1, #value do hash = (hash * 33 + value:byte(index)) % 2147483647 end
        return string.format("%08x", hash)
    end
    local relayRoom = "r-" .. topicHash(tostring(game.GameId) .. "|" .. tostring(game.JobId)
        .. "|plex-peer-relay-2026")
    local configuredRelayUrl = tostring(env.PlexRelayUrl or env.PLEX_RELAY_URL or env.__PlexRelayUrl
        or "https://lucent-rugelach-72c398.netlify.app/api/sync")

    local function normalizeRelayUrl(value)
        value = tostring(value or ""):match("^%s*(.-)%s*$"):gsub("/+$", "")
        if value ~= "" and not value:find("/api/sync", 1, true) then value ..= "/api/sync" end
        return value
    end

    if shared.PlexPeerSync and shared.PlexPeerSync.Destroy then
        pcall(shared.PlexPeerSync.Destroy, shared.PlexPeerSync)
    end

    local sync = {
        Enabled = false,
        SyncSpoofers = true,
        SyncCosmetics = true,
        Connections = {},
        Assemblies = {},
        Peers = {},
        Sequence = 0,
        LastFingerprint = nil,
        LastSend = 0,
        Sending = false,
        Polling = false,
        Alive = true,
        Session = string.format("%x-%x", LocalPlayer.UserId, math.random(0, 0xFFFFFF)),
        RelayUrl = normalizeRelayUrl(configuredRelayUrl),
        Room = relayRoom,
        Cursor = 0,
        LastPoll = 0,
        LastError = nil,
        Transport = type(requestFunction) == "function" and "Netlify API" or "unavailable",
    }

    local function removePeer(player)
        if not player then return end
        sync.Peers[player.UserId] = nil
        if shared.PlexSpooferPeerSync then pcall(shared.PlexSpooferPeerSync.Remove, player) end
        if shared.PlexProfilePeerSync then pcall(shared.PlexProfilePeerSync.Remove, player) end
        if shared.LionCosmeticChanger and shared.LionCosmeticChanger.RemovePeerData then
            pcall(shared.LionCosmeticChanger.RemovePeerData, player)
        end
    end

    local function clearPeers()
        for userId in pairs(sync.Peers) do
            removePeer(Players:GetPlayerByUserId(userId))
        end
        table.clear(sync.Peers)
        table.clear(sync.Assemblies)
    end

    local function exportedState()
        local state = {v=1}
        if sync.SyncSpoofers then
            if shared.PlexSpooferPeerSync then state.i = shared.PlexSpooferPeerSync.Export() end
            if shared.PlexProfilePeerSync then state.p = shared.PlexProfilePeerSync.Export() end
        end
        if sync.SyncCosmetics and shared.LionCosmeticChanger and shared.LionCosmeticChanger.ExportPeerData then
            state.c, state.q = shared.LionCosmeticChanger.ExportPeerData()
        end

        local encoded = HttpService:JSONEncode(state)
        while #encoded > MAX_RELAY_STATE_SIZE and state.c and next(state.c) do
            local key
            for candidate in pairs(state.c) do
                if candidate ~= state.q then key = candidate break end
            end
            if not key then break end
            state.c[key] = nil
            encoded = HttpService:JSONEncode(state)
        end
        return state, encoded
    end

    local function channel()
        local channels = TextChatService:FindFirstChild("TextChannels")
        return channels and (channels:FindFirstChild("RBXGeneral") or channels:FindFirstChildWhichIsA("TextChannel"))
    end

    function sync:IsProtocol(message)
        return message and type(message.Metadata) == "string"
            and message.Metadata:sub(1, #PREFIX) == PREFIX
    end

    function sync:Broadcast(force)
        if not self.Enabled or self.Sending then return false end
        if type(requestFunction) ~= "function" then
            self.LastError = "executor request API unavailable"
            return false
        end
        if self.RelayUrl == "" then
            self.LastError = "relay URL is not configured"
            return false
        end
        local state, encoded = exportedState()
        local now = os.clock()
        if not force and encoded == self.LastFingerprint
            and now - self.LastSend < RELAY_HEARTBEAT_INTERVAL then return true end
        if not force and now - self.LastSend < 2.5 then return false end

        self.Sending = true
        self.Sequence += 1
        local payload = HttpService:JSONEncode({
            version=1,
            room=self.Room,
            userId=LocalPlayer.UserId,
            session=self.Session,
            sequence=self.Sequence,
            state=state,
        })
        task.spawn(function()
            local ok, result = pcall(requestFunction, {
                Url=self.RelayUrl,
                Method="POST",
                Body=payload,
                Headers={["Content-Type"]="application/json"},
            })
            local status = ok and type(result) == "table" and tonumber(result.StatusCode) or 0
            local sent = status >= 200 and status < 300
            if sent then
                self.LastFingerprint = encoded
                self.LastSend = os.clock()
                self.LastError = nil
            else
                self.LastError = ok and ("relay publish HTTP " .. tostring(result and result.StatusCode))
                    or tostring(result)
            end
            self.Sending = false
        end)
        return true
    end

    local function applyState(player, state)
        if not sync.Enabled or not player or player == LocalPlayer or type(state) ~= "table" or state.v ~= 1 then return end
        sync.Peers[player.UserId] = state
        if sync.SyncSpoofers then
            if state.i and shared.PlexSpooferPeerSync then
                pcall(shared.PlexSpooferPeerSync.Apply, player, state.i)
            elseif shared.PlexSpooferPeerSync then
                pcall(shared.PlexSpooferPeerSync.Remove, player)
            end
            if state.p and shared.PlexProfilePeerSync then
                pcall(shared.PlexProfilePeerSync.Apply, player, state.p)
            elseif shared.PlexProfilePeerSync then
                pcall(shared.PlexProfilePeerSync.Remove, player)
            end
        end
        if sync.SyncCosmetics and shared.LionCosmeticChanger then
            if state.c and shared.LionCosmeticChanger.ApplyPeerData then
                pcall(shared.LionCosmeticChanger.ApplyPeerData, player, state.c)
            elseif shared.LionCosmeticChanger.RemovePeerData then
                pcall(shared.LionCosmeticChanger.RemovePeerData, player)
            end
        end
    end

    local function receive(message)
        if not sync.Enabled or not sync:IsProtocol(message) or not message.TextSource then return end
        local player = Players:GetPlayerByUserId(message.TextSource.UserId)
        if not player or player == LocalPlayer then return end
        local token, indexText, totalText, payload = message.Metadata:match("^PX1|([^|]+)|(%d+)|(%d+)|(.*)$")
        local index, total = tonumber(indexText), tonumber(totalText)
        if not token or not index or not total or total < 1 or total > MAX_CHUNKS or index < 1 or index > total then return end
        local key = tostring(player.UserId) .. ":" .. token
        local assembly = sync.Assemblies[key]
        if not assembly or assembly.Total ~= total then
            assembly = {Total=total, Parts={}, Count=0, Started=os.clock()}
            sync.Assemblies[key] = assembly
        end
        if not assembly.Parts[index] then
            assembly.Parts[index] = payload
            assembly.Count += 1
        end
        if assembly.Count ~= total then return end
        sync.Assemblies[key] = nil
        local encoded = table.concat(assembly.Parts)
        if #encoded > CHUNK_SIZE * MAX_CHUNKS then return end
        local ok, state = pcall(HttpService.JSONDecode, HttpService, encoded)
        if ok then
            applyState(player, state)
            if not sync.LastFingerprint then task.delay(0.5, function() sync:Broadcast(true) end) end
        end
    end

    local function pollRelay()
        if not sync.Enabled or sync.Polling or type(requestFunction) ~= "function" then return end
        if sync.RelayUrl == "" then return end
        local now = os.clock()
        -- Executor HTTP requests can pause the Roblox VM even from task.spawn.
        -- Polling every scheduler pass caused a visible hitch about every four
        -- seconds. State changes still publish immediately; this is only the
        -- low-frequency receive/expiry refresh.
        if now - sync.LastPoll < RELAY_POLL_INTERVAL then return end
        sync.LastPoll = now
        sync.Polling = true
        task.spawn(function()
            local url = sync.RelayUrl .. "?room=" .. HttpService:UrlEncode(sync.Room)
                .. "&since=" .. tostring(sync.Cursor)
                .. "&excludeUserId=" .. tostring(LocalPlayer.UserId)
            local ok, result = pcall(requestFunction, {
                Url=url,
                Method="GET",
                Headers={Accept="application/json"},
            })
            if ok and type(result) == "table" and tonumber(result.StatusCode) == 200 then
                local decodedOK, response = pcall(HttpService.JSONDecode, HttpService, tostring(result.Body or ""))
                if decodedOK and type(response) == "table" and response.ok == true then
                    local active = {}
                    for _, userId in ipairs(type(response.activeUserIds) == "table" and response.activeUserIds or {}) do
                        userId = tonumber(userId)
                        if userId then active[userId] = true end
                    end
                    for userId in pairs(sync.Peers) do
                        if not active[userId] then removePeer(Players:GetPlayerByUserId(userId)) end
                    end
                    for _, peer in ipairs(type(response.peers) == "table" and response.peers or {}) do
                        local userId = tonumber(peer.userId)
                        local player = userId and Players:GetPlayerByUserId(userId)
                        if player and player ~= LocalPlayer and type(peer.state) == "table" then
                            local firstSeen = sync.Peers[userId] == nil
                            applyState(player, peer.state)
                            if firstSeen then task.delay(0.25, function() sync:Broadcast(true) end) end
                        end
                    end
                    sync.Cursor = math.max(sync.Cursor, tonumber(response.cursor) or 0)
                    sync.LastError = nil
                else
                    sync.LastError = "relay returned invalid JSON"
                end
            else
                sync.LastError = ok and ("relay poll HTTP " .. tostring(result and result.StatusCode))
                    or tostring(result)
            end
            sync.Polling = false
        end)
    end

    function sync:PollNow()
        self.LastPoll = 0
        pollRelay()
    end

    local function unregister()
        if type(requestFunction) ~= "function" or sync.RelayUrl == "" then return end
        local url = sync.RelayUrl .. "?room=" .. HttpService:UrlEncode(sync.Room)
            .. "&userId=" .. tostring(LocalPlayer.UserId)
            .. "&session=" .. HttpService:UrlEncode(sync.Session)
        task.spawn(function()
            pcall(requestFunction, {Url=url, Method="DELETE", Headers={Accept="application/json"}})
        end)
    end

    function sync:Configure(url)
        local normalized = normalizeRelayUrl(url)
        if normalized == self.RelayUrl then return end
        if self.Enabled then unregister() end
        self.RelayUrl = normalized
        self.Cursor = 0
        self.LastPoll = 0
        self.LastFingerprint = nil
        env.PlexRelayUrl = normalized
        clearPeers()
        if self.Enabled then self:Broadcast(true) end
    end

    function sync:SetOptions(spoofers, cosmetics)
        self.SyncSpoofers = spoofers == true
        self.SyncCosmetics = cosmetics == true
        self.LastFingerprint = nil
        clearPeers()
        if self.Enabled then self:Broadcast(true) end
    end

    function sync:SetEnabled(enabled)
        enabled = enabled == true
        if self.Enabled == enabled then return end
        self.Enabled = enabled
        if not enabled then
            unregister()
            clearPeers()
            return
        end
        self.LastFingerprint = nil
        self.Cursor = 0
        self.LastPoll = 0
        self:Broadcast(true)
    end

    function sync:Destroy()
        unregister()
        self.Alive = false
        self.Enabled = false
        clearPeers()
        for _, connection in ipairs(self.Connections) do pcall(function() connection:Disconnect() end) end
        table.clear(self.Connections)
        if shared.PlexPeerSync == self then shared.PlexPeerSync = nil end
    end

    table.insert(sync.Connections, TextChatService.MessageReceived:Connect(receive))
    table.insert(sync.Connections, Players.PlayerRemoving:Connect(removePeer))
    table.insert(sync.Connections, Players.PlayerAdded:Connect(function()
        if sync.Enabled then task.delay(2, function()
            sync:Broadcast(true)
            sync:PollNow()
        end) end
    end))
    task.spawn(function()
        while sync.Alive do
            task.wait(2)
            local now = os.clock()
            for key, assembly in pairs(sync.Assemblies) do
                if now - assembly.Started > 8 then sync.Assemblies[key] = nil end
            end
            if sync.Enabled and not sync.Sending then sync:Broadcast(false) end
            if sync.Enabled then pollRelay() end
        end
    end)

    shared.PlexPeerSync = sync
    mainapi:Clean(function() sync:Destroy() end)
end

