        Placeholder = "https://your-site.netlify.app/api/sync",
        Function = function(value)
            if shared.PlexPeerSync then shared.PlexPeerSync:Configure(value) end
        end
    })
    local function updatePeerSyncOptions()
        if shared.PlexPeerSync then
            shared.PlexPeerSync:SetOptions(
                not PeerSyncSpoofers or PeerSyncSpoofers.Enabled,
                not PeerSyncCosmetics or PeerSyncCosmetics.Enabled
            )
        end
