            shared.PlexPeerSync:PollNow()
            task.delay(0.8, function()
                local sync = shared.PlexPeerSync
                if not sync then return end
                local peers = 0
                for _ in pairs(sync.Peers) do peers += 1 end
                mainapi:Notify({Text=sync.LastError and ("Plex sync error: " .. sync.LastError)
                    or ("Plex sync online via " .. sync.Transport .. " | peers: " .. peers), Duration=3})
            end)
        end
    end})
    PlexUserSync:AddLabel({Text = "Shares supported spoofers, profile stats, avatars, and cosmetics with Plex users in this server through your Netlify relay."})

