        if nametag.Enabled then task.delay(0.25,scan) end
    end))
    mainapi:CreateIdleWorker("YourNametag", {Interval=0.05,
        IsActive=function() return nametag.Enabled == true end,
        Update=function()
        local now=os.clock()
        if now-lastScan>=1 then lastScan=now;scan() end
        local tint=currentTint()
        for label,saved in pairs(original) do
            if label.Parent and isOwnNameLabel(label) then
                applyLabel(label,tint)
            else
                if label.Parent then
                    pcall(function()
                        if saved.Applied==nil or label.TextColor3==saved.Applied then
                            label.TextColor3=saved.Color
                        end
                    end)
                end
                original[label]=nil
            end
        end
    end})
    mainapi:Clean(function()
        restore()
        for label,connection in pairs(watched) do
            pcall(function() connection:Disconnect() end)
            watched[label]=nil
        end
    end)
end)

