run(function()
    local ChatSpam, InOrder, ChatMode, RandomCustomText, CustomText
    local spamLoopRunning = false
    local modeIndex = {}
    local TextChatService = cloneref(game:GetService("TextChatService"))

    local modeMessages = {
        custom = {},
        smol = {
            "tiny wins still count",
            "small text big result",
            "smol but locked in"
        },
        corny = {
            "that round was nacho average duel",
            "you just got served with extra cheese",
            "corny line, clean win"
        },
        wholesome = {
            "good fight",
            "nice shot",
            "well played"
        },
        ["auto ban"] = {
            "ban phase handled",
            "voting the loadout",
            "random ban locked"
        }
    }

    local customPresets = {
        "...",
        "message...",
        "good fight",
        "nice shot",
        "well played"
    }

    local function sendChat(text)
        text = tostring(text or "")
        if text == "" then return end

        local ok = pcall(function()
            local channels = TextChatService:FindFirstChild("TextChannels")
            local channel = channels and (channels:FindFirstChild("RBXGeneral") or channels:FindFirstChild("RBXSystem"))
            if channel and channel.SendAsync then
                channel:SendAsync(text)
            else
                error("TextChannel unavailable")
            end
        end)
        if ok then return end

        pcall(function()
            ReplicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(text, "All")
        end)
    end

    local function getNextMessage()
        local mode = ChatMode and ChatMode.Value or "custom"
        if mode == "custom" then
            local text = CustomText and CustomText.Value or ""
            if text == "" or text == "message..." then
                text = RandomCustomText and RandomCustomText.Value or "..."
            end
            return text
        end

        local messages = modeMessages[mode] or modeMessages.custom
        if #messages == 0 then
            return CustomText and CustomText.Value or "..."
        end

        if InOrder and InOrder.Enabled then
            local nextIndex = (modeIndex[mode] or 0) + 1
            if nextIndex > #messages then nextIndex = 1 end
            modeIndex[mode] = nextIndex
            return messages[nextIndex]
        end

        return messages[math.random(1, #messages)]
    end

-- END PLEX SOURCE: shared/024_misc_and_animation.lua
-- BEGIN PLEX SOURCE: modules/chat_spam.lua
    ChatSpam = Other:AddModule({
        Name = "chat spam",
        Function = function(callback)
            if callback and not spamLoopRunning then
                spamLoopRunning = true
                task.spawn(function()
                    while ChatSpam.Enabled do
                        pcall(sendChat, getNextMessage())
                        task.wait(1.5)
                    end
                    spamLoopRunning = false
                end)
            end
        end
    })

    InOrder = ChatSpam:AddToggle({
        Name = "in order"
    })

    ChatMode = ChatSpam:AddDropdown({
        Name = "chat mode",
        List = {"custom", "smol", "corny", "wholesome", "auto ban"},
        Default = "custom"
    })

    RandomCustomText = ChatSpam:AddDropdown({
        Name = "random custom text",
        List = customPresets,
        Default = "..."
    })

    CustomText = ChatSpam:AddInputBox({
        Name = "add custom text",
        Default = "message...",
        Placeholder = "message..."
    })

    ChatSpam:AddButton({
        Name = "refresh modes",
        Function = function()
            table.clear(modeIndex)
        end
    })

-- END PLEX SOURCE: modules/chat_spam.lua
-- BEGIN PLEX SOURCE: modules/kill_messages.lua
    do
        local killPresets = {
            "{name} just got deleted",
            "gg {name}",
            "{display} was no match",
            "sit down {name}",
            "another one down: {name}",
            "{name} needs more practice",
        }
        local km = {Index = 0, Last = 0, Wrapper = nil, Original = nil, Slots = nil}
        local KillMessages, KillMode, KillTemplate, KillCooldown, KillOrder

        local function formatKill(player)
            local text = KillTemplate and KillTemplate.Value or ""
            if text == "" or text == "message..." then
                if KillOrder and KillOrder.Enabled then
                    km.Index = km.Index % #killPresets + 1
                    text = killPresets[km.Index]
                else
                    text = killPresets[math.random(1, #killPresets)]
                end
            end
            return (text:gsub("{name}", player.Name):gsub("{display}", player.DisplayName))
        end

        local function onKill(player)
            if not KillMessages.Enabled then return end
            local now = os.clock()
            if now - km.Last < (KillCooldown and KillCooldown.Value or 2) then return end
            km.Last = now
            local message = formatKill(player)
            local mode = KillMode and KillMode.Value or "chat"
            if mode == "chat" or mode == "both" then pcall(sendChat, message) end
            if mode == "notification" or mode == "both" then
                mainapi:SafeNotify({Title = "kill", Text = message, Duration = 3})
            end
        end

        local function unhook()
            local slots = km.Slots
            if slots and km.Wrapper and slots.Create == km.Wrapper then slots.Create = km.Original end
            km.Wrapper = nil
        end

        KillMessages = Other:AddModule({Name = "Kill Messages", Function = function(enabled)
            if not enabled then unhook() return end
            if km.Wrapper then return end
            local ok, slots = pcall(function()
                return require(LocalPlayer.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.FighterInterface.EliminationSlots)
            end)
            if not ok or type(slots) ~= "table" or type(slots.Create) ~= "function" then
                mainapi:SafeNotify({Title = "kill messages", Text = "elimination hook unavailable", Duration = 4})
                return
            end
            km.Slots, km.Original = slots, slots.Create
            km.Wrapper = function(self, eliminatedPlayer, assisted, ...)
                if eliminatedPlayer ~= LocalPlayer and not assisted and typeof(eliminatedPlayer) == "Instance" then
                    task.spawn(onKill, eliminatedPlayer)
                end
                return km.Original(self, eliminatedPlayer, assisted, ...)
            end
            slots.Create = km.Wrapper
        end})
        KillMode = KillMessages:AddDropdown({Name = "output", List = {"chat", "notification", "both"}, Default = "chat"})
        KillOrder = KillMessages:AddToggle({Name = "in order"})
        KillCooldown = KillMessages:AddSlider({Name = "cooldown", Min = 0, Max = 10, Default = 2, Decimal = 10, Suffix = "s"})
        KillTemplate = KillMessages:AddInputBox({Name = "custom message", Default = "message...", Placeholder = "{name} / {display}"})
        mainapi:Clean(unhook)
    end
end)

