run(function()
    local Xray
    local Transparency
    local modified = setmetatable({}, {__mode = "k"})
    local scanVersion = 0
    local applyVersion = 0

    local function modifyPart(v)
        if Xray.Enabled and v:IsA('BasePart') then
            if modified[v] == nil then modified[v] = v.LocalTransparencyModifier end
            v.LocalTransparencyModifier = 1 - (Transparency and Transparency.Value or 0.5)
        end
    end

-- END PLEX SOURCE: shared/028_movement.lua
-- BEGIN PLEX SOURCE: modules/xray.lua
    Xray = Render:AddModule({
        Name = 'XRay',
        Function = function(callback)
            scanVersion += 1
            if callback then
                Xray:Clean(workspace.DescendantAdded:Connect(modifyPart))
                local version = scanVersion
                task.spawn(function()
                    for i, v in ipairs(workspace:GetDescendants()) do
                        if version ~= scanVersion or not Xray.Enabled then return end
                        modifyPart(v)
                        if i % 500 == 0 then RunService.Heartbeat:Wait() end
                    end
                end)
            else
                for part, original in pairs(modified) do
                    if part.Parent then part.LocalTransparencyModifier = original end
                end
                table.clear(modified)
            end
        end
    })
    Transparency = Xray:AddSlider({
        Name = 'Transparency',
        Min = 0,
        Max = 1,
        Default = 0.5,
        Function = function(val)
            applyVersion += 1
            if not Xray.Enabled then return end
            local version = applyVersion
            task.spawn(function()
                local count = 0
                for part in pairs(modified) do
                    if version ~= applyVersion or not Xray.Enabled then return end
                    if part.Parent then part.LocalTransparencyModifier = 1 - val end
                    count += 1
                    if count % 500 == 0 then RunService.Heartbeat:Wait() end
                end
            end)
        end,
        Decimal = 10
    })
end)

