            for part in modified do
                part.CanCollide = true
            end
            table.clear(modified)
            fflag = nil
        end
    })
    StudLimit = Phase:AddSlider({
        Name = 'Wall Size',
        Min = 1,
        Max = 20,
        Default = 5,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end,
        Darker = true,
        Visible = false
    })
end)

