    ;(function()
        local module, tonemapper, look, strength, temperature, saturation, contrast, brightness
        local grading, correction
        local presets = {
            Neutral = {0, 0, 0, Color3.new(1, 1, 1)},
            Cinematic = {-0.15, 0.18, -0.02, Color3.fromRGB(225, 240, 255)},
            Warm = {0.12, 0.08, 0.02, Color3.fromRGB(255, 232, 205)},
            Cool = {-0.08, 0.12, 0, Color3.fromRGB(205, 230, 255)},
            Vintage = {-0.3, -0.08, 0.03, Color3.fromRGB(255, 235, 200)},
            Monochrome = {-1, 0.15, 0, Color3.new(1, 1, 1)},
            Vibrant = {0.35, 0.12, 0, Color3.new(1, 1, 1)},
        }
        local function applyGrading()
            if not module or not module.Enabled then
                if grading then grading:Destroy(); grading = nil end
                if correction then correction:Destroy(); correction = nil end
                return
            end
            if not grading then
                grading = Instance.new("ColorGradingEffect")
                grading.Name = "PlexColorGrading"
                grading.Parent = Lighting
            end
            if not correction then
                correction = Instance.new("ColorCorrectionEffect")
                correction.Name = "PlexGradingLook"
                correction.Parent = Lighting
            end
            grading.TonemapperPreset = Enum.TonemapperPreset[tonemapper and tonemapper.Value or "Default"]
            local preset = presets[look and look.Value or "Neutral"] or presets.Neutral
            local amount = (strength and strength.Value or 100) / 100
            correction.Saturation = math.clamp((preset[1] + (saturation and saturation.Value or 0)) * amount, -1, 1)
            correction.Contrast = math.clamp((preset[2] + (contrast and contrast.Value or 0)) * amount, -1, 1)
            correction.Brightness = math.clamp((preset[3] + (brightness and brightness.Value or 0)) * amount, -1, 1)
            local temp = (temperature and temperature.Value or 0) / 100
            local tint = preset[4]:Lerp(temp >= 0 and Color3.fromRGB(255, 210, 165) or Color3.fromRGB(170, 210, 255), math.abs(temp))
            correction.TintColor = Color3.new(1, 1, 1):Lerp(tint, amount)
        end
        module = Movement:AddModule({Name = "Color Grading", Function = applyGrading})
        tonemapper = module:AddDropdown({Name = "preset", List = {"Default", "Retro"}, Default = "Default", Function = applyGrading})
        look = module:AddDropdown({Name = "look", List = {"Neutral", "Cinematic", "Warm", "Cool", "Vintage", "Monochrome", "Vibrant"}, Default = "Neutral", Function = applyGrading})
        strength = module:AddSlider({Name = "look intensity", Min = 0, Max = 100, Default = 100, Function = applyGrading})
        temperature = module:AddSlider({Name = "temperature", Min = -100, Max = 100, Default = 0, Function = applyGrading})
        saturation = module:AddSlider({Name = "saturation adjustment", Min = -1, Max = 1, Default = 0, Decimal = 100, Function = applyGrading})
        contrast = module:AddSlider({Name = "contrast adjustment", Min = -1, Max = 1, Default = 0, Decimal = 100, Function = applyGrading})
        brightness = module:AddSlider({Name = "brightness adjustment", Min = -1, Max = 1, Default = 0, Decimal = 100, Function = applyGrading})
    end)()

