    local function normalizeSkyAsset(value)
        local s = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then return "" end
        if s:match("^%d+$") then return "rbxassetid://" .. s end
        local id = s:match("[?&]id=(%d+)") or s:match("rbxassetid://(%d+)")
        return id and ("rbxassetid://" .. id) or s
    end

    local function applyCustomSkybox()
        if not (CustomSkybox and CustomSkybox.Enabled) then
            if SkyboxModule and SkyboxModule.Enabled then
                applySkybox(SelectedSkybox.Value, true)
            end
            return
        end
        local sky = getEffect("Sky", "LionSkybox")
        for _, obj in ipairs(Lighting:GetChildren()) do
            if obj:IsA("Sky") and obj ~= sky then
                WorldVisualState.OriginalSkyboxes[obj] = obj.Parent
                obj.Parent = nil
            end
        end
        sky.SkyboxBk = normalizeSkyAsset(CustomBk.Value)
        sky.SkyboxDn = normalizeSkyAsset(CustomDn.Value)
        sky.SkyboxFt = normalizeSkyAsset(CustomFt.Value)
        sky.SkyboxLf = normalizeSkyAsset(CustomLf.Value)
        sky.SkyboxRt = normalizeSkyAsset(CustomRt.Value)
        sky.SkyboxUp = normalizeSkyAsset(CustomUp.Value)
        sky.StarCount = CustomStars.Value
        sky.SunAngularSize = CustomSunSize.Value
        sky.MoonAngularSize = CustomMoonSize.Value
        sky.CelestialBodiesShown = CustomSunSize.Value > 0 or CustomMoonSize.Value > 0
        sky.Parent = Lighting
    end

