run(function()
    local amount, horizontal
    local tag = "PlexStretchedResolution"
    local module
    local function stop()
        pcall(RunService.UnbindFromRenderStep, RunService, tag)
    end

-- END PLEX SOURCE: shared/042_world.lua
-- BEGIN PLEX SOURCE: modules/stretched_resolution.lua
    module = Movement:AddModule({Name="Stretched resolution",Function=function(enabled)
        stop()
        if not enabled then return end
        RunService:BindToRenderStep(tag, Enum.RenderPriority.Camera.Value + 2, function()
            local camera = workspace.CurrentCamera
            if not camera or not module.Enabled then return end
            local x = math.clamp(horizontal and tonumber(horizontal.Value) or 1, 0.1, 1)
            local y = math.clamp(amount and tonumber(amount.Value) or 0.88, 0.1, 1)
            camera.CFrame *= CFrame.new(0, 0, 0, x, 0, 0, 0, y, 0, 0, 0, 1)
        end)
    end})
    horizontal = module:AddSlider({Name="stretch x",Min=0.1,Max=1,Default=1,Decimal=100})
    amount = module:AddSlider({Name="stretch amount",Min=0.1,Max=1,Default=0.88,Decimal=100})
    mainapi:Clean(stop)
end)

