-- BEGIN PLEX SOURCE: shared/043_world.lua
run(function()
    local soundESP, sourceFilter, footstepsOnly, minimumVolume, markerRange, markerTime
    local active = {}
    local watched = setmetatable({}, {__mode = "k"})
    local markerCount = 0

    local function soundPart(sound)
        local parent = sound.Parent
        if not parent or not sound:IsDescendantOf(workspace) then return nil end
        if parent:IsA("Attachment") then parent = parent.Parent end
        if parent and parent:IsA("BasePart") then return parent end
        local model = parent and (parent:IsA("Model") and parent or parent:FindFirstAncestorOfClass("Model"))
        return model and getCombatTargetRoot(model) or nil
    end

    local function sourceAllowed(part)
        local filter = sourceFilter and sourceFilter.Value or "all"
        if filter == "all" then return true end
        local model = part:FindFirstAncestorOfClass("Model")
        local owner
        while model and not owner do
            owner = Players:GetPlayerFromCharacter(model)
            model = model:FindFirstAncestorOfClass("Model")
        end
        local sameTeam = owner and owner ~= LocalPlayer and owner.Team ~= nil
            and LocalPlayer.Team ~= nil and not owner.Neutral and not LocalPlayer.Neutral
            and owner.Team == LocalPlayer.Team
        if filter == "self" then return owner == LocalPlayer end
        if filter == "team" then return sameTeam end
        return owner ~= LocalPlayer and not sameTeam
    end

    local function showSound(sound)
        if not soundESP.Enabled or markerCount >= 24 then return end
        if sound.Volume < (minimumVolume and minimumVolume.Value or 0) then return end
        local name = sound.Name:lower()
        if footstepsOnly.Enabled and not (name:find("foot", 1, true) or name:find("step", 1, true)
            or name:find("walk", 1, true) or name:find("run", 1, true)) then return end
        local part = soundPart(sound)
        if not part or not sourceAllowed(part) then return end
        local camera = workspace.CurrentCamera
        if camera and (camera.CFrame.Position - part.Position).Magnitude > markerRange.Value then return end

        if active[sound] then active[sound]:Destroy() markerCount -= 1 end
        local marker = Instance.new("BillboardGui")
        marker.Name = "PlexSoundESP"
        marker.Adornee = part
        marker.AlwaysOnTop = true
        marker.MaxDistance = markerRange.Value
        marker.Size = UDim2.fromOffset(128, 30)
        marker.StudsOffsetWorldSpace = Vector3.new(0, 2.5, 0)
        local label = Instance.new("TextLabel")
        label.Size = UDim2.fromScale(1, 1)
        label.BackgroundColor3 = Color3.fromRGB(16, 12, 24)
        label.BackgroundTransparency = 0.1
        label.TextColor3 = Color3.fromRGB(255, 110, 235)
        label.TextStrokeTransparency = 0.7
        label.Font = Enum.Font.GothamBold
        label.TextSize = 11
        label.Text = "♪ " .. sound.Name
        label.TextTruncate = Enum.TextTruncate.AtEnd
        label.Parent = marker
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 6)
        corner.Parent = label
        local outline = Instance.new("UIStroke")
        outline.Color = Color3.fromRGB(240, 35, 220)
        outline.Thickness = 1
        outline.Parent = label
        marker.Parent = LocalPlayer:FindFirstChildOfClass("PlayerGui") or mainapi.MainScreenGui.Parent
        active[sound] = marker
        markerCount += 1
        task.delay(markerTime.Value, function()
            if active[sound] ~= marker then return end
            active[sound] = nil
            markerCount -= 1
            marker:Destroy()
        end)
    end

    local function watchSound(sound)
        if not sound:IsA("Sound") or watched[sound] then return end
        watched[sound] = true
        soundESP:Clean(sound.Played:Connect(function() showSound(sound) end))
        if sound.Playing then showSound(sound) end
    end

-- END PLEX SOURCE: shared/043_world.lua
-- BEGIN PLEX SOURCE: modules/sound_esp.lua
    soundESP = Render:AddModule({Name = "Sound ESP", Function = function(enabled)
        if not enabled then
            for sound, marker in pairs(active) do
                active[sound] = nil
                marker:Destroy()
            end
            markerCount = 0
            table.clear(watched)
            return
        end
        soundESP:Clean(workspace.DescendantAdded:Connect(watchSound))
        task.spawn(function()
            local scanned = 0
            for _, object in ipairs(workspace:GetDescendants()) do
                if not soundESP.Enabled then return end
                if object:IsA("Sound") then watchSound(object) end
                scanned += 1
                if scanned >= 100 then scanned = 0 RunService.Heartbeat:Wait() end
            end
        end)
    end})
    sourceFilter = soundESP:AddDropdown({Name = "source", List = {"all", "enemies", "team", "self"}, Default = "enemies"})
    footstepsOnly = soundESP:AddToggle({Name = "footsteps only"})
    minimumVolume = soundESP:AddSlider({Name = "minimum volume", Min = 0, Max = 1, Default = 0, Decimal = 100})
    markerRange = soundESP:AddSlider({Name = "max distance", Min = 25, Max = 1000, Default = 250, Suffix = " studs"})
    markerTime = soundESP:AddSlider({Name = "marker duration", Min = 0.2, Max = 3, Default = 0.9, Decimal = 10, Suffix = " s"})
end)

-- END PLEX SOURCE: modules/sound_esp.lua
-- BEGIN PLEX SOURCE: shared/044_world.lua
run(function()
    local motionBlur, intensity, maximum
    local effect = Instance.new("BlurEffect")
    effect.Name = "PlexMotionBlur"
    effect.Size = 0

-- END PLEX SOURCE: shared/044_world.lua
-- BEGIN PLEX SOURCE: modules/motion_blur.lua
    motionBlur = Movement:AddModule({Name = "Motion Blur", Function = function(enabled)
        if not enabled then
            effect.Size = 0
            effect.Parent = nil
            return
        end
        effect.Parent = Lighting
        local previous
        local nextUpdate = 0
        motionBlur:Clean(RunService.RenderStepped:Connect(function(dt)
            local camera = workspace.CurrentCamera
            if not camera then previous = nil return end
            local direction = camera.CFrame.LookVector
            if previous and os.clock() >= nextUpdate then
                local speed = math.acos(math.clamp(previous:Dot(direction), -1, 1)) / math.max(dt, 1 / 240)
                effect.Size = math.clamp(speed * intensity.Value, 0, maximum.Value)
                nextUpdate = os.clock() + 0.05
            end
            previous = direction
        end))
    end})
    intensity = motionBlur:AddSlider({Name = "intensity", Min = 0, Max = 12, Default = 2, Decimal = 10})
    maximum = motionBlur:AddSlider({Name = "maximum blur", Min = 0, Max = 56, Default = 18})
    mainapi:Clean(effect)
end)


