-- BEGIN PLEX SOURCE: shared/045_world.lua
run(function()

-- END PLEX SOURCE: shared/045_world.lua
-- BEGIN PLEX SOURCE: modules/performance.lua
    local Performance = Other:AddModule({Name = "Performance", HideEnabled = true})

    local particleClasses = {
        ParticleEmitter = true, Trail = true, Smoke = true, Fire = true, Sparkles = true,
    }
    local postClasses = {
        BloomEffect = true, BlurEffect = true, ColorCorrectionEffect = true,
        SunRaysEffect = true, DepthOfFieldEffect = true,
    }
    local particleSaved = setmetatable({}, {__mode = "k"})
    local textureSaved = setmetatable({}, {__mode = "k"})
    local postSaved = setmetatable({}, {__mode = "k"})
    local shadowDefault = Lighting.GlobalShadows
    local qualityDefault
    local atmoSaved = setmetatable({}, {__mode = "k"})
    local cloudSaved = setmetatable({}, {__mode = "k"})
    local NoParticles, NoShadows, NoPostFX, LowQuality, NoAtmosphere, NoTextures
    local FpsCapEnabled, FpsCap

    local function setParticle(inst, disabled)
        if not particleClasses[inst.ClassName] then return end
        if disabled then
            if particleSaved[inst] == nil then
                local ok, value = pcall(function() return inst.Enabled end)
                if ok then particleSaved[inst] = value end
            end
            pcall(function() inst.Enabled = false end)
        elseif particleSaved[inst] ~= nil then
            local value = particleSaved[inst]
            particleSaved[inst] = nil
            pcall(function() inst.Enabled = value end)
        end
    end

    local function setTexture(inst, disabled)
        if not (inst:IsA("Decal") or inst:IsA("Texture")) then return end
        if disabled then
            if textureSaved[inst] == nil then textureSaved[inst] = inst.Transparency end
            pcall(function() inst.Transparency = 1 end)
        elseif textureSaved[inst] ~= nil then
            local value = textureSaved[inst]
            textureSaved[inst] = nil
            pcall(function() inst.Transparency = value end)
        end
    end

    local function setPost(inst, disabled)
        if not postClasses[inst.ClassName] then return end
        if disabled then
            if postSaved[inst] == nil then
                local ok, value = pcall(function() return inst.Enabled end)
                if ok then postSaved[inst] = value end
            end
            pcall(function() inst.Enabled = false end)
        elseif postSaved[inst] ~= nil then
            local value = postSaved[inst]
            postSaved[inst] = nil
            pcall(function() inst.Enabled = value end)
        end
    end

    local alive=true
    local previousParticles,previousTextures=false,false
    local workspaceScanRunning = false
    local workspaceScanVersion = 0
    local function scanWorkspace()
        local particles=NoParticles and NoParticles.Enabled==true
        local textures=NoTextures and NoTextures.Enabled==true
        local needsScan=(particles and not previousParticles) or (textures and not previousTextures)
        previousParticles,previousTextures=particles,textures
        if not particles then for inst in pairs(particleSaved) do setParticle(inst,false) end end
        if not textures then for inst in pairs(textureSaved) do setTexture(inst,false) end end
        if not alive or not needsScan then return end
        workspaceScanVersion += 1
        if workspaceScanRunning then return end
        if not (NoParticles and NoParticles.Enabled) and not (NoTextures and NoTextures.Enabled)
            and next(particleSaved) == nil and next(textureSaved) == nil then return end
        workspaceScanRunning = true
        task.spawn(function()
            repeat
                local version = workspaceScanVersion
                if not alive or not (NoParticles.Enabled or NoTextures.Enabled) then break end
                local descendants = workspace:GetDescendants()
                for i, inst in ipairs(descendants) do
                    if not alive or not (NoParticles.Enabled or NoTextures.Enabled) then break end
                    setParticle(inst, NoParticles and NoParticles.Enabled == true)
                    setTexture(inst, NoTextures and NoTextures.Enabled == true)
                    if i % 500 == 0 then RunService.Heartbeat:Wait() end
                end
            until not alive or version == workspaceScanVersion
            workspaceScanRunning = false
        end)
    end

    local function scanLighting()
        for _, inst in ipairs(Lighting:GetDescendants()) do
            setPost(inst, NoPostFX.Enabled)
        end
    end

    local function applyShadows()
        Lighting.GlobalShadows = not NoShadows.Enabled and shadowDefault or false
    end

    local function applyQuality()
        pcall(function()
            local render = settings().Rendering
            qualityDefault = qualityDefault or render.QualityLevel
            render.QualityLevel = LowQuality.Enabled and Enum.QualityLevel.Level01 or qualityDefault
        end)
    end

    local function applyAtmosphere()
        for _, inst in ipairs(Lighting:GetChildren()) do
            if inst:IsA("Atmosphere") then
                if NoAtmosphere.Enabled then
                    if atmoSaved[inst] == nil then atmoSaved[inst] = inst.Density end
                    inst.Density = 0
                elseif atmoSaved[inst] ~= nil then
                    inst.Density = atmoSaved[inst]
                    atmoSaved[inst] = nil
                end
            end
        end
        local terrain = workspace:FindFirstChildOfClass("Terrain")
        if terrain then
            for _, inst in ipairs(terrain:GetChildren()) do
                if inst:IsA("Clouds") then
                    if NoAtmosphere.Enabled then
                        if cloudSaved[inst] == nil then cloudSaved[inst] = inst.Enabled end
                        inst.Enabled = false
                    elseif cloudSaved[inst] ~= nil then
                        inst.Enabled = cloudSaved[inst]
                        cloudSaved[inst] = nil
                    end
                end
            end
        end
    end

    local function applyFpsCap()
        if not setfpscap then return end
        pcall(setfpscap, FpsCapEnabled.Enabled and FpsCap.Value or 1000)
    end

    NoParticles = Performance:AddToggle({Name = "remove particles & effects", Function = scanWorkspace})
    NoShadows = Performance:AddToggle({Name = "disable shadows", Function = applyShadows})
    NoPostFX = Performance:AddToggle({Name = "disable post processing", Function = scanLighting})
    LowQuality = Performance:AddToggle({Name = "low render quality", Function = applyQuality})
    NoAtmosphere = Performance:AddToggle({Name = "disable atmosphere & clouds", Function = applyAtmosphere})
    NoTextures = Performance:AddToggle({Name = "remove textures", Function = scanWorkspace})
    FpsCapEnabled = Performance:AddToggle({Name = "limit fps", Function = applyFpsCap})
    FpsCap = Performance:AddSlider({Name = "fps limit", Min = 30, Max = 360, Default = 60, Function = applyFpsCap})

    local benchmarkConnection, previousBenchmark
    local function summarizeFrameTimes(samples, elapsed)
        table.sort(samples)
        local count=#samples
        local function percentile(value) return samples[math.clamp(math.ceil(count*value),1,count)]*1000 end
        return {FPS=count/elapsed, MeanMs=elapsed/count*1000, P95Ms=percentile(0.95), P99Ms=percentile(0.99), Frames=count}
    end
    Performance:AddButton({Name="benchmark frame time (5s)", Function=function()
        if benchmarkConnection then return end
        local samples,elapsed={},0
        mainapi:Notify({Text="Measuring 5 seconds. Keep the same camera and scene when comparing.",Duration=5})
        benchmarkConnection=RunService.Heartbeat:Connect(function(dt)
            if dt<=0 then return end
            elapsed+=dt
            samples[#samples+1]=dt
            if elapsed<5 and #samples<10000 then return end
            benchmarkConnection:Disconnect();benchmarkConnection=nil
            local result=summarizeFrameTimes(samples,elapsed)
            mainapi.LastPerformanceBenchmark=result
            local comparison=previousBenchmark and string.format(" | %.2fx vs previous",result.FPS/previousBenchmark.FPS) or ""
            previousBenchmark=result
            mainapi:Notify({Text=string.format("%.0f FPS | avg %.2fms | p95 %.2fms | p99 %.2fms%s",
                result.FPS,result.MeanMs,result.P95Ms,result.P99Ms,comparison),Duration=10})
        end)
    end})
    Performance:AddButton({Name="boost while keeping particles", Function=function()
        NoShadows:Toggle(true)
        NoPostFX:Toggle(true)
        LowQuality:Toggle(true)
        NoAtmosphere:Toggle(true)
    end})

    Performance:AddButton({Name = "quick boost (all)", Function = function()
        NoParticles:Toggle(true)
        NoShadows:Toggle(true)
        NoPostFX:Toggle(true)
        LowQuality:Toggle(true)
        NoAtmosphere:Toggle(true)
    end})

    mainapi:Clean(workspace.DescendantAdded:Connect(function(inst)
        if NoParticles.Enabled then setParticle(inst, true) end
        if NoTextures.Enabled then setTexture(inst, true) end
    end))
    mainapi:Clean(Lighting.DescendantAdded:Connect(function(inst)
        if NoPostFX.Enabled then setPost(inst, true) end
        if NoAtmosphere.Enabled and inst:IsA("Atmosphere") then
            atmoSaved[inst] = inst.Density
            inst.Density = 0
        end
    end))
    mainapi:Clean(function()
        if benchmarkConnection then benchmarkConnection:Disconnect();benchmarkConnection=nil end
        alive=false
        workspaceScanVersion+=1
        for inst in pairs(particleSaved) do setParticle(inst, false) end
        for inst in pairs(textureSaved) do setTexture(inst, false) end
        for inst in pairs(postSaved) do setPost(inst, false) end
        NoShadows.Enabled = false
        LowQuality.Enabled = false
        NoAtmosphere.Enabled = false
        applyShadows()
        applyQuality()
        applyAtmosphere()
    end)
end)

-- END PLEX SOURCE: modules/performance.lua
-- BEGIN PLEX SOURCE: modules/blurry_textures.lua
;(function()
    local overrides={
        DFFlagTextureQualityOverrideEnabled="True",
        DFIntTextureQualityOverride="0",
