    local defaults = {
        Technology = Lighting.Technology,
        EnvironmentDiffuseScale = Lighting.EnvironmentDiffuseScale,
        EnvironmentSpecularScale = Lighting.EnvironmentSpecularScale,
    }
    local extraProperties = {"ShadowSoftness", "LightingStyle", "PrioritizeLightingQuality", "GeographicLatitude"}
    for _, property in ipairs(extraProperties) do
        pcall(function() defaults[property] = Lighting[property] end)
    end

    local applying = false
    local function apply()
        if applying then return end
        applying = true
        local enabled = WorldQuality and WorldQuality.Enabled
        local technology = defaults.Technology
        if enabled and TechEnabled and TechEnabled.Enabled and TechMode then
            pcall(function() technology = Enum.Technology[TechMode.Value] or defaults.Technology end)
        end
        local diffuse = enabled and DiffuseEnabled and DiffuseEnabled.Enabled
            and DiffuseScale and DiffuseScale.Value or defaults.EnvironmentDiffuseScale
        local specular = enabled and SpecularEnabled and SpecularEnabled.Enabled
            and SpecularScale and SpecularScale.Value or defaults.EnvironmentSpecularScale
        pcall(function()
            if Lighting.Technology ~= technology then Lighting.Technology = technology end
        end)
        if Lighting.EnvironmentDiffuseScale ~= diffuse then Lighting.EnvironmentDiffuseScale = diffuse end
        if Lighting.EnvironmentSpecularScale ~= specular then Lighting.EnvironmentSpecularScale = specular end
        if LatitudeValue then
            pcall(function()
                local softness = defaults.ShadowSoftness
                if enabled and SoftnessEnabled.Enabled then softness = SoftnessValue.Value end
                if softness ~= nil and Lighting.ShadowSoftness ~= softness then Lighting.ShadowSoftness = softness end
                local style = defaults.LightingStyle
                if enabled and StyleEnabled.Enabled then style = Enum.LightingStyle[StyleMode.Value] end
                if style ~= nil and Lighting.LightingStyle ~= style then Lighting.LightingStyle = style end
                local priority = defaults.PrioritizeLightingQuality
                if enabled and PriorityEnabled.Enabled then priority = true end
                if priority ~= nil and Lighting.PrioritizeLightingQuality ~= priority then Lighting.PrioritizeLightingQuality = priority end
                local latitude = defaults.GeographicLatitude
                if enabled and LatitudeEnabled.Enabled then latitude = LatitudeValue.Value end
                if latitude ~= nil and Lighting.GeographicLatitude ~= latitude then Lighting.GeographicLatitude = latitude end
            end)
        end
        applying = false
    end

