run(function()
    local Extras
    local Rotate, Speed, Direction, Method, RemoveSun, RemoveMoon, RemoveStars
    local skyState = setmetatable({}, {__mode = "k"})
    local tickValue = 0

    local function getSky()
        return Lighting:FindFirstChild("LionSkybox") or Lighting:FindFirstChildOfClass("Sky")
    end

    local function remember(sky)
        local state = skyState[sky]
        if state then return state end
        state = {Removed = {}, Orientation = sky.SkyboxOrientation, Latitude = Lighting.GeographicLatitude}
        skyState[sky] = state
        return state
    end

    local function setOrientation(sky, value) sky.SkyboxOrientation = value end
    local function setLatitude(value) Lighting.GeographicLatitude = value end

    local function restoreSky(sky)
        local state = sky and skyState[sky]
        if not state then return end
        for property, value in pairs(state.Removed) do
            pcall(function() sky[property] = value end)
        end
        table.clear(state.Removed)
        pcall(setOrientation, sky, state.Orientation)
        pcall(setLatitude, state.Latitude)
    end

    local function sync(sky, state, property, remove, empty)
        local removed = state.Removed
        if remove then
            local current = sky[property]
            if current ~= empty then
                removed[property] = current
                sky[property] = empty
            end
        elseif removed[property] ~= nil then
            sky[property] = removed[property]
            removed[property] = nil
        end
    end

    local function applyStatic()
        local sky = getSky()
        if not sky then return end
        local state = remember(sky)
        sync(sky, state, "SunTextureId", RemoveSun.Enabled, "")
        sync(sky, state, "MoonTextureId", RemoveMoon.Enabled, "")
        sync(sky, state, "StarCount", RemoveStars.Enabled, 0)
        if not Rotate.Enabled and tickValue ~= 0 then
            tickValue = 0
            pcall(setOrientation, sky, state.Orientation)
            pcall(setLatitude, state.Latitude)
        end
    end

    local function updateRotation(dt)
        if not (Extras.Enabled and Rotate.Enabled) then return end
        local sky = getSky()
        if not sky then return end
        remember(sky)
        tickValue += dt * Speed.Value * 0.5
        local angle
        if Method.Value == "Wave" then
            angle = math.sin(tickValue) * 180
        elseif Method.Value == "Alternate" then
            angle = math.abs((tickValue * 40 % 720) - 360) - 180
        else
            angle = (tickValue * 20) % 360
        end
        local rotation = Vector3.zero
        if Direction.Value == "Vertical" then
            rotation = Vector3.new(angle, 0, 0)
        elseif Direction.Value == "Diagonal" then
            rotation = Vector3.new(angle, angle, angle)
        else
            rotation = Vector3.new(0, angle, 0)
        end
        local ok = pcall(setOrientation, sky, rotation)
        if not ok and Direction.Value == "Horizontal" then
            Lighting.GeographicLatitude = angle
        end
    end

-- END PLEX SOURCE: shared/049_world.lua
-- BEGIN PLEX SOURCE: modules/skybox_extras.lua
    Extras = Movement:AddModule({Name = "Skybox Extras", Function = function(enabled)
        if enabled then
            applyStatic()
            local nextStatic = 0
            Extras:Clean(RunService.Heartbeat:Connect(function(dt)
                local now = os.clock()
                if now >= nextStatic then
                    nextStatic = now + 0.2
                    applyStatic()
                end
                updateRotation(dt)
            end))
        else
            for sky in pairs(skyState) do restoreSky(sky) end
            tickValue = 0
        end
    end})
    Rotate = Extras:AddToggle({Name = "skybox rotator"})
    Speed = Extras:AddSlider({Name = "rotation speed", Min = 0, Max = 100, Default = 1, Decimal = 10})
    Direction = Extras:AddDropdown({Name = "direction", List = {"Horizontal", "Vertical", "Diagonal"}, Default = "Horizontal"})
    Method = Extras:AddDropdown({Name = "method", List = {"Spin", "Wave", "Alternate"}, Default = "Spin"})
    RemoveSun = Extras:AddToggle({Name = "remove sun", Function = applyStatic})
    RemoveMoon = Extras:AddToggle({Name = "remove moon", Function = applyStatic})
    RemoveStars = Extras:AddToggle({Name = "remove stars", Function = applyStatic})
end)

