run(function()
    local Textures
    local Material, ApplyViewmodel
    local originals = setmetatable({}, {__mode = "k"})
    local minecraft = setmetatable({}, {__mode = "k"})
    local materialLookup = {}
    local minecraftIds = {
        Wood = "3258599312", WoodPlanks = "8676581022", Brick = "8558400252",
        Cobblestone = "5003953441", Concrete = "7341687607", DiamondPlate = "6849247561",
        Fabric = "118776397", Granite = "4722586771", Grass = "4722588177",
        Ice = "3823766459", Marble = "62967586", Metal = "62967586", Sand = "152572215",
    }
    for _, enumValue in ipairs(Enum.Material:GetEnumItems()) do
        materialLookup[enumValue.Name:lower()] = enumValue
    end

    local function clearMinecraft(part)
        local list = minecraft[part]
        if not list then return end
        for _, obj in ipairs(list) do pcall(function() obj:Destroy() end) end
        minecraft[part] = nil
    end

    local function excluded(part)
        local model = part:FindFirstAncestorOfClass("Model")
        if model and model:FindFirstChildOfClass("Humanoid") then return true end
        local viewmodels = workspace:FindFirstChild("ViewModels")
        local camera = workspace.CurrentCamera
        if ApplyViewmodel and ApplyViewmodel.Enabled then return false end
        return (viewmodels and part:IsDescendantOf(viewmodels)) or (camera and part:IsDescendantOf(camera))
    end

    local function applyPart(part)
        if not (Textures.Enabled and part:IsA("BasePart")) or excluded(part) then return end
        if not originals[part] then originals[part] = {Material = part.Material, Color = part.Color} end
        part.Color = Textures.Value or Color3.fromRGB(244, 244, 244)
        if Material.Value == "Minecraft" then
            clearMinecraft(part)
            local list = {}
            minecraft[part] = list
            local sourceName = originals[part].Material.Name
            local id = minecraftIds[sourceName] or "5003953441"
            for _, face in ipairs(Enum.NormalId:GetEnumItems()) do
                local tex = Instance.new("Texture")
                tex.Texture = "rbxassetid://" .. id
                tex.Face = face
                tex.Color3 = part.Color
                tex.Transparency = part.Transparency
                tex.StudsPerTileU = 3
                tex.StudsPerTileV = 3
                tex.Parent = part
                table.insert(list, tex)
            end
        else
            clearMinecraft(part)
            local key = tostring(Material.Value or "Plastic"):gsub("%s+", ""):lower()
            local selected = materialLookup[key]
            if selected then part.Material = selected end
        end
    end

    local function restore()
        for part, old in pairs(originals) do
            if part and part.Parent then
                pcall(function()
                    part.Material = old.Material
                    part.Color = old.Color
                end)
            end
            clearMinecraft(part)
            originals[part] = nil
        end
    end

    local textureScanVersion = 0
    local function applyAll()
        textureScanVersion += 1
        if not Textures.Enabled then restore(); return end
        local version = textureScanVersion
        task.spawn(function()
            local descendants = workspace:GetDescendants()
            for i, obj in ipairs(descendants) do
                if version ~= textureScanVersion or not Textures.Enabled then return end
                applyPart(obj)
                if i % 500 == 0 then RunService.Heartbeat:Wait() end
            end
        end)
    end

-- END PLEX SOURCE: shared/050_world.lua
-- BEGIN PLEX SOURCE: modules/world_textures.lua
    Textures = Movement:AddModule({
        Name = "World Textures",
        Color = Color3.fromRGB(244, 244, 244),
        Function = function(enabled)
            if enabled then
                applyAll()
                Textures:Clean(workspace.DescendantAdded:Connect(function(obj)
                    task.defer(applyPart, obj)
                end))
            else
                textureScanVersion += 1
                restore()
            end
        end
    })
    Material = Textures:AddDropdown({
        Name = "material",
        List = {"Air", "Asphalt", "Basalt", "Brick", "Cardboard", "Carpet", "Ceramic Tiles", "Clay Roof Tiles", "Cobblestone", "Concrete", "Corroded Metal", "Cracked Lava", "Diamond Plate", "Fabric", "Foil", "ForceField", "Glacier", "Glass", "Granite", "Grass", "Ground", "Ice", "Leafy Grass", "Leather", "Limestone", "Marble", "Metal", "Minecraft", "Mud", "Neon", "Pavement", "Pebble", "Plaster", "Plastic", "Rock", "Roof Shingles", "Rubber", "Salt", "Sand", "Sandstone", "Slate", "Smooth Plastic", "Snow", "Water", "Wood", "Wood Planks"},
        Default = "Brick",
        Function = function() restore(); applyAll() end,
    })
    ApplyViewmodel = Textures:AddToggle({Name = "apply to viewmodel", Function = function() restore(); applyAll() end})
end)

