run(function()
    local Walkspeed, Multiplier
    local baseSpeed
    local applying = false
    local watchedHumanoid
    local speedConnection

    local function disconnectSpeed()
        if speedConnection then
            speedConnection:Disconnect()
            speedConnection = nil
        end
        watchedHumanoid = nil
    end

    local function restore()
        if watchedHumanoid and watchedHumanoid.Parent and baseSpeed then
            applying = true
            watchedHumanoid.WalkSpeed = baseSpeed
            applying = false
        end
    end

    local function bindHumanoid(humanoid)
        if watchedHumanoid == humanoid then return end
        restore()
        disconnectSpeed()
        watchedHumanoid = humanoid
        baseSpeed = humanoid.WalkSpeed
        speedConnection = humanoid:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
            if applying then return end
            local desired = baseSpeed and baseSpeed * Multiplier.Value
            if Walkspeed.Enabled and desired and math.abs(humanoid.WalkSpeed - desired) < 0.05 then return end
            baseSpeed = humanoid.WalkSpeed
        end)
    end

    local function apply()
        local character = LocalPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not humanoid then return end
        bindHumanoid(humanoid)
        if Walkspeed.Enabled then
            local desired = (baseSpeed or humanoid.WalkSpeed) * Multiplier.Value
            if math.abs(humanoid.WalkSpeed - desired) > 0.05 then
                applying = true
                humanoid.WalkSpeed = desired
                applying = false
            end
        end
    end

-- END PLEX SOURCE: shared/053_world.lua
-- BEGIN PLEX SOURCE: modules/walkspeed.lua
    Walkspeed = Player:AddModule({Name = "Walkspeed", Function = function(enabled)
        if enabled then
            Walkspeed:Clean(RunService.Heartbeat:Connect(apply))
            Walkspeed:Clean(LocalPlayer.CharacterAdded:Connect(function(character)
                disconnectSpeed()
                task.defer(function()
                    local humanoid = character:WaitForChild("Humanoid", 5)
                    if humanoid and Walkspeed.Enabled then bindHumanoid(humanoid); apply() end
                end)
            end))
        else
            restore()
            disconnectSpeed()
        end
    end})
    Multiplier = Walkspeed:AddSlider({Name = "multiplier", Min = 1, Max = 10, Default = 1.5, Decimal = 100, Suffix = "x", Function = apply})
    mainapi:Clean(function() restore(); disconnectSpeed() end)
end)

