        if name == "MouseButton1" or name == "MouseButton2" or name == "MouseButton3" then return name, "mouse" end
    end
    local function typingAllowed(settings, kind)
        return kind ~= "keyboard" or settings.Typing or not UserInputService:GetFocusedTextBox()
    end
    local function recolorKey(name)
        local item = keyWidgets[name]
        if not item then return end
        local palette = plexOverlayPalette()
        item.BackgroundColor3 = pressed[name] and palette.accent or (palette.card or palette.surface or palette.bg)
        item.TextColor3 = pressed[name] and Color3.new(1, 1, 1) or palette.text
