        item.BorderSizePixel = 0
        item.Position = UDim2.fromOffset(x, y)
        item.Size = UDim2.fromOffset(width, height)
        item.Text = label
        item.Font = Enum.Font.GothamMedium
        item.TextSize = 11
        item.Parent = parent
        round(item, overlaySettings.Style == "QWERTY" and 4 or 6)
