        stroke.Name = "Outline"
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Transparency = 0.5
        stroke.Parent = item
        keyWidgets[name] = item
    end
    local compactRows = {
        {{"W", "W", 1}},
        {{"A", "A", 0}, {"S", "S", 1}, {"D", "D", 2}},
        {{"LeftShift", "SHIFT", 0}, {"LeftControl", "CTRL", 1}, {"Space", "SPACE", 2}},
    }
    local arrowRows = {
        {{"Up", "↑", 1}},
        {{"Left", "←", 0}, {"Down", "↓", 1}, {"Right", "→", 2}},
        {{"LeftShift", "SHIFT", 0}, {"LeftControl", "CTRL", 1}, {"Space", "SPACE", 2}},
    }
    local fullRows = {
        {{"Escape","ESC",1},{"One","1",1},{"Two","2",1},{"Three","3",1},{"Four","4",1},{"Five","5",1},{"Six","6",1},{"Seven","7",1},{"Eight","8",1},{"Nine","9",1},{"Zero","0",1},{"Backspace","⌫",2}},
        {{"Tab","TAB",1.5},{"Q","Q",1},{"W","W",1},{"E","E",1},{"R","R",1},{"T","T",1},{"Y","Y",1},{"U","U",1},{"I","I",1},{"O","O",1},{"P","P",1},{"BackSlash","\\",1.5}},
        {{"CapsLock","CAPS",1.75},{"A","A",1},{"S","S",1},{"D","D",1},{"F","F",1},{"G","G",1},{"H","H",1},{"J","J",1},{"K","K",1},{"L","L",1},{"Return","ENTER",2.25}},
        {{"LeftShift","SHIFT",2},{"Z","Z",1},{"X","X",1},{"C","C",1},{"V","V",1},{"B","B",1},{"N","N",1},{"M","M",1},{"Comma",",",1},{"Period",".",1},{"RightShift","SHIFT",2}},
        {{"LeftControl","CTRL",1.5},{"LeftAlt","ALT",1.5},{"Space","SPACE",5},{"RightAlt","ALT",1.5},{"RightControl","CTRL",1.5},{"Left","←",1},{"Down","↓",1},{"Up","↑",1},{"Right","→",1}},
    }
    local function buildOverlay()
        if overlay then overlay:Destroy() end
