        title.TextSize = 10
        title.Font = Enum.Font.GothamBold
        title.BackgroundTransparency = 1
        title.Position = UDim2.fromOffset(10, 5)
        title.Size = UDim2.new(1, -20, 0, 18)
        title.Parent = overlayFrame
        local keyboardWidth, keyboardHeight = 0, 0
        if overlaySettings.Keyboard then
            if overlaySettings.Style == "QWERTY" then
                for rowIndex, row in ipairs(fullRows) do
                    local x = 10
                    for _, spec in ipairs(row) do
                        local width = spec[3] * 30 - 4
                        key(overlayFrame, spec[1], spec[2], x, 28 + (rowIndex - 1) * 30, width, 26)
                        x += spec[3] * 30
                    end
                    keyboardWidth = math.max(keyboardWidth, x - 10)
                end
                keyboardHeight = 146
            else
                local rows = overlaySettings.Style == "Arrow keys" and arrowRows or compactRows
                for rowIndex, row in ipairs(rows) do
                    for _, spec in ipairs(row) do key(overlayFrame, spec[1], spec[2], 10 + spec[3] * 46, 28 + (rowIndex - 1) * 40, 40, 34) end
                end
