            key(overlayFrame, "MouseButton2", "RMB", x + 42, 28, 38, 52)
            key(overlayFrame, "MouseButton3", "MMB", x, 84, 80, 30)
        end
        overlayFrame.Size = UDim2.fromOffset(math.max(100, keyboardWidth + mouseWidth + 20), 38 + math.max(keyboardHeight, overlaySettings.Mouse and 86 or 0))
