    function PlexInputExtras:SetOverlay(enabled, settings)
        if enabled and not alive then return end
        overlaySettings = settings
        local layout = enabled and (settings.Style .. tostring(settings.Mouse) .. tostring(settings.Keyboard)) or nil
        if enabled and overlay and overlayLayout == layout then
            overlayFrame.Position = UDim2.fromOffset(settings.X, settings.Y)
