        local prefix = kind == "mouse" and "Mouse" or "Keyboard"
        local selected = settings[prefix .. "Preset"]
        local id = selected == "Custom asset" and tostring(settings[prefix .. "Id"]):match("^%s*(%d+)%s*$") or presets[selected]
        if not id or tonumber(id) == 0 then return end
        lastSoundAt[kind] = now
        local pool = soundPool[kind]
        if not pool then
            pool = {}
            soundPool[kind] = pool
            for index = 1, 4 do
                local sound = Instance.new("Sound")
                sound.Name = "PlexInput" .. prefix
                sound.Parent = game:GetService("SoundService")
                pool[index] = sound
            end
        end
        soundCursor[kind] = (soundCursor[kind] or 0) % #pool + 1
        local sound = pool[soundCursor[kind]]
        sound:Stop()
