            local _, kind = inputName(input)
            if kind and typingAllowed(settings, kind) then self:PlayInputSound(kind, settings) end
        end)
    end
    mainapi:Clean(function()
        alive = false
        PlexInputExtras:SetOverlay(false, overlaySettings)
        PlexInputExtras:SetSounds(false, soundSettings)
    end)
end)()

