local PlexMusicPlayer = {}
;(function()
    local tracks, localAssets, iconAssets = {}, {}, {}
    local gui, panel, sound, equalizer, widgets
    local connections, themeItems = {}, {}
    local current, playing, enabled, minimized, alive = nil, false, false, false, true
    local volume, shuffle, repeatMode, bass, speed = 50, false, "All", false, 1
    local folder, search, page = "Plex/Songs", "", 1
    local generation, progressConnection = 0, nil
    local drawList, refresh, playIndex, build
    local ui = LionLibrary and LionLibrary.NativeUI
    local function connect(signal, callback)
        local connection = signal:Connect(callback)
        connections[#connections + 1] = connection
        return connection
    end
    local function stopProgress()
        if progressConnection then progressConnection:Disconnect(); progressConnection = nil end
    end
    local function timeText(value)
        value = math.max(0, math.floor(value or 0))
        return string.format("%d:%02d", math.floor(value / 60), value % 60)
    end
    local function progress()
        if not widgets or not sound then return end
        local length = sound.TimeLength
        widgets.Time.Text = timeText(sound.TimePosition) .. " / " .. timeText(length)
        widgets.Fill.Size = UDim2.fromScale(length > 0 and math.clamp(sound.TimePosition / length, 0, 1) or 0, 1)
    end
    local function startProgress()
        stopProgress()
        if not playing or minimized then return end
        local elapsed = 0
        progressConnection = RunService.Heartbeat:Connect(function(dt)
            elapsed += dt
            if elapsed < 0.25 then return end
            elapsed %= 0.25
            progress()
        end)
    end
    local function status(text)
        if widgets then widgets.Status.Text = text end
    end
    local function retheme()
        local palette = plexOverlayPalette()
        for _, item in ipairs(themeItems) do
            if item.Object.Parent then item.Object[item.Property] = palette[item.Role] or palette.bg end
        end
        if widgets then
            widgets.Shuffle.Text = shuffle and "shuffle on" or "shuffle"
            widgets.Repeat.Text = "repeat " .. repeatMode:lower()
            widgets.Bass.Text = bass and "bass on" or "bass boost"
        end
    end
    local function themed(object, property, role)
        themeItems[#themeItems + 1] = {Object=object, Property=property, Role=role}
    end
    local function create(class, parent, name, x, y, w, h, text)
        local object = Instance.new(class)
        object.Name, object.BorderSizePixel = name, 0
        object.Position, object.Size = UDim2.fromOffset(x, y), UDim2.fromOffset(w, h)
        if object:IsA("GuiButton") or object:IsA("TextLabel") or object:IsA("TextBox") then
            object.Text, object.TextSize, object.Font = text or "", 12, Enum.Font.GothamMedium
            themed(object, "TextColor3", "text")
        end
        themed(object, "BackgroundColor3", "surface")
        object.Parent = parent
        if not object:IsA("TextLabel") then
            local corner = Instance.new("UICorner")
            corner.CornerRadius, corner.Parent = UDim.new(0, 5), object
        else object.BackgroundTransparency = 1 end
        return object
    end
    local function button(parent, name, x, y, w, text, callback)
        local object = create("TextButton", parent, name, x, y, w, 26, text)
        connect(object.Activated, callback)
        return object
    end
    local function loadIcons()
        if next(iconAssets) then return end
        local loader = getcustomasset or getsynasset
        if type(loader) ~= "function" or type(writefile) ~= "function" or type(makefolder) ~= "function" then return end
        pcall(function()
            if not isfolder("Plex") then makefolder("Plex") end
            if not isfolder("Plex/MusicIcons") then makefolder("Plex/MusicIcons") end
            for name, data in pairs(PlexMusicIcons) do
                local path = "Plex/MusicIcons/v1_" .. name .. ".png"
                if type(isfile) ~= "function" or not isfile(path) then
                    local png = data:gsub("..", function(byte) return string.char(tonumber(byte,16)) end)
                    writefile(path, png)
                end
                iconAssets[name] = loader(path)
            end
        end)
    end
    local function icon(parent, name, size, x, y)
        local object
        if iconAssets[name] then
            object = Instance.new("ImageLabel")
            object.Name, object.Image = "Icon", iconAssets[name]
            object.BackgroundTransparency = 1
            object.Size = UDim2.fromOffset(size, size)
            object.AnchorPoint = Vector2.new(0.5, 0.5)
            object.Parent = parent
            themed(object, "ImageColor3", "text")
        elseif ui and ui.icon then
            local aliases = {play="play_arrow",pause="pause",previous="skip_previous",next="skip_next",minimize="remove",close="close",music="music_note",volume="volume_up",left="left",right="right"}
            object = ui.icon(parent, aliases[name] or name, size)
            if object:IsA("TextLabel") then themed(object,"TextColor3","text") end
        end
        if object then object.Position = x and UDim2.fromOffset(x,y) or UDim2.fromScale(0.5,0.5) end
        return object
    end
    local function iconButton(parent, name, x, y, width, artwork, callback)
        local object = button(parent,name,x,y,width,"",callback)
        icon(object,artwork,16)
        return object
    end
    local function selectedTrack() return current and tracks[current] end
    refresh = function()
        if not widgets then return end
        local track = selectedTrack()
        widgets.Title.Text = track and track.Name or "No song selected"
        widgets.Count.Text = tostring(#tracks) .. " songs"
        if widgets.PlayIcon and widgets.PlayIcon:IsA("ImageLabel") then
            widgets.PlayIcon.Image = iconAssets[playing and "pause" or "play"] or ""
        elseif widgets.PlayIcon then
            widgets.PlayIcon.Text = playing and "pause" or "play_arrow"
        end
        widgets.Volume.Text = "volume  " .. tostring(volume) .. "%"
        widgets.VolumeFill.Size = UDim2.fromScale(volume / 100, 1)
        widgets.Speed.Text = speed == 1 and "normal" or string.format("%.2fx", speed)
        retheme()
        progress()
    end
    function PlexMusicPlayer:Pause()
        if not sound then return end
        sound:Pause(); playing = false
        stopProgress(); refresh()
    end
    playIndex = function(index)
        if not enabled or not sound or not tracks[index] then return end
        generation += 1
        local request = generation
        local track = tracks[index]
        local uri = track.Uri
        if track.Path then
            if not localAssets[track.Path] then
                local loader = getcustomasset or getsynasset
                if type(loader) ~= "function" then status("Local audio unsupported by this executor"); return end
                local ok, result = pcall(loader, track.Path)
                if not enabled or not alive or generation ~= request then return end
                if not ok or type(result) ~= "string" then status("Could not load " .. track.Name); return end
                localAssets[track.Path] = result
            end
            uri = localAssets[track.Path]
        end
        sound:Stop()
        current, playing = index, true
        sound.SoundId, sound.TimePosition = uri, 0
        sound:Play()
        status("Loading audio…")
        startProgress(); refresh(); drawList()
        -- One timeout per explicit track request, never a retry or discovery loop.
        task.delay(12, function()
            if enabled and generation == request and sound and not sound.IsLoaded then
                PlexMusicPlayer:Pause(); status("Audio unavailable or not permitted in this experience")
            end
        end)
    end
    function PlexMusicPlayer:Step(direction, automatic)
        if #tracks == 0 then status("Add an audio ID or refresh the Songs folder"); return end
        if automatic and repeatMode == "One" then playIndex(current or 1); return end
        local nextIndex = (current or (direction > 0 and 0 or 2)) + direction
        if shuffle and #tracks > 1 then
            local offset = math.random(1, #tracks - 1)
            nextIndex = ((current or 1) - 1 + offset) % #tracks + 1
        elseif automatic and nextIndex > #tracks and repeatMode == "Off" then
            playing = false; stopProgress(); refresh(); status("Playlist finished"); return
        end
        playIndex((nextIndex - 1) % #tracks + 1)
    end
    function PlexMusicPlayer:TogglePlayback()
        if not enabled then return end
        if playing then self:Pause()
        elseif selectedTrack() and sound.SoundId ~= "" and (sound.TimeLength == 0 or sound.TimePosition < sound.TimeLength) then
            sound:Resume(); playing = true; startProgress(); refresh()
        else self:Step(1, false) end
    end
    function PlexMusicPlayer:AddAsset(id, name)
        id = tostring(id):match("^%s*(%d+)%s*$")
        if not id or tonumber(id) <= 0 then status("Enter a numeric audio asset ID"); return false end
        local uri = "rbxassetid://" .. id
        for _, track in ipairs(tracks) do if track.Uri == uri then status("Audio already in playlist"); return false end end
        if #tracks >= 200 then status("Playlist limit: 200 songs"); return false end
        name = tostring(name or ""):sub(1, 100)
        tracks[#tracks + 1] = {Name=name ~= "" and name or "Audio " .. id, Uri=uri}
        if drawList then drawList() end
        refresh(); status("Added audio " .. id)
        return true
    end
    function PlexMusicPlayer:RefreshSongs()
        if not enabled then return end
        if type(listfiles) ~= "function" or type(isfolder) ~= "function" then status("Executor file APIs unavailable"); return end
        local ok, files = pcall(function()
            if not isfolder("Plex") then makefolder("Plex") end
            if not isfolder(folder) then makefolder(folder) end
            return listfiles(folder)
        end)
        if not ok or type(files) ~= "table" then status("Cannot read " .. folder); return end
        -- Preserve assets and active local track identity while refreshing the explicit snapshot.
        local active = selectedTrack()
        local nextTracks = {}
        for _, track in ipairs(tracks) do if not track.Path then nextTracks[#nextTracks + 1] = track end end
        table.sort(files)
        for _, path in ipairs(files) do
            local normalized = path:gsub("\\", "/")
            local extension = normalized:match("%.([^%.]+)$")
            if extension and ({mp3=true, ogg=true, wav=true})[extension:lower()] and #nextTracks < 200 then
                local name = normalized:match("([^/]+)$")
                nextTracks[#nextTracks + 1] = {Name=name, Path=path}
            end
        end
        tracks, current = nextTracks, nil
        for index, track in ipairs(tracks) do
            if active and (track == active or (track.Path and track.Path == active.Path)) then current = index; break end
        end
        if active and not current then sound:Stop(); playing = false; stopProgress() end
        page = 1; drawList(); refresh(); status("Songs folder refreshed · " .. folder)
    end
    drawList = function()
        if not widgets then return end
        local matches = {}
        for index, track in ipairs(tracks) do
            if track.Name:lower():find(search, 1, true) then matches[#matches + 1] = index end
        end
        local pages = math.max(1, math.ceil(#matches / 8))
        page = math.clamp(page, 1, pages)
        widgets.Page.Text = tostring(page) .. " / " .. tostring(pages)
        for slot, row in ipairs(widgets.Rows) do
            local index = matches[(page - 1) * 8 + slot]
            row.Index = index
            row.Button.Visible = index ~= nil
            if index then row.Button.Text = (index == current and "Playing · " or "    ") .. tracks[index].Name end
        end
        widgets.Empty.Visible = #matches == 0
    end
    build = function()
        loadIcons()
        gui = Instance.new("ScreenGui")
        gui.Name, gui.ResetOnSpawn, gui.IgnoreGuiInset = "PlexMusicPlayer", false, true
        gui.DisplayOrder = mainapi.MainScreenGui.DisplayOrder + 2
        gui.Parent = mainapi.MainScreenGui.Parent
        panel = create("Frame", gui, "MusicPlayer", 24, 100, 300, 514)
        themed(panel, "BackgroundColor3", "pop")
        panel.Active = true
        local stroke = Instance.new("UIStroke"); stroke.Thickness = 1; stroke.Parent = panel
        themed(stroke, "Color", "edge")
        local header = create("TextLabel", panel, "Header", 12, 0, 174, 34, "       Music Player")
        icon(header,"music",17,10,17)
        header.TextXAlignment, header.Active = Enum.TextXAlignment.Left, true
        widgets = {Rows={}}
        widgets.Count = create("TextLabel", panel, "Count", 174, 0, 60, 34, "0 songs")
        iconButton(panel, "Minimize", 238, 4, 26, "minimize", function()
            minimized = not minimized
            panel.Size = UDim2.fromOffset(300, minimized and 34 or 514)
            for _, child in ipairs(panel:GetChildren()) do
                if child:IsA("GuiObject") and child ~= header and child ~= widgets.Count and child.Name ~= "Minimize" and child.Name ~= "Close" then child.Visible = not minimized end
            end
            if not minimized then drawList() end
            startProgress()
        end)
        iconButton(panel, "Close", 268, 4, 26, "close", function() mainapi.Modules["Music Player"]:Toggle(false) end)
        widgets.Title = create("TextLabel", panel, "TrackTitle", 12, 38, 276, 26, "No song selected")
        widgets.Title.TextTruncate = Enum.TextTruncate.AtEnd
        widgets.Time = create("TextLabel", panel, "Time", 12, 65, 276, 20, "0:00 / 0:00")
        local seek = button(panel, "Seek", 12, 88, 276, "", function() end)
        seek.Size = UDim2.fromOffset(276, 8)
        widgets.Fill = create("Frame", seek, "Fill", 0, 0, 0, 8)
        themed(widgets.Fill, "BackgroundColor3", "accent")
        connect(seek.InputBegan, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                if sound.TimeLength > 0 then sound.TimePosition = math.clamp((input.Position.X-seek.AbsolutePosition.X)/seek.AbsoluteSize.X, 0, 1)*sound.TimeLength; progress() end
            end
        end)
        iconButton(panel, "Previous", 88, 106, 34, "previous", function() PlexMusicPlayer:Step(-1) end)
        widgets.Play = button(panel, "Play", 132, 106, 36, "", function() PlexMusicPlayer:TogglePlayback() end)
        widgets.PlayIcon = icon(widgets.Play,"play",18)
        themed(widgets.Play, "BackgroundColor3", "accent")
        iconButton(panel, "Next", 178, 106, 34, "next", function() PlexMusicPlayer:Step(1) end)
        widgets.Volume = create("TextLabel", panel, "VolumeText", 12, 140, 276, 20)
        icon(widgets.Volume,"volume",15,68,10)
        local volumeBar = button(panel, "Volume", 12, 164, 276, "", function() end)
        volumeBar.Size = UDim2.fromOffset(276, 10)
        widgets.VolumeFill = create("Frame", volumeBar, "Fill", 0, 0, 0, 10)
        themed(widgets.VolumeFill, "BackgroundColor3", "accent")
        local draggingVolume, dragInput, dragStart, panelStart
        local function setVolume(input)
            PlexMusicPlayer:SetVolume(math.floor(math.clamp((input.Position.X-volumeBar.AbsolutePosition.X)/volumeBar.AbsoluteSize.X, 0, 1)*100+0.5))
        end
        connect(volumeBar.InputBegan, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then draggingVolume=input; setVolume(input) end
        end)
        connect(header.InputBegan, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragInput=input; dragStart=input.Position; panelStart=panel.Position end
        end)
        connect(UserInputService.InputChanged, function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
            if draggingVolume and (draggingVolume.UserInputType ~= Enum.UserInputType.Touch or draggingVolume == input) then setVolume(input) end
            if dragInput and (dragInput.UserInputType ~= Enum.UserInputType.Touch or dragInput == input) then
                local delta = input.Position - dragStart
                local camera = workspace.CurrentCamera
                local size = camera and camera.ViewportSize or Vector2.new(1920,1080)
                panel.Position = UDim2.fromOffset(math.clamp(panelStart.X.Offset+delta.X,0,math.max(0,size.X-300)),math.clamp(panelStart.Y.Offset+delta.Y,0,math.max(0,size.Y-34)))
            end
        end)
        connect(UserInputService.InputEnded, function(input)
            if input == draggingVolume or input.UserInputType == Enum.UserInputType.MouseButton1 then draggingVolume=nil end
            if input == dragInput or input.UserInputType == Enum.UserInputType.MouseButton1 then dragInput=nil end
        end)
        widgets.Shuffle = button(panel,"Shuffle",12,184,64,"shuffle",function() shuffle=not shuffle; refresh() end)
        widgets.Repeat = button(panel,"Repeat",80,184,76,"repeat all",function() repeatMode=({All="One",One="Off",Off="All"})[repeatMode]; refresh() end)
        widgets.Bass = button(panel,"Bass",160,184,66,"bass boost",function() bass=not bass; equalizer.Enabled=bass; refresh() end)
        widgets.Speed = button(panel,"Speed",230,184,58,"normal",function() speed=speed==1 and 0.75 or (speed==0.75 and 1.25 or 1); sound.PlaybackSpeed=speed; refresh() end)
        local box = create("TextBox",panel,"Search",12,220,276,26,"")
        box.PlaceholderText, box.ClearTextOnFocus = "Search songs…", false
        local searchPadding=Instance.new("UIPadding"); searchPadding.PaddingLeft=UDim.new(0,28); searchPadding.Parent=box
        box.TextXAlignment=Enum.TextXAlignment.Left
        icon(box,"search",15,14,13)
        connect(box:GetPropertyChangedSignal("Text"),function() search=box.Text:lower(); page=1; drawList() end)
        for slot=1,8 do
            local row={}
            row.Button=button(panel,"Song"..slot,12,252+(slot-1)*22,276,"",function() if row.Index then playIndex(row.Index) end end)
            row.Button.Size=UDim2.fromOffset(276,20)
            row.Button.TextXAlignment, row.Button.TextTruncate = Enum.TextXAlignment.Left, Enum.TextTruncate.AtEnd
            widgets.Rows[slot]=row
        end
        widgets.Empty=create("TextLabel",panel,"Empty",12,275,276,110,"No songs yet\n\nDrop MP3 / OGG / WAV files into\nworkspace / Plex / Songs\nthen press Refresh Songs")
        widgets.Empty.TextSize=11
        iconButton(panel,"PageBack",12,432,34,"left",function() page=math.max(1,page-1); drawList() end)
        widgets.Page=create("TextLabel",panel,"Page",52,432,196,26,"1 / 1")
        iconButton(panel,"PageNext",254,432,34,"right",function() page+=1; drawList() end)
        local refreshButton=button(panel,"Refresh",12,464,276,"Refresh Songs",function() PlexMusicPlayer:RefreshSongs() end)
        icon(refreshButton,"refresh",15,64,13)
        widgets.Status=create("TextLabel",panel,"Status",12,492,276,18,"")
        widgets.Status.TextSize, widgets.Status.TextTruncate=10,Enum.TextTruncate.AtEnd
        if ui and ui.onThemeChanged then connections[#connections+1]=ui.onThemeChanged(retheme) end
        drawList(); refresh()
    end
    function PlexMusicPlayer:SetVolume(value)
        volume=math.clamp(tonumber(value) or 50,0,100)
        if sound then sound.Volume=volume/100 end
        refresh()
    end
    function PlexMusicPlayer:SetEnabled(value)
        if value and (not alive or enabled) then return end
        enabled=value
        generation+=1
        if not value then
            playing=false; minimized=false; stopProgress()
            for _, connection in ipairs(connections) do
                if type(connection)=="function" then connection() else connection:Disconnect() end
            end
            table.clear(connections); table.clear(themeItems)
            if sound then sound:Destroy() end
            if gui then gui:Destroy() end
            sound, equalizer, gui, panel, widgets = nil,nil,nil,nil,nil
            return
        end
        sound=Instance.new("Sound")
        sound.Name, sound.Volume, sound.PlaybackSpeed="PlexMusic",volume/100,speed
        sound.Parent=game:GetService("SoundService")
        equalizer=Instance.new("EqualizerSoundEffect")
        equalizer.Name,equalizer.LowGain,equalizer.Enabled="PlexBass",6,bass
        equalizer.Parent=sound
        connect(sound.Ended,function() if enabled and playing then PlexMusicPlayer:Step(1,true) end end)
        connect(sound.Loaded,function() if enabled then status("Ready"); progress() end end)
        build()
    end
    mainapi:Clean(function() alive=false; PlexMusicPlayer:SetEnabled(false); table.clear(tracks); table.clear(localAssets) end)
end)()

