-- BEGIN PLEX SOURCE: modules/music_player.lua
run(function()
    local id, title = "", ""
    local player = Other:AddModule({Name="Music Player", Function=function(enabled) PlexMusicPlayer:SetEnabled(enabled) end})
    player:AddLabel({Text="Floating playlist · local files or Roblox audio"})
    player:AddLabel({Text="Local folder: workspace / Plex / Songs"})
    player:AddInputBox({Name="audio asset id", Default="", Numeric=true, Function=function(value) id=value end})
    player:AddInputBox({Name="song name", Default="", Function=function(value) title=value end})
    player:AddButton({Name="add audio to playlist", Function=function() PlexMusicPlayer:AddAsset(id,title) end})
    player:AddButton({Name="refresh local songs", Function=function() PlexMusicPlayer:RefreshSongs() end})
    player:AddSlider({Name="volume", Min=0, Max=100, Default=50, Suffix="%", Function=function(value) PlexMusicPlayer:SetVolume(value) end})
end)

