-- BEGIN PLEX SOURCE: modules/enemy_ranks.lua
run(function()
    local EnemyRanks
    local cache, avatars, rows, pending = {}, {}, {}, {}
    local panel, list, empty, title, stroke, headerLine, season, profileRemote
    local generation = 0
    local fields = {avatar=true, level=true, rank=true, elo=true, streak=true, wins=false}
    local enemiesOnly = false
    local fetch
    local nativeUI = LionLibrary and LionLibrary.NativeUI

    local function eligible(player)
        return player ~= LocalPlayer and (not enemiesOnly or LocalPlayer.Neutral or player.Neutral or player.Team ~= LocalPlayer.Team)
    end

    local function theme()
        if not panel then return end
        local colors = plexOverlayPalette()
        local fonts = nativeUI and nativeUI.F
        panel.BackgroundColor3 = colors.pop or colors.bg
        panel.BackgroundTransparency=0.04
        if headerLine then headerLine.BackgroundColor3=colors.accent end
        stroke.Color = colors.edge
        title.TextColor3 = colors.text
        empty.TextColor3 = colors.dim or colors.muted
        list.ScrollBarImageColor3 = colors.accent
        if fonts then title.FontFace = fonts.semibold or fonts.medium or fonts.body end
        for _, row in pairs(rows) do
            row.Title.TextColor3 = colors.text
            row.Frame.BackgroundColor3=colors.surface or colors.bg
            row.Details.TextColor3 = colors.dim or colors.muted
            if fonts then row.Title.FontFace = fonts.medium or fonts.body; row.Details.FontFace = fonts.body end
        end
    end

    local function resize()
        if not panel then return end
        local count=0
        for _, row in pairs(rows) do if row.Frame.Visible then count+=1 end end
        empty.Visible=count==0
        empty.Text=enemiesOnly and "No enemies in this server" or "No other players in this server"
        panel.Size=UDim2.fromOffset(360,42+math.max(1,math.min(count,8))*68)
    end

    local function updateRow(player)
        local row=rows[player]
        if not row then return end
        row.Frame.Visible=eligible(player)
        local saved=cache[player.UserId] or {}
        local elo=tonumber(player:GetAttribute("DisplayELO")) or saved.ELO
        local rank="Unknown"
        if elo~=nil then
            local ok,name=pcall(season.GetRank,season,elo,player.UserId)
            if ok and name then rank=name end
        elseif saved.Unranked then rank="Unranked" end
        local ranks=season.CurrentSeason and season.CurrentSeason.RankProfile and season.CurrentSeason.RankProfile.Ranks
        local rankInfo=ranks and ranks[rank]
        row.RankIcon.Image=rankInfo and rankInfo.Image or ""
        row.RankIcon.Visible=fields.rank
        row.RankIcon.Position=fields.avatar and UDim2.fromOffset(38,39) or UDim2.fromOffset(8,29)
        row.Avatar.Visible=fields.avatar
        row.Avatar.Image=avatars[player.UserId] or ""
        local textX=fields.avatar and 60 or 10
        row.Title.Position=UDim2.fromOffset(textX,5)
        row.Title.Size=UDim2.new(1,-textX-8,0,20)
        local detailsX=not fields.avatar and fields.rank and 30 or textX
        row.Details.Position=UDim2.fromOffset(detailsX,27)
        row.Details.Size=UDim2.new(1,-detailsX-8,0,32)
        row.Title.Text=player.DisplayName.." (@"..player.Name..")"
        local details={}
        if fields.level then table.insert(details,"Level "..tostring(player:GetAttribute("Level") or saved.Level or "?")) end
        if fields.rank then table.insert(details,rank) end
        if fields.elo then table.insert(details,elo and elo>=0 and tostring(math.floor(elo)).." ELO" or "ELO ?") end
        if fields.streak then table.insert(details,"Streak "..tostring(player:GetAttribute("StatisticDuelsWinStreak") or "?")) end
        if fields.wins then table.insert(details,"Wins "..tostring(saved.CasualWins or "?").." / Ranked "..tostring(saved.RankedWins or "?")) end
        row.Details.Text=table.concat(details,"  Â·  ")
        resize()
    end

    local function updateAllRows()
        for player in pairs(rows) do updateRow(player) end
    end

    -- Queue work once per join/enable/manual refresh, never from row rendering.
    local function queuePlayer(player)
        if not rows[player] then return end
        local saved=cache[player.UserId]
        if (not saved or saved.Pending) or (fields.avatar and not avatars[player.UserId]) then
            if pending[player] then return end
            pending[player]=true
            local token=generation
            task.defer(function()
                if token~=generation or not EnemyRanks.Enabled then return end
                pending[player]=nil
                fetch(player,token)
            end)
        end
    end

    fetch = function(player,token)
        local row=rows[player]
        if token~=generation or not EnemyRanks.Enabled or not row then return end
        local userId=player.UserId
        local saved=cache[userId]
        if not saved then
            local request={Pending=true}
            cache[userId]=request
            task.spawn(function()
                local ok,data=pcall(profileRemote.InvokeServer,profileRemote,player)
                if token~=generation or rows[player]~=row or cache[userId]~=request or not EnemyRanks.Enabled then return end
                cache[userId]=ok and type(data)=="table" and {
                    ELO=tonumber(data.RankedCurrentELO),Unranked=(tonumber(data.RankedWins) or 0)==0,
                    Level=tonumber(data.Level),CasualWins=tonumber(data.CasualWins),RankedWins=tonumber(data.RankedWins),
                } or {Failed=true}
                updateRow(player)
            end)
        end
        if fields.avatar and not avatars[userId] and not row.AvatarPending then
            row.AvatarPending=true
            task.spawn(function()
                local ok,image=pcall(Players.GetUserThumbnailAsync,Players,userId,Enum.ThumbnailType.HeadShot,Enum.ThumbnailSize.Size100x100)
                if token~=generation or rows[player]~=row or not EnemyRanks.Enabled then return end
                row.AvatarPending=false
                avatars[userId]=ok and image or ""
                updateRow(player)
            end)
        end
    end

    local function addPlayer(player)
        if player==LocalPlayer or rows[player] then return end
        local frame=Instance.new("Frame")
        frame.BackgroundTransparency=0.08
        frame.BorderSizePixel=0
        local cardCorner=Instance.new("UICorner");cardCorner.CornerRadius=UDim.new(0,6);cardCorner.Parent=frame
        frame.Size=UDim2.new(1,-8,0,64)
        frame.LayoutOrder=player.UserId%2147483647
        frame.Parent=list
        local avatar=Instance.new("ImageLabel")
        avatar.BackgroundTransparency=1
        avatar.Size=UDim2.fromOffset(42,42)
        avatar.Position=UDim2.fromOffset(8,10)
        avatar.Parent=frame
        local corner=Instance.new("UICorner"); corner.CornerRadius=UDim.new(0,8); corner.Parent=avatar
        local rankIcon=Instance.new("ImageLabel")
        rankIcon.BackgroundTransparency=1
        rankIcon.Size=UDim2.fromOffset(16,16)
        rankIcon.Position=UDim2.fromOffset(38,39)
        rankIcon.Parent=frame
        local function label(size)
            local object=Instance.new("TextLabel")
            object.BackgroundTransparency=1
            object.Font=Enum.Font.Gotham
            object.TextSize=size
            object.TextXAlignment=Enum.TextXAlignment.Left
            object.TextYAlignment=Enum.TextYAlignment.Top
            object.TextWrapped=true
            object.Parent=frame
            return object
        end
        rows[player]={Frame=frame,Avatar=avatar,RankIcon=rankIcon,Title=label(12),Details=label(11),Connections={}}
        for _,property in ipairs({"Team","Neutral","DisplayName"}) do
            table.insert(rows[player].Connections,player:GetPropertyChangedSignal(property):Connect(function() updateRow(player) end))
        end
        for _,attribute in ipairs({"DisplayELO","Level","StatisticDuelsWinStreak"}) do
            table.insert(rows[player].Connections,player:GetAttributeChangedSignal(attribute):Connect(function() updateRow(player) end))
        end
        updateRow(player)
        theme()
        queuePlayer(player)
    end

    local function removePlayer(player)
        local row=rows[player]
        if not row then return end
        for _,connection in ipairs(row.Connections) do connection:Disconnect() end
        row.Frame:Destroy()
        rows[player]=nil
        pending[player]=nil
        if cache[player.UserId] and cache[player.UserId].Pending then cache[player.UserId]=nil end
        resize()
    end

    -- Keep the legacy module name so saved toggle/keybind IDs remain valid.
    EnemyRanks=Other:AddModule({Name="Enemy Ranks",Function=function(enabled)
        generation+=1
        if not enabled then return end
        local ok,result=pcall(function() return require(ReplicatedStorage.Modules.SeasonLibrary) end)
        if not ok then return end
        season=result
        profileRemote=ReplicatedStorage.Remotes.Misc.RequestProfile
        panel=Instance.new("Frame")
        panel.Name="PlexLobbyInfo"
        panel.AnchorPoint=Vector2.new(1,0)
        panel.Position=UDim2.new(1,-18,0,92)
        panel.Size=UDim2.fromOffset(360,102)
