run(function()
    local feature, native, request, oldDetails, oldSetELO
    local detailsWrapper, eloWrapper
    local cache, pending = {}, {}
    local slots=setmetatable({}, {__mode="k"})
    local generation=0
    local display={rank=true,level=true,platform=true,avatar=true,streak=true}
    local function record(slot)
        local saved=slots[slot]
        if not saved then
            saved={Had=slot._display_elo_set,ELO=slot._display_elo,Properties=setmetatable({}, {__mode="k"})}
            slots[slot]=saved
        end
        return saved
    end
    local function ownProperty(saved,object,key,value)
        local properties=saved.Properties[object]
        if not properties then properties={};saved.Properties[object]=properties end
        local entry=properties[key]
        if not entry then entry={Original=object[key]};properties[key]=entry
        elseif object[key]~=entry.Applied then entry.Original=object[key] end
        entry.Applied=value
        if object[key]~=value then object[key]=value end
    end
    local function presentation(slot)
        if not feature.Enabled or mainapi.Uninjecting or slot._destroyed or slot._user_id==LocalPlayer.UserId then return end
        local frame=slot.SlotFrame
        local container=frame and frame:FindFirstChild("Container")
        local avatar=container and container:FindFirstChild("Headshot")
        if not avatar then return end
        local saved=record(slot)
        ownProperty(saved,avatar,"Visible",display.avatar)
        if saved.Container~=container then
            saved.Container=container
            saved.Widgets={
                {container:FindFirstChild("Rank"),nil,18},
                {container:FindFirstChild("Level"),nil,22},
                {container:FindFirstChild("Controls"),nil,16},
            }
        end
        local widgets=saved.Widgets
        widgets[1][2]=display.rank and slot._display_elo_set==true
        widgets[2][2]=display.level and tonumber(slot._level)~=nil
        widgets[3][2]=display.platform
        local count=0
        for _,widget in ipairs(widgets) do if widget[1] and widget[2] then count+=1 end end
        local index=0
        for _,widget in ipairs(widgets) do
            local object,visible,size=widget[1],widget[2],widget[3]
            if object then
                ownProperty(saved,object,"Visible",visible==true)
                if visible then
                    index+=1
                    local x,y=avatar.Position.X,avatar.Position.Y
                    local w,h=avatar.Size.X,avatar.Size.Y
                    ownProperty(saved,object,"AnchorPoint",Vector2.new(0.5,0.5))
                    ownProperty(saved,object,"Position",UDim2.new(
                        x.Scale+w.Scale*(0.5-avatar.AnchorPoint.X),x.Offset+w.Offset*(0.5-avatar.AnchorPoint.X)+(index-(count+1)/2)*26,
                        y.Scale+h.Scale*(1-avatar.AnchorPoint.Y),y.Offset+h.Offset*(1-avatar.AnchorPoint.Y)))
                    ownProperty(saved,object,"Size",UDim2.fromOffset(size,size))
                    ownProperty(saved,object,"ZIndex",avatar.ZIndex+2)
                end
            end
        end
        local streak=container:FindFirstChild("Streak")
        if streak then ownProperty(saved,streak,"Visible",display.streak and streak.Visible) end
    end
    local function restore()
        generation+=1
        if native then
            if native._UpdateDetails==detailsWrapper then native._UpdateDetails=oldDetails end
            if native.SetDisplayELO==eloWrapper then native.SetDisplayELO=oldSetELO end
            for slot,saved in pairs(slots) do
                if not slot._destroyed then
                    if saved.Applied~=nil and slot._display_elo==saved.Applied then pcall(oldSetELO,slot,saved.Had and saved.ELO or nil) end
                    if saved.LevelCaptured and slot._level==saved.AppliedLevel then slot._level=saved.Level end
                    pcall(oldDetails,slot)
                    for object,properties in pairs(saved.Properties) do
                        if object.Parent then for key,entry in pairs(properties) do
                            if object[key]==entry.Applied then object[key]=entry.Original end
                        end end
                    end
                end
            end
        end
        table.clear(slots)
        table.clear(pending)
    end
    local function apply(slot,data)
        if not feature.Enabled or mainapi.Uninjecting or slot._destroyed or type(data)~="table" then return end
        local saved=record(slot)
        local elo=data.ELO
        if type(elo)=="number" and (not slot._display_elo_set or saved.Applied~=nil) then
            if saved.Applied~=elo or slot._display_elo~=elo then saved.Applied=elo;oldSetELO(slot,elo) end
        end
        if (tonumber(slot._level) or 0)<1 and type(data.Level)=="number" then
            saved.LevelCaptured=true;saved.Level=slot._level;saved.AppliedLevel=data.Level
            slot._level=data.Level
        end
    end
    local function requested(slot)
        if not feature.Enabled or mainapi.Uninjecting or slot._destroyed then return end
        local userId=slot._user_id
        if not userId or userId==LocalPlayer.UserId then return end
        if slot._display_elo_set and (tonumber(slot._level) or 0)>0 and not (slots[slot] and slots[slot].Applied~=nil) then return end
        local data=cache[userId]
        if data~=nil then apply(slot,data); return end
        if pending[userId] then pending[userId][slot]=true; return end
        local player=Players:GetPlayerByUserId(userId)
        if not player then return end
        local waiting=setmetatable({[slot]=true},{__mode="k"})
        pending[userId]=waiting
        local token=generation
        task.spawn(function()
            local ok,profile=pcall(request.InvokeServer,request,player)
            if token~=generation or not feature.Enabled then return end
            pending[userId]=nil
            local value=ok and type(profile)=="table" and {ELO=tonumber(profile.RankedCurrentELO),Level=tonumber(profile.Level)}
            cache[userId]=value or false
            if value then
                for target in pairs(waiting) do
                    if not target._destroyed then apply(target,value); pcall(oldDetails,target); presentation(target) end
                end
            end
        end)
    end
    feature=Other:AddModule({Name="Bring Back Enemy Ranks",Function=function(enabled)
        if not enabled then restore(); return end
        native=require(LocalPlayer.PlayerScripts.Modules.TeammateSlot)
        request=ReplicatedStorage.Remotes.Misc.RequestProfile
        oldDetails=native._UpdateDetails
        oldSetELO=native.SetDisplayELO
        detailsWrapper=function(self,...)
            requested(self)
            local result=oldDetails(self,...)
            presentation(self)
            return result
        end
        eloWrapper=function(self,elo,...)
            -- Preserve a newer native value instead of restoring an obsolete one.
            if slots[self] then slots[self].Applied=nil;slots[self].Had=elo~=nil;slots[self].ELO=elo end
            local result=oldSetELO(self,elo,...)
            if elo==nil then requested(self) end
            presentation(self)
            return result
        end
        native._UpdateDetails=detailsWrapper
        native.SetDisplayELO=eloWrapper
        feature:Clean(restore)
    end})
    for _,spec in ipairs({{"rank icon","rank"},{"native level","level"},{"platform icon","platform"},{"profile picture","avatar"},{"win streak","streak"}}) do
        feature:AddToggle({Name="show "..spec[1],Default=true,Function=function(value)
            display[spec[2]]=value==true
            if feature.Enabled then for slot in pairs(slots) do
                if not slot._destroyed then pcall(oldDetails,slot);presentation(slot) end
            end end
        end})
    end
    feature:AddLabel({Text="Uses native teammate rank icons. Profiles are fetched once, only when the client requests a slot update."})
end)

