run(function()
    local RankedPreview
    RankedPreview = Other:AddModule({Name = "Ranked Access Preview", Function = function(enabled)
        if not enabled then return end
        local module = LocalPlayer.PlayerScripts.Modules.Pages:FindFirstChild("Ranked")
        local ok, page = pcall(function() return module and require(module) end)
        local locked = ok and page and page.Locked and page.Locked.LockedFrame
        local unlocked = ok and page and page.UnlockedFrame
        if not (locked and unlocked) then
            mainapi:Notify({Text = "The ranked page is unavailable.", Duration = 3})
            return
        end
        local originalLocked, originalUnlocked = locked.Visible, unlocked.Visible
        local updating = false
        local function refreshPreview()
            if updating or not RankedPreview.Enabled then return end
            updating = true
            local identity = getthreadidentity and getthreadidentity()
            if setthreadidentity then pcall(setthreadidentity, 8) end
            pcall(function()
                locked.Visible = false
                unlocked.Visible = true
            end)
            if identity and setthreadidentity then pcall(setthreadidentity, identity) end
            updating = false
        end
        local lockedConnection = locked:GetPropertyChangedSignal("Visible"):Connect(refreshPreview)
        local unlockedConnection = unlocked:GetPropertyChangedSignal("Visible"):Connect(refreshPreview)
        RankedPreview:Clean(function()
            lockedConnection:Disconnect()
            unlockedConnection:Disconnect()
            pcall(function()
                locked.Visible, unlocked.Visible = originalLocked, originalUnlocked
            end)
        end)
        refreshPreview()
    end})
    RankedPreview:AddLabel({Text = "Visual preview. Ranked eligibility stays controlled by the server."})
end)

