run(function()
local function checkhooks()
    local modules = mainapi and mainapi.Modules
    local issues = {}
    local checked = 0

    if type(modules) ~= "table" then
        issues[#issues + 1] = "module registry is unavailable"
    else
        for name, module in pairs(modules) do
            checked += 1
            if type(module) ~= "table" then
                issues[#issues + 1] = tostring(name) .. " is not a module table"
            else
                if type(name) ~= "string" or name == "" or module.Name ~= name then
                    issues[#issues + 1] = tostring(name) .. " has a missing or mismatched name"
                end
                if type(module.Function) ~= "function" then
                    issues[#issues + 1] = tostring(name) .. " has no callback function"
                end
                if type(module.Connections) ~= "table" then
                    issues[#issues + 1] = tostring(name) .. " has no cleanup-hook list"
                else
                    for hookId, hook in pairs(module.Connections) do
                        local ok, disconnect = pcall(function()
                            return hook.Disconnect
                        end)
                        if not ok or type(disconnect) ~= "function" then
                            issues[#issues + 1] = tostring(name) .. " has an invalid cleanup hook at " .. tostring(hookId)
                        end
                    end
                end
            end
        end
    end

    if checked == 0 then
        issues[#issues + 1] = "no modules were registered"
    end

    if #issues == 0 then
        print("[Plex] Hook check passed for " .. tostring(checked) .. " modules")
        if mainapi and type(mainapi.Notify) == "function" then
            mainapi:Notify({Text = "Hook check passed for " .. tostring(checked) .. " modules", Duration = 3})
        end
    else
        for _, issue in ipairs(issues) do
            warn("[Plex] Hook check: " .. issue)
        end
        if mainapi and type(mainapi.Notify) == "function" then
            mainapi:Notify({Text = "Hook check found " .. tostring(#issues) .. " issue(s)", Duration = 4})
        end
    end

    return #issues == 0, issues, checked
end

local CheckHooks = Other:AddModule({Name = "Check Hooks", HideEnabled = true})
local SettingsChecks = LionTabs.settings:AddLeftGroupbox("diagnostics")
SettingsChecks:AddButton({Text = "check hooks", Func = checkhooks})
end)

