-- BEGIN PLEX SOURCE: shared/062_weapon_profiles.lua
-- Per-feature editors share persistent defaults and weapon overrides.
run(function()
    local profiles={Version=2,Enabled=false,Features={},Defaults={}}
    local baseline,active,connections,selectors,selections={},{},{},{},{}
    local currentWeapon,controllerConnection
    local started,applying,ready,generation=false,false,false,0
    local function copy(value) return HttpService:JSONDecode(HttpService:JSONEncode(value)) end
    local function eligible(name) return mainapi.Modules[name] and name~="Uninject" and name~="Interface" end
    local api={}
    function api:Capture(name)
        local module=mainapi.Modules[name]
        assert(eligible(name), "Choose a feature")
        local record={Enabled=module.Enabled,Settings={}}
        for _,setting in pairs(module.Settings) do if setting.Save and not setting.WeaponProfileControl then setting:Save(record.Settings) end end
        if module.Bind then record.Bind=module.Bind.Name end
        local key=module.KeyPickerId and Options[module.KeyPickerId]
        record.Mode=key and key.Mode
        if module.Colors or module.Value then
            record.Colors={}
            for i,color in ipairs(module.Colors or {module.Value}) do
                record.Colors[i]={R=color.R,G=color.G,B=color.B,Transparency=module.ColorTransparency and module.ColorTransparency[i]}
            end
        end
        return copy(record)
    end
    function api:Apply(name, record)
        local module=mainapi.Modules[name]
        if not eligible(name) or type(record)~="table" then return end
        -- Load synchronously updates widget values; the normal setting callback
        -- owns the feature effect. Enable after the complete settings are ready.
        for settingName,value in pairs(record.Settings or {}) do
            local setting=module.Settings[settingName]
            if setting and setting.Load then setting:Load(value) end
        end
        for i,color in ipairs(record.Colors or {}) do
            local id=lionId("Color",name,"enabled",module.Colors and tostring(i) or nil)
            local option=Options[id]
            if option and option.SetValueRGB then option:SetValueRGB(Color3.new(color.R,color.G,color.B),color.Transparency) end
        end
        module:SetBind(record.Bind or "None")
        local key=module.KeyPickerId and Options[module.KeyPickerId]
        module:Toggle(record.Mode=="Always" or (record.Mode~="Never" and record.Enabled==true))
        -- Persistent modes own the final state. In particular Hold must remain
        -- inactive until its input is pressed, even if a preset was saved held.
        if key and record.Mode and key.SetMode then key:SetMode(record.Mode) end
    end
    local function defaultFor(name)
        return profiles.Defaults[name] or baseline[name]
    end
    local function hasOverrides()
        for _,records in pairs(profiles.Features) do if next(records) then return true end end
        return false
    end
    local function setSelector(name,selection)
        selections[name]=selection
        local selector=selectors[name]
        if selector then selector:Load({Value=selection}) end
    end
    function api:Edit(name,selection)
        if applying or not ready then return end
        local selected={}
        for key,value in pairs(type(selection)=="table" and selection or {}) do
            if type(key)=="number" then selected[value]=true elseif value then selected[key]=true end
        end
        local hasSpecific=false
        for key in pairs(selected) do if key~="All weapons" then hasSpecific=true end end
        if selected["All weapons"] and hasSpecific then
            if selections[name] and selections[name]["All weapons"] then selected["All weapons"]=nil
            else selected={["All weapons"]=true} end
        end
        if not next(selected) then selected={["All weapons"]=true} end
        local names={};for weapon in pairs(selected) do names[#names+1]=weapon end;table.sort(names)
        local records=profiles.Features[name] or {}
        local record=selected["All weapons"] and defaultFor(name) or records[names[1]] or defaultFor(name)
        applying=true
        local ok,err=pcall(function()
            setSelector(name,selected)
            if record then self:Apply(name,record) end
        end)
        applying=false
        if not ok then warn("[Plex Weapon Config] "..tostring(err)) end
    end
    function api:OnFeatureChanged(name)
        if not ready or applying or shared.ModernLoading or (LionSaveManager and LionSaveManager.Loading) or not eligible(name) then return end
        local selection=selections[name] or {["All weapons"]=true}
        local record=self:Capture(name)
        if selection["All weapons"] then profiles.Defaults[name]=record
        else
            if not profiles.Defaults[name] then profiles.Defaults[name]=copy(defaultFor(name) or record) end
            profiles.Features[name]=profiles.Features[name] or {}
            for weapon in pairs(selection) do profiles.Features[name][weapon]=copy(record) end
            profiles.Enabled=true
            if not started then mainapi:StartWeaponProfiles(false) end
        end
        active[name]=record
    end
    function api:SelectWeapon(weapon,force)
        if applying or (weapon==currentWeapon and not force) then return end
        currentWeapon=weapon
        if not profiles.Enabled then return end
        applying=true
        local ok,err=pcall(function()
            local names={}
            for name in pairs(profiles.Features) do names[name]=true end
            for name in pairs(profiles.Defaults) do names[name]=true end
            for name in pairs(names) do
                local specific=weapon and profiles.Features[name] and profiles.Features[name][weapon]
                local record=specific or defaultFor(name)
                if record and active[name]~=record then self:Apply(name,record) end
                active[name]=record
                setSelector(name,specific and {[weapon]=true} or {["All weapons"]=true})
            end
        end)
        applying=false
        if not ok then mainapi:Notify({Text="Weapon config: "..tostring(err),Duration=4}) end
    end
    function api:Export() return copy(profiles) end
    function api:SetEnabled(value)
        if value~=true then
            applying=true
            for name in pairs(active) do if defaultFor(name) then self:Apply(name,defaultFor(name)) end end
            applying=false
            table.clear(active)
            for _,connection in ipairs(connections) do connection:Disconnect() end
            table.clear(connections)
            if controllerConnection then controllerConnection:Disconnect();controllerConnection=nil end
            started=false;currentWeapon=nil
        end
        profiles.Enabled=value==true
        if profiles.Enabled and hasOverrides() then
            if not started then mainapi:StartWeaponProfiles(true) else self:SelectWeapon(currentWeapon,true) end
        end
    end
    function api:Import(data)
        self:SetEnabled(false)
        profiles.Features={};profiles.Defaults={}
        for name in pairs(mainapi.Modules) do if eligible(name) then baseline[name]=self:Capture(name) end end
        if type(data)=="table" and (data.Version==1 or data.Version==2) then
            for name,records in pairs(type(data.Features)=="table" and data.Features or {}) do
                if eligible(name) and type(records)=="table" then profiles.Features[name]=copy(records) end
            end
            for name,record in pairs(type(data.Defaults)=="table" and data.Defaults or {}) do
                if eligible(name) and type(record)=="table" then profiles.Defaults[name]=copy(record) end
            end
            self:SetEnabled(data.Enabled==true)
        end
    end
    function api:RemoveSelected(name)
        local records=profiles.Features[name]
        for weapon in pairs(selections[name] or {}) do if records and weapon~="All weapons" then records[weapon]=nil end end
        self:Edit(name,selections[name])
        if LionSaveManager then LionSaveManager:ScheduleAutoSave() end
    end
    function mainapi:StartWeaponProfiles(applyInitial)
        if started or not profiles.Enabled or not hasOverrides() then return end
        started=true
        local controller=mainapi:GetCombatInputController("FighterController")
        if not controller then started=false;return end
        local function bind(fighter,initial)
            for _,connection in ipairs(connections) do connection:Disconnect() end
            table.clear(connections)
            local function changed()
                generation+=1
                local token=generation
                task.defer(function()
                    if token==generation and not mainapi.Uninjecting then
                        local item=fighter and fighter.EquippedItem
                        api:SelectWeapon(item and (item.Info and item.Info.Name or item.Name))
                    end
                end)
            end
            if fighter then table.insert(connections,fighter.EquippedItemChanged:Connect(changed)) end
            if initial==false then
                local item=fighter and fighter.EquippedItem
                currentWeapon=item and (item.Info and item.Info.Name or item.Name)
            else changed() end
        end
        bind(controller.LocalFighter,applyInitial)
        controllerConnection=controller.ObjectAdded:Connect(function(fighter)
            if fighter.Player==LocalPlayer then bind(fighter) end
        end)
    end
    function mainapi:InitializeWeaponProfiles()
        local library=require(ReplicatedStorage.Modules.ItemLibrary)
        local weapons={"All weapons"}
        local names={}
        for name in pairs(library.Items or {}) do names[#names+1]=name end
        table.sort(names);for _,name in ipairs(names) do weapons[#weapons+1]=name end
        local index=0
        for name,module in pairs(mainapi.Modules) do if eligible(name) then
            baseline[name]=api:Capture(name)
            selections[name]={["All weapons"]=true}
            local selector=module:AddDropdown({Name="weapon config",List=weapons,Default={["All weapons"]=true},Multi=true,
                Function=function(value) api:Edit(name,value) end})
            selector.WeaponProfileControl=true
            selectors[name]=selector
            LionSaveManager.Ignore=LionSaveManager.Ignore or {}
            LionSaveManager.Ignore[lionId("Dropdown",name,"weapon config")]=true
            module:AddButton({Name="use defaults for selected weapons",Function=function() api:RemoveSelected(name) end})
            index+=1;if index%8==0 then RunService.Heartbeat:Wait() end
        end end
        ready=true
        LionSaveManager.CustomSave=function()return {WeaponProfiles=api:Export()}end
        LionSaveManager.BeforeLoad=function()api:SetEnabled(false)end
        LionSaveManager.CustomLoad=function(data) api:Import(type(data)=="table" and data.WeaponProfiles) end
    end
    mainapi.WeaponProfiles=api
    mainapi:Clean(function()
        generation+=1;ready=false;profiles.Enabled=false
        if controllerConnection then controllerConnection:Disconnect() end
        for _,connection in ipairs(connections) do connection:Disconnect() end
        table.clear(connections);table.clear(active)
    end)
end)

-- END PLEX SOURCE: shared/062_weapon_profiles.lua
-- BEGIN PLEX SOURCE: shared/063_servers.lua
-- Public Roblox lobby data is fetched only on refresh. Ping may be absent;
-- never turn server FPS or player count into a fictitious latency measurement.
run(function()
    function mainapi:InitializeServerBrowser()
        local ui,menu=LionLibrary.NativeUI,LionLibrary.NativeMenu
        local sub=menu.subs.servers.browser
        local group=ui.group(sub.L,"Rivals servers",{simple=true})
        local status=group:AddLabel("Refresh to load public lobby servers. Ping is shown only when Roblox reports it.")
        local rows,selected,busy,lastFetch={},nil,false,-math.huge
        local placeId=17625359962 -- Verified root place for RIVALS universe 6035872082.
        local refreshList=group:list("servers",{pageSize=20,items=function()return rows end,
            selected=function()return selected end,onSelect=function(value)selected=value end})
        local function fetch()
            if busy then return end
            if os.clock()-lastFetch<15 then status:SetText("Wait 15 seconds between server refreshes.") return end
            busy=true;lastFetch=os.clock();status:SetText("Loading servers…")
            task.spawn(function()
                local ok,result=pcall(function()
                    local response=HttpService:JSONDecode(game:HttpGet("https://games.roblox.com/v1/games/"..placeId.."/servers/Public?sortOrder=Asc&excludeFullGames=true&limit=100"))
                    assert(type(response.data)=="table","Invalid server response")
                    local found={}
                    for _,server in ipairs(response.data) do
                        if server.id~=game.JobId and tonumber(server.playing) and tonumber(server.maxPlayers) and server.playing<server.maxPlayers then
                            local ping=tonumber(server.ping)
                            table.insert(found,{id=server.id,ping=ping,players=server.playing,
                                label=(ping and (math.floor(ping).." ms") or "Ping unknown").." · "..server.playing.."/"..server.maxPlayers.." · "..server.id:sub(1,8)})
                        end
                    end
                    table.sort(found,function(a,b)
                        if (a.ping or math.huge)~=(b.ping or math.huge) then return (a.ping or math.huge)<(b.ping or math.huge) end
                        return a.players<b.players
                    end)
                    return found
                end)
                busy=false
                if mainapi.Uninjecting then return end
                if ok then rows=result;refreshList();status:SetText(#rows.." available servers · ranked by reported ping, then population")
                else status:SetText("Server query failed: "..tostring(result)) end
            end)
        end
        local function join(id)
            if not id then mainapi:Notify({Text="Select a server first",Duration=3}) return end
            local exists=false;for _,row in ipairs(rows) do if row.id==id then exists=true break end end
            if not exists then return end
            game:GetService("TeleportService"):TeleportToPlaceInstance(placeId,id,LocalPlayer)
        end
        group:button("refresh servers",fetch)
        group:button("join selected server",function()join(selected)end)
        group:button("join lowest reported ping",function()
            if rows[1] and rows[1].ping then join(rows[1].id)
            else mainapi:Notify({Text="Roblox did not report ping. Select a server manually.",Duration=5}) end
        end)
        mainapi.ServerBrowser={Refresh=fetch,GetServers=function()return rows end}
    end
end)

